schemas.schema-01-systematic.prisma:
/// Core global settings for the entire AI Shopping Mall system. Stores
/// key-value configuration data (system environment parameters, feature
/// flags, legal, policy constraints, etc) that impact cross-domain
/// functionality. Critical for environment-wide policy propagation and
/// system-level toggles. Each configuration entry is atomic and
/// version-auditable.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_backend_system_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique key identifying the system configuration parameter (e.g.,
  /// 'maintenance_mode', 'default_locale').
  conf_key String

  /// The effective value of the system configuration parameter. Content, type,
  /// and semantics are determined by conf_key.
  conf_value String

  /// Optional business/admin description of the setting's meaning or scope.
  description String?

  /// Creation timestamp of this configuration entry.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp of this entry.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp (if entry was deleted logically; otherwise null).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_ai_backend_order_payments shopping_mall_ai_backend_order_payments[]

  @@unique([conf_key])
}

/// Represents a business channel in the AI Shopping Mall system (e.g.,
/// separate brand, marketplace, partner-tenant, B2B space). Channels
/// partition the marketplace, enabling isolated business/marketing policies
/// and operations. Key relationships: may host multiple sections and
/// categories (via mapping). Includes branding, access, and activation
/// fields.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_backend_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Administrator who created or manages this channel. References {@link
  /// shopping_mall_ai_backend_admins.id}.
  created_by_admin_id String @db.Uuid

  /// Unique business code for channel reference, external integration, and
  /// business logic (e.g., 'KOR_BRAND01').
  code String

  /// Channel's official display name.
  name String

  /// Detailed business purpose or scope for this channel.
  description String?

  /// Branding/logo file URI.
  logo_url String? @db.VarChar(80000)

  /// Whether the channel is currently active (business logic switch).
  active Boolean

  /// Channel creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp (if entry was deleted logically; otherwise null).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  createdByAdmin shopping_mall_ai_backend_admins @relation(fields: [created_by_admin_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_backend_sections shopping_mall_ai_backend_sections[]
  shopping_mall_ai_backend_channel_category_map shopping_mall_ai_backend_channel_category_map[]
  shopping_mall_ai_backend_product_channel_map shopping_mall_ai_backend_product_channel_map[]

  @@unique([code])
  @@index([created_by_admin_id])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Sections are curated areas within a channel to organize products/events
/// (e.g., best sellers, promotions). Each section belongs to a channel.
/// Business can define as many dynamic sections as needed. Includes display
/// order and status/visibility options.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_backend_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Linked business channel's {@link shopping_mall_ai_backend_channels.id}.
  channel_id String @db.Uuid

  /// Admin who created this section. References {@link
  /// shopping_mall_ai_backend_admins.id}.
  created_by_admin_id String @db.Uuid

  /// Unique identifier for section within channel (e.g., 'best', 'main',
  /// 'promotion').
  code String

  /// Section's display name.
  name String

  /// Detailed context for this section's curation purpose.
  description String?

  /// Explicit order for sorting/display of this section within the channel.
  display_order Int @db.Integer

  /// Visibility toggle for the section (e.g., is this section shown to users
  /// currently).
  visible Boolean

  /// Section creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp (if deleted logically).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  channel shopping_mall_ai_backend_channels @relation(fields: [channel_id], references: [id], onDelete: Cascade)
  createdByAdmin shopping_mall_ai_backend_admins @relation(fields: [created_by_admin_id], references: [id], onDelete: Cascade)

  @@index([created_by_admin_id])

  @@unique([channel_id, code])
  @@index([channel_id, display_order])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product/category taxonomy tree (multi-level). Each row is a single
/// category that can be nested by parent_id (hierarchical). Enables
/// fine-grained classification for products and curation. Used for search,
/// filtering, menu, recommendation, and reporting. Soft deletes allow
/// preserving taxonomy for historical/business reference.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_backend_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Optional parent category for hierarchy. Self-references {@link
  /// shopping_mall_ai_backend_categories.id}.
  parent_id String? @db.Uuid

  /// Admin who created this category. References {@link
  /// shopping_mall_ai_backend_admins.id}.
  created_by_admin_id String @db.Uuid

  /// Unique category code (internal taxonomical ID).
  code String

  /// Display name for this category (shown to users/business).
  name String

  /// Detailed context or purpose of this category.
  description String?

  /// Ordering index for UI rendering.
  display_order Int @db.Integer

  /// Whether the category is shown to users (UI toggle).
  visible Boolean

  /// Category creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp (if logically deleted).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  parent shopping_mall_ai_backend_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)
  createdByAdmin shopping_mall_ai_backend_admins @relation(fields: [created_by_admin_id], references: [id], onDelete: Cascade)

  recursive shopping_mall_ai_backend_categories[] @relation("recursive")
  shopping_mall_ai_backend_channel_category_map shopping_mall_ai_backend_channel_category_map[]
  shopping_mall_ai_backend_product_category_map shopping_mall_ai_backend_product_category_map[]

  @@index([created_by_admin_id])

  @@unique([code])
  @@index([parent_id])
  @@index([display_order])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Junction table associating channels and categories for dynamic curation.
/// Enables a many-to-many relationship: one channel can promote many
/// categories, one category can appear in many channels. Composite unique to
/// prevent duplication. Used for section/category navigation, AI curation,
/// analytics, and partitioned UIs.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_backend_channel_category_map {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Referenced channel {@link shopping_mall_ai_backend_channels.id}.
  channel_id String @db.Uuid

  /// Referenced category {@link shopping_mall_ai_backend_categories.id}.
  category_id String @db.Uuid

  /// Mapping creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp (null if active).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  channel shopping_mall_ai_backend_channels @relation(fields: [channel_id], references: [id], onDelete: Cascade)
  category shopping_mall_ai_backend_categories @relation(fields: [category_id], references: [id], onDelete: Cascade)

  @@unique([channel_id, category_id], map: "shopping_mall_ai_backend_channel_category_map_channel__d837cc87")
  @@index([category_id])
  @@index([channel_id])
}

/// Centralized metadata for all files or attachments used system-wide
/// (images, docs, certificates, legal, product assets, etc). Manages the
/// business-context origin of the file, owner, access control, security
/// context, and expiry. Structured for true polymorphic ownership: supports
/// reference to any business entity type via owner_id and owner_type. This
/// design enables attachments to be linked to admins, products, customers,
/// sellers, orders, etc., supporting long-term scalability, compliance and
/// cross-domain file use. Polymorphism is managed at the application and
/// convention layer; owner_type must be present and valid for each
/// attachment. Critical for file compliance, auditing, and tracking linked
/// business data.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_backend_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// UUID of the owning entity for the attachment; compatible with any
  /// business object's PK (admin, product, customer, order, etc.). Interpreted
  /// in conjunction with owner_type for context.
  owner_id String @db.Uuid

  /// String discriminator specifying business type/classification of owner
  /// (e.g., 'admin', 'seller', 'product', 'customer', 'order', etc.). Used for
  /// context routing and polymorphic relations. Must match one of the
  /// supported domain types documented in system.
  owner_type String

  /// Original file name as uploaded.
  file_name String

  /// File size in bytes.
  file_size Int @db.Integer

  /// MIME type (content type) for file; used for validation and download.
  mime_type String

  /// Physical storage URI for file data (object storage, CDN URI, local, etc).
  storage_uri String @db.VarChar(80000)

  /// SHA-256 checksum hash for file integrity and deduplication.
  hash_sha256 String

  /// Timestamp of actual upload/ingest of this file into the system.
  uploaded_at DateTime @db.Timestamptz

  /// Expiration timestamp of this file; after which file should be deleted or
  /// is invalid. Null if indefinite/never expires.
  expire_at DateTime? @db.Timestamptz

  /// Attachment record creation time (audit field).
  created_at DateTime @db.Timestamptz

  /// Record last update timestamp (audit field).
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp (for logical deletes, otherwise null).
  deleted_at DateTime? @db.Timestamptz

  /// Optional business/admin description about the file content, usage
  /// purpose, or any compliance detail.
  description String?

  //----
  // RELATIONS
  //----
  shopping_mall_ai_backend_attachment_logs shopping_mall_ai_backend_attachment_logs[]

  @@unique([hash_sha256])
  @@index([owner_id, owner_type])
  @@index([file_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Attachment/file event logs (upload, download, deletion, access) for
/// auditing and forensic operations. Polymorphic support for owner; records
/// WHAT (event/action type), WHEN, WHERE (ip), and context about every file
/// operation. Ensures traceability for file access, regulatory compliance,
/// and troubleshooting. FK to attachments (polymorphic), logs operator_admin
/// as actor when available.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_backend_attachment_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Attachment file {@link shopping_mall_ai_backend_attachments.id}.
  attachment_id String @db.Uuid

  /// Type of file event (e.g., 'upload', 'download', 'delete', 'access',
  /// 'expire', etc.).
  event_type String

  /// Business or technical context of the event. Optional log details for
  /// troubleshooting or tracing.
  event_context String?

  /// IP address from which the attachment event happened (for audit/security
  /// purposes).
  ip_address String

  /// Admin/operator who performed the action (when relevant). References admin
  /// ID, nullable for automated/system events or non-admin actions.
  operated_by_admin_id String? @db.Uuid

  /// Precise timestamp when the event occurred.
  event_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  attachment shopping_mall_ai_backend_attachments @relation(fields: [attachment_id], references: [id], onDelete: Cascade)

  @@index([attachment_id])
  @@index([operated_by_admin_id], map: "shopping_mall_ai_backend_attachment_logs_operated_by_a_4a3a72e6")
  @@index([event_type])
}

schemas.schema-02-actors.prisma:
/// Customer account data for the shoppingMallAiBackend system. Records all
/// registered end users including personal/contact details, login
/// credentials, account status, channel for signup, and profile setup. This
/// model is the master entity for customer identity including relationship
/// to addresses, external OAuth links, and customer histories. Does not
/// contain calculated or denormalized data.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_backend_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's unique business email address used for authentication and
  /// notifications.
  email String

  /// Hashed value of the customer's login password.
  password_hash String

  /// Full name of the customer for verification and profile display.
  name String

  /// Customer's unique display nickname. Required for social, review, and
  /// community activities.
  nickname String

  /// Customer's mobile phone number (used for verification and contact).
  phone String

  /// URI for customer's profile image. Used for display in UI.
  profile_image_uri String? @db.VarChar(80000)

  /// Account status (active, locked, dormant, withdrawn, etc.).
  /// Business-driven state for access and communications.
  status String

  /// Indicates whether the customer's email is verified.
  email_verified Boolean

  /// Indicates whether the customer's phone is verified.
  phone_verified Boolean

  /// Timestamp of initial customer registration.
  joined_at DateTime @db.Timestamptz

  /// Most recent login datetime for the customer account.
  last_login_at DateTime? @db.Timestamptz

  /// Creation timestamp for record (for auditing).
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update to customer data.
  updated_at DateTime @db.Timestamptz

  /// Timestamp of soft deletion (if any, null when not deleted).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_ai_backend_customer_addresses shopping_mall_ai_backend_customer_addresses[]
  shopping_mall_ai_backend_customer_external_links shopping_mall_ai_backend_customer_external_links[]
  shopping_mall_ai_backend_customer_histories shopping_mall_ai_backend_customer_histories[]
  shopping_mall_ai_backend_orders shopping_mall_ai_backend_orders[]
  shopping_mall_ai_backend_carts shopping_mall_ai_backend_carts[]
  shopping_mall_ai_backend_issued_coupons shopping_mall_ai_backend_issued_coupons[]
  shopping_mall_ai_backend_coupon_usages shopping_mall_ai_backend_coupon_usages[]
  shopping_mall_ai_backend_points shopping_mall_ai_backend_points?
  shopping_mall_ai_backend_coin_wallets shopping_mall_ai_backend_coin_wallets[]
  shopping_mall_ai_backend_coin_snapshots shopping_mall_ai_backend_coin_snapshots[]
  shopping_mall_ai_backend_mileage_wallets shopping_mall_ai_backend_mileage_wallets?
  shopping_mall_ai_backend_product_inquiries shopping_mall_ai_backend_product_inquiries[]
  shopping_mall_ai_backend_product_reviews shopping_mall_ai_backend_product_reviews[]
  shopping_mall_ai_backend_moderation_events shopping_mall_ai_backend_moderation_events[]
  shopping_mall_ai_backend_appeals shopping_mall_ai_backend_appeals[]
  shopping_mall_ai_backend_favorite_products shopping_mall_ai_backend_favorite_products[]
  shopping_mall_ai_backend_favorite_inquiries shopping_mall_ai_backend_favorite_inquiries[]
  shopping_mall_ai_backend_favorite_addresses shopping_mall_ai_backend_favorite_addresses[]

  @@unique([email])
  @@unique([nickname])
  @@index([status])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Addresses owned and managed by customers. Stores multiple shipping or
/// billing addresses per customer, including main/default flag. References
/// parent customer entity. Separate model ensures that address history,
/// verification events, and clustering are possible without denormalization.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_backend_customer_addresses {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link shopping_mall_ai_backend_customers.id}.
  customer_id String @db.Uuid

  /// User-defined alias or description (e.g., Home, Work, Parent's house) for
  /// quick selection.
  alias String?

  /// Recipient's name for delivery purposes (may differ from account name).
  receiver_name String

  /// Recipient's phone number.
  receiver_phone String

  /// Postal code for address verification and delivery routing.
  postal_code String

  /// Primary street address information.
  address_line1 String

  /// Secondary (optional) address info (unit, building, floor).
  address_line2 String?

  /// City or locality used for logistics and region assignment.
  city String

  /// State or province within the country.
  state String

  /// Country (ISO 3166-1 alpha-2 code preferred).
  country String

  /// Indicates if this address is marked as the customer's primary default
  /// address.
  is_primary Boolean

  /// Creation timestamp for the address record.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last modification for address data.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, null if address is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_ai_backend_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_backend_favorite_addresses shopping_mall_ai_backend_favorite_addresses[]

  @@unique([customer_id, alias], map: "shopping_mall_ai_backend_customer_addresses_customer_i_ae3100f8")
  @@index([customer_id])
  @@index([alias(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// External OAuth/OpenID/social account links attached to customer accounts
/// for login and profile federation. One record per (customer, provider,
/// external ID) combination. Includes metadata for identity provider.
/// Enables SSO/integration without denormalizing into customer profile.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_backend_customer_external_links {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link shopping_mall_ai_backend_customers.id}.
  customer_id String @db.Uuid

  /// External auth provider (e.g., google, kakao, naver, apple, etc.).
  provider String

  /// External system's user identifier (sub, sns ID, etc).
  external_id String

  /// Datetime of first link (binding) with customer account.
  linked_at DateTime @db.Timestamptz

  /// Most recent successful authentication event at provider, if known.
  last_auth_at DateTime? @db.Timestamptz

  /// Opaque JSON data with provider-specific profile payload (trusted identity
