  metadata_json String?

  /// Creation timestamp of this external link record.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for external link info.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null if not deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_ai_backend_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_backend_customer_external_links_custo_55a82c47")

  @@unique([provider, external_id], map: "shopping_mall_ai_backend_customer_external_links_provi_549d8a76")
  @@unique([customer_id, provider], map: "shopping_mall_ai_backend_customer_external_links_custo_3eebcf29")
  @@index([customer_id], map: "shopping_mall_ai_backend_customer_external_links_custo_0f52a72a")
  @@index([provider(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Snapshot-based record of significant lifecycle events or changes to a
/// customer account. Enables audit trails, compliance histories, and
/// rollback/recovery for customer state including registration,
/// verification, profile changes, status shifts (dormant/withdrawn), etc.
/// Always references customer entity and records event type, old/new values,
/// and trigger context.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_backend_customer_histories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link shopping_mall_ai_backend_customers.id}.
  customer_id String @db.Uuid

  /// Type of lifecycle event (created, updated, verified, password_changed,
  /// locked, withdrawn, etc).
  event_type String

  /// JSON snapshot of previous state/fields (before change).
  old_value_json String?

  /// JSON snapshot of new state/fields (after change).
  new_value_json String?

  /// Trigger source (user, system, admin, external).
  triggered_by String

  /// Additional contextual metadata about the event (IP address, device,
  /// channel, error codes etc.).
  meta_json String?

  /// Datetime the history event occurred.
  occurred_at DateTime @db.Timestamptz

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_ai_backend_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  @@index([customer_id])
  @@index([event_type])
}

