import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendPoint";
import type { IPageIShoppingMallAiBackendPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendPoint";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the admin's ability to list customer point wallets with paginated and filtered queries.
 *
 * This test covers:
 * - Standard listing of all point wallets, checking pagination.
 * - Filtering by customer_id, by balance range (min_balance, max_balance), and by update datetime window.
 * - Edge cases: invalid filter formats, using the API as a non-admin (access denied), and requesting pagination beyond available data.
 * - Result integrity: Only expected (filtered) records are returned based on applied filter conditions.
 * - Compliance: An audit log is assumed to be generated for admin access (this may only be verifiable indirectly if no direct artifact is exposed).
 *
 * Steps:
 * 1. Query as admin with no filters: validate success, page contents, and type structure.
 * 2. Query with specific customer_id filter: results are only for that customer.
 * 3. Query filtering with min_balance and max_balance: all wallets in result are within the range.
 * 4. Query with updated_from/updated_to (using edge times): only wallets within interval returned.
 * 5. Query with bad/incomplete formats: verify error occurs.
 * 6. Attempt as non-admin: verify error/forbidden.
 */
export async function test_api_point_wallets_paginated_listing_with_filtering(connection: api.IConnection) {
  // 1. Query as admin, no filters
  const standard = await api.functional.shoppingMallAiBackend.admin.points.search(connection, {
    body: {},
  });
  typia.assert(standard);
  TestValidator.predicate("default pagination page number is first page")(standard.pagination.current === 1);
  TestValidator.predicate("all data are point wallet records")(standard.data.every(wallet => typeof wallet.id === "string" && typeof wallet.customer_id === "string"));

  // If there are any records, choose one for filtering
  if (standard.data.length > 0) {
    const reference = RandomGenerator.pick(standard.data);
    // 2. Query with customer_id filter
    const filteredByCustomer = await api.functional.shoppingMallAiBackend.admin.points.search(connection, {
      body: { customer_id: reference.customer_id },
    });
    typia.assert(filteredByCustomer);
    TestValidator.predicate("filtered by customer_id")(filteredByCustomer.data.every(w => w.customer_id === reference.customer_id));
  }

  // 3. Query with min_balance and max_balance
  const balanceRange = await api.functional.shoppingMallAiBackend.admin.points.search(connection, {
    body: { min_balance: 10, max_balance: 100000 },
  });
  typia.assert(balanceRange);
  TestValidator.predicate("within balance range")(balanceRange.data.every(w => w.balance >= 10 && w.balance <= 100000));

  // 4. Query with updated_from/updated_to
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
  const now = new Date();
  const timeRange = await api.functional.shoppingMallAiBackend.admin.points.search(connection, {
    body: {
      updated_from: sevenDaysAgo.toISOString(),
      updated_to: now.toISOString(),
    },
  });
  typia.assert(timeRange);
  TestValidator.predicate("all updated_at inside window")(
    timeRange.data.every(w => new Date(w.updated_at) >= sevenDaysAgo && new Date(w.updated_at) <= now)
  );

  // 5. Edge: invalid format (bad uuid for customer_id)
  await TestValidator.error("bad uuid should be rejected")(async () => {
    await api.functional.shoppingMallAiBackend.admin.points.search(connection, {
      body: { customer_id: "not-a-uuid" as any },
    });
  });

  // 6. Attempt as non-admin (simulate by omitting Authorization header)
  const { Authorization, ...restHeaders } = connection.headers ?? {};
  const noAuthConnection: api.IConnection = { ...connection, headers: restHeaders };
  await TestValidator.error("non-admin access forbidden")(async () => {
    await api.functional.shoppingMallAiBackend.admin.points.search(noAuthConnection, { body: {} });
  });
  // Note: Audit log check is presumed by successful privileged access; direct artifact may not be testable here.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendPoint";
import type { IPageIShoppingMallAiBackendPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendPoint";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate error handling for unauthorized access when fetching point wallet records as a non-admin user.
 *
 * This test ensures that only admin users are able to query the paginated point wallet list in the shopping mall backend. Attempting to perform the filtering/search operation with a non-admin account should result in an authorization error. This is critical for compliance and privacy, as financial wallet data must be protected from unauthorized access at the API gateway level.
 *
 * Steps:
 * 1. Attempt to request the point wallet list filter/pagination endpoint (`PATCH /shoppingMallAiBackend/admin/points`) using a connection that is NOT authenticated as an admin user.
 * 2. Supply a typical request body payload (filters/pagination) for realism.
 * 3. Assert that access is denied and the API returns an error (such as 401 Unauthorized or 403 Forbidden).
 * 4. Validate that business logic blocks the request with an appropriate error code for compliance logging.
 */
export async function test_api_point_wallets_filtering_permission_error(
  connection: api.IConnection,
) {
  // Step 1: Attempt to call the admin point wallet list endpoint as a non-admin/non-privileged user
  const request: IShoppingMallAiBackendPoint.IRequest = {
    page: 1,
    limit: 5,
  };

  // Step 2: Assert that an error is thrown (access denied)
  await TestValidator.error("non-admin cannot access admin wallet listing endpoint")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.points.search(connection, {
        body: request,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCategory";
import type { IPageIShoppingMallAiBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test: Search, filter, paginate, and check hierarchy for admin categories.
 *
 * Validates the category search API for shopping mall admin:
 * - Filtering by code/name/query using real created data
 * - Pagination parameters (page, pageSize) and output
 * - Visibility filtering (visible=true/false)
 * - Correct category hierarchy (parent/child)
 * - Soft-deleted categories are excluded (direct deletion not available, so this is documented)
 * - Enforces correct admin authorization (permission error for unauthenticated)
 * - Validation error on malformed request (e.g., page as string)
 *
 * Steps:
 * 1. Register an admin user
 * 2. As admin, create a parent and a child category (child refers to parent)
 * 3. Query categories by name filter and validate both categories are returned, checking parent/child relationship
 * 4. Confirm hierarchy attributes (child's parent_id matches parent.id)
 * 5. Test pagination by setting pageSize=1 and verifying single result per page
 * 6. Create a hidden category, search with visible=false, and ensure only hidden category is returned
 * 7. Attempt to search as unauthenticated user and expect a permission error
 * 8. Send malformed request (page as string) and expect validation error
 */
export async function test_api_category_search_with_filters_pagination_and_hierarchy(connection: api.IConnection) {
  // 1. Register an admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SecurePass123!";
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);

  // 2. Create parent category
  const parentCode = "parent_" + RandomGenerator.alphaNumeric(8);
  const parentName = "Parent Category " + RandomGenerator.alphabets(5);
  const parent = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: null,
      created_by_admin_id: admin.adminId,
      code: parentCode,
      name: parentName,
      description: "A parent category for hierarchy test.",
      display_order: 1,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(parent);

  // 3. Create child category
  const childCode = "child_" + RandomGenerator.alphaNumeric(8);
  const childName = "Child Category " + RandomGenerator.alphabets(5);
  const child = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: parent.id,
      created_by_admin_id: admin.adminId,
      code: childCode,
      name: childName,
      description: "A child category for hierarchy test.",
      display_order: 2,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(child);

  // 4. Search categories by parent name - should get both parent and child
  const searchResponse = await api.functional.shoppingMallAiBackend.admin.categories.searchCategories(connection, {
    body: {
      name: "Parent Category",
      page: 1,
      pageSize: 10,
    } satisfies IShoppingMallAiBackendCategory.IRequest,
  });
  typia.assert(searchResponse);

  // Confirm presence by id
  TestValidator.predicate("parent present in returned set")(searchResponse.data.some(c => c.id === parent.id));
  TestValidator.predicate("child present in returned set")(searchResponse.data.some(c => c.id === child.id && c.parent_id === parent.id));
  // Confirm child's parent_id matches
  const foundChild = searchResponse.data.find(c => c.id === child.id);
  TestValidator.equals("child has correct parent_id")(foundChild?.parent_id)(parent.id);

  // 5. Pagination test: request pageSize = 1 for exact pagination
  const paged = await api.functional.shoppingMallAiBackend.admin.categories.searchCategories(connection, {
    body: {
      name: "Category",
      page: 1,
      pageSize: 1,
    } satisfies IShoppingMallAiBackendCategory.IRequest,
  });
