/**
 * Test admin category creation: valid creation, duplicate rejection, parent_id validation, non-admin permission enforcement.
 *
 * This E2E test verifies the shopping mall admin category creation endpoint with all relevant business scenarios:
 *   1. Valid admin creates root category and output matches input.
 *   2. Duplicate codes are rejected as errors.
 *   3. Invalid parent_id is rejected as error.
 *   4. Non-admin (unauthenticated) users are denied.
 *
 * Steps:
 * 1. Admin registration and get credentials (adminId).
 * 2. Admin creates a root category (matching persisted values).
 * 3. Try to create another category using the same code (should fail).
 * 4. Try to create with a random (non-existent) parent_id (should fail).
 * 5. Try category creation with an unauthenticated/empty connection (should be denied).
 */
export async function test_api_category_creation_valid_duplicate_and_invalid_parent(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const adminSignUp: IAdminAuth.JwtWithProfile = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminSignUp);
  const adminId = adminSignUp.adminId;

  // 2. Admin creates a new root category
  const uniqueCode = RandomGenerator.alphaNumeric(8);
  const categoryInput: IShoppingMallAiBackendCategory.ICreate = {
    code: uniqueCode,
    name: RandomGenerator.name(),
    description: RandomGenerator.content()()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    visible: true,
    created_by_admin_id: adminId,
    parent_id: null
  };
  const created: IShoppingMallAiBackendCategory = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, { body: categoryInput });
  typia.assert(created);
  TestValidator.equals("code matches")(created.code)(categoryInput.code);
  TestValidator.equals("name matches")(created.name)(categoryInput.name);
  TestValidator.equals("created_by_admin_id matches")(created.created_by_admin_id)(adminId);
  TestValidator.equals("parent_id matches")(created.parent_id)(null);
  TestValidator.equals("visible matches")(created.visible)(categoryInput.visible);
  TestValidator.equals("display_order matches")(created.display_order)(categoryInput.display_order);
  if (typeof categoryInput.description === "string")
    TestValidator.equals("description matches")(created.description)(categoryInput.description);

  // 3. Duplicate code (should fail)
  const duplicateInput: IShoppingMallAiBackendCategory.ICreate = {
    code: uniqueCode,
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
