  });

  // 4. Invalid parent_id (should fail)
  const invalidParentId = typia.random<string & tags.Format<"uuid">>();
  const invalidParentInput: IShoppingMallAiBackendCategory.ICreate = {
    code: RandomGenerator.alphaNumeric(9),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    visible: true,
    created_by_admin_id: adminId,
    parent_id: invalidParentId
  };
  await TestValidator.error("invalid parent_id should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, { body: invalidParentInput });
