/**
 * Validate updating an existing channel-category mapping resource as admin, with both successful and invalid/edge scenarios.
 *
 * This test covers both successful mapping updates and validation of error handling for duplicates and invalid/non-existent IDs using the admin API. It asserts audit/update fields and unique constraints.
 *
 * Step-by-step workflow:
 * 1. Create a business channel (A) as a prerequisite.
 * 2. Create a category (X) as a prerequisite.
 * 3. Create the initial mapping from A↔X.
 * 4. Create another channel (B) and category (Y) for update and duplicate conflict scenarios.
 * 5. Update the mapping by changing its category to Y (still channel A): should succeed; verify returned mapping reflects the new category and updated_at advances.
 * 6. Create a new mapping B↔Y.
 * 7. Attempt to update mapping (A↔Y) to (B↔Y) (conflict with existing mapping), expect duplicate constraint error.
 * 8. Attempt to update mapping using a non-existent mapping UUID, expect not found error.
 */
export async function test_api_channel_category_map_update_success_and_invalid(
  connection: api.IConnection,
) {
  // 1. Create admin UUID for creator fields
  const adminId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Create channel A
  const channelA = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: `chnl-a-${RandomGenerator.alphaNumeric(10)}`,
      name: `ChannelA-${RandomGenerator.alphabets(5)}`,
      created_by_admin_id: adminId,
      description: RandomGenerator.paragraph()(),
      logo_url: null,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channelA);

  // 3. Create category X
  const categoryX = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: null,
      created_by_admin_id: adminId,
      code: `cat-x-${RandomGenerator.alphaNumeric(8)}`,
      name: `CatX-${RandomGenerator.alphabets(4)}`,
      description: RandomGenerator.paragraph()(),
      display_order: 1,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(categoryX);

  // 4. Create initial mapping A↔X
  const mappingAX = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.createChannelCategoryMap(connection, {
    body: {
      channel_id: channelA.id,
      category_id: categoryX.id,
    } satisfies IShoppingMallAiBackendChannelCategoryMap.ICreate,
  });
  typia.assert(mappingAX);

  // 5. Create channel B
  const channelB = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: `chnl-b-${RandomGenerator.alphaNumeric(10)}`,
      name: `ChannelB-${RandomGenerator.alphabets(5)}`,
      created_by_admin_id: adminId,
      description: RandomGenerator.paragraph()(),
      logo_url: null,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channelB);

  // 6. Create category Y
  const categoryY = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: null,
      created_by_admin_id: adminId,
      code: `cat-y-${RandomGenerator.alphaNumeric(8)}`,
      name: `CatY-${RandomGenerator.alphabets(4)}`,
      description: RandomGenerator.paragraph()(),
      display_order: 2,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(categoryY);

  // 7. Update mapping: change category to Y (A↔Y)
  const updatedMappingAY = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.updateChannelCategoryMap(connection, {
    channelCategoryMapId: mappingAX.id,
    body: { category_id: categoryY.id } satisfies IShoppingMallAiBackendChannelCategoryMap.IUpdate,
  });
  typia.assert(updatedMappingAY);
  TestValidator.equals("category changed")(updatedMappingAY.category_id)(categoryY.id);
  TestValidator.notEquals("updated_at advanced")(updatedMappingAY.updated_at)(mappingAX.updated_at);

  // 8. Create mapping B↔Y
  const mappingBY = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.createChannelCategoryMap(connection, {
    body: {
      channel_id: channelB.id,
      category_id: categoryY.id,
    } satisfies IShoppingMallAiBackendChannelCategoryMap.ICreate,
  });
  typia.assert(mappingBY);

  // 9. Try to update mappingAY to channel B and category Y (B↔Y) = duplicate constraint
  await TestValidator.error("duplicate constraint - (B,Y)")(() =>
    api.functional.shoppingMallAiBackend.admin.channelCategoryMap.updateChannelCategoryMap(connection, {
      channelCategoryMapId: updatedMappingAY.id,
      body: { channel_id: channelB.id, category_id: categoryY.id } satisfies IShoppingMallAiBackendChannelCategoryMap.IUpdate,
    })
  );

  // 10. Try to update with non-existent mapping UUID
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found - non-existent id")(() =>
    api.functional.shoppingMallAiBackend.admin.channelCategoryMap.updateChannelCategoryMap(connection, {
      channelCategoryMapId: fakeId,
      body: { category_id: categoryY.id } satisfies IShoppingMallAiBackendChannelCategoryMap.IUpdate,
    })
  );
}

