  // 7. Simulate unauthorized access (no Authorization header)
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("unauthorized search fails or yields no data")(async () => {
    const out = await api.functional.shoppingMallAiBackend.seller.products.search(unauthConn, {
      body: {},
    });
    typia.assert(out);
    TestValidator.equals("unauthorized yields zero data")(out.data.length)(0);
  });
}

