import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test the retrieval and access control of a seller history record by admin.
 *
 * This function validates the following scenario flows:
 * 1. Admin successfully fetches an existing seller history record and checks all fields.
 * 2. Attempt to fetch a non-existent history record (should receive not found error).
 * 3. Attempt to fetch with a valid historyId under a mismatched sellerId (should receive not found/forbidden).
 * 4. Access control: ensure only admins can fetch seller history records—other roles must be denied.
 *
 * Steps:
 * 1. Log in as admin and get token.
 * 2. Query/search for an existing seller with history (using admin).
 * 3. Fetch admin side seller history event list for that seller. Require at least one event to continue.
 * 4. Use a valid sellerId/historyId pair for positive case.
 * 5. Attempt fetch with random, non-existent historyId for negative case.
 * 6. Attempt fetch with valid historyId, but wrong sellerId.
 * 7. Access control (non-admin/anonymous) cannot be E2E tested here due to connection typing limits.
 */
export async function test_api_seller_history_detail_success_and_access_control(connection: api.IConnection) {
  // 1. Log in as admin to acquire token
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234";
  // Simulate (or require) the existence of admin credentials in test environment
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);

  // 2. Search for a seller with existing action history
  const sellersPage = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: {
      page: 1,
      limit: 10
    } satisfies IShoppingMallAiBackendSeller.IRequest,
  });
  typia.assert(sellersPage);
  const seller = sellersPage.data.find((s) => s.status === "active") ?? sellersPage.data[0];
  TestValidator.predicate("seller exists")(!!seller);

  // 3. Fetch history list for this seller (require at least one record)
  const sellerHistoriesPage = await api.functional.shoppingMallAiBackend.admin.sellers.histories.search(connection, {
    sellerId: seller.id,
    body: {
      seller_id: seller.id,
      page: 1,
      limit: 5
    } satisfies IShoppingMallAiBackendSellerHistory.IRequest,
  });
  typia.assert(sellerHistoriesPage);
  const history = sellerHistoriesPage.data[0];
  TestValidator.predicate("At least one history record exists")(!!history);

  // 4. Success case: fetch the history by correct sellerId/historyId
  const fetched = await api.functional.shoppingMallAiBackend.admin.sellers.histories.at(connection, {
    sellerId: seller.id,
    historyId: history.id,
  });
  typia.assert(fetched);
  TestValidator.equals("seller_id matches")(fetched.seller_id)(seller.id);
  TestValidator.equals("historyId matches")(fetched.id)(history.id);

  // 5. Negative case: fetch with random (non-existent) historyId
  await TestValidator.error("not found for random historyId")(() =>
    api.functional.shoppingMallAiBackend.admin.sellers.histories.at(connection, {
      sellerId: seller.id,
      historyId: typia.random<string & tags.Format<"uuid">>()
    })
  );

  // 6. Negative case: mismatch sellerId/historyId
  // Find or generate another seller
  let otherSellerId = null;
  if (sellersPage.data.length > 1) {
    otherSellerId = sellersPage.data.find((s) => s.id !== seller.id)?.id;
  } else {
    // Try to get another seller by re-querying next page
    const moreSellersPage = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
      body: { page: 2, limit: 10 } satisfies IShoppingMallAiBackendSeller.IRequest,
    });
    typia.assert(moreSellersPage);
    otherSellerId = moreSellersPage.data.find((s) => s.id !== seller.id)?.id;
  }
  if (otherSellerId) {
    await TestValidator.error("historyId not belonging to other seller should fail")(() =>
      api.functional.shoppingMallAiBackend.admin.sellers.histories.at(connection, {
        sellerId: otherSellerId!,
        historyId: history.id,
      })
    );
  }

  // 7. Access control (non-admin/anonymous) cannot be E2E tested here due to connection typing limits.
}

