import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachment";
import type { IShoppingMallAiBackendAttachmentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachmentLog";

/**
 * Validate mutation restrictions and behavior for attachment log updates.
 *
 * This test ensures that only permitted fields (event_context and operated_by_admin_id) in an attachment log record can be updated, while immutable fields (event_type, event_at, ip_address) cannot be modified. This guarantees audit policy compliance for system event logs.
 *
 * Workflow:
 * 1. Create a new attachment to act as the parent for a log entry.
 * 2. Register a log event for the attachment, capturing its initial immutable and mutable metadata.
 * 3. Update allowed fields (event_context and operated_by_admin_id) using the log's unique ID, and verify mutability is respected and persisted.
 * 4. Attempt updates using invalid/non-existent attachmentId or attachmentLogId and confirm API rejects the call with a business error.
 * 5. Confirm that no other fields can be mutated by type constraints.
 */
export async function test_api_attachment_log_update_metadata_restrictions(connection: api.IConnection) {
  // 1. Create a new attachment for testing
  const attachment = await api.functional.shoppingMallAiBackend.admin.attachments.create(connection, {
    body: {
      owner_id: typia.random<string & tags.Format<"uuid">>(),
      owner_type: "admin",
      file_name: "test_file.txt",
      file_size: 1024,
      mime_type: "text/plain",
      storage_uri: "s3://test-bucket/test_file.txt",
      hash_sha256: typia.random<string>(),
      uploaded_at: new Date().toISOString(),
      expire_at: null,
      description: "Testing attachment for log update mutations."
    } satisfies IShoppingMallAiBackendAttachment.ICreate
  });
  typia.assert(attachment);

  // 2. Register a log entry for this attachment
  const log = await api.functional.shoppingMallAiBackend.admin.attachments.logs.create(connection, {
    attachmentId: attachment.id,
    body: {
      event_type: "upload",
      ip_address: "127.0.0.1",
      event_at: new Date().toISOString(),
      operated_by_admin_id: typia.random<string & tags.Format<"uuid">>(),
      event_context: "Initial event log context."
    } satisfies IShoppingMallAiBackendAttachmentLog.ICreate
  });
  typia.assert(log);

  // 3. Update allowed mutable fields (event_context and operated_by_admin_id)
  const newContext = "Updated event context for audit trail validation.";
  const newOperatorId = typia.random<string & tags.Format<"uuid">>();
  const updatedLog = await api.functional.shoppingMallAiBackend.admin.attachments.logs.update(connection, {
    attachmentId: attachment.id,
    attachmentLogId: log.id,
    body: {
      event_context: newContext,
      operated_by_admin_id: newOperatorId
    } satisfies IShoppingMallAiBackendAttachmentLog.IUpdate
  });
  typia.assert(updatedLog);
  // Confirm mutable fields have changed
  TestValidator.equals("event_context updated")(updatedLog.event_context)(newContext);
  TestValidator.equals("operated_by_admin_id updated")(updatedLog.operated_by_admin_id)(newOperatorId);
  // Confirm immutable fields are unchanged
  TestValidator.equals("event_type unchanged")(updatedLog.event_type)(log.event_type);
  TestValidator.equals("event_at unchanged")(updatedLog.event_at)(log.event_at);
  TestValidator.equals("ip_address unchanged")(updatedLog.ip_address)(log.ip_address);

  // 4. Attempt update with a non-existent attachment ID
  await TestValidator.error("invalid attachmentId")(() =>
    api.functional.shoppingMallAiBackend.admin.attachments.logs.update(connection, {
      attachmentId: typia.random<string & tags.Format<"uuid">>(),
      attachmentLogId: log.id,
