 *
 * This test simulates a real customer journey:
 *
 * 1. Register a new customer using unique credentials (email, phone, etc.) via the sign-up API. Confirm the response includes JWT token information and a valid customer profile without sensitive info (e.g., password hash).
 * 2. Using the registered and logged-in session (headers updated with JWT from registration), create a new shopping cart with status 'active'. Verify the created cart record has proper structure (id, status, created/updated timestamps, etc.), status set to 'active', and no missing required fields. Ensure nulls are set explicitly where allowed.
 * 3. Attempt to create a second 'active' cart for the same customer (using the same authenticated session). Expect a business logic error and confirm it is handled by rejecting the API call—using TestValidator to ensure the proper error is thrown (without relying on the exact error message).
 * 4. Verify no superfluous carts are created and customer remains with at most one active cart.
 */
export async function test_api_cart_customer_create_success(connection: api.IConnection) {
  // Step 1: Register a new customer using unique credentials
  const email = typia.random<string & tags.Format<"email">>();
  const password = "ShoppingCart123!";
