  const orderInput: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    order_number: RandomGenerator.alphaNumeric(12),
    total_amount: typia.random<number>(),
    currency_code: "USD",
    current_status: "created",
    // Optional fields
    // order_group_id and note are intentionally left undefined
  };
  const createdOrder = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderInput });
  typia.assert(createdOrder);

  // Step 2: Create snapshot as admin
  const snapshotPayload: IShoppingMallAiBackendOrderSnapshot.ICreate = {
    snapshot_json: JSON.stringify(createdOrder),
    snapshot_reason: "created",
  };
