import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICustomerValidateToken } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerValidateToken";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test invalid, expired, or tampered JWT validation for customer authentication.
 *
 * This test verifies that the /auth/customer/validate endpoint robustly rejects expired, forged, random, or missing JWT values in the Authorization header. For each scenario, it confirms:
 *   - 'valid': false is returned
 *   - No customer object is present in response
 *   - Ensures session safety and prevents information leakage on authentication failure
 *
 * Steps:
 * 1. Call with NO Authorization header: expect 'valid' === false, no 'customer'.
 * 2. Call with random garbage token: expect 'valid' === false, no 'customer'.
 * 3. Call with plausible but expired JWT: expect 'valid' === false, no 'customer'.
 * 4. Call with tampered JWT: expect 'valid' === false, no 'customer'.
 */
export async function test_api_customer_validate_token_expired_or_invalid(
  connection: api.IConnection,
) {
  // 1. No Authorization header set
  const respNoAuth = await api.functional.auth.customer.validate.validateToken({
    ...connection,
    headers: Object.fromEntries(Object.entries({ ...connection.headers }).filter(([k]) => k !== "Authorization")),
  });
  typia.assert(respNoAuth);
  TestValidator.equals("invalid: no Authorization header")(respNoAuth.valid)(false);
  TestValidator.equals("no customer: no Authorization header")(respNoAuth.customer)(undefined);

  // 2. Garbage token (random string)
  const respGarbage = await api.functional.auth.customer.validate.validateToken({
    ...connection,
    headers: { ...connection.headers, Authorization: "Bearer foobar" },
  });
  typia.assert(respGarbage);
  TestValidator.equals("invalid: garbage token")(respGarbage.valid)(false);
  TestValidator.equals("no customer: garbage token")(respGarbage.customer)(undefined);

  // 3. Expired JWT (fake JWT structure with expired timestamp)
  // NOTE: True expired JWT would be created by real test infra; for now use well-structured but expired sample
  const expiredJwt =
    "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJleHAiOjEwMDAwLCJpYXQiOjE1MTYyMzkwMjJ9.signature";
  const respExpired = await api.functional.auth.customer.validate.validateToken({
    ...connection,
    headers: { ...connection.headers, Authorization: `Bearer ${expiredJwt}` },
  });
  typia.assert(respExpired);
  TestValidator.equals("invalid: expired JWT")(respExpired.valid)(false);
  TestValidator.equals("no customer: expired JWT")(respExpired.customer)(undefined);

  // 4. Tampered (corrupted) JWT: take expired JWT, change last character
  const tamperedJwt = expiredJwt.slice(0, -1) + "x";
  const respTampered = await api.functional.auth.customer.validate.validateToken({
    ...connection,
    headers: { ...connection.headers, Authorization: `Bearer ${tamperedJwt}` },
  });
  typia.assert(respTampered);
  TestValidator.equals("invalid: tampered JWT")(respTampered.valid)(false);
  TestValidator.equals("no customer: tampered JWT")(respTampered.customer)(undefined);
}

