/**
 * Test successful password change for an authenticated customer.
 *
 * This test verifies that an authenticated customer can successfully change their account password using the API by providing the correct current password and a new strong password.
 *
 * Business context: Password changes are an essential operation for secure account management. The test ensures the API correctly enforces credential checking, password policies, resets JWT session on success, and records a password change audit event (customer_histories compliance).
 *
 * Steps:
 * 1. Register a new customer with unique credentials (email, password, etc.)
 * 2. Login to obtain a valid session (JWT Authorization header set)
 * 3. Perform a password change by specifying the original (current) password and a new strong password
 * 4. Assert that password change is successful per API response
 * 5. Assert that JWT session is reset (token likely changes after password change)
 * 6. Attempt login with the new password to verify the update
 * 7. Attempt login with the old password should fail (optional, if error-throwing logic is allowed)
 */
export async function test_api_customer_change_password_success(
  connection: api.IConnection,
) {
  // Step 1: Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const oldPassword = "OldPassword123!";
  const signUpRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: oldPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(10),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(signUpRes);

  // Step 2: Login to obtain a session JWT
  const signInRes = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: oldPassword
    } satisfies ICustomerSignIn.Request
  });
  typia.assert(signInRes);
  const firstToken = signInRes.setHeaders.Authorization;

  // Step 3: Change password with correct current password
  const newPassword = "NewStrongPassword456!";
  const changeRes = await api.functional.auth.customer.password.changePassword(connection, {
    body: {
      currentPassword: oldPassword,
      newPassword: newPassword
    } satisfies ICustomerChangePassword.Request
  });
  typia.assert(changeRes);
  TestValidator.equals("password change success")(changeRes.success)(true);

  // Step 4: JWT session should be reset (token changes after password update)
  // To verify, log in with the new password (token must differ)
  const afterChangeSignInRes = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: newPassword
    } satisfies ICustomerSignIn.Request
  });
  typia.assert(afterChangeSignInRes);
  const secondToken = afterChangeSignInRes.setHeaders.Authorization;
  TestValidator.notEquals("JWT token should be reset after password change")(firstToken)(secondToken);

  // Step 5: Optional - Old password should no longer work
  await TestValidator.error("old password should not work after change")(() =>
    api.functional.auth.customer.login.signIn(connection, {
      body: {
        email: customerEmail,
        password: oldPassword
      } satisfies ICustomerSignIn.Request
    })
  );
}

