import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerChangePassword } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerChangePassword";

/**
 * Validate password change failure when current password is incorrect for customers.
 *
 * Business context: Customers should not be able to change their password unless providing the valid current password. The operation must fail, clearly indicate failure, and the session/JWT must remain valid so that no forced logout occurs due to this logic error.
 *
 * Step-by-step process:
 * 1. Register a new customer (using unique email, password, and required properties)
 * 2. Attempt to change password using an incorrect current password (different from sign-up password)
 * 3. Validate that the API returns success: false, provides an error message, and that the session/JWT is not invalidated (another operation is still permitted afterwards)
 * 4. Try an additional call with another wrong password to confirm session is still active
 */
export async function test_api_customer_change_password_incorrect_current(
  connection: api.IConnection,
) {
  // 1. Register a new customer for fresh test data
  const uniqueEmail = typia.random<string & tags.Format<"email">>();
  const signUpPassword = "Password123@";
  const signUpOutput = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: uniqueEmail,
      password: signUpPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(10),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpOutput);

  // 2. Attempt to change password with an incorrect current password
  const fakeOldPassword = signUpPassword + "-WRONG";
  const response = await api.functional.auth.customer.password.changePassword(connection, {
    body: {
      currentPassword: fakeOldPassword,
      newPassword: "AnotherPassword!456",
    } satisfies ICustomerChangePassword.Request,
  });
  typia.assert(response);
  TestValidator.equals("password not changed success")(response.success)(false);
  TestValidator.predicate("error message present")(typeof response.message === "string" && response.message.length > 0);

  // 3. The session must remain active: try another change with a different wrong password
  const stillValid = await api.functional.auth.customer.password.changePassword(connection, {
    body: {
      currentPassword: "completely-wrong-password!!!!",
      newPassword: "NewerPassword!789",
    } satisfies ICustomerChangePassword.Request,
  });
  typia.assert(stillValid);
  TestValidator.equals("session not broken on failed change")(stillValid.success)(false);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICustomerChangePassword } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerChangePassword";

/**
 * Validate that the password change operation is denied if unauthenticated.
 *
 * Ensures the /auth/customer/password endpoint rejects attempts to change a customer's password when no valid authentication (JWT) is provided. This covers both the complete absence of the Authorization header and the use of an invalid/bogus token. The API should return permission errors or failure responses, and NOT perform any password update.
 *
 * Steps:
 * 1. Prepare a valid password change request body (random current and new password)
 * 2. Attempt to call the endpoint WITHOUT any Authorization header — must fail
 * 3. Attempt to call with a syntactically valid but bogus token — must fail
 * 4. Validate (a) failure responses, and (b) that an error is thrown (unauthorized)
 */
export async function test_api_customer_change_password_unauthenticated(
  connection: api.IConnection,
) {
  // 1. Prepare a plausible password change body
  const body: ICustomerChangePassword.Request = {
    currentPassword: RandomGenerator.alphaNumeric(10),
    newPassword: RandomGenerator.alphaNumeric(12),
  };

  // 2. Try with NO authentication (header omitted)
  await TestValidator.error("unauthenticated password change must fail")(
    async () => {
      const unauthConnection = {
        ...connection,
        headers: {
          ...connection.headers,
        },
      };
      await api.functional.auth.customer.password.changePassword(unauthConnection, { body });
    },
  );

  // 3. Try with an invalid/bogus JWT
  await TestValidator.error("invalid token password change must fail")(
    async () => {
      const bogusConnection = {
        ...connection,
        headers: {
          ...connection.headers,
          Authorization: "Bearer invalid.jwt.token",
        },
      };
      await api.functional.auth.customer.password.changePassword(bogusConnection, { body });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates admin registration functionality via POST /auth/admin/register.
 *
 * This test ensures that a new admin can register using a unique, valid email
 * address and a compliant password. Upon successful registration, the platform
 * must return a JWT, the new admin's profile, and set HTTP headers for
 * client-side JWT authentication (Authorization header), as well as create
 * required server-side audit logs.
 *
 * Steps:
 * 1. Generate a unique, valid admin email and a compliant password.
 * 2. Call the registration endpoint with these credentials.
 * 3. Assert that the response contains:
 *    - JWT token string (in the jwt field)
 *    - adminId (uuid format)
 *    - email matches what was registered
 *    - name, role, and status fields are set (per business policy; likely default)
 *    - setHeaders.Authorization is present and matches/begins with jwt
 * 4. Verify the returned adminId and email are correctly formatted.
 * 5. (If possible given system) Validate that audit logs are written (not implemented here unless API exposes it).
 * 6. Ensure no other admin exists with the same email (out of scope for this single register test, but consider duplicate registration in a separate case).
 */
export async function test_api_admin_registration_success(connection: api.IConnection) {
  // 1. Generate unique, valid email and password
  const email: string = typia.random<string & tags.Format<"email">>();
  const password: string = RandomGenerator.alphaNumeric(12);

  // 2. Register new admin
  const output: IAdminAuth.JwtWithProfile = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(output);

  // 3. Assert JWT and adminId are issued and correctly formatted
  TestValidator.predicate("jwt must be non-empty string")(typeof output.jwt === "string" && output.jwt.length > 0);
  TestValidator.predicate("adminId is uuid format")(/^[0-9a-fA-F-]{36}$/.test(output.adminId));
  TestValidator.equals("registered email matches")(output.email)(email);

  // 4. Assert setHeaders.Authorization is present and contains the JWT
  TestValidator.predicate("Authorization header set")(typeof output.setHeaders?.Authorization === "string" && output.setHeaders.Authorization.includes(output.jwt));

  // 5. Assert profile properties (name, role, status) are strings
  TestValidator.predicate("name is non-empty string")(typeof output.name === "string" && output.name.length > 0);
  TestValidator.predicate("role is non-empty string")(typeof output.role === "string" && output.role.length > 0);
  TestValidator.predicate("status is non-empty string")(typeof output.status === "string" && output.status.length > 0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate duplicate admin registration prevention.
 *
 * This test ensures that attempting to register an admin with an email address that already exists in the system fails as expected.
 * It enforces the unique constraint policy on admin emails. No new account or JWT should be created when a duplicate registration is attempted.
 *
 * Business Context:
 * Email uniqueness is critical to platform security and proper RBAC administration. This prevents accidental or malicious admin account collisions.
 *
 * Workflow:
 * 1. Register an admin with a random, valid business email and password.
 * 2. Attempt to register a second admin using the same email but a different password.
 * 3. Validate that the second registration attempt throws an error (unique constraint violation) and that no new JWT or account is issued.
 *
 * Edge Cases:
 * - Ensure the error arises from the registration call and is not due to type or input validation errors.
 */
export async function test_api_admin_registration_duplicate_email(
  connection: api.IConnection,
) {
  // 1. Register the initial admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const passwordA = "PasswordA#1234";
  const firstAdmin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: passwordA,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(firstAdmin);
  TestValidator.equals("admin email matches")(firstAdmin.email)(adminEmail);

  // 2. Attempt duplicate registration with the same email but different password
  const passwordB = "PasswordB#5678";
  await TestValidator.error("duplicate admin registration must fail")(
    async () => {
      await api.functional.auth.admin.register.signUp(connection, {
        body: {
          email: adminEmail,
          password: passwordB,
        } satisfies IAdminAuth.SignUp,
      });
    },
  );
}

