 *
 * Business context:
 * This test verifies that a seller can successfully delete their own KYC/compliance business verification document (such as uploading and then removing a business registration/license). The workflow also validates correct onboarding, document upload, authentication and secure deletion, as well as ensuring the deleted resource becomes inaccessible. This guarantees proper audit-logging and regulatory compliance.
 *
 * Step-by-step process:
 * 1. Register a new seller with valid information (for onboarding/KYC).
 * 2. Authenticate as the seller to obtain a valid JWT/session.
 * 3. Create a business verification record (representing a document such as business license).
 * 4. Delete the business verification record as the seller (using correct IDs).
 * 5. (Not implementable: attempt to fetch the deleted record, audit log validation) No fetch endpoint is exposed for individual verifications or audit logs, so cannot check their post-deletion state.
 */
export async function test_api_seller_business_verification_delete_success(
  connection: api.IConnection,
) {
  // 1. Register a new seller
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const signUpRequest: ISellerAuth.SignUp = {
    email: sellerEmail,
    password: "Secure1234!",
    companyName: RandomGenerator.alphaNumeric(10),
    businessNumber: RandomGenerator.alphaNumeric(10),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.alphaNumeric(12),
    phone: RandomGenerator.mobile(),
  };
  const sellerSignUp = await api.functional.auth.seller.register.signUp(
    connection,
    { body: signUpRequest },
  );
  typia.assert(sellerSignUp);

  // 2. Seller authenticates (login)
  const sellerLogin = await api.functional.auth.seller.login.signIn(
    connection,
    {
      body: {
        email: signUpRequest.email,
        password: signUpRequest.password,
      },
    },
