import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendChannel";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductChannelMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductChannelMap";

/**
 * Validate the admin update of a product-channel mapping.
 *
 * This scenario ensures that an admin can:
 *   1. Create a new channel (for cross-exposure or business partitioning)
 *   2. Create a new product (with seller reference and display properties)
 *   3. Map the just-created product to the just-created channel by establishing a product-channel mapping
 *   4. Update mutable mapping attributes (such as status field)
 *   5. Validate that updated mapping attributes are correctly reflected in the response
 *
 * Steps:
 *   - Step 1: Create a channel with required core details (unique code and admin ID, plus enabled state)
 *   - Step 2: Create a product referring to a seller (simulated via random UUID for this test, since seller entity is not covered here), and with mock code, display name, and status
 *   - Step 3: Map the product to the channel creating an initial mapping, optionally using an initial status (e.g., 'active')
 *   - Step 4: Update the mapping via the update endpoint, mutating the status (e.g., set to 'inactive' or another string different than original)
 *   - Step 5: Validate that the response accurately reflects new mapping values (esp. check new status, and mapping IDs didn't change)
 *   - Step 6: Optionally check timestamp update (updated_at > created_at)
 */
export async function test_api_product_channel_map_update_successful(connection: api.IConnection) {
  // 1. Create a new admin channel (with business-unique code and required admin fields)
  const adminId: string = typia.random<string & tags.Format<"uuid">>();
  const channelInput: IShoppingMallAiBackendChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.name(),
    created_by_admin_id: adminId,
    description: RandomGenerator.paragraph()(),
    logo_url: null,
    active: true,
  };
  const channel = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, { body: channelInput });
  typia.assert(channel);

  // 2. Create a new product, referencing this (mock) seller and required code at minimum
  const productInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    main_image_uri: null,
    status: "draft",
  };
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, { body: productInput });
  typia.assert(product);

  // 3. Map the product to the channel
  const mapInput: IShoppingMallAiBackendProductChannelMap.ICreate = {
    product_id: product.id,
    channel_id: channel.id,
    status: "active",
  };
  const mapping = await api.functional.shoppingMallAiBackend.admin.products.productChannelMap.createProductChannelMap(connection, {productId: product.id, body: mapInput});
  typia.assert(mapping);

  // 4. Update the mapping's status to another string (e.g. 'inactive')
  const updateInput: IShoppingMallAiBackendProductChannelMap.IUpdate = {
    status: "inactive",
  };
  const updated = await api.functional.shoppingMallAiBackend.admin.products.productChannelMap.updateProductChannelMap(connection, {
    productId: product.id,
    productChannelMapId: mapping.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 5. Assertions: mapping ID unchanged, status value updated, product/channel ref unchanged, timestamps reasonable
  TestValidator.equals("Mapping ID should remain")(updated.id)(mapping.id);
  TestValidator.equals("Product ID unchanged")(updated.product_id)(mapping.product_id);
  TestValidator.equals("Channel ID unchanged")(updated.channel_id)(mapping.channel_id);
  TestValidator.notEquals("Status changed")(updated.status)(mapping.status);
  TestValidator.equals("Status equals 'inactive'")(updated.status)("inactive");
  TestValidator.predicate("Updated after created")(new Date(updated.updated_at).getTime() >= new Date(updated.created_at).getTime());
}

