/**
 * Validate creation of point wallet transaction histories as admin with audit, business rule, and error checks.
 *
 * Business context:
 * - Admin must be able to create point wallet histories (manual, accrual, etc.) for existing wallets.
 * - Transaction should reference a valid wallet and update audit fields appropriately.
 * - Creation must fail if required fields are missing/invalid or if wallet does not exist.
 * - Attempting duplicate creation or out-of-bounds adjustments must raise clear errors.
 *
 * Test steps:
 * 1. Create a customer point wallet as a prerequisite for point histories.
 * 2. Create a valid transaction history for the wallet and validate audit fields.
 * 3. Test invalid input (non-existent point wallet).
 * 4. Test missing required fields (should error at runtime only).
 * 5. Test duplicate transaction input (should error or prevent creation under business rule).
 * 6. Test out-of-bounds point balance adjustment (negative balances should error).
 */
export async function test_api_point_history_creation_success_and_duplicate_validation(
  connection: api.IConnection,
) {
  // 1. Create a point wallet (admin privilege required)
  const walletInput: IShoppingMallAiBackendPoint.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    balance: 1000,
  };
  const wallet = await api.functional.shoppingMallAiBackend.admin.points.create(connection, { body: walletInput });
  typia.assert(wallet);

  // 2. Create valid point history (manual adjustment by admin)
  const actor_admin_id = typia.random<string & tags.Format<"uuid">>();
  const historyInput: IShoppingMallAiBackendPointHistory.ICreate = {
    point_wallet_id: wallet.id,
    change_type: "manual",
    change_amount: 200,
    balance_after: wallet.balance + 200,
    actor_type: "admin",
    actor_id: actor_admin_id,
  };
  const history = await api.functional.shoppingMallAiBackend.admin.pointHistories.create(connection, { body: historyInput });
  typia.assert(history);
  // Audit/field checks
  TestValidator.equals("wallet link")(history.point_wallet_id)(wallet.id);
  TestValidator.equals("amount")(history.change_amount)(200);
  TestValidator.equals("change type")(history.change_type)("manual");
  TestValidator.equals("actor type")(history.actor_type)("admin");
  TestValidator.equals("balance after")(history.balance_after)(wallet.balance + 200);
  TestValidator.predicate("actor_id is uuid")(typeof history.actor_id === "string" && history.actor_id.length > 0);
  TestValidator.predicate("created_at is date-time")(!!Date.parse(history.created_at));

  // 3. Error: Use non-existent wallet for point history
  const fakeWalletId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent wallet reference")(() =>
    api.functional.shoppingMallAiBackend.admin.pointHistories.create(connection, {
      body: {
        ...historyInput,
        point_wallet_id: fakeWalletId,
      },
    }),
  );

  // 4. Error: Missing required field (change_amount)
  await TestValidator.error("missing change_amount")(() =>
    api.functional.shoppingMallAiBackend.admin.pointHistories.create(connection, {
      body: {
        point_wallet_id: wallet.id,
        change_type: "manual",
        balance_after: wallet.balance + 200,
        actor_type: "admin",
        actor_id: typia.random<string & tags.Format<"uuid">>(),
        // change_amount intentionally omitted
      } as any,
    }),
  );

  // 5. Error: Attempt duplicate
  await TestValidator.error("duplicate transaction")(() =>
    api.functional.shoppingMallAiBackend.admin.pointHistories.create(connection, {
      body: historyInput,
    }),
  );

  // 6. Error: Out-of-bounds adjustment (negative balance)
  await TestValidator.error("out-of-bounds adjustment")(() =>
    api.functional.shoppingMallAiBackend.admin.pointHistories.create(connection, {
      body: {
        point_wallet_id: wallet.id,
        change_type: "manual",
        change_amount: -9999999,
        balance_after: -9998999,
        actor_type: "admin",
        actor_id: typia.random<string & tags.Format<"uuid">>(),
      },
    }),
  );
}

