 *
 * This test simulates an admin updating a point transaction record. It covers:
 * 1. Creating a point wallet for a synthetic customer.
 * 2. Creating a point wallet history/transaction for that wallet.
 * 3. Performing a valid update to the remarks/audit field.
 * 4. Attempting to update a non-existent record (should error out).
 *
 * Steps:
 * 1. Generate synthetic customer UUID.
 * 2. Admin creates a new point wallet for that customer.
 * 3. Admin creates an initial point history record associated with above wallet.
 * 4. Admin successfully updates the remarks for that point history. Validate that the remarks field changes and other business fields are unchanged after update.
 * 5. Try to update a non-existent pointHistoryId. Assert error is thrown (runtime check only).
 */
export async function test_api_point_history_update_metadata_and_audit_logging(
  connection: api.IConnection,
) {
  // 1. Generate synthetic customer UUID
  const customerId = typia.random<string & tags.Format<"uuid">>();

  // 2. Admin creates a new point wallet for the customer
  const wallet = await api.functional.shoppingMallAiBackend.admin.points.create(connection, {
    body: {
      customer_id: customerId,
      balance: 0,
    } satisfies IShoppingMallAiBackendPoint.ICreate,
  });
  typia.assert(wallet);

  // 3. Admin creates a point history record for the wallet
  const history = await api.functional.shoppingMallAiBackend.admin.pointHistories.create(connection, {
