  // All business fields except mutable remarks/created_at must be unchanged
  TestValidator.equals("immutable business fields remain")({ ...updated, remarks: undefined, created_at: undefined })({ ...history, remarks: undefined, created_at: undefined });

  // 5. Attempt update to non-existent pointHistoryId (should throw error)
  await TestValidator.error("non-existent pointHistoryId should error")(
