import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendPoint";
import type { IShoppingMallAiBackendPointHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendPointHistory";

/**
 * Validate compliance of soft-delete logic for point wallet transaction history (admin-only).
 *
 * This test ensures that an admin can soft-delete a point wallet transaction (history) and that the correct compliance behavior is triggered:
 *
 * 1. Create a customer point wallet.
 * 2. Add a transaction history to the wallet.
 * 3. Soft-delete the transaction history by pointHistoryId as admin (should mark as deleted, not remove row).
 * 4. Re-attempt to delete the same pointHistoryId (should error or be idempotent no-op).
 * 5. Attempt to delete a random, non-existent pointHistoryId (should error as not found).
 * 6. Confirm that all steps follow audit/compliance expectations (by no error and correct state transitions).
 *
 * Note: SDK does not support querying actives directly, so presence/absence in active set is not verified.
 */
export async function test_api_point_history_soft_delete_compliance(connection: api.IConnection) {
  // 1. Create point wallet for a customer
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const wallet = await api.functional.shoppingMallAiBackend.admin.points.create(connection, {
    body: {
      customer_id: customerId,
      balance: 1000,
    } satisfies IShoppingMallAiBackendPoint.ICreate,
  });
  typia.assert(wallet);

  // 2. Add a transaction history to the wallet
  const tx = await api.functional.shoppingMallAiBackend.admin.pointHistories.create(connection, {
    body: {
      point_wallet_id: wallet.id,
      change_type: "accrual",
      change_amount: 100,
      balance_after: 1100,
      actor_type: "admin",
      actor_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IShoppingMallAiBackendPointHistory.ICreate,
  });
  typia.assert(tx);

  // 3. Soft-delete this point history transaction by id (valid case)
  await api.functional.shoppingMallAiBackend.admin.pointHistories.erase(connection, {
    pointHistoryId: tx.id,
  });
  // Success if no error thrown

  // 4. TRY: Soft-delete same history again (should error or be a safe no-op)
  await TestValidator.error("Delete already deleted pointHistoryId should error or be idempotent")(() =>
    api.functional.shoppingMallAiBackend.admin.pointHistories.erase(connection, {
      pointHistoryId: tx.id,
    })
  );

  // 5. TRY: Delete a non-existent pointHistoryId (simulate with random uuid)
  await TestValidator.error("Delete non-existent pointHistoryId should error")(() =>
    api.functional.shoppingMallAiBackend.admin.pointHistories.erase(connection, {
      pointHistoryId: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductContent";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate product content detail access and authorization.
 *
 * This test verifies that a seller can correctly fetch detailed information about a specific content (such as an image, video, or document) for a product they own, and that forbidden or not-found errors are returned when an unrelated seller or unauthenticated party attempts access.
 *
 * Workflow:
 * 1. Register seller (sellerA) and acquire JWT
 * 2. Authenticate as sellerA
 * 3. Create a product as sellerA
 * 4. Add content (e.g., image) to the product as sellerA
 * 5. Retrieve the product content detail as sellerA (expect full fields)
 * 6. Register and authenticate sellerB
 * 7. Attempt detail access as sellerB (expect forbidden or not-found error)
 * 8. Clear authentication (simulate anonymous)
 * 9. Attempt detail access unauthenticated (expect unauthorized error)
 */
export async function test_api_product_content_detail_access_and_authorization(connection: api.IConnection) {
  // 1. Register sellerA and get JWT
  const sellerA_signup = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Sellera@12345!",
      companyName: RandomGenerator.alphaNumeric(12),
      businessNumber: "1000000001",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(16),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerA_signup);
  TestValidator.predicate("jwt issued for sellerA")(typeof sellerA_signup.jwt === "string" && sellerA_signup.jwt.length > 0);

  // 2. Set sellerA JWT in connection
  connection.headers = { ...connection.headers, Authorization: sellerA_signup.setHeaders.Authorization };

  // 3. Create product as sellerA
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerA_signup.sellerId,
      code: RandomGenerator.alphaNumeric(14),
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
      main_image_uri: `https://images.cdn.com/${RandomGenerator.alphaNumeric(12)}.jpg`,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 4. Add content to the product as sellerA
  const content = await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      content_type: "main_image",
      content_uri: `https://content.cdn.com/${RandomGenerator.alphaNumeric(15)}.jpg`,
      content_order: 0,
      content_description: "Main product showcase image",
      status: "active",
    } satisfies IShoppingMallAiBackendProductContent.ICreate,
  });
  typia.assert(content);

  // 5. SellerA fetches product content detail (should succeed)
  const detail = await api.functional.shoppingMallAiBackend.seller.products.productContents.at(connection, {
    productId: product.id,
    productContentId: content.id,
  });
  typia.assert(detail);
  TestValidator.equals("content id matches")(detail.id)(content.id);
  TestValidator.equals("product id matches")(detail.product_id)(product.id);
  TestValidator.equals("content uri matches")(detail.content_uri)(content.content_uri);
  TestValidator.equals("content type matches")(detail.content_type)(content.content_type);
  TestValidator.equals("content order matches")(detail.content_order)(content.content_order);
  TestValidator.equals("status matches")(detail.status)(content.status);

  // 6. Register sellerB and switch JWT
  const sellerB_signup = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Sellerb@67890!",
      companyName: RandomGenerator.alphaNumeric(11),
      businessNumber: "2000000002",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(17),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerB_signup);
  TestValidator.predicate("jwt issued for sellerB")(typeof sellerB_signup.jwt === "string" && sellerB_signup.jwt.length > 0);

  // Switch to sellerB JWT
  connection.headers = { ...connection.headers, Authorization: sellerB_signup.setHeaders.Authorization };

  // 7. SellerB tries to fetch sellerA's product content (should fail: forbidden or not found)
  await TestValidator.error("non-owner seller cannot fetch product content")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productContents.at(connection, {
      productId: product.id,
      productContentId: content.id,
    });
  });

  // 8. Remove Authorization to simulate anonymous
  connection.headers = { ...connection.headers };
  delete connection.headers.Authorization;
  // 9. Unauthenticated fetch (should fail: unauthorized)
  await TestValidator.error("unauthenticated access denied")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productContents.at(connection, {
      productId: product.id,
      productContentId: content.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductContent";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate admin access control for fetching product content detail.
 *
 * Business context:
 * This test ensures that an admin is able to fetch the complete detail of a product content by specifying both a valid productId and productContentId, only after the content is legitimately created by a seller. It also verifies handling of invalid/mismatched IDs. Simulating fetch of a soft-deleted content is not possible here as there's no delete/soft-delete endpoint for content.
 *
 * Steps:
 * 1. Register an admin account.
 * 2. Register a seller account (for product/content creation).
 * 3. Seller creates a product.
 * 4. Seller creates a product content attached to the product.
 * 5. Admin fetches the product content detail by correct IDs, verifies content fields match what seller created.
 * 6. Admin attempts to fetch content with:
 *    a) Invalid productId
 *    b) Invalid productContentId
 *    and asserts not found errors occur.
 */
export async function test_api_product_content_detail_admin_access_control(
  connection: api.IConnection,
) {
  // 1. Register admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPW" + typia.random<string>().substring(0, 8);
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);
  // Apply Authorization header for admin (client auto-handles setHeaders)

  // 2. Register a seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "sellerPW" + typia.random<string>().substring(0, 8);
  const seller = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: "TestCompany" + typia.random<string>().substring(0, 4),
      businessNumber: "" + (1000000000 + Math.floor(Math.random() * 100000000)).toString(),
      representativeName: "SellerRep" + typia.random<string>().substring(0, 3),
      address: "123 Market St, Test City", // arbitrary valid
      phone: "010" + Math.floor(10000000 + Math.random() * 90000000).toString(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(seller);
  // Apply Authorization header for seller (client auto-handles setHeaders)

  // 3. Seller creates a product
  const productReq: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: seller.sellerId,
    code: "SKU" + typia.random<string>().substring(0, 6),
    name: "Test Product " + typia.random<string>().substring(0, 5),
    description: "A test product for admin access E2E", // valid
    main_image_uri: "https://cdn.example.com/product/" + typia.random<string & tags.Format<"uuid">>(),
    status: "draft", // Accepts arbitrary status per schema doc
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: productReq,
  });
  typia.assert(product);

  // 4. Seller creates product content
  const contentReq: IShoppingMallAiBackendProductContent.ICreate = {
    product_id: product.id,
    content_type: "main_image", // valid per documentation
    content_uri: "https://cdn.example.com/product/content/" + typia.random<string & tags.Format<"uuid">>(),
    content_order: 0,
    content_description: "Main image for product", // optional
    status: "active", // active/hidden/pending etc
  };
  const content = await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
    productId: product.id,
    body: contentReq,
  });
  typia.assert(content);

  // 5. Admin fetches product content (should succeed, verify all fields)
  const fetchedContent = await api.functional.shoppingMallAiBackend.admin.products.productContents.at(connection, {
    productId: product.id,
    productContentId: content.id,
  });
  typia.assert(fetchedContent);
  // Essential field validations
  TestValidator.equals("content id matches")(fetchedContent.id)(content.id);
  TestValidator.equals("product_id matches")(fetchedContent.product_id)(product.id);
  TestValidator.equals("content type matches")(fetchedContent.content_type)(contentReq.content_type);
  TestValidator.equals("content uri matches")(fetchedContent.content_uri)(contentReq.content_uri);
  TestValidator.equals("content_order matches")(fetchedContent.content_order)(contentReq.content_order);
  TestValidator.equals("status matches")(fetchedContent.status)(contentReq.status);
  TestValidator.equals("content_description matches")(fetchedContent.content_description)(contentReq.content_description);
  // dates and deleted_at, created_at etc. are not further checked here as they are auto-managed

  // 6a. Attempt fetch with invalid productId
  const invalidProductId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("fetch with non-existent productId should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productContents.at(connection, {
      productId: invalidProductId,
      productContentId: content.id,
    });
  });

  // 6b. Attempt fetch with invalid productContentId
  const invalidContentId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("fetch with non-existent product content id should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productContents.at(connection, {
      productId: product.id,
      productContentId: invalidContentId,
    });
  });

  // 7. Soft-delete test omitted (no delete/disable endpoint provided)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductContent";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test creation and validation of product content creation by a seller.
 *
 * This test simulates a complete business workflow: a seller is registered, a product is created, and product content (e.g., an image or video) is added. The test verifies both successful creation and rejects invalid content submissions.
 *
 * Step-by-step process:
 * 1. Register a new seller and obtain authentication
 * 2. Create a product as the authenticated seller
 * 3. Create product content (main_image) for this product with valid required fields
 * 4. Assert that the product content is created correctly with all fields
 * 5. Test error: missing required field (content_type omitted)
 * 6. Test error: invalid content_type value
 * 7. Test error: malformed content_uri
 * 8. Test error: creating content with duplicate order for same product (should fail by business rule)
 */
export async function test_api_product_content_creation_and_validation(
  connection: api.IConnection,
) {
  // 1. Register as a new seller (returns JWT, sellerId)
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const signUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "TestPassword1234$",
      companyName: RandomGenerator.name(),
      businessNumber: ArrayUtil.repeat(10)(() => String(typia.random<number>())).join("") ,
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResp);

  // Attach seller's JWT to connection for authenticated calls
  connection.headers = {
    ...connection.headers,
    Authorization: signUpResp.setHeaders.Authorization,
  };
  const sellerId = signUpResp.sellerId;

  // 2. Create a product
  const productResp = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      main_image_uri: null,
      status: "draft",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productResp);

  // 3. Create valid product content
  const productId = productResp.id;
  const content_order = typia.random<number & tags.Type<"int32">>();
  const validContent = await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
    productId,
    body: {
      product_id: productId,
      content_type: "main_image",
      content_uri: "https://cdn.example.com/product-images/" + RandomGenerator.alphaNumeric(10),
      content_order,
      content_description: RandomGenerator.paragraph()(),
      status: "active",
    } satisfies IShoppingMallAiBackendProductContent.ICreate,
  });
  typia.assert(validContent);
  TestValidator.equals("product id matches")(validContent.product_id)(productId);
  TestValidator.equals("content type matches")(validContent.content_type)("main_image");
  TestValidator.equals("order matches")(validContent.content_order)(content_order);
  TestValidator.equals("status matches")(validContent.status)("active");

  // 4. Error: missing required field (content_type omitted)
  await TestValidator.error("missing content_type should fail")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
      productId,
      body: {
        product_id: productId,
        // content_type: omitted intentionally
        content_uri: "https://cdn.example.com/xmissingtype/" + RandomGenerator.alphaNumeric(8),
        content_order: typia.random<number & tags.Type<"int32">>(),
        content_description: RandomGenerator.paragraph()(),
        status: "active",
      } as any, // Only for test: force TS to allow omission
    });
  });

  // 5. Error: invalid content_type value
  await TestValidator.error("invalid content_type")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
      productId,
      body: {
        product_id: productId,
        content_type: "INVALID_TYPE",
        content_uri: "https://cdn.example.com/invalidtype/" + RandomGenerator.alphaNumeric(8),
        content_order: typia.random<number & tags.Type<"int32">>(),
        content_description: RandomGenerator.paragraph()(),
        status: "active",
      } satisfies IShoppingMallAiBackendProductContent.ICreate,
    });
  });

  // 6. Error: malformed content_uri
  await TestValidator.error("malformed content_uri")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
      productId,
      body: {
        product_id: productId,
        content_type: "main_image",
        content_uri: "not_a_uri",
        content_order: typia.random<number & tags.Type<"int32">>(),
        content_description: RandomGenerator.paragraph()(),
        status: "active",
      } satisfies IShoppingMallAiBackendProductContent.ICreate,
    });
  });

  // 7. Error: duplicate content_order for same product
  await TestValidator.error("duplicate content_order for same product")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
      productId,
      body: {
        product_id: productId,
        content_type: "gallery_image",
        content_uri: "https://cdn.example.com/duporder/" + RandomGenerator.alphaNumeric(8),
        content_order, // duplicate order
        content_description: RandomGenerator.paragraph()(),
        status: "active",
      } satisfies IShoppingMallAiBackendProductContent.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductContent";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate admin creation and error handling for product content records.
 *
 * This test verifies that an admin can successfully create new product content for an existing product, checks correct field association, and covers key error cases:
 *  - Creation for a non-existent product (should fail with not found)
 *  - Creation with an invalid value (e.g., content_type) (should trigger validation error)
 *
 * Steps:
 * 1. Register an admin and seller account
 * 2. Seller creates a product for use as parent
 * 3. Admin creates product content for the product (happy path)
 * 4. Validate output and association
 * 5. Attempt content creation for a non-existent product (expect error)
 * 6. Attempt creation with an invalid content_type (expect error)
 */
export async function test_api_product_content_creation_by_admin_error_handling(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin!234";
  const adminRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(adminRes);

  // 2. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Seller!123";
  const sellerRes = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: "Test Seller Co.",
      businessNumber: "1234567890",
      representativeName: "John Seller",
      address: "123 Main St, City, Country",
      phone: "010-5555-5555"
    }
  });
  typia.assert(sellerRes);

  // 3. Seller creates a product
  const productInput = {
    seller_id: sellerRes.sellerId,
    code: "SKU-" + typia.random<string>(),
    name: "Product for Content Test",
    description: "A sample product for product content E2E test.",
    main_image_uri: null,
    status: "pending"
  } satisfies IShoppingMallAiBackendProduct.ICreate;
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: productInput });
  typia.assert(product);

  // 4. Admin creates product content for the product
  const contentInput = {
    product_id: product.id,
    content_type: "main_image",
    content_uri: "https://cdn.example.com/image1.png",
    content_order: 0,
    content_description: "Main product image",
    status: "active"
  } satisfies IShoppingMallAiBackendProductContent.ICreate;
  const productContent = await api.functional.shoppingMallAiBackend.admin.products.productContents.create(connection, {
    productId: product.id,
    body: contentInput
  });
  typia.assert(productContent);
  TestValidator.equals("content association")(productContent.product_id)(product.id);
  TestValidator.equals("content type")(productContent.content_type)(contentInput.content_type);
  TestValidator.equals("status")(productContent.status)(contentInput.status);
  TestValidator.equals("content order")(productContent.content_order)(contentInput.content_order);
  TestValidator.equals("description")(productContent.content_description)(contentInput.content_description);

  // 5. Error: Create content for non-existent product (should fail)
  const bogusId = typia.random<string & tags.Format<"uuid">>();
  const fakeContentInput = { ...contentInput, product_id: bogusId };
  await TestValidator.error("non-existent product")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productContents.create(connection, {
      productId: bogusId,
      body: fakeContentInput
    });
  });

  // 6. Error: Invalid content_type (not a platform-constrained value, runtime error)
  await TestValidator.error("invalid content_type")(async () => {
    const invalidContentInput = {
      ...contentInput,
      content_type: "invalid_type"
    } satisfies IShoppingMallAiBackendProductContent.ICreate;
    await api.functional.shoppingMallAiBackend.admin.products.productContents.create(connection, {
      productId: product.id,
      body: invalidContentInput
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductContent";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate updating an existing product content by the owner seller, and business/permission enforcement.
 *
 * This test covers:
 * 1. Register seller A
 * 2. Seller A creates a product
 * 3. Seller A adds product content (record initial values)
 * 4. Seller A updates content (change content_type, description, status)
 *    - Validate response reflects changes
 * 5. Attempt update as another seller (Seller B) – expect permission denial (error)
 * 6. Attempt update with invalid values (e.g. missing required, nonsense content_type, content_order negative)
 *    - Expect schema/business validation errors
 * 7. Soft-delete content (simulate by updating content's deleted_at if API allowed, else skip)
 *    - Attempt update after deletion, expect not found/error
 *
 * All steps assert correct type and expected business logic.
 */
export async function test_api_product_content_update_and_permissions(connection: api.IConnection) {
  // 1. Register seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "TestPassword1!",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerAReg);
  const sellerAId = sellerAReg.sellerId;

  // 2. Seller A creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "draft",
    },
  });
  typia.assert(product);
  const productId = product.id;

  // 3. Seller A adds a product content entity
  const contentCreateBody = {
    product_id: productId,
    content_type: "gallery_image",
    content_uri: "https://cdn.example.com/img1.jpg",
    content_order: 0,
    content_description: "Initial main image for product",
    status: "active",
  };
  const content = await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
    productId,
    body: contentCreateBody,
  });
  typia.assert(content);

  // 4. Seller A issues a valid update to the content
  const updateBody = {
    content_type: "main_image",
    content_description: "Changed to main image, updated text",
    status: "pending",
  };
  const updatedContent = await api.functional.shoppingMallAiBackend.seller.products.productContents.update(connection, {
    productId,
    productContentId: content.id,
    body: updateBody,
  });
  typia.assert(updatedContent);
  TestValidator.equals("content_type updated")(updatedContent.content_type)("main_image");
  TestValidator.equals("description updated")(updatedContent.content_description)("Changed to main image, updated text");
  TestValidator.equals("status updated")(updatedContent.status)("pending");

  // 5. Register a different seller (Seller B) for permission denial test
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "TestPassword1!",
      companyName: RandomGenerator.name(),
      businessNumber: "9876543210",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerBReg);
  // Swap to Seller B's JWT for next request
  connection.headers = { ...connection.headers, Authorization: sellerBReg.setHeaders.Authorization };

  // 6. Seller B attempts update – expect permission denial
  await TestValidator.error("permission denial for non-owner update")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productContents.update(connection, {
      productId,
      productContentId: content.id,
      body: {
        content_type: "gallery_image",
        status: "hidden",
      },
    });
  });

  // 7. Attempt update with invalid schema (negative content_order)
  connection.headers = { ...connection.headers, Authorization: sellerAReg.setHeaders.Authorization };
  await TestValidator.error("invalid content_order rejected")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productContents.update(connection, {
      productId,
      productContentId: content.id,
      body: {
        content_order: -1, // negative not allowed
      },
    });
  });
  // 8. Attempt update with invalid content_type value
  await TestValidator.error("invalid content_type rejected")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productContents.update(connection, {
      productId,
      productContentId: content.id,
      body: {
        content_type: "not_a_real_type",
      },
    });
  });

  // 9. (If API allowed) soft-delete content then attempt update (simulate by setting deleted_at if field/external call available)
  // For this test, simulate soft-delete by direct update (if API allowed) -- else, skip with a comment.
  // Skipping direct deletion as API is not present (only test not-found/update-after-deletion logic if API exists).
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that an admin can fetch full detail for a product bundle regardless of seller.
 *
 * This test ensures:
 * - Seller can register and create a product.
 * - Seller creates a bundle under the product.
 * - Admin registers and can fetch the bundle by product/bundle ID, even when not the owner seller.
 * - All schema fields should be present and correct in the fetched bundle.
 * - Admin may receive fields not visible to sellers (admin auditing, etc) — validate if present.
 * - Unauthorized/missing bundle ID should trigger error (tested as negative case).
 *
 * Process:
 * 1. Register a seller.
 * 2. As the seller, create a product.
 * 3. As the seller, create a product bundle for the product.
 * 4. Register an admin.
 * 5. As admin, fetch the bundle with correct IDs and check all fields.
 * 6. Try to fetch with a non-existent bundle ID as admin and confirm error.
 */
export async function test_api_product_bundle_detail_view_as_admin(connection: api.IConnection) {
  // 1. Register a seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Testpass123!";
  const sellerSignUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile()
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(sellerSignUpResp);
  const sellerId = sellerSignUpResp.sellerId;

  // 2. As seller, create a product
  const createdProduct = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "draft"
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(createdProduct);

  // 3. As seller, create a bundle for the product
  const createdBundle = await api.functional.shoppingMallAiBackend.seller.products.productBundles.create(connection, {
    productId: createdProduct.id,
    body: {
      main_product_id: createdProduct.id,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.content()()(),
      bundle_policy: "manual",
      bundle_price: 49900,
      status: "active"
    } satisfies IShoppingMallAiBackendProductBundle.ICreate
  });
  typia.assert(createdBundle);

  // 4. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Adminpass123!";
  const adminSignUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminSignUpResp);
  // Simulate admin session: the SDK should handle Authorization header already

  // 5a. As admin, get the bundle by productId and bundleId
  const output = await api.functional.shoppingMallAiBackend.admin.products.productBundles.at(connection, {
    productId: createdProduct.id,
    productBundleId: createdBundle.id
  });
  typia.assert(output);

  // 5b. Check that all fields are correct
  TestValidator.equals("productBundle.id")(output.id)(createdBundle.id);
  TestValidator.equals("main_product_id")(output.main_product_id)(createdProduct.id);
  TestValidator.equals("code")(output.code)(createdBundle.code);
  TestValidator.equals("name")(output.name)(createdBundle.name);
  TestValidator.equals("description")(output.description)(createdBundle.description);
  TestValidator.equals("bundle_policy")(output.bundle_policy)(createdBundle.bundle_policy);
  TestValidator.equals("bundle_price")(output.bundle_price)(createdBundle.bundle_price);
  TestValidator.equals("status")(output.status)(createdBundle.status);
  // Non-nullable audit fields
  TestValidator.predicate("created_at present")(typeof output.created_at === "string");
  TestValidator.predicate("updated_at present")(typeof output.updated_at === "string");
  // Possibly soft-delete remains null
  TestValidator.equals("deleted_at")(output.deleted_at)(null);

  // 6. Attempt to fetch with non-existing bundle id and expect error
  await TestValidator.error("non-existent id fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productBundles.at(connection, {
      productId: createdProduct.id,
      productBundleId: typia.random<string & tags.Format<"uuid">>()
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test product bundle creation by a seller in the shopping mall backend.
 *
 * This test covers the full workflow required for a seller to create a bundle:
 * 1. Register and authenticate a new seller via the public onboarding API.
 * 2. Use the authenticated seller context to create a new product, which will be used for the bundle.
 * 3. Create a valid product bundle for that product, verify successful creation and audit fields.
 * 4. Negative test: try to create the bundle without required fields (should fail).
 * 5. Negative test: try to create a bundle for a product not owned by the seller (should fail - permission error).
 * 6. Negative test: try to create a bundle with the same unique code as an existing bundle (should fail - duplicate code validation).
 *
 * Positive and negative scenario steps:
 * - All business-required fields are set correctly for bundle creation.
 * - Returned bundle object has correct fields and audit timestamps populated.
 * - Product owner mismatch and unique code violation are validated.
 */
export async function test_api_product_bundle_creation_by_seller(connection: api.IConnection) {
  // 1. Register a seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: "123 Test Address",
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerResponse);
  const sellerId = sellerResponse.sellerId;
  // Install JWT/Authorization header for seller account
  connection.headers = Object.assign({}, connection.headers, sellerResponse.setHeaders);

  // 2. Create a product owned by the seller
  const productCode = RandomGenerator.alphaNumeric(8);
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: productCode,
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);
  TestValidator.equals("product.seller_id == current sellerId")(product.seller_id)(sellerId);
  TestValidator.equals("product created code matches")(product.code)(productCode);

  // 3. Create a valid product bundle for that product
  const bundleCode = RandomGenerator.alphaNumeric(8);
  const bundle = await api.functional.shoppingMallAiBackend.seller.products.productBundles.create(connection, {
    productId: product.id,
    body: {
      main_product_id: product.id,
      code: bundleCode,
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      bundle_policy: null,
      bundle_price: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProductBundle.ICreate,
  });
  typia.assert(bundle);
  TestValidator.equals("bundle.main_product_id == product.id")(bundle.main_product_id)(product.id);
  TestValidator.equals("bundle code matches")(bundle.code)(bundleCode);
  TestValidator.equals("bundle status")(bundle.status)("active");
  TestValidator.predicate("bundle.created_at is ISO8601 date")(bundle.created_at.length > 0);
  TestValidator.predicate("bundle.updated_at is ISO8601 date")(bundle.updated_at.length > 0);
  TestValidator.equals("bundle.deleted_at is null or omitted")(bundle.deleted_at ?? null)(null);

  // 4. Negative: missing required fields (e.g., no code & name)
  await TestValidator.error("Missing required fields should error")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productBundles.create(connection, {
        productId: product.id,
        body: {
          main_product_id: product.id,
          status: "active",
        } as any, // Intentional for negative test
      });
    },
  );

  // 5. Negative: other seller tries to create bundle for a product they don't own
  const otherSellerEmail = typia.random<string & tags.Format<"email">>();
  const otherSellerResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: otherSellerEmail,
      password: "OtherPassword123!",
      companyName: RandomGenerator.name(),
      businessNumber: "0987654321",
      representativeName: RandomGenerator.name(),
      address: "456 Other Road",
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(otherSellerResp);
  connection.headers = Object.assign({}, connection.headers, otherSellerResp.setHeaders);

  await TestValidator.error("Seller cannot create bundle for product they don't own")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productBundles.create(connection, {
        productId: product.id,
        body: {
          main_product_id: product.id,
          code: RandomGenerator.alphaNumeric(8),
          name: RandomGenerator.alphabets(8),
          status: "active",
        } satisfies IShoppingMallAiBackendProductBundle.ICreate,
      });
    },
  );

  // 6. Negative: duplicate bundle code for same product
  // Switch back to original seller
  connection.headers = Object.assign({}, connection.headers, sellerResponse.setHeaders);
  await TestValidator.error("Duplicate bundle code should error")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productBundles.create(connection, {
        productId: product.id,
        body: {
          main_product_id: product.id,
          code: bundleCode, // same as above
          name: RandomGenerator.alphabets(8),
          status: "active",
        } satisfies IShoppingMallAiBackendProductBundle.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that an admin can create a product bundle for any valid product in the system, enforcing all permissions and business rules.
 *
 * Business context:
 * Bundles are business groupings of products (e.g., for marketing or custom package deals) that platform admins (not just sellers) may create. Creating a bundle requires referencing a valid underlying product and providing mandatory fields (code, name, status). Admin privilege should be sufficient, and incorrect/incomplete or inconsistent data should result in failure.
 *
 * Test process:
 * 1. Register a new seller (who will own the base product).
 * 2. Register a valid product as that seller (provides real productId for bundle).
 * 3. Register an admin and ensure connection carries admin credentials.
 * 4. As an admin, create a bundle for the valid product (success expected). Assert all returned data matches inputs, ownership, and business rules. Validate type with typia.assert().
 * 5. Attempt to create a bundle omitting required fields; assert this fails (TestValidator.error).
 * 6. Attempt to create a bundle using a random/invalid productId (referential integrity check); assert this fails (TestValidator.error).
 */
export async function test_api_product_bundle_creation_by_admin(connection: api.IConnection) {
  // 1. Register a new seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerRes = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "Seller@1234",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(10) + " Street",
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerRes);

  // 2. Register a product under the seller
  const productInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: sellerRes.sellerId,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.paragraph()(),
    main_image_uri: null,
    status: "published", // assume this is a valid status string
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: productInput,
  });
  typia.assert(product);

  // 3. Register an admin and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "Admin@12345",
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminRes);
  // Authorization header is now set in 'connection'

  // 4. As admin, create a valid bundle for the existing product
  const bundleInput: IShoppingMallAiBackendProductBundle.ICreate = {
    main_product_id: product.id,
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.paragraph()(),
    bundle_policy: "manual",
    bundle_price: 9999,
    status: "active",
  };
  const bundle = await api.functional.shoppingMallAiBackend.admin.products.productBundles.create(connection, {
    productId: product.id,
    body: bundleInput,
  });
  typia.assert(bundle);
  // Validate main_product_id points to the correct product
  TestValidator.equals("bundle main_product_id matches")(bundle.main_product_id)(product.id);
  TestValidator.equals("bundle code")(bundle.code)(bundleInput.code);
  TestValidator.equals("bundle status")(bundle.status)(bundleInput.status);

  // 5. Attempt to create bundle omitting required fields (should fail)
  await TestValidator.error("missing required fields")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productBundles.create(connection, {
      productId: product.id,
      body: {
        main_product_id: product.id,
        // code and name missing on purpose!
        status: "active",
      } as any, // Only for testing error, never use as any in production code.
    });
  });

  // 6. Attempt to create bundle with invalid productId (referential integrity failure)
  await TestValidator.error("invalid productId")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productBundles.create(connection, {
      productId: typia.random<string & tags.Format<"uuid">>(), // random, doesn't exist
      body: {
        ...bundleInput,
        main_product_id: typia.random<string & tags.Format<"uuid">>(), // random, doesn't exist
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate seller updating a product bundle (ownership, successful update, auth error, and invalid data).
 *
 * Business context:
 * - Bundles are auxiliary product groupings with specific pricing and status, tied to products.
 * - Only owner sellers can update their bundles.
 * - Updates allow changing name, description, price, status, etc, subject to validation.
 *
 * Process:
 * 1. Register Seller A (owner)
 * 2. Seller A creates a product
 * 3. Seller A creates a bundle for the product
 * 4. Seller A updates bundle properties using the update API
 * 5. Validate updated fields in the API response
 * 6. Register Seller B, and verify that a non-owner cannot update Seller A's bundle (should error)
 * 7. Try invalid update payloads (e.g., empty name, negative price) and confirm validation failure
 */
export async function test_api_product_bundle_update_by_seller(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const signUpA = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "testpassword123",
      companyName: RandomGenerator.alphaNumeric(8),
      businessNumber: (Math.floor(1000000000 + Math.random() * 9000000000)).toString(),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(12),
      phone: "010" + (Math.floor(10000000 + Math.random() * 90000000)).toString(),
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(signUpA);
  // Connection should now have Seller A JWT

  // 2. Seller A creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: signUpA.sellerId,
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 3. Seller A creates a product bundle for the product
  const bundle = await api.functional.shoppingMallAiBackend.seller.products.productBundles.create(connection, {
    productId: product.id,
    body: {
      main_product_id: product.id,
      code: RandomGenerator.alphaNumeric(10),
      name: "Initial Bundle",
      description: "Original description",
      bundle_policy: null,
      bundle_price: 1234.56,
      status: "active",
    } satisfies IShoppingMallAiBackendProductBundle.ICreate
  });
  typia.assert(bundle);

  // 4. Seller A updates the bundle fields
  const updatedFields: IShoppingMallAiBackendProductBundle.IUpdate = {
    name: "Updated Bundle Name",
    description: "Updated bundle description.",
    bundle_price: 5555.99,
    status: "hidden",
  };
  const updatedBundle = await api.functional.shoppingMallAiBackend.seller.products.productBundles.update(connection, {
    productId: product.id,
    productBundleId: bundle.id,
    body: updatedFields
  });
  typia.assert(updatedBundle);

  // 5. Validate updated fields in the API response
  TestValidator.equals("bundle name")(updatedBundle.name)(updatedFields.name);
  TestValidator.equals("description")(updatedBundle.description)(updatedFields.description);
  TestValidator.equals("bundle_price")(updatedBundle.bundle_price)(updatedFields.bundle_price);
  TestValidator.equals("status")(updatedBundle.status)(updatedFields.status);

  // 6. Register Seller B and test forbidden update
