/**
 * Validates admin's capability to search, filter, and paginate a specific customer's addresses via the admin endpoint.
 *
 * Business context:
 * An admin can list and search through a customer's addresses—using various fields as filters and paginating the result set. This functionality is critical for support tooling, compliance audits, and dashboard UIs. The test ensures the endpoint applies all business rules correctly and is robust to both valid and invalid queries.
 *
 * Test Workflow:
 * 1. Register a new admin account.
 * 2. Log in as this admin to ensure proper Authorization handling.
 * 3. Register a new customer account.
 * 4. As the admin, create several addresses for this customer, deliberately spreading field values (city, state, is_primary, alias).
 * 5. List all addresses without filters; ensure count matches created records.
 * 6. Filter by city; validate only matching addresses are returned.
 * 7. Filter by state; validate only matching addresses are returned.
 * 8. Filter by is_primary=true; ensure only the primary address is returned.
 * 9. Test pagination: limit=2, page=2; verify pagination fields and result slice.
 * 10. Try querying addresses of a random (non-existent) customerId; expect error thrown.
 */
export async function test_api_customer_admin_search_addresses_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adm!nP@ssw0rd";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Login as admin
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);
  TestValidator.equals("admin JWT set")(typeof adminSignIn.jwt)("string");

  // 3. Register new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "cust0m3rP@ss",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  const customerId = customerSignUp.customer.id;

  // 4. As admin, create several addresses with intentional value spread
  const cityA = "Seoul";
  const cityB = "Busan";
  const stateA = "Seoul Special City";
  const stateB = "Busan Province";
  const addresses: IShoppingMallAiBackendCustomerAddress[] = [];
  for (let i = 0; i < 5; ++i) {
    const addr = await api.functional.shoppingMallAiBackend.admin.customers.addresses.update(connection, {
      customerId,
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        receiver_name: RandomGenerator.name(),
        receiver_phone: RandomGenerator.mobile(),
        postal_code: `1234${i}`,
        address_line1: `Test Address ${i}`,
        address_line2: `Bldg Suite ${i}`,
        city: i % 2 === 0 ? cityA : cityB,
        state: i % 2 === 0 ? stateA : stateB,
        country: "KR",
        is_primary: i === 0,
        alias: i === 0 ? "Home" : `Work${i}`,
      } satisfies IShoppingMallAiBackendCustomerAddress.IUpdate,
    });
    typia.assert(addr);
    addresses.push(addr);
  }

  // 5. List addresses without filter (all)
  const all = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: {},
  });
  typia.assert(all);
  TestValidator.equals("address count matches")(all.data.length)(addresses.length);

  // 6. Filter by city
  const byCity = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: { city: cityA },
  });
  typia.assert(byCity);
  TestValidator.predicate(`all city == ${cityA}`)(byCity.data.every((a: IShoppingMallAiBackendCustomerAddress) => a.city === cityA));

  // 7. Filter by state
  const byState = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: { state: stateB },
  });
  typia.assert(byState);
  TestValidator.predicate(`all state == ${stateB}`)(byState.data.every((a: IShoppingMallAiBackendCustomerAddress) => a.state === stateB));

  // 8. Filter by is_primary true
  const primaries = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: { is_primary: true },
  });
  typia.assert(primaries);
  TestValidator.predicate("all primary")(primaries.data.every((a: IShoppingMallAiBackendCustomerAddress) => a.is_primary));
  TestValidator.equals("single primary")(primaries.data.length)(1);

  // 9. Pagination: limit=2, page=2
  const paged = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: { limit: 2, page: 2 },
  });
  typia.assert(paged);
  TestValidator.equals("page size")(paged.pagination.limit)(2);
  TestValidator.equals("page 2")(paged.pagination.current)(2);
  TestValidator.equals("pagination total records")(paged.pagination.records)(addresses.length);
  TestValidator.equals("pagination total pages")(paged.pagination.pages)(Math.ceil(addresses.length / 2));

  // 10. Query with non-existent customerId (expect error)
  const badCustomerId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent customerId fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
      customerId: badCustomerId,
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
