/**
 * Validate admin search and pagination of product option stock records.
 *
 * This test ensures that an admin can:
 * 1. Register and login as admin (with proper authentication)
 * 2. Create a product as admin
 * 3. Create a product option for the product
 * 4. Register multiple stock records tied to the new product option
 * 5. Search the stock records using the PATCH endpoint as admin
 * 6. Validate the returned structure, pagination, and filtering (such as by status or warehouse_location)
 */
export async function test_api_product_option_stock_search_success_admin(connection: api.IConnection) {
  // 1. Register a new admin (random email/password)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Login as the new admin (token will be attached to connection)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Create a product as admin
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 4. Create a product option for this product
  const productOption = await api.functional.shoppingMallAiBackend.admin.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: RandomGenerator.alphaNumeric(12),
      option_name: "color",
      option_values: "red,blue,green",
      extra_price: 1000,
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProductOption.ICreate,
  });
  typia.assert(productOption);

  // 5. Add multiple stock records for the product option
  const statuses = ["active", "locked", "reserved"];
  const warehouseLocations = ["A01-B01", "A01-B02", "A02-B01"];
  const stockRecords = await ArrayUtil.asyncRepeat(5)(async (i) => {
    const stock = await api.functional.shoppingMallAiBackend.admin.productOptions.productOptionStocks.create(connection, {
      productOptionId: productOption.id,
      body: {
        product_option_id: productOption.id,
        stock_count: 10 * (i + 1),
        safety_stock: i % 2 === 0 ? 5 : null,
        inbound_count: i % 3 === 0 ? 3 : null,
        warehouse_location: warehouseLocations[i % warehouseLocations.length],
        status: statuses[i % statuses.length],
      } satisfies IShoppingMallAiBackendProductOptionStock.ICreate,
    });
    typia.assert(stock);
    return stock;
  });
  TestValidator.equals("created stocks")(stockRecords.length)(5);

  // 6. Search stock records (first page, page size 3, status filter)
  const searchStatus = "active";
  const searchLocation = warehouseLocations[0];
  const search = await api.functional.shoppingMallAiBackend.admin.productOptions.productOptionStocks.search(connection, {
    productOptionId: productOption.id,
    body: {
      filter: {
        productOptionId: productOption.id,
        status: searchStatus,
        warehouse_location: searchLocation,
      },
      page: 1,
      pageSize: 3,
    } satisfies IShoppingMallAiBackendProductOptionStock.IRequest,
  });
  typia.assert(search);

  // 7. Validate result structure and filtering
  TestValidator.equals("pagination current page")(search.pagination.current)(1);
  TestValidator.equals("pagination limit")(search.pagination.limit)(3);
  // All results should have status === searchStatus and matching warehouse_location
  search.data.forEach((stock) => {
    TestValidator.equals("filter status")(stock.status)(searchStatus);
    TestValidator.equals("filter warehouse")(stock.warehouse_location)(searchLocation);
    TestValidator.equals("product option ID matches")(stock.product_option_id)(productOption.id);
  });
}

