  await TestValidator.error("duplicate keyword must fail")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.createProductSearchKeyword(
      connection,
      {
        productId,
        body: {
          product_id: productId,
          search_keyword: searchKeyword,
        } satisfies IShoppingMallAiBackendProductSearchKeyword.ICreate,
      },
    );
  });
}

