/**
 * Test successful update of a product search keyword as a seller.
 *
 * This test simulates a realistic seller workflow: registration, product creation, adding a search keyword to the product, and then updating the keyword using the PUT endpoint. It verifies that the update is reflected in the returned data and persists the change. Due to the current API and available DTOs, only the `search_keyword` string is updatable—change history is not tracked in the exposed types, so this step is omitted.
 *
 * Step-by-step process:
 * 1. Register a new seller to get authentication and obtain seller details (for product ownership).
 * 2. Create a new product for the seller using required and optional fields.
 * 3. Add a search keyword to the created product.
 * 4. Update the search keyword for this product using the update endpoint.
 * 5. Assert that the response from the update matches the updated value and product/keyword relationships remain consistent.
 */
export async function test_api_product_search_keyword_update_success(
  connection: api.IConnection,
) {
  // 1. Register a new seller account
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const signUpInput: ISellerAuth.SignUp = {
    email: sellerEmail,
    password: "Password123!",
    companyName: RandomGenerator.alphaNumeric(8),
    businessNumber: "1234567890",
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.alphaNumeric(12),
    phone: RandomGenerator.mobile(),
  };
  const sellerAuth = await api.functional.auth.seller.register.signUp(connection, { body: signUpInput });
  typia.assert(sellerAuth);

  // 2. Create a new product for this seller
  const createProductInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: sellerAuth.sellerId,
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.content()()(1),
    main_image_uri: null,
    status: "published",
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: createProductInput });
  typia.assert(product);

  // 3. Add a product search keyword
  const initialKeyword = "init-keyword-" + RandomGenerator.alphaNumeric(6);
  const createKeywordInput: IShoppingMallAiBackendProductSearchKeyword.ICreate = {
    product_id: product.id,
    search_keyword: initialKeyword,
  };
  const productKeyword = await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.createProductSearchKeyword(connection, {
    productId: product.id,
    body: createKeywordInput,
  });
  typia.assert(productKeyword);
  TestValidator.equals("initial search keyword matches")(productKeyword.search_keyword)(initialKeyword);
  TestValidator.equals("keyword product_id matches")(productKeyword.product_id)(product.id);

  // 4. Update the search keyword value
  const updatedKeyword = "updated-keyword-" + RandomGenerator.alphaNumeric(8);
  const updateKeywordInput: IShoppingMallAiBackendProductSearchKeyword.IUpdate = {
    search_keyword: updatedKeyword,
  };
  const updatedProductKeyword = await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.updateProductSearchKeyword(connection, {
    productId: product.id,
    productSearchKeywordId: productKeyword.id,
    body: updateKeywordInput,
  });
  typia.assert(updatedProductKeyword);

  // 5. Validate that the update persisted and relationships are correct
  TestValidator.equals("updated search keyword matches")(updatedProductKeyword.search_keyword)(updatedKeyword);
  TestValidator.equals("product_id remains unchanged")(updatedProductKeyword.product_id)(product.id);
  TestValidator.equals("keyword id unchanged")(updatedProductKeyword.id)(productKeyword.id);
}

