import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";
import type { IPageIShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductReview";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates admin's ability to perform advanced review search with full scope and filters.
 *
 * Business Context: The admin must be able to fetch a paginated, filtered, and ordered list of all product reviews for moderation, analytics, and compliance needs. The search should cover filters for product, customer, rating, review status (normal/blocked/deleted), created-at time windows, keyword search, and pagination. The results should cover: wide result sets, narrow filtered sets, empty sets, and handle errors (
 * e.g., malformed paging/filter, forbidden access).
 *
 * Steps:
 * 1. Authenticate as admin
 * 2. Create multiple products as admin (with some active, some soft-deleted)
 * 3. Insert product reviews by customers for various products (with rating/status/text/time diversity)
 * 4. Perform search covering (for each, assert correct result and pagination):
 *    - No filters: ensure all reviews returned, pagination enforced
 *    - Filter by product, customer, rating (from/to), status
 *    - Filter by created_at time window
 *    - Keyword search
 *    - Ordering by created_at and rating (asc/desc)
 *    - Pagination incl. edge/out-of-bounds
 *    - Search yielding empty result
 *    - Malformed/invalid filter (error check)
 *    - Permission error (not logged in)
 * 5. Assert only reviews for non-deleted products are visible, filters actually filter, sort orders are correct, error responses as expected
 */
export async function test_api_admin_review_search_with_full_scope_and_filters(connection: api.IConnection) {
  // Step 1: Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin1234";
  // We must assume a known admin to log in; create credentials if fixture/admin exists, else needs fixture preparation
  // For e2e, try and assume login exists (if otherwise, skip test)
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);
  if (adminAuth.setHeaders && adminAuth.setHeaders.Authorization) {
    connection.headers = { ...(connection.headers ?? {}), Authorization: adminAuth.setHeaders.Authorization };
  }

  // Step 2: Create multiple products (active and soft-deleted)
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const productActive = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: `SKU-ACTIVE-1`,
      name: "Active Product 1",
      status: "published",
      description: "First active product",
      main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productActive);
  const productDeleted = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: `SKU-DEL-1`,
      name: "Soft Deleted Product",
      status: "discontinued",
      description: "A discontinued product",
      main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productDeleted);

  // Step 3: Insert reviews with variety (simulate multiple customers, products, ratings, times, status, and keywords)
  const customerA = typia.random<string & tags.Format<"uuid">>();
  const customerB = typia.random<string & tags.Format<"uuid">>();
  const orderItemA = typia.random<string & tags.Format<"uuid">>();
  const orderItemB = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  // Reviews for active product
  const review1 = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: productActive.id,
      order_item_id: orderItemA,
      title: "Great Product A",
      body: "Love this! AI was accurate.",
      rating: 5,
      status: "normal",
      ai_sentiment_score: 0.8,
      ai_spam_score: 0.01,
    } satisfies IShoppingMallAiBackendProductReview.ICreate,
  });
  typia.assert(review1);
  const review2 = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: productActive.id,
      order_item_id: orderItemB,
      title: "OK Product",
      body: "Average experience.",
      rating: 3,
      status: "blocked",
      ai_sentiment_score: -0.1,
      ai_spam_score: 0.2,
    } satisfies IShoppingMallAiBackendProductReview.ICreate,
  });
  typia.assert(review2);
  // Review for soft-deleted product (should not appear by business rule)
  await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: productDeleted.id,
      order_item_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Should Not Appear",
      body: "This is on a deleted/discontinued product.",
      rating: 2,
      status: "normal",
      ai_sentiment_score: null,
      ai_spam_score: 0.9,
    } satisfies IShoppingMallAiBackendProductReview.ICreate,
  });

  // Step 4: Search scenarios
  // a) No filters: expect 2 reviews for active
  const allResult = await api.functional.shoppingMallAiBackend.admin.productReviews.search(connection, {
    body: {
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendProductReview.IRequest,
  });
  typia.assert(allResult);
  TestValidator.predicate("all reviews included")(
    allResult.data.length === 2 && allResult.data.some(r => r.id === review1.id) && allResult.data.some(r => r.id === review2.id)
  );

  // b) Filter by product_id (active only): expect only review1 and review2
  const filtActive = await api.functional.shoppingMallAiBackend.admin.productReviews.search(connection, {
    body: {
      product_id: productActive.id,
      page: 1,
      limit: 5,
    } satisfies IShoppingMallAiBackendProductReview.IRequest,
  });
  typia.assert(filtActive);
  TestValidator.equals("only active product reviews")(
    filtActive.data.map(x=>x.id).sort()
  )(
    [review1.id, review2.id].sort()
  );
  // c) By customer_id: only review1 for customerA
  const filtCustA = await api.functional.shoppingMallAiBackend.admin.productReviews.search(connection, {
    body: {
      customer_id: customerA,
      page: 1,
      limit: 5,
    } satisfies IShoppingMallAiBackendProductReview.IRequest,
  });
  typia.assert(filtCustA);
  TestValidator.equals("review by customerA")(filtCustA.data.length)(1);
  TestValidator.equals("review1 id")(filtCustA.data[0].id)(review1.id);

  // d) By rating (from 4): only review1
  const filtRating = await api.functional.shoppingMallAiBackend.admin.productReviews.search(connection, {
    body: {
      rating_from: 4,
      page: 1,
      limit: 5,
    } satisfies IShoppingMallAiBackendProductReview.IRequest,
  });
  typia.assert(filtRating);
  TestValidator.equals("rating >= 4")(filtRating.data.length)(1);
  TestValidator.equals("review1 id")(filtRating.data[0].id)(review1.id);

  // e) By status: blocked
  const filtBlocked = await api.functional.shoppingMallAiBackend.admin.productReviews.search(connection, {
    body: {
      status: "blocked",
      page: 1,
      limit: 5,
    } satisfies IShoppingMallAiBackendProductReview.IRequest,
  });
  typia.assert(filtBlocked);
  TestValidator.equals("blocked count")(filtBlocked.data.length)(1);
  TestValidator.equals("blocked review id")(filtBlocked.data[0].id)(review2.id);

  // f) Keyword search (title)
  const filtKeyword = await api.functional.shoppingMallAiBackend.admin.productReviews.search(connection, {
    body: {
      search: "accurate",
      page: 1,
      limit: 5,
    } satisfies IShoppingMallAiBackendProductReview.IRequest,
  });
  typia.assert(filtKeyword);
  TestValidator.equals("keyword in title or body")(filtKeyword.data.length)(1);
  TestValidator.equals("keyword review id")(filtKeyword.data[0].id)(review1.id);

  // g) Pagination (limit=1), page 1: only review1 or review2; page 2: other
  const paged1 = await api.functional.shoppingMallAiBackend.admin.productReviews.search(connection, {
    body: {
      page: 1,
      limit: 1,
      sort_by: "created_at",
      sort_direction: "asc",
    } satisfies IShoppingMallAiBackendProductReview.IRequest,
  });
  typia.assert(paged1);
  TestValidator.equals("one per page")(paged1.data.length)(1);
  const paged2 = await api.functional.shoppingMallAiBackend.admin.productReviews.search(connection, {
    body: {
      page: 2,
      limit: 1,
      sort_by: "created_at",
      sort_direction: "asc",
    } satisfies IShoppingMallAiBackendProductReview.IRequest,
  });
  typia.assert(paged2);
  TestValidator.equals("one per page")(paged2.data.length)(1);
  TestValidator.notEquals("paged [1] vs [2]")(paged1.data[0].id)(paged2.data[0].id);

  // h) Out-of-bounds page: should return empty data[]
  const pageOob = await api.functional.shoppingMallAiBackend.admin.productReviews.search(connection, {
    body: {
      page: 10,
      limit: 5,
    } satisfies IShoppingMallAiBackendProductReview.IRequest,
  });
  typia.assert(pageOob);
  TestValidator.equals("empty on out-of-bounds")(pageOob.data.length)(0);

  // i) Invalid filter: negative page/limit
  await TestValidator.error("invalid page negative")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.productReviews.search(connection, {
        body: {
          page: -1,
          limit: 2,
        } as any,
      });
    }
  );
  await TestValidator.error("invalid filter: bad rating")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.productReviews.search(connection, {
        body: {
          page: 1,
          limit: 2,
          rating_from: 6,
        } as any,
      });
    }
  );

  // j) Permission error: remove JWT (logout) and retry
  const prevAuth = connection.headers?.Authorization;
  if (connection.headers) delete connection.headers.Authorization;
  await TestValidator.error("not logged in")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.productReviews.search(connection, {
        body: {
          page: 1,
          limit: 5,
        } satisfies IShoppingMallAiBackendProductReview.IRequest,
      });
    }
  );
  // Restore auth for other tests
  if (prevAuth && connection.headers) connection.headers.Authorization = prevAuth;
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test retrieval of a customer's own product review detail, ensuring permission scoping and error handling.
 *
 * This E2E test ensures a customer can fetch full details of their own product review (all fields: auth, product, order item, rating, status, AI moderation, timestamps, body), and covers privacy/permission protection by denying access to other users' reviews. Also validates error handling for not-found and deleted review cases.
 *
 * Steps:
 * 1. Customer A logs in, creates a product review, and retrieves its full detail (success – validates all fields).
 * 2. Customer B (different account) attempts to fetch Customer A's review detail and receives a permission-denied error (forbidden/not found).
 * 3. Customer A attempts to fetch a non-existent review, expects a not found error or appropriate code.
 */
export async function test_api_customer_retrieve_own_review_detail(connection: api.IConnection) {
  // 1. Customer A login
  const customerAEmail = typia.random<string & tags.Format<"email">>();
  const customerAPassword = "TestPass!123";
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerAEmail,
      password: customerAPassword,
    },
  });

  // 2. Customer A creates a review
  const productId = typia.random<string & tags.Format<"uuid">>();
  const orderItemId = typia.random<string & tags.Format<"uuid">>();
  const createInput: IShoppingMallAiBackendProductReview.ICreate = {
    product_id: productId,
    order_item_id: orderItemId,
    title: "Excellent!",
    body: "This product exceeded my expectations.",
    rating: 5,
    status: "normal",
    ai_sentiment_score: 0.95,
    ai_spam_score: 0.01,
  };
  const createdReview = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, { body: createInput });
  typia.assert(createdReview);

  // 3. Customer A retrieves their own review by ID
  const reviewDetail = await api.functional.shoppingMallAiBackend.customer.productReviews.at(connection, { productReviewId: createdReview.id });
  typia.assert(reviewDetail);
  TestValidator.equals("Customer ID matches")(reviewDetail.customer_id)(createdReview.customer_id);
  TestValidator.equals("Review ID content matches")(reviewDetail.id)(createdReview.id);
  TestValidator.equals("Product ID content matches")(reviewDetail.product_id)(createdReview.product_id);
  TestValidator.equals("Order item matches")(reviewDetail.order_item_id)(createdReview.order_item_id);
  TestValidator.equals("Rating matches")(reviewDetail.rating)(createdReview.rating);
  TestValidator.equals("Status matches")(reviewDetail.status)(createdReview.status);
  TestValidator.equals("Title matches")(reviewDetail.title)(createdReview.title);
  TestValidator.equals("Body matches")(reviewDetail.body)(createdReview.body);
  TestValidator.equals("AI Sentiment matches")(reviewDetail.ai_sentiment_score)(createdReview.ai_sentiment_score);
  TestValidator.equals("AI Spam matches")(reviewDetail.ai_spam_score)(createdReview.ai_spam_score);

  // 4. Customer B login (different user)
  const customerBEmail = typia.random<string & tags.Format<"email">>();
  const customerBPassword = "TestPass!456";
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerBEmail,
      password: customerBPassword,
    },
  });

  // 5. Customer B tries to fetch Customer A's review (should error with forbidden/not found)
  await TestValidator.error("Deny access to other user's review")(async () => {
    await api.functional.shoppingMallAiBackend.customer.productReviews.at(connection, { productReviewId: createdReview.id });
  });

  // 6. Customer A logs back in
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerAEmail,
      password: customerAPassword,
    },
  });

  // 7. Attempt to fetch a non-existent review
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Non-existent review fetch returns error")(async () => {
    await api.functional.shoppingMallAiBackend.customer.productReviews.at(connection, { productReviewId: nonExistentId });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate seller retrieval of a product review by review ID for ownership, forbidden access, and error cases.
 *
 * This test ensures:
 * 1. Seller can retrieve a review for a product they own, with all business/AI moderation fields present.
 * 2. Fetching a review for a product not owned by the seller returns forbidden.
 * 3. Fetching a soft-deleted or non-existent review returns not found.
 * 4. All outputs are strictly type-validated and business rules are enforced.
 *
 * Steps:
 * 1. Authenticate as Seller 1 and obtain JWT.
 * 2. Create a product as Seller 1.
 * 3. Create a review for this product as a customer (simulated as no customer login API is available).
 * 4. Seller 1 fetches review by reviewId (expect full data).
 * 5. Authenticate as Seller 2.
 * 6. Seller 2 tries to fetch the same review (expect forbidden error).
 * 7. Attempt fetching with random soft-deleted and non-existent review IDs (expect not found errors).
 */
export async function test_api_seller_retrieve_review_for_owned_product(connection: api.IConnection) {
  // 1. Authenticate as Seller 1 and obtain JWT
  const seller1Email = typia.random<string & tags.Format<"email">>();
  const seller1Pass = "pw123!";
  const seller1Auth = await api.functional.auth.seller.login.signIn(connection, {
    body: { email: seller1Email, password: seller1Pass },
  });
  typia.assert(seller1Auth);
  connection.headers = { ...connection.headers, Authorization: `Bearer ${seller1Auth.token}` };

  // 2. Create a new product as Seller 1
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: seller1Auth.sellerId,
      code: `P-${Date.now()}-${Math.floor(Math.random()*10000)}`,
      name: "Product for Review Test",
      status: "published",
    },
  });
  typia.assert(product);

  // 3. Create a product review (as a customer; no explicit customer auth available)
  const review = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: product.id,
      order_item_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Great Product!",
      body: "This is a review for E2E testing.",
      rating: 4,
      status: "normal",
      ai_sentiment_score: 0.9,
      ai_spam_score: 0.01,
    },
  });
  typia.assert(review);

  // 4. Fetch the review as Seller 1 (should succeed)
  const result = await api.functional.shoppingMallAiBackend.seller.productReviews.at(connection, { productReviewId: review.id });
  typia.assert(result);
  TestValidator.equals("review id matches")(result.id)(review.id);
  TestValidator.equals("product id matches")(result.product_id)(product.id);
  TestValidator.equals("seller id matches")(product.seller_id)(seller1Auth.sellerId);
  TestValidator.predicate("AI fields present")(typeof result.ai_sentiment_score === "number" || result.ai_sentiment_score === null);
  TestValidator.predicate("AI spam field present")(typeof result.ai_spam_score === "number" || result.ai_spam_score === null);

  // 5. Authenticate as Seller 2
  const seller2Email = typia.random<string & tags.Format<"email">>();
  const seller2Pass = "pw456!";
  const seller2Auth = await api.functional.auth.seller.login.signIn(connection, {
    body: { email: seller2Email, password: seller2Pass },
  });
  typia.assert(seller2Auth);
  connection.headers = { ...connection.headers, Authorization: `Bearer ${seller2Auth.token}` };

  // 6. Seller 2 tries to fetch review (should be forbidden)
  await TestValidator.error("forbidden for seller not owning product")(() =>
    api.functional.shoppingMallAiBackend.seller.productReviews.at(connection, { productReviewId: review.id })
  );

  // 7. Soft-deleted and non-existent review fetch tests (simulate not found)
  const deletedOrRandomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found for soft-deleted review")(() =>
    api.functional.shoppingMallAiBackend.seller.productReviews.at(connection, { productReviewId: deletedOrRandomId })
  );

  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found for non-existent review")(() =>
    api.functional.shoppingMallAiBackend.seller.productReviews.at(connection, { productReviewId: randomId })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSeller";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test the successful update of a seller's organization profile and business attributes.
 *
 * This test simulates a complete business workflow for a seller updating their profile, including company name, representative name, phone, and address. It comprehensively covers:
 *
 * 1. Seller registration to initialize a unique business/seller identity
 * 2. Seller authentication to acquire credentials/JWT for authorized profile update
 * 3. Submission of a valid update payload for company name, representative, contact, and address fields
 * 4. Verification that the API returns the updated profile and enforces type safety and business logic
 * 5. Implied compliance: All changes must be audit logged (although direct DB access or retrieval of seller_histories is out of API contract scope)
 *
 * Steps:
 * 1. Register a new seller using valid and unique business profile information.
 * 2. Log in as that seller to obtain JWT/session (handled automatically via connection context).
 * 3. Construct an updated profile payload by changing company_name, representative_name, phone, and address fields.
 * 4. Call the seller update API with the new data, referencing the seller's own ID.
 * 5. Assert that the response data reflects the submitted changes as expected, and that the type assertion passes for the updated seller entity.
 * 6. (Cannot directly verify audit logs from API, but update should complete successfully if business rules are met.)
 */
export async function test_api_seller_update_profile_success(connection: api.IConnection) {
  // 1. Register a new seller account
  const registrationInput: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    companyName: RandomGenerator.alphabets(8),
    businessNumber: RandomGenerator.alphaNumeric(10),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(1),
    phone: RandomGenerator.mobile(),
  };

  const registration = await api.functional.auth.seller.register.signUp(connection, {
    body: registrationInput,
  });
  typia.assert(registration);

  // 2. Authenticate (login) as the seller to obtain JWT (handled by connection)
  const login = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: registrationInput.email,
      password: registrationInput.password,
    },
  });
  typia.assert(login);

  // 3. Construct an update payload with new seller profile attributes
  const updatePayload: IShoppingMallAiBackendSeller.IUpdate = {
    id: registration.sellerId,
    company_name: RandomGenerator.alphabets(10),
    representative_name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
    address: RandomGenerator.paragraph()(1),
    // business_number and other optional fields are left unchanged for this update
  };

  // 4. Perform the update
  const updatedSeller = await api.functional.shoppingMallAiBackend.seller.sellers.update(connection, {
    body: updatePayload,
  });
  typia.assert(updatedSeller);

  // 5. Assert the changed fields
  TestValidator.equals("company_name")(updatedSeller.company_name)(updatePayload.company_name);
  TestValidator.equals("representative_name")(updatedSeller.representative_name)(updatePayload.representative_name);
  TestValidator.equals("address")(updatedSeller.address)(updatePayload.address);
  TestValidator.equals("phone")(updatedSeller.phone)(updatePayload.phone);
  TestValidator.equals("id")(updatedSeller.id)(registration.sellerId);

  // 6. Confirm non-changed fields are preserved
  TestValidator.equals("business_number")(updatedSeller.business_number)(registration.businessNumber);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSeller";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate seller profile update failure cases with invalid or non-compliant data submission.
 *
 * This test confirms that when a seller attempts to update their profile with invalid data – such as missing required fields, invalid business registration number, or malformed phone – the API responds with validation errors and does not update the seller profile.
 *
 * Steps:
 * 1. Register a new seller with valid data.
 * 2. Authenticate as the newly registered seller.
 * 3. Attempt to update the profile with invalid data:
 *    a. Omit required fields (e.g., missing company name via null).
 *    b. Supply an invalid business registration number (bad format/length).
 *    c. Pass null where not allowed (e.g., representative name).
 *    d. Set an invalid phone format (e.g., random string).
 * 4. Confirm the API responds with an error in each case (TestValidator.error) and (if possible) that seller profile is unchanged.
 *    Note: As there is no profile fetch/read method in the API, post-update state verification cannot be performed.
 */
export async function test_api_seller_update_profile_invalid_data(connection: api.IConnection) {
  // Step 1: Register a new seller with valid data
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "ValidPass123$";
  const registerResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(registerResp);

  // Step 2: Authenticate as the seller
  const loginResp = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(loginResp);
  const sellerId: string = registerResp.sellerId;

  // Step 3a: Omit company_name by setting it null (treated invalid by backend)
  await TestValidator.error("missing company_name (set null)")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.update(connection, {
        body: {
          id: sellerId,
          company_name: null,
        } satisfies IShoppingMallAiBackendSeller.IUpdate,
      });
    }
  );

  // Step 3b: Invalid (non-numeric/short) business registration number
  await TestValidator.error("invalid business number format")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.update(connection, {
        body: {
          id: sellerId,
          business_number: "A12B34C", // Clearly not valid (should be digits)
        } satisfies IShoppingMallAiBackendSeller.IUpdate,
      });
    }
  );

  // Step 3c: Null for representative_name
  await TestValidator.error("null representative name")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.update(connection, {
        body: {
          id: sellerId,
          representative_name: null,
        } satisfies IShoppingMallAiBackendSeller.IUpdate,
      });
    }
  );

  // Step 3d: Phone in invalid format
  await TestValidator.error("invalid phone")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.update(connection, {
        body: {
          id: sellerId,
          phone: "not-a-phone!!!",
        } satisfies IShoppingMallAiBackendSeller.IUpdate,
      });
    }
  );

  // Step 4: Unable to validate data unchanged due to lack of profile-read endpoint.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSeller";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that unauthorized or anonymous users cannot update a seller's organization profile.
 *
 * This test ensures that only authenticated owners (correct session) can update their business profile. Any attempt by an unauthenticated actor or a user with invalid credentials must be strictly rejected, and the profile data must not change.
 *
 * Steps:
 * 1. Register (sign up) a true seller to own a seller profile.
 * 2. Attempt to update the profile with a PUT request while **not** authenticated (no token in headers) using the correct seller ID.
 *    - Expect an authorization/authentication error response (should NOT succeed).
 *    - Confirm that no fields are updated.
 * 3. (Edge case) Optionally: Attempt to update the profile using a different/fake seller's token if an authentication API existed. (SKIPPED: not implementable with current functions)
 * 4. (Omitted) Cannot implement audit log readout due to lack of API.
 *
 * Business logic: Unauthorized update attempts must not succeed and must never modify profile data. Attackers or anonymous clients must be blocked by security layer. Test focuses only on what is possible to verify with current API and DTOs.
 */
export async function test_api_seller_update_profile_unauthorized(connection: api.IConnection) {
  // 1. Register the owner seller
  const inputSignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPassword123!",
    companyName: "Acme Corp Unauthorized Test",
    businessNumber: "1234567890",
    representativeName: "Alice Malory",
    address: "100 Test Main Street, Cityville",
    phone: "010-5555-0101"
  } satisfies ISellerAuth.SignUp;
  const reg = await api.functional.auth.seller.register.signUp(connection, {
    body: inputSignUp
  });
  typia.assert(reg);

  // 2. Attempt unauthorized PUT (no authentication header)
  // Remove JWT token from connection.headers if set
  const connWithoutAuth = { ...connection, headers: { ...connection.headers } };
  if (connWithoutAuth.headers?.Authorization) delete connWithoutAuth.headers.Authorization;

  const updatePayload: IShoppingMallAiBackendSeller.IUpdate = {
    id: reg.sellerId,
    company_name: "Hacked Name Should Not Apply"
  };
  await TestValidator.error("unauthenticated update must fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.update(connWithoutAuth, { body: updatePayload });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSeller";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates that an admin can update the profile of a seller organization, ensuring correct compliance and audit behavior.
 *
 * This covers these major flows:
 * 1. Register and authenticate an admin (to perform updates on behalf of the platform)
 * 2. Register a new seller – ensuring a seller exists to be updated
 * 3. As admin, update the seller's profile (e.g., company name, address, and status)
 * 4. Verify that the response reflects the updates and still conforms to all type and business requirements
 *    (e.g., update logged in history, but since there is NO direct endpoint to validate log, we can only do positive tests)
 * 5. All updates must be type-safe, and edge cases (e.g., null, unchanged fields) should be handled gracefully
 */
export async function test_api_admin_update_seller_profile_success(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPW!234";
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignup);

  // 2. Login as the admin (to ensure a VALID JWT is set on connection)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register a seller that will be updated
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "sellerPW!345";
  const origCompanyName = "Original Company " + RandomGenerator.alphabets(6);
  const sellerSignupInput: ISellerAuth.SignUp = {
    email: sellerEmail,
    password: sellerPassword,
    companyName: origCompanyName,
    businessNumber: "1" + typia.random<string>().substring(0, 9),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(10),
    phone: RandomGenerator.mobile(),
  };
  const sellerSignup = await api.functional.auth.seller.register.signUp(connection, {
    body: sellerSignupInput,
  });
  typia.assert(sellerSignup);

  // 4. Prepare update fields (admin updating profile)
  const updateCompanyName = origCompanyName + " Updated";
  const updateAddress = RandomGenerator.paragraph()(12);
  const updateStatus = "active";
  const updateBody: IShoppingMallAiBackendSeller.IUpdate = {
    id: sellerSignup.sellerId,
    company_name: updateCompanyName,
    address: updateAddress,
    status: updateStatus,
  };

  // 5. As ADMIN, call the update endpoint for the seller
  const updatedSeller = await api.functional.shoppingMallAiBackend.admin.sellers.update(connection, {
    body: updateBody,
  });
  typia.assert(updatedSeller);

  // 6. Validate that the returned object matches the update
  TestValidator.equals("company name")(updatedSeller.company_name)(updateCompanyName);
  TestValidator.equals("address")(updatedSeller.address)(updateAddress);
  TestValidator.equals("status")(updatedSeller.status)(updateStatus);
  TestValidator.equals("id")(updatedSeller.id)(sellerSignup.sellerId);

  // 7. Non-updated fields remain unchanged (except those possibly system-modified, e.g. updated_at)
  TestValidator.equals("email")(updatedSeller.email)(sellerSignupInput.email);
  TestValidator.equals("business number")(updatedSeller.business_number)(sellerSignupInput.businessNumber);
  TestValidator.equals("representative name")(updatedSeller.representative_name)(sellerSignupInput.representativeName);
  TestValidator.equals("phone")(updatedSeller.phone)(sellerSignupInput.phone);

  // 8. Confirm types/format
  typia.assert<IShoppingMallAiBackendSeller>(updatedSeller);

  // NOTE: We cannot directly validate that seller_histories log is updated, but assume audit log works if no error.
}

