/**
 * Validate that updating a seller's profile via the admin endpoint fails on invalid data.
 *
 * This test ensures that the admin update fails when:
 * - the payload includes a duplicate `business_number` (matching another seller)
 * - the payload uses a malformed or empty `company_name`
 * - the payload is missing required fields (e.g., omits the `id`)
 *
 * Validation errors should be triggered and no unintended/partial updates occur.
 * Note: Profile readback is omitted as no GET endpoint is provided.
 *
 * Steps:
 * 1. Register an admin account.
 * 2. Log in as that admin (JWT set on connection).
 * 3. Register a first seller.
 * 4. Register a second seller (for duplication test).
 * 5. Try to update the first seller with (a) a duplicate business_number, (b) malformed company_name, and (c) missing required field.
 * 6. Ensure all invalid cases trigger proper errors.
 */
export async function test_api_admin_update_seller_profile_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin@12345!";
  const adminResult = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
