  // 5b. Attempt to update seller1 with malformed company_name
  await TestValidator.error("malformed company_name should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.sellers.update(connection, {
      body: {
        id: seller1.sellerId,
        company_name: "",
      },
    });
  });

  // 5c. Attempt to update with missing required id (compile error normally; tested for runtime)
  await TestValidator.error("missing id should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.sellers.update(connection, {
      body: {
        company_name: "Should Fail",
      } as any,
    });
  });
  // 6. No readback possible (no GET endpoint present)
}

