  const signInResponse = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(signInResponse);

  const sellerId = signInResponse.sellerId;

  // 3. Create a business verification record for the seller
  const verificationStatus = RandomGenerator.pick([
    "pending", "approved", "rejected", "reupload_required"
  ]);
  const documentFileUri = `https://files.example.com/${RandomGenerator.alphaNumeric(20)}`;
  const verificationNote = RandomGenerator.paragraph()();
  const newVerificationId = typia.random<string & tags.Format<"uuid">>();

  const updateResponse = await api.functional.shoppingMallAiBackend.seller.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: newVerificationId,
      verification_status: verificationStatus,
      document_file_uri: documentFileUri,
      note: verificationNote,
      reviewed_by: null,
      reviewed_at: null,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate,
