import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that a non-privileged customer cannot search the product-channel mapping for a product via the admin API.
 *
 * Business Context: This test ensures robust access controls over sensitive product-channel mapping operations. Only admins (or the product's authorized seller) should be able to search mappings for a product. Search attempts by unrelated actors (such as a regular customer) must result in a permission-denied error (403 Forbidden), providing evidence for audit and compliance review.
 *
 * Steps:
 * 1. Register a new customer account using the public registration API (simulates an unrelated end user).
 * 2. As this customer (not an admin), attempt to search the product-channel map for an arbitrary product via the admin endpoint.
 * 3. Confirm that the API denies the request, returning a 403 Forbidden or appropriate permission error for auditability.
 * 4. No search results should be returned to the customer, as the operation is forbidden by access control policies.
 */
export async function test_api_product_channel_map_search_no_permission(connection: api.IConnection) {
  // 1. Register a customer (unprivileged user).
  const signUpResp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpResp);

  // Switch the connection's Authorization header to use the new customer's token.
  connection.headers = {
    ...connection.headers,
    Authorization: signUpResp.setHeaders.Authorization,
  };

  // 2 & 3. Attempt forbidden search as this customer.
  await TestValidator.error("non-privileged customer cannot access admin productChannelMap search")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productChannelMap.search(connection, {
      productId: typia.random<string & tags.Format<"uuid">>(), // Arbitrary product
      body: {}, // No search filters needed
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinWallet";
import type { IPageIShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCoinWallet";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test advanced searching for coin wallets in admin panel.
 *
 * This test validates that the coin wallet search API supports advanced filtering (by wallet type, status, owner IDs) and that only admins can use this endpoint. It also tests pagination, ownership privacy, error responses for invalid filters, and proper authorization enforcement.
 *
 * 1. Attempt search as non-admin (unauthenticated) and confirm error is thrown.
 * 2. Log in as admin to get authentication token.
 * 3. Create wallets for admin, seller, and customer with different types and statuses for meaningful search conditions.
 * 4. As admin, search with filters: by wallet_type, wallet_status, or owner ID, and verify all returned wallets match the filter.
 * 5. Search with invalid filter values and confirm results are empty.
 */
export async function test_api_coin_wallet_search_with_advanced_filters(connection: api.IConnection) {
  // 1. Attempt unauthorized search as non-admin
  await TestValidator.error("unauthorized access prevented")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
      body: { limit: 5 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
    });
  });

  // 2. Admin login to acquire access token
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Test1234!";
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);

  // 3. Create admin wallet
  const adminWallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_admin_id: adminAuth.adminId,
      wallet_type: "mainnet",
      wallet_status: "active",
      wallet_address: typia.random<string>(),
      wallet_label: "Admin Wallet",
      security_code: null,
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate,
  });
  typia.assert(adminWallet);

  // 3. Create seller wallet
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const sellerWallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_seller_id: sellerId,
      wallet_type: "event",
      wallet_status: "locked",
      wallet_address: typia.random<string>(),
      wallet_label: "Seller Wallet",
      security_code: null,
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate,
  });
  typia.assert(sellerWallet);

  // 3. Create customer wallet
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const customerWallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_customer_id: customerId,
      wallet_type: "reward",
      wallet_status: "active",
      wallet_address: typia.random<string>(),
      wallet_label: "Customer Wallet",
      security_code: null,
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate,
  });
  typia.assert(customerWallet);

  // 4. Search by wallet_type
  const resByType = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_type: "mainnet", limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resByType);
  TestValidator.predicate("wallet_type filter")(resByType.data.every((w) => w.wallet_type === "mainnet"));

  // 4. Search by wallet_status
  const resByStatus = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_status: "active", limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resByStatus);
  TestValidator.predicate("wallet_status filter")(resByStatus.data.every((w) => w.wallet_status === "active"));

  // 4. Search by admin owner id
  const resByAdminId = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_owner_admin_id: adminAuth.adminId, limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resByAdminId);
  TestValidator.predicate("admin owner id filter")(resByAdminId.data.every((w) => w.wallet_owner_admin_id === adminAuth.adminId));

  // 4. Search by seller owner id
  const resBySellerId = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_owner_seller_id: sellerId, limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resBySellerId);
  TestValidator.predicate("seller owner id filter")(resBySellerId.data.every((w) => w.wallet_owner_seller_id === sellerId));

  // 4. Search by customer owner id
  const resByCustomerId = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_owner_customer_id: customerId, limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resByCustomerId);
  TestValidator.predicate("customer owner id filter")(resByCustomerId.data.every((w) => w.wallet_owner_customer_id === customerId));

  // 5. Search with invalid type filter
  const resByInvalidType = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_type: "not_a_real_type", limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resByInvalidType);
  TestValidator.equals("no wallets for invalid type")(resByInvalidType.data.length)(0);

  // 5. Search with impossible admin owner id
  const resImpossibleAdmin = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(), limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resImpossibleAdmin);
  TestValidator.equals("no wallets for impossible admin owner id")(resImpossibleAdmin.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinWallet";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin retrieval of detailed coin wallet information and access control.
 *
 * Ensures that an admin can successfully retrieve all coin wallet metadata by UUID, that returned fields match those provided at creation, and that robust error handling and access controls are enforced. Negative scenarios for querying a non-existent wallet and attempting unauthorized access are both validated as runtime errors.
 *
 * Steps:
 * 1. Admin logs in to acquire credentials.
 * 2. Admin creates a new coin wallet and records input fields.
 * 3. Admin retrieves the wallet detail by UUID and checks that all major fields match what was created.
 * 4. Attempts retrieval of a non-existent wallet (error case).
 * 5. Simulates unauthorized wallet retrieval (error case). Soft deletion is omitted due to lack of API.
 */
export async function test_api_coin_wallet_detail_retrieval_success_and_access_control(connection: api.IConnection) {
  // 1. Admin logs in to get JWT for authenticated context
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "TestPassword123!";
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);

  // 2. Admin creates a new coin wallet (as owner_admin_id)
  const walletCreateInput: IShoppingMallAiBackendCoinWallet.ICreate = {
    wallet_owner_admin_id: adminSignIn.adminId,
    wallet_type: "event",
    wallet_status: "active",
    wallet_address: typia.random<string>(),
    wallet_label: "Unit Test Wallet",
    security_code: "9287",
  };
  const createdWallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: walletCreateInput,
  });
  typia.assert(createdWallet);

  // 3. Retrieve and validate wallet details as admin
  const detail = await api.functional.shoppingMallAiBackend.admin.coinWallets.at(connection, {
    coinWalletId: createdWallet.id,
  });
  typia.assert(detail);
  TestValidator.equals("wallet id matches")(detail.id)(createdWallet.id);
  TestValidator.equals("wallet owner admin id matches")(detail.wallet_owner_admin_id)(walletCreateInput.wallet_owner_admin_id);
  TestValidator.equals("wallet type matches")(detail.wallet_type)(walletCreateInput.wallet_type);
  TestValidator.equals("wallet status matches")(detail.wallet_status)(walletCreateInput.wallet_status);
  TestValidator.equals("wallet address matches")(detail.wallet_address)(walletCreateInput.wallet_address);
  TestValidator.equals("wallet label matches")(detail.wallet_label)(walletCreateInput.wallet_label);
  TestValidator.equals("security code matches")(detail.security_code)(walletCreateInput.security_code);

  // 4. Attempt retrieval with random non-existent coinWalletId (should error)
  await TestValidator.error("error on non-existent coinWalletId")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.at(connection, {
      coinWalletId: typia.random<string & tags.Format<"uuid">>()
    });
  });

  // 5. Simulate retrieval without admin privileges (empty headers/no JWT): access should be denied
  const noAuthConnection = { ...connection, headers: {} };
  await TestValidator.error("access denied for unauthorized")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.at(noAuthConnection, {
      coinWalletId: createdWallet.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinWallet";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate creation of coin wallets via the admin API.
 *
 * This test covers:
 * 1. Ensuring admin login is required before wallet creation.
 * 2. Successful creation of coin wallets for admin, seller, and customer, each with their own permitted owner field populated.
 * 3. Uniqueness constraint on wallet_address: duplicate address should result in rejection.
 * 4. Only one wallet per (owner,type) is allowed: duplicate creation for the same (owner,type) pair should fail, even with unique address.
 * 5. Mutually exclusive owner fields: providing more than one owner field (e.g., admin and seller both set) should fail.
 * 6. Argument and data validation: all required fields enforced, proper data formats, no business rule circumvention.
 * 7. Role-based access: without admin login, creation is denied (if possible to test in SDK context).
 *
 * Steps:
 * 1. Login as admin.
 * 2. Create a valid admin coin wallet; verify output fields.
 * 3. Attempt duplicate creation by wallet_address (should fail).
 * 4. Attempt duplicate creation by (owner, type) (should fail).
 * 5. Create wallets for seller and customer scenarios.
 * 6. Attempt creation with multiple owner fields (should fail).
 * 7. (If technically feasible) Attempt without admin Authorization (should fail for unauthorized user).
 */
export async function test_api_coin_wallet_creation_success_duplicate_and_validation(connection: api.IConnection) {
  // 1. Login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SecurePassword123!";

  // Assume the admin credentials exist in system for this integration test.
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);

  // 2. Successful creation of admin wallet
  const testAddress = `coinwallet-${typia.random<string>()}`;
  const createWalletBody = {
    wallet_owner_admin_id: adminAuth.adminId,
    wallet_type: "mainnet",
    wallet_status: "active",
    wallet_address: testAddress,
    wallet_label: "Primary admin wallet",
    security_code: "4291",
  } satisfies IShoppingMallAiBackendCoinWallet.ICreate;
  const createdWallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: createWalletBody,
  });
  typia.assert(createdWallet);
  TestValidator.equals("address matches")(createdWallet.wallet_address)(testAddress);

  // 3. Attempt to create another wallet with the same address (should fail)
  await TestValidator.error("duplicate wallet_address should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
      body: {
        ...createWalletBody,
        wallet_type: "event",
        wallet_status: "locked",
      },
    });
  });

  // 4. Attempt to create another wallet with same (owner, type) (should fail)
  await TestValidator.error("duplicate owner/type should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
      body: {
        ...createWalletBody,
        wallet_address: `coinwallet-${typia.random<string>()}`,
      },
    });
  });

  // 5. Create seller and customer wallets, unique constraints per owner applied
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const customerId = typia.random<string & tags.Format<"uuid">>();
  // Seller
  const sellerWallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_seller_id: sellerId,
      wallet_type: "reward",
      wallet_status: "active",
      wallet_address: `wallet-${typia.random<string>()}`,
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate,
  });
  typia.assert(sellerWallet);
  // Customer
  const customerWallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_customer_id: customerId,
      wallet_type: "event",
      wallet_status: "locked",
      wallet_address: `wallet-${typia.random<string>()}`,
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate,
  });
  typia.assert(customerWallet);

  // 6. Mutually exclusive owner fields: double owners should fail
  await TestValidator.error("owner field conflict should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
      body: {
        wallet_owner_admin_id: adminAuth.adminId,
        wallet_owner_seller_id: sellerId,
        wallet_type: "reward",
        wallet_status: "active",
        wallet_address: `wallet-${typia.random<string>()}`,
      },
    });
  });

  // 7. (Optional/if technically feasible): without admin Authorization should fail
  // If SDK allows disconnecting/removing Authorization, simulate here – else, skip per system constraints.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinWallet";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate update and permission logic for coin wallet updates (admin endpoint).
 *
 * This test ensures only allowed fields (wallet_status, wallet_label, security_code) of an admin-owned coin wallet are mutable and that update attempts on immutable fields (wallet_address, owner references) fail. It also verifies admin-only role access, update on non-existent and deleted wallets, and correct audit trail field behavior.
 *
 * Steps:
 * 1. Authenticate as admin (via /auth/admin/login)
 * 2. Create a coin wallet (with admin ownership, via /shoppingMallAiBackend/admin/coinWallets)
 * 3. Update allowed mutable fields (status, label, security_code) – verify update
 * 4. Attempt to update forbidden/immutable fields (simulate as business logic, expect server error)
 * 5. Attempt to update a non-existent wallet – expect not found/error
 * 6. Simulate deleted wallet then attempt update – expect error
 * 7. Verify audit trail behavior (updated_at > created_at)
 */
export async function test_api_coin_wallet_update_valid_and_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPW_!234";
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 2. Create a coin wallet (admin ownership)
  const createBody: IShoppingMallAiBackendCoinWallet.ICreate = {
    wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(),
    wallet_type: "mainnet",
    wallet_status: "active",
    wallet_address: typia.random<string>(),
    wallet_label: "Initial Coin Wallet",
    security_code: "1234",
  };
  const created = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, { body: createBody });
  typia.assert(created);
  TestValidator.equals("create fields match")(created.wallet_owner_admin_id)(createBody.wallet_owner_admin_id);
  TestValidator.equals("wallet_type match")(created.wallet_type)(createBody.wallet_type);
  TestValidator.equals("wallet_status match")(created.wallet_status)(createBody.wallet_status);
  TestValidator.equals("wallet_address match")(created.wallet_address)(createBody.wallet_address);
  TestValidator.equals("wallet_label match")(created.wallet_label)(createBody.wallet_label);
  TestValidator.equals("security_code match")(created.security_code)(createBody.security_code);

  // 3. Update allowed/mutable fields
  const updateBody: IShoppingMallAiBackendCoinWallet.IUpdate = {
    wallet_status: "locked",
    wallet_label: "Updated label",
    security_code: "9999",
  };
  const updated = await api.functional.shoppingMallAiBackend.admin.coinWallets.update(connection, {
    coinWalletId: created.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("status changed")(updated.wallet_status)(updateBody.wallet_status);
  TestValidator.equals("label changed")(updated.wallet_label)(updateBody.wallet_label);
  TestValidator.equals("security_code changed")(updated.security_code)(updateBody.security_code);
  TestValidator.equals("address unchanged")(updated.wallet_address)(created.wallet_address);
  TestValidator.equals("owner ID unchanged")(updated.wallet_owner_admin_id)(created.wallet_owner_admin_id);

  // 4. Attempt to update immutable fields (simulate forbidden change logic)
  await TestValidator.error("immutable fields cannot be updated")(async () => {
    // Even though TypeScript doesn't let us send forbidden fields, simulate bad API payload as any
    await api.functional.shoppingMallAiBackend.admin.coinWallets.update(connection, {
      coinWalletId: created.id,
      body: {
        wallet_status: "active",
        wallet_address: typia.random<string>(), // forbidden
        wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(), // forbidden
      } as any,
    });
  });

  // 5. Attempt update of non-existent wallet
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("update on non-existent wallet fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.update(connection, {
      coinWalletId: randomId,
      body: updateBody,
    });
  });

  // 6. Simulate deleted wallet then try update (since no real delete, just try new wallet update expecting error for deleted_at logic)
  const toDelete = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, { body: { ...createBody, wallet_address: typia.random<string>() } });
  typia.assert(toDelete);
  // (If the API let us flag deleted_at, we'd set it and expect rejection. Here, just expect logic error for possibly soft-deleted wallets)
  await TestValidator.error("update on deleted wallet fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.update(connection, {
      coinWalletId: toDelete.id,
      body: updateBody,
    });
  });

  // 7. Verify audit trail works (updated_at should increase on successful update)
  TestValidator.predicate("updated_at advanced")(new Date(updated.updated_at).getTime() > new Date(updated.created_at).getTime());
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
