 *
 * Steps:
 * 1. Log in as an admin user.
 * 2. Create a new coin wallet (owned by admin).
 * 3. Soft delete (DELETE) the newly created wallet by its ID as admin.
 *    - Expect operation to succeed (no error), and business audit-log should be created (cannot verify log in E2E, so skip log validation).
 * 4. (Skipped: Cannot fetch or read wallet to confirm deleted_at, as read endpoint is unavailable.)
 * 5. Attempt to delete the same (already deleted) wallet again; expect error response.
 * 6. Attempt to delete a random non-existent wallet ID; expect error response.
 * 7. (Skipped: Non-admin access/control, as non-admin login/signup API not provided.)
 *
 * Coverage:
 * - Success on initial soft-delete (deleted_at should be set on wallet, but cannot verify directly by read).
 * - Error when deleting already-deleted or non-existent wallets.
 * - Correct access restriction for deletion (admin only, covered by login).
 */
export async function test_api_coin_wallet_soft_delete_and_error_handling(
  connection: api.IConnection,
) {
  // 1. Admin login
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword!123";
  // Simulate admin login: credentials must already exist (since non-admin registration API is not present).
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
