        body: {
          product_id: product.id,
          snapshot_code: "", // required, but invalid (should not be empty)
          snapshot_type: "", // required, but invalid (should not be empty)
          name: "", // required, but invalid (should not be empty)
          status: "", // required, but invalid (should not be empty)
        } as IShoppingMallAiBackendProductSnapshot.ICreate,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSnapshot";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that an admin user can successfully create a product snapshot for any product, regardless of product ownership (including foreign products).
 *
 * Business context:
 * This test simulates a workflow in which an admin user is required to create and persist a snapshot for the product of a seller—verifying that admins have the authority to act independently of ownership constraints, and that audit/integrity fields (like created_at) are correctly set for compliance verification.
 *
 * Step-by-step test process:
 * 1. Register a new seller with all required credentials.
 * 2. As the seller, create a new product with business-accurate fields.
 * 3. Register and authenticate as an admin.
 * 4. As admin, create a product snapshot for the product just created (using correct productId and evidence fields).
 * 5. Validate all business and audit fields of the snapshot response.
 */
export async function test_api_product_snapshot_creation_success_by_admin(connection: api.IConnection) {
  // 1. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Passw0rd!";
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphabets(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUp);

  // 2. Create product as seller
  const productCreate = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerSignUp.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productCreate);

  // 3. Register as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminP@ss123";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 4. Create product snapshot as admin for the seller's product
  const snapshotCode = RandomGenerator.alphaNumeric(10);
  const snapshotType = "created";
  const snapshotName = productCreate.name + " - Initial Snapshot";
  const snapshotDescription = productCreate.description || null;

  const snapshot = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.create(connection, {
    productId: productCreate.id,
    body: {
      product_id: productCreate.id,
      snapshot_code: snapshotCode,
      snapshot_type: snapshotType,
      name: snapshotName,
      description: snapshotDescription,
      main_image_uri: null,
      status: productCreate.status,
    } satisfies IShoppingMallAiBackendProductSnapshot.ICreate,
  });
  typia.assert(snapshot);

  // 5. Response validation
  TestValidator.equals("product_id matches")(snapshot.product_id)(productCreate.id);
  TestValidator.equals("snapshot_code matches")(snapshot.snapshot_code)(snapshotCode);
  TestValidator.equals("snapshot_type matches")(snapshot.snapshot_type)(snapshotType);
  TestValidator.equals("name matches")(snapshot.name)(snapshotName);
  TestValidator.equals("description matches")(snapshot.description)(snapshotDescription);
  TestValidator.equals("status matches")(snapshot.status)(productCreate.status);
  TestValidator.predicate("created_at is ISO8601")(typeof snapshot.created_at === "string" && !isNaN(Date.parse(snapshot.created_at)));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSnapshot";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that creating a product snapshot by an admin fails with a validation error when required evidence fields are missing or contain invalid data.
 *
 * This tests the integrity of compliance and rollback traceability in the snapshot system for the shopping mall backend admin API.
 * Ensures the system does not allow persisting an incomplete or corrupted product snapshot by admin intervention, and that errors are properly surfaced and audited.
 *
 * Steps:
 * 1. Register a new admin account (and receive JWT for session).
 * 2. Register a new seller account (to create a seller-owned product for snapshotting).
 * 3. Seller creates a product using correct/valid fields.
 * 4. Switch session (authenticate) to admin using JWT headers.
 * 5. Attempt to create a product snapshot for the product, but deliberately omit required fields (e.g., missing snapshot_code or name) or use invalid values per schema.
 * 6. Expect API to return a validation error: request fails, no snapshot is created. Ensure API does NOT return a successful response.
 *
 * Note: Only steps for which SDK and DTOs exist have been implemented. Assumes the platform enforces field-level validation on the admin snapshot endpoint.
 */
export async function test_api_product_snapshot_creation_admin_validation_error(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234qwer!";
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);

  // 2. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "zxcv1234!";
  const seller = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: "Test Seller",
      businessNumber: "1234567890",
      representativeName: "Alice Seller",
      address: "12345 Test Avenue, Seoul",
      phone: "010-1234-5678",
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(seller);

  // 3. Seller creates a valid product
  connection.headers = { ...connection.headers, Authorization: seller.setHeaders.Authorization };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: seller.sellerId,
      code: "PRD" + Math.floor(Math.random() * 100000),
      name: "Test Product",
      status: "draft",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 4. Switch session to admin by restoring admin's JWT header
  connection.headers = { ...connection.headers, Authorization: admin.setHeaders.Authorization };

  // 5. Attempt product snapshot creation with invalid fields (missing required 'snapshot_code')
  await TestValidator.error("should throw validation error for missing required snapshot_code")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.create(connection, {
        productId: product.id,
        body: {
          // snapshot_code is omitted on purpose
          snapshot_type: "created",
          name: product.name,
          status: product.status,
        } as any,
      });
    },
  );

  // 6. Attempt with invalid field types (e.g., invalid uuid for product_id)
  await TestValidator.error("should throw validation error for invalid product_id format")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.create(connection, {
        productId: "invalid-uuid-format" as any,
        body: {
          product_id: "invalid-uuid-format" as any,
          snapshot_code: "snap-err-001",
          snapshot_type: "created",
          name: product.name,
          status: product.status,
        } satisfies IShoppingMallAiBackendProductSnapshot.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSnapshot";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test that a seller can update allowable metadata fields for their product snapshot.
 *
 * This test ensures that sellers are able to update certain mutable metadata (like description or status) for a product snapshot on a product they own, while core immutable evidence fields are preserved. This covers the business policy around evidence/audit and product lifecycle compliance.
 *
 * Steps:
 * 1. Register a seller account.
 * 2. Create a product belonging to that seller.
 * 3. Create an initial snapshot for that product.
 * 4. Update the snapshot's allowed metadata fields (e.g., description, status).
 * 5. Verify that only those fields are updated, core evidence fields remain unchanged, and the response accurately reflects changes. Also confirm that audit/history preservation aligns with business expectations (e.g., immutable fields not changed).
 */
export async function test_api_product_snapshot_update_metadata_by_seller(connection: api.IConnection) {
  // 1. Register a seller
  const signUpInput: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Testpassword123!",
    companyName: RandomGenerator.name(),
    businessNumber: ArrayUtil.repeat(10)(() => `${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<9>>()}`).join(""),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile(),
  };
  const sellerAuth = await api.functional.auth.seller.register.signUp(connection, { body: signUpInput });
  typia.assert(sellerAuth);
  TestValidator.equals("email matches")(sellerAuth.email)(signUpInput.email);
  const sellerId = sellerAuth.sellerId;

  // 2. Create a product for this seller
  const productInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: sellerId,
    code: ArrayUtil.repeat(8)(() => RandomGenerator.alphaNumeric(1)).join("").toUpperCase(),
    name: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
    main_image_uri: `https://cdn.example.com/product-images/${typia.random<string & tags.Format<"uuid">>()}.jpg`,
    status: "draft",
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: productInput });
  typia.assert(product);
  TestValidator.equals("seller_id")(product.seller_id)(sellerId);

  // 3. Create a snapshot of the product
  const snapshotInput: IShoppingMallAiBackendProductSnapshot.ICreate = {
    product_id: product.id,
    snapshot_code: `SNAP${ArrayUtil.repeat(4)(() => RandomGenerator.alphaNumeric(1)).join("")}`,
    snapshot_type: "created",
    name: product.name,
    description: product.description,
    main_image_uri: product.main_image_uri,
    status: product.status,
  };
  const snapshot = await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.create(connection, { productId: product.id, body: snapshotInput });
  typia.assert(snapshot);
  TestValidator.equals("productId")(snapshot.product_id)(product.id);

  // 4. Update snapshot's mutable metadata (description and status)
  const updateInput: IShoppingMallAiBackendProductSnapshot.IUpdate = {
    description: RandomGenerator.content()()(),
    status: "approved",
  };
  const updatedSnapshot = await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.update(connection, {
    productId: product.id,
    productSnapshotId: snapshot.id,
    body: updateInput
  });
  typia.assert(updatedSnapshot);
  // 5. Validate metadata update and evidence field immutability
  TestValidator.equals("updated description")(updatedSnapshot.description)(updateInput.description);
  TestValidator.equals("updated status")(updatedSnapshot.status)(updateInput.status);
  // Core immutable fields remain unchanged
  TestValidator.equals("snapshot_code unchanged")(updatedSnapshot.snapshot_code)(snapshot.snapshot_code);
  TestValidator.equals("snapshot_type unchanged")(updatedSnapshot.snapshot_type)(snapshot.snapshot_type);
  TestValidator.equals("name unchanged")(updatedSnapshot.name)(snapshot.name);
  TestValidator.equals("main_image_uri unchanged")(updatedSnapshot.main_image_uri)(snapshot.main_image_uri);
  TestValidator.equals("product_id unchanged")(updatedSnapshot.product_id)(snapshot.product_id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSnapshot";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Verify that a seller cannot update a product snapshot they do not own (ownership enforcement, 403 forbidden).
 *
 * This test simulates two sellers: Seller A (the owner) and Seller B (non-owner). Seller A creates a product and a snapshot. Seller B then attempts to update Seller A's product snapshot, which must be forbidden by the platform.
 *
 * **Test Process:**
 * 1. Register Seller A (who will create the product & snapshot)
 * 2. Register Seller B (who will attempt the unauthorized update)
 * 3. Seller A creates a product
 * 4. Seller A creates a product snapshot
 * 5. Seller B attempts to update Seller A's snapshot (should receive 403)
