/**
 * Validate successful retrieval of channel section details by admin.
 *
 * This test ensures that an authenticated admin can successfully fetch the complete details of a section within a channel using its channelId and sectionId. It verifies the inclusion and correctness of all significant business fields, audit and relational metadata, and validates the non-deleted state. The scenario represents core admin capabilities for managing channel curation flows.
 *
 * Step-by-step process:
 * 1. Register a new admin and authenticate. 
 * 2. As the admin, create a new business channel.
 * 3. Create a new section within the created channel (with this admin as creator).
 * 4. Retrieve the section via GET using both channelId and sectionId as path params.
 * 5. Assert all business fields, audit fields, relational metadata, nullability, and ISO date/time format are accurate.
 */
export async function test_api_channel_section_detail_success(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassw0rd!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminSignUp);
  // After registration, Authorization header is set in connection; use adminId for object creation
  const adminId = adminSignUp.adminId;

  // 2. Create a new business channel using this admin's ID as creator
  const channelInput: IShoppingMallAiBackendChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.name(),
    created_by_admin_id: adminId,
    description: RandomGenerator.paragraph()(),
    logo_url: null,
    active: true
  };
  const channel = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: channelInput
  });
  typia.assert(channel);

  // 3. Create a new section in the created channel as this admin
  const sectionInput: IShoppingMallAiBackendSection.ICreate = {
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    visible: true,
    channel_id: channel.id,
    created_by_admin_id: adminId
  };
  const section = await api.functional.shoppingMallAiBackend.admin.channels.sections.createSection(connection, {
    channelId: channel.id,
    body: sectionInput
  });
  typia.assert(section);

  // 4. Retrieve the section details by channelId and sectionId (admin-only route)
  const fetched = await api.functional.shoppingMallAiBackend.admin.channels.sections.at(connection, {
    channelId: channel.id,
    sectionId: section.id
  });
  typia.assert(fetched);

  // 5. Assert all business fields and audit/relational metadata
  TestValidator.equals("section.id matches")(fetched.id)(section.id);
  TestValidator.equals("channel_id matches")(fetched.channel_id)(sectionInput.channel_id);
  TestValidator.equals("created_by_admin_id matches")(fetched.created_by_admin_id)(sectionInput.created_by_admin_id);
  TestValidator.equals("code matches")(fetched.code)(sectionInput.code);
  TestValidator.equals("name matches")(fetched.name)(sectionInput.name);
  TestValidator.equals("description matches")(fetched.description)(sectionInput.description);
  TestValidator.equals("display_order matches")(fetched.display_order)(sectionInput.display_order);
  TestValidator.equals("visible matches")(fetched.visible)(sectionInput.visible);
  // Check audit and metadata fields are well-formed ISO date strings
  TestValidator.predicate("created_at is ISO8601")(/\d{4}-\d{2}-\d{2}T\d{2}:/i.test(fetched.created_at));
  TestValidator.predicate("updated_at is ISO8601")(/\d{4}-\d{2}-\d{2}T\d{2}:/i.test(fetched.updated_at));
  // Section should not be deleted
  TestValidator.equals("deleted_at is null or undefined")((fetched.deleted_at ?? null))(null);
}

