import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendComplianceEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceEvent";
import type { IShoppingMallAiBackendComplianceSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceSnapshot";

/**
 * Validates admin ability to update metadata or evidence payload of a compliance snapshot.
 *
 * Business context:
 * - Compliance snapshots are attached to compliance events for audit, regulatory, and forensics.
 * - Only admins are permitted to create/update compliance events/snapshots.
 * - All changes are subject to audit; core evidence payload is generally immutable except when explicitly updated and logged.
 *
 * Workflow:
 * 1. Create a compliance event as admin (with valid event type, actor, target).
 * 2. Create a compliance snapshot attached to this event.
 * 3. Update allowed metadata and evidence fields of the snapshot (demonstrate change).
 * 4. Assert all updated fields match what was sent, and key immutable fields (such as compliance_event_id) remain unchanged.
 */
export async function test_api_compliance_event_snapshot_update_success(connection: api.IConnection) {
  // 1. Create a compliance event
  const complianceEvent = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
    body: {
      event_type: "policy_update",
      actor_id: null, // System-initiated example for audit
      actor_type: "admin",
      target_type: "order",
      target_id: typia.random<string & tags.Format<"uuid">>(),
      event_payload: JSON.stringify({ policy: "shipping_delay", old: "2d", new: "5d" })
    } satisfies IShoppingMallAiBackendComplianceEvent.ICreate
  });
  typia.assert(complianceEvent);

  // 2. Attach a compliance snapshot under the event
  const originalSnapshotPayload = JSON.stringify({ orderId: typia.random<string & tags.Format<"uuid">>(), status: "pending" });
  const complianceSnapshot = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.create(connection, {
    complianceEventId: complianceEvent.id,
    body: {
      compliance_event_id: complianceEvent.id,
      entity_type: "order",
      entity_id: complianceEvent.target_id ?? null,
      snapshot_payload: originalSnapshotPayload,
    } satisfies IShoppingMallAiBackendComplianceSnapshot.ICreate
  });
  typia.assert(complianceSnapshot);

  // 3. Update metadata/evidence fields of the snapshot
  const updatedPayload: IShoppingMallAiBackendComplianceSnapshot.IUpdate = {
    entity_type: "order_amended",
    entity_id: complianceEvent.target_id ?? null,
    snapshot_payload: JSON.stringify({ orderId: typia.random<string & tags.Format<"uuid">>(), previousStatus: "pending", currentStatus: "delivered", note: "audit annotation" })
  };

  const updatedSnapshot = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.update(connection, {
    complianceEventId: complianceEvent.id,
    complianceSnapshotId: complianceSnapshot.id,
    body: updatedPayload,
  });
  typia.assert(updatedSnapshot);

  // 4. Validate updated fields and immutables
  TestValidator.equals("entity_type updated")(updatedSnapshot.entity_type)(updatedPayload.entity_type);
  TestValidator.equals("entity_id updated")(updatedSnapshot.entity_id)(updatedPayload.entity_id);
  TestValidator.equals("snapshot_payload updated")(updatedSnapshot.snapshot_payload)(updatedPayload.snapshot_payload);
  TestValidator.equals("compliance_event_id constant")(updatedSnapshot.compliance_event_id)(complianceEvent.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendComplianceEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceEvent";
import type { IShoppingMallAiBackendComplianceSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceSnapshot";

/**
 * Validate soft deletion (logical removal) of a compliance snapshot by admin.
 *
 * This test verifies that an admin can create a compliance event and attach a snapshot, then soft-delete (logically remove) the snapshot. The test confirms:
 * - Soft delete can be performed by admin for a compliance snapshot, using event and snapshot IDs.
 * - Attempting to delete the same snapshot again, or a non-existent snapshot, fails as expected (error is thrown).
 *
 * Due to lack of a listing endpoint for compliance snapshots, the test cannot directly confirm logical exclusion from active queries, but ensures all deletions complete and errors are properly thrown for invalid or duplicate operations.
 *
 * **Workflow:**
 * 1. Create a compliance event required for snapshot.
 * 2. Attach a compliance snapshot to the event.
 * 3. Perform soft deletion (logical remove) on the snapshot.
 * 4. Attempt to delete same snapshot again (should fail).
 * 5. Attempt to delete a random, non-existent snapshot (should fail).
 */
export async function test_api_compliance_event_snapshot_delete_soft_delete(
  connection: api.IConnection,
) {
  // 1. Create a compliance event (admin workflow)
  const event = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
    body: {
      event_type: "policy_update",
      actor_id: null,
      actor_type: "admin",
      target_type: "order",
      target_id: null,
      event_payload: JSON.stringify({ action: "policy update for test" }),
    } satisfies IShoppingMallAiBackendComplianceEvent.ICreate,
  });
  typia.assert(event);

  // 2. Attach a compliance snapshot to event
  const snapshot = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.create(connection, {
    complianceEventId: event.id,
    body: {
      compliance_event_id: event.id,
      entity_type: "order",
      entity_id: null,
      snapshot_payload: JSON.stringify({ beforeState: "evidence for snapshot deletion test" }),
    } satisfies IShoppingMallAiBackendComplianceSnapshot.ICreate,
  });
  typia.assert(snapshot);

  // 3. Perform soft deletion (logical removal) as admin
  await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.erase(
    connection,
    {
      complianceEventId: event.id,
      complianceSnapshotId: snapshot.id,
    },
  );

  // 4. Attempt to soft-delete again (should error)
  await TestValidator.error("Delete already-deleted compliance snapshot should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.erase(
        connection,
        {
          complianceEventId: event.id,
          complianceSnapshotId: snapshot.id,
        },
      );
    },
  );

  // 5. Attempt to delete a non-existent snapshot
  const fakeSnapshotId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Delete non-existent compliance snapshot should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.erase(
        connection,
        {
          complianceEventId: event.id,
          complianceSnapshotId: fakeSnapshotId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
