/**
 * Validate retrieval of compliance snapshot details by id (admin access).
 *
 * Tests point-in-time audit/evidence retrieval of a compliance snapshot as an admin user, ensuring both correct data-fidelity (success) and robust error handling (not-found for non-existent id). The process covers:
 *
 * 1. Create a compliance event (admin as actor, arbitrary target entity, and metadata/payload for audit).
 * 2. Create/attach a compliance snapshot linked to the event with a full evidence payload and concrete entity context.
 * 3. Retrieve the created snapshot by id. Fully validate all properties: id, compliance_event_id, entity_type, entity_id, snapshot_payload, and created_at—ensuring content matches and evidence chain is preserved.
 * 4. Attempt retrieval of a non-existent snapshot id to confirm system returns a not-found error (negative test scenario).
 *
 * This validates both audit trace data integrity for compliance purposes and robustness of error reporting in the compliance snapshot retrieval API. Type assertions are performed for all outputs, and business values are checked via TestValidator, per scenario plan.
 */
export async function test_api_compliance_snapshot_detail_retrieval(
  connection: api.IConnection
) {
  // 1. Create a compliance event (admin action, minimal input for traceability)
  const eventInput = {
    event_type: "policy_update",
    actor_type: "admin",
    target_type: "customer",
    event_payload: JSON.stringify({ reason: "GDPR update", details: "Test policy update event" }),
  } satisfies IShoppingMallAiBackendComplianceEvent.ICreate;
  const event = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, { body: eventInput });
  typia.assert(event);

  // 2. Attach a compliance snapshot to the event (concrete entity and evidence payload)
  const concreteEntityId = typia.random<string & tags.Format<"uuid">>();
  const snapshotInput = {
    compliance_event_id: event.id,
    entity_type: "customer",
    entity_id: concreteEntityId,
    snapshot_payload: JSON.stringify({ before: {}, after: { status: "compliant" } }),
  } satisfies IShoppingMallAiBackendComplianceSnapshot.ICreate;
  const snapshot = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.create(connection, {
    complianceEventId: event.id,
    body: snapshotInput,
  });
  typia.assert(snapshot);

  // 3. Retrieve the snapshot by id and fully validate details
  const snapshotDetail = await api.functional.shoppingMallAiBackend.admin.complianceSnapshots.at(connection, {
    complianceSnapshotId: snapshot.id,
  });
  typia.assert(snapshotDetail);
  TestValidator.equals("compliance_event_id")(snapshotDetail.compliance_event_id)(snapshot.compliance_event_id);
  TestValidator.equals("entity_type")(snapshotDetail.entity_type)(snapshot.entity_type);
  TestValidator.equals("entity_id")(snapshotDetail.entity_id)(snapshot.entity_id);
  TestValidator.equals("snapshot_payload")(snapshotDetail.snapshot_payload)(snapshot.snapshot_payload);
  TestValidator.equals("created_at")(snapshotDetail.created_at)(snapshot.created_at);

  // 4. Attempt to retrieve a non-existent snapshot (should throw not-found error)
  await TestValidator.error("non-existent snapshot fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.complianceSnapshots.at(connection, {
      complianceSnapshotId: typia.random<string & tags.Format<"uuid">>()
    });
  });
}

