/**
 * E2E test for searching and paginating business rules as an admin.
 *
 * This test validates the admin search endpoint for business rules, covering filtering, pagination, permissions,
 * and error handling.
 *
 * Steps:
 * 1. Create at least two distinct business rules using the admin create endpoint. Each uses different values for code, description, and status.
 * 2. Search by rule_code to confirm only the matching rule is returned.
 * 3. Search by enforcement_status to confirm only matching statuses appear.
 * 4. Paginate with page_size=1 to confirm pagination works and total record count is accurate.
 * 5. Try search filters that yield zero results (nonexistent code).
 * 6. Pass malformed filters (e.g., bad date strings) to validate error handling (if supported by implementation).
 * 7. Attempt search as a non-admin (simulate with stripped headers or a fresh connection) to confirm permission error is thrown.
 */
export async function test_api_business_rules_search_and_filter(connection: api.IConnection) {
  // 1. Create two distinct business rules as admin
  const now = new Date().toISOString();
  const rule1 = await api.functional.shoppingMallAiBackend.admin.businessRules.create(connection, {
    body: {
      rule_code: `RULE_${RandomGenerator.alphabets(6)}`,
      rule_description: `Compliance requirement A - ${RandomGenerator.content()()()}`,
      enforcement_status: "active",
      reason_for_change: null,
      effective_from: now,
      effective_to: null
    } satisfies IShoppingMallAiBackendBusinessRule.ICreate
  });
  typia.assert(rule1);

  const rule2 = await api.functional.shoppingMallAiBackend.admin.businessRules.create(connection, {
    body: {
      rule_code: `RULE_${RandomGenerator.alphabets(6)}`,
      rule_description: `Technical sunset; keyword: SpecialX - ${RandomGenerator.content()()()}`,
      enforcement_status: "retired",
      reason_for_change: "Sunset per annual audit",
      effective_from: now,
      effective_to: null
    } satisfies IShoppingMallAiBackendBusinessRule.ICreate
  });
  typia.assert(rule2);

  // 2. Search by rule_code (should only match rule1)
  const searchByCode = await api.functional.shoppingMallAiBackend.admin.businessRules.search(connection, {
    body: {
      rule_code: rule1.rule_code
    } satisfies IShoppingMallAiBackendBusinessRule.IRequest
  });
  typia.assert(searchByCode);
  TestValidator.equals("rule_code search count")(searchByCode.data.length)(1);
  TestValidator.equals("rule_code match")(searchByCode.data[0].id)(rule1.id);

  // 3. Search by enforcement_status (should match only rule1 for "active")
  const searchByStatus = await api.functional.shoppingMallAiBackend.admin.businessRules.search(connection, {
    body: {
      enforcement_status: "active"
    } satisfies IShoppingMallAiBackendBusinessRule.IRequest
  });
  typia.assert(searchByStatus);
  TestValidator.predicate("status filter includes rule1 only")(
    searchByStatus.data.some(r => r.id === rule1.id)
  );
  TestValidator.predicate("status filter excludes retired")(
    searchByStatus.data.every(r => r.enforcement_status === "active")
  );

  // 4. Paginate with page_size=1
  const pageSearch = await api.functional.shoppingMallAiBackend.admin.businessRules.search(connection, {
    body: {
      page: 1,
      page_size: 1
    } satisfies IShoppingMallAiBackendBusinessRule.IRequest
  });
  typia.assert(pageSearch);
  TestValidator.equals("page_size=1")(pageSearch.data.length)(1);
  TestValidator.predicate("pagination records >= 2")(pageSearch.pagination.records >= 2);

  // 5. Filter yields empty set
  const empty = await api.functional.shoppingMallAiBackend.admin.businessRules.search(connection, {
    body: {
      rule_code: "NOT_FOUND_CODE_123"
    } satisfies IShoppingMallAiBackendBusinessRule.IRequest
  });
  typia.assert(empty);
  TestValidator.equals("empty results")(empty.data.length)(0);

  // 6. Malformed filter: bad effective_from date
  await TestValidator.error("malformed date param should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.businessRules.search(connection, {
      body: {
        effective_from: "bad-date" as any
      } satisfies IShoppingMallAiBackendBusinessRule.IRequest
    });
  });

  // 7. Attempt search as non-admin (simulate by stripping headers)
  const unauthConnection = { ...connection, headers: {} };
  await TestValidator.error("non-admin permission denied")(async () => {
    await api.functional.shoppingMallAiBackend.admin.businessRules.search(unauthConnection, {
      body: {} as IShoppingMallAiBackendBusinessRule.IRequest
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Validate that after registering and authenticating as a customer, the user is able to create an order and then fetch its detailed information by orderId, ensuring access control and correct data integrity.
 *
 * 1. Register a new customer account
 * 2. Log in as the new customer to obtain JWT
 * 3. Create an order associated with the customer
 * 4. Fetch the order detail using the orderId
 * 5. Assert that the fetched order fields exactly match those returned upon creation and belong to the authenticated customer
 * 6. Ensure sensitive fields are available as per customer access policy.
 */
export async function test_api_customer_order_detail_success_owner(connection: api.IConnection) {
  // 1. Register a new customer account
  const signUpInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "pass1234!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphaNumeric(8),
    phone: RandomGenerator.mobile(),
  } satisfies ICustomerSignUp.Request;
  const signUp = await api.functional.auth.customer.register.signUp(connection, { body: signUpInput });
  typia.assert(signUp);
  const customer = signUp.customer;
  TestValidator.equals("registered email matches")(customer.email)(signUpInput.email);

  // 2. Log in as that customer (mainly to trigger any login history/audit logic and refresh token if needed)
  const loginResponse = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: signUpInput.email,
      password: signUpInput.password,
    } satisfies ICustomerSignIn.Request,
  });
  typia.assert(loginResponse);
  TestValidator.equals("login email matches")(loginResponse.customer.email)(signUpInput.email);

  // 3. Create an order associated with this customer
  const orderCreateInput = {
    customer_id: customer.id,
    order_number: RandomGenerator.alphaNumeric(10),
    total_amount: typia.random<number>(),
    currency_code: "USD",
    current_status: "created",
    // optional fields set as null
    order_group_id: null,
    note: null,
  } satisfies IShoppingMallAiBackendOrder.ICreate;

  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderCreateInput });
  typia.assert(order);

  // 4. Retrieve full detail via GET /shoppingMallAiBackend/customer/orders/{orderId}
  const loadedOrder = await api.functional.shoppingMallAiBackend.customer.orders.at(connection, { orderId: order.id });
  typia.assert(loadedOrder);

  // 5. Assert that all primitive fields of response match the original order creation
  TestValidator.equals("order.id matches")(loadedOrder.id)(order.id);
  TestValidator.equals("order.customer_id matches")(loadedOrder.customer_id)(customer.id);
  TestValidator.equals("order.order_number matches")(loadedOrder.order_number)(orderCreateInput.order_number);
  TestValidator.equals("order.total_amount matches")(loadedOrder.total_amount)(orderCreateInput.total_amount);
  TestValidator.equals("order.currency_code matches")(loadedOrder.currency_code)(orderCreateInput.currency_code);
  TestValidator.equals("order.current_status matches")(loadedOrder.current_status)(orderCreateInput.current_status);
  TestValidator.equals("order.order_group_id matches")(loadedOrder.order_group_id)(orderCreateInput.order_group_id);
  TestValidator.equals("order.note matches")(loadedOrder.note)(orderCreateInput.note);

  // 6. Validate audit fields are present (created_at, updated_at, deleted_at can be checked for existence/format)
  TestValidator.predicate("created_at is ISO string")(typeof loadedOrder.created_at === "string" && !isNaN(Date.parse(loadedOrder.created_at)));
  TestValidator.predicate("updated_at is ISO string")(typeof loadedOrder.updated_at === "string" && !isNaN(Date.parse(loadedOrder.updated_at)));
  // deleted_at should be null or undefined for active order
  TestValidator.predicate("deleted_at is null or undefined")(loadedOrder.deleted_at === null || loadedOrder.deleted_at === undefined);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Validates that customers are prevented from accessing order details they do not own.
 *
 * This test ensures access control by confirming that a customer can only view their own order details. Two customers are created; the first creates an order, and the second attempts to access the first customer's order, which should result in a forbidden error.
 *
 * Step-by-step process:
 * 1. Register customer #1 and authenticate (capture their token).
 * 2. Register customer #2 and authenticate (capture their token).
 * 3. Using customer #1's connection, create an order. Store its orderId.
 * 4. Attempt to retrieve the order by orderId using customer #2's connection (switch token).
 * 5. Confirm that the request fails with a forbidden error (do not validate specific error message, just assert error occurs).
 */
export async function test_api_customer_order_detail_forbidden_not_owner(connection: api.IConnection) {
  // 1. Register customer #1
  const customer1Email = typia.random<string & tags.Format<"email">>();
  const customer1Password = "Test1234!";
  const customer1Reg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer1Email,
      password: customer1Password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customer1Reg);

  // 2. Register customer #2
  const customer2Email = typia.random<string & tags.Format<"email">>();
  const customer2Password = "Test1234!";
  const customer2Reg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer2Email,
      password: customer2Password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customer2Reg);

  // 3. Login as customer #1 (to ensure a clean authentication)
  const loginCustomer1 = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customer1Email,
      password: customer1Password,
    },
  });
  typia.assert(loginCustomer1);

  // 4. Create order as customer #1
  const orderInput: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: loginCustomer1.customer.id,
    order_number: RandomGenerator.alphaNumeric(16),
    total_amount: typia.random<number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<1000000>>(),
    currency_code: "USD",
    current_status: "created",
  };
  const createdOrder = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: orderInput,
  });
  typia.assert(createdOrder);

  // 5. Login as customer #2 to override the connection/session
  const loginCustomer2 = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customer2Email,
      password: customer2Password,
    },
  });
  typia.assert(loginCustomer2);

  // 6. Attempt to fetch customer #1's order as customer #2. This should fail with forbidden error
  await TestValidator.error("customer #2 should not access order #1's detail")(async () => {
    await api.functional.shoppingMallAiBackend.customer.orders.at(connection, {
      orderId: createdOrder.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Test that requesting a customer order detail with a non-existent orderId returns a not found error.
 *
 * This scenario ensures that when a customer attempts to fetch an order that does not exist in the database, the API returns an appropriate error (typically a 404 Not Found or similar business error) and does not accidentally leak data or succeed with invalid input.
 *
 * Steps:
 * 1. Register a new customer account to establish a valid API context and acquire a JWT.
 * 2. Log the customer in (if not already authenticated by registration response) to ensure Authorization header is present for subsequent requests.
 * 3. Attempt to fetch the details of a customer order using a random (guaranteed non-existent) UUID as the orderId path parameter.
 * 4. Validate that the API returns a not found error (e.g., 404), and does not return any order entity data.
 */
export async function test_api_customer_order_detail_not_found(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "test1234!";
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });

  // 2. Log in to ensure token is present (may replace previous Authorization if needed)
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies ICustomerSignIn.Request,
  });

  // 3. Attempt to fetch a non-existent order
  const nonExistentOrderId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("order not found error")(() =>
    api.functional.shoppingMallAiBackend.customer.orders.at(connection, {
      orderId: nonExistentOrderId,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate seller's ability to retrieve full order detail for their own products.
 *
 * Ensures that a seller can only retrieve order details that reference their own product(s).
 * The following scenario is tested end-to-end:
 *
 * 1. Seller registers and receives authentication (JWT).
 * 2. Seller creates a new product.
 * 3. Customer registers and receives authentication (JWT).
 * 4. Customer places an order referencing the product created by the seller.
 * 5. Switches authentication context back to the seller.
 * 6. Seller retrieves the order by its ID.
 * 7. The response is asserted to verify that the order references the correct customer and was successfully retrieved.
 */
export async function test_api_seller_order_detail_success_owner(connection: api.IConnection) {
  // 1. Seller registration
  const sellerEmail = typia.random<string & tags.Format<"email">>()
  const sellerPassword = "passw0rd1!";
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: (Math.floor(Math.random() * 9000000000) + 1000000000).toString(),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(15),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUp);

  // 2. Seller login (to set Authorization for seller product creation)
  const sellerLogin = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(sellerLogin);

  // 3. Seller creates a product
  const productCode = RandomGenerator.alphaNumeric(8);
  const sellerId = sellerSignUp.sellerId;
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: productCode,
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 4. Customer registration
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Customer#1234";
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);

  // 5. Customer login (Authorization for order placement)
  const customerLogin = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    } satisfies ICustomerSignIn.Request,
  });
  typia.assert(customerLogin);

  // 6. Customer places an order referencing seller's product
  // Note: order_number must be unique, use random string for safety
  const orderNumber = `ORDER-${Math.floor(Math.random()*1e7).toString().padStart(7,"0")}`;
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerSignUp.customer.id,
      order_number: orderNumber,
      total_amount: 10000, // test amount
      currency_code: "KRW",
      note: RandomGenerator.paragraph()(),
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(order);

  // 7. Switch to seller context for retrieving the order
  const sellerLoginAgain = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(sellerLoginAgain);

  // 8. Seller requests order detail by orderId
  const fetchedOrder = await api.functional.shoppingMallAiBackend.seller.orders.at(connection, {
    orderId: order.id,
  });
  typia.assert(fetchedOrder);

  // 9. Business Assertions
  // Matching order id
  TestValidator.equals("order.id matches expected")(fetchedOrder.id)(order.id);

  // Matching customer reference
  TestValidator.equals("order.customer_id matches customer")(fetchedOrder.customer_id)(customerSignUp.customer.id);
  // Check that the current_status is as expected
  TestValidator.equals("status")(fetchedOrder.current_status)("created");
  // Should match test currency, amount, and order_number
  TestValidator.equals("order_number")(fetchedOrder.order_number)(orderNumber);
  TestValidator.equals("currency_code")(fetchedOrder.currency_code)("KRW");
  TestValidator.equals("total_amount")(fetchedOrder.total_amount)(10000);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Ensure that sellers cannot retrieve details of orders irrelevant to their own products.
 *
 * Business context: In a multi-seller marketplace, data privacy and business separation require that sellers may only view orders containing their own products. This test validates that access controls are enforced at the API level.
 *
 * Process:
 * 1. Register Seller A and Seller B with unique business data.
 * 2. Seller A logs in and creates a product.
 * 3. Register and log in as a customer.
 * 4. Customer creates an order for Seller A's product.
 * 5. Seller B logs in and attempts to access the order detail; this access should be forbidden.
 *
 * This scenario demonstrates that a seller cannot retrieve details of an order that is not associated with their products, enforcing business-level data privacy.
 */
export async function test_api_seller_order_detail_forbidden_not_owner(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAPassword = "passwordA123!";
  const sellerAReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: sellerAPassword,
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerAReg);

  // 2. Register Seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBPassword = "passwordB123!";
  const sellerBReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: sellerBPassword,
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerBReg);

  // 3. Seller A logs in
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerAEmail,
      password: sellerAPassword,
    },
  });

  // 4. Seller A creates a product
  const productA = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAReg.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: "Seller A Product",
      description: RandomGenerator.paragraph()(),
      status: "published",
    },
  });
  typia.assert(productA);

  // 5. Register and log in as customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "custPass123!";
  const customerReg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerReg);
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    },
  });

  // 6. Customer creates an order for Seller A's product (minimal info due to schema limits)
  const orderNumber = RandomGenerator.alphaNumeric(12);
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerReg.customer.id,
      order_number: orderNumber,
      total_amount: 10000,
      currency_code: "KRW",
      current_status: "created",
    },
  });
  typia.assert(order);

  // 7. Seller B logs in
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerBEmail,
      password: sellerBPassword,
    },
  });

  // 8. Seller B tries to access Seller A's order and should receive forbidden error
  await TestValidator.error("Seller B must not access Seller A's order details")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.orders.at(connection, {
        orderId: order.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that an authenticated admin user can fetch the full details of an order in the system.
 *
 * This test covers the admin workflow for order access:
 * 1. Register an admin and capture credentials
 * 2. Authenticate as the admin so that subsequent requests have admin privileges
 * 3. Register a new customer account
 * 4. Login as the new customer
 * 5. Create an order as the customer
 * 6. Login again as the admin to ensure Authorization context is correct
 * 7. Fetch the order as the admin using its UUID
 * 8. Verify all expected fields of the order response, and confirm identity and status fields match those from creation
 *
 * Checks that the admin has privileged access to view any order.
 */
export async function test_api_admin_order_detail_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "Admin!1234";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Login as the admin to obtain JWT and Authorization context
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);

  // 3. Register a new customer
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerPassword: string = "Cust!1234";
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  const customerId = customerSignUp.customer.id;

  // 4. Login as the new customer
  const customerSignIn = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    } satisfies ICustomerSignIn.Request,
  });
  typia.assert(customerSignIn);

  // 5. Create an order as the customer
  const orderCreateData: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customerId,
    order_number: `ORD-${typia.random<string & tags.Pattern<"^[A-Z0-9]{6,16}$">>()}`,
    total_amount: typia.random<number & tags.Type<"uint32"> & tags.Minimum<1000> & tags.Maximum<1000000>>() ,
    currency_code: "USD",
    current_status: "created",
    // order_group_id and note are optional and left undefined here
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: orderCreateData,
  });
  typia.assert(order);

  // 6. Login again as the admin to ensure JWT context is set
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });

  // 7. Fetch the order as the admin using the UUID
  const fetchedOrder = await api.functional.shoppingMallAiBackend.admin.orders.at(connection, {
    orderId: order.id,
  });
  typia.assert(fetchedOrder);

  // 8. Validate the returned order fields
  TestValidator.equals("order id matches")(fetchedOrder.id)(order.id);
  TestValidator.equals("customer id matches")(fetchedOrder.customer_id)(customerId);
  TestValidator.equals("order number matches")(fetchedOrder.order_number)(orderCreateData.order_number);
  TestValidator.equals("total amount matches")(fetchedOrder.total_amount)(orderCreateData.total_amount);
  TestValidator.equals("currency code matches")(fetchedOrder.currency_code)(orderCreateData.currency_code);
