    productOptionId: productOption.id,
    body: {
      product_option_id: productOption.id,
      stock_count: 50,
      safety_stock: 10,
      inbound_count: 5,
      warehouse_location: "A1-02-01",
      status: "active",
    } satisfies IShoppingMallAiBackendProductOptionStock.ICreate,
