  // 4. Retrieve the product option stock as the owning seller (should succeed)
  const output = await api.functional.shoppingMallAiBackend.seller.productOptions.productOptionStocks.at(connection, {
    productOptionId: productOption.id,
    productOptionStockId: productOptionStock.id,
