 * - Authenticate (login) with those credentials to obtain JWT/session
 * - Use the authenticated session to perform a password change, supplying the correct current password and a policy-compliant strong new password
 * - Validate the response indicates password change succeeded
 * - (DB side: password_hash must update, seller_histories should log event, and session is reset, but these cannot be verified via the API directly.)
 * - Confirm that a login with the new password is accepted and issues a new JWT (i.e., session reset works)
 * - Confirm that a login with the old password is now rejected (if login API returns error on credentials failure)
 *
 * Steps:
 * 1. Register seller (capture credentials)
 * 2. Login as seller (obtain token)
 * 3. Change password using correct current password and valid new password
 * 4. Login again with new password (should succeed)
 * 5. Attempt login with old password (should fail)
 */
export async function test_api_seller_change_password_success(connection: api.IConnection) {
  // 1. Register a new seller account
  const sellerEmail = typia.random<string & tags.Format<'email'>>();
  const initialPassword = 'Initial@12345';
  const newPassword = 'NewPass!2345';
  // Using alphaNumeric for company name generation (RandomGenerator.company() does not exist)
