  typia.assert(sellerB_signUp);
  // 3. Seller A logs in
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerA_signUp.email,
      password: "Test1234@A"
    }
  });
  // 4. Seller A creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerA_signUp.sellerId,
      code: "PRD-A-" + Math.floor(Math.random() * 100000),
      name: "TestA Product",
      description: "A's confidential item.",
      main_image_uri: null,
