  typia.assert(product);
  // 5. Seller A creates a product option
  const option = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: "SKU-A-001",
      option_name: "Size",
      option_values: "M|L|XL",
      extra_price: 2000.0,
