      snapshot_json: JSON.stringify(order),
      snapshot_reason: "created",
    },
  });
  typia.assert(firstSnapshot);
  await new Promise((r) => setTimeout(r, 1200)); // Ensure timestamp difference
  order.current_status = "paid";
  const secondSnapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.create(connection, {
    orderId,
    body: {
      snapshot_json: JSON.stringify(order),
      snapshot_reason: "paid",
