  typia.assert(noSnapshotsResults);
  TestValidator.equals("empty results for non-existent order")(noSnapshotsResults.data.length)(0);

  // 12. Switch to customer context, attempt search (should fail with authorization)
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
