import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderSnapshot";
import type { IPageIShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates seller-side order snapshot search and pagination functionality, including filtering, paging, and error handling.
 * 
 * Business context: Sellers track historical states of their orders for compliance, rollback, and evidence. Snapshots are immutable views of entire order states at key moments (creation, payment, shipped, etc). The seller should only see snapshots of their own products' orders, filtered or paginated as needed.
 *
 * End-to-end workflow:
 * 1. Register a new seller and sign in.
 * 2. Seller creates a product for sale.
 * 3. Register a customer.
 * 4. Customer creates a new order for seller's product.
 * 5. Seller creates multiple snapshots for the order, with different reasons and timestamps.
 * 6. As the seller, search for order snapshots by orderId with:
 *    - No filter (should return all snapshots for the order)
 *    - Filter by snapshot_reason (should only return matching reasons)
 *    - Date range filters (created_after, created_before)
 *    - Pagination (limit, page)
 *    - Sorting (asc/desc by created_at)
 * 7. Try forbidden access: try to fetch as another seller (should error), invalid snapshot filter (should error/return empty), non-existent orderId (should error).
 *
 * 8. Assert list/data/pagination structure, snapshot content, and error handling for incorrect scenarios.
 */
export async function test_api_order_snapshot_search_pagination_and_seller_access(connection: api.IConnection) {
  // 1. Register Seller + sign-in (token is set in connection.headers)
  const sellerEmail = typia.random<string & tags.Format<'email'>>();
  const companyName = RandomGenerator.name();
  const sellerReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "1234secure##",
      companyName,
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerReg); 
  const sellerId = sellerReg.sellerId;

  // 2. Seller creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      main_image_uri: null,
      status: "published",
    },
  });
  typia.assert(product);

  // 3. Register customer
  const customerEmail = typia.random<string & tags.Format<'email'>>();
  const customerReg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "5678secure@#",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerReg);
  const customerId = customerReg.customer.id;

  // 4. Customer creates order for this product
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId,
      order_group_id: null,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 49900,
      currency_code: "KRW",
      note: null,
      current_status: "created",
    },
  });
  typia.assert(order);

  // 5. Seller creates N = 3 distinct snapshots of the order, with different reasons
  const snapshots = [];
  for (let i = 0; i < 3; i++) {
    const reason = ["created", "paid", "shipped"][i];
    // snapshot_json stores full order state as JSON, emulate with serialized order
    const snap = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.create(connection, {
      orderId: order.id,
      body: {
        snapshot_json: JSON.stringify({ ...order, mockInd: i }),
        snapshot_reason: reason,
      },
    });
    typia.assert(snap);
    snapshots.push(snap);
  }

  // 6.1 As seller: no filter - return all
  const all = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
    orderId: order.id,
    body: {},
  });
  typia.assert(all);
  TestValidator.predicate("all snapshots returned")(all.data.length === 3);

  // 6.2. Filter by snapshot_reason
  const filtered = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
    orderId: order.id,
    body: { snapshot_reason: "paid" },
  });
  typia.assert(filtered);
  TestValidator.equals("single paid snapshot")(filtered.data.length)(1);
  TestValidator.equals("paid reason snap")(filtered.data[0].snapshot_reason)("paid");

  // 6.3. Date filtering: created_after, created_before
  const { created_at: firstTime } = snapshots[0];
  const { created_at: lastTime } = snapshots[2];
  const after1 = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
    orderId: order.id,
    body: { created_after: firstTime },
  });
  typia.assert(after1);
  TestValidator.predicate("after firstTime filtered")(after1.data.every(s => s.created_at >= firstTime));
  const beforeLast = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
    orderId: order.id,
    body: { created_before: lastTime },
  });
  typia.assert(beforeLast);
  TestValidator.predicate("before lastTime filtered")(beforeLast.data.every(s => s.created_at <= lastTime));

  // 6.4. Limit/pagination: limit 2, page 1, page 2
  const page1 = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
    orderId: order.id,
    body: { limit: 2, page: 1 },
  });
  typia.assert(page1);
  TestValidator.equals("pagination page 1")(page1.data.length)(2);
  const page2 = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
    orderId: order.id,
    body: { limit: 2, page: 2 },
  });
  typia.assert(page2);
  TestValidator.predicate("pagination page 2")(page2.data.length >= 1);

  // 6.5. Sorting by created_at desc
  const desc = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
    orderId: order.id,
    body: { sort_by: "created_at", sort_direction: "desc" },
  });
  typia.assert(desc);
  TestValidator.predicate("sorted desc")(desc.data.length > 0 && desc.data[0].created_at >= desc.data[desc.data.length - 1].created_at);

  // 7a. Try forbidden access: as another seller
  const otherSellerReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<'email'>>(),
      password: "other999##",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(otherSellerReg);
  TestValidator.error("forbidden for other seller")(() => 
    api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
      orderId: order.id,
      body: {},
    })
  );

  // 7b. Invalid filter: nonsense snapshot_reason
  TestValidator.predicate("no result for nonsense reason")((await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
    orderId: order.id,
    body: { snapshot_reason: "__notarealreason__" },
  })).data.length === 0);

  // 7c. Non-existent orderId
  TestValidator.error("error for non-existent orderId")(() =>
    api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
      orderId: typia.random<string & tags.Format<'uuid'>>(),
      body: {},
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Test updating the status and session token of a customer's shopping cart.
 *
 * This test verifies that a customer can update their own cart's status and session token, and that the update is reflected in the cart data. It also checks that only the owner (customer) can perform the update; other users cannot modify the cart.
 *
 * Steps:
 * 1. Register a new customer to own the cart.
 * 2. Log in as that customer to obtain credentials/JWT.
 * 3. Create a new cart (status = 'active', possibly random session_token).
 * 4. Update the cart's status (e.g., set status to 'checked_out') and modify session_token. Assert returned cart reflects new state.
 * 5. Attempt to update this cart as a different (non-owner) customer and verify it fails.
 */
export async function test_api_cart_update_status_active_by_owner(connection: api.IConnection) {
  // 1. Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "TestPassword123!";
  const customerNickname = RandomGenerator.alphaNumeric(8);
  const customerName = RandomGenerator.name();
  const customerPhone = RandomGenerator.mobile();

  const signUpOutput = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: customerName,
      nickname: customerNickname,
      phone: customerPhone,
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpOutput);
  TestValidator.equals("registered customer email")(signUpOutput.customer.email)(customerEmail);

  // 2. Log in as that customer (refresh JWT/headers)
  const signInOutput = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    } satisfies ICustomerSignIn.Request,
  });
  typia.assert(signInOutput);
  TestValidator.equals("logged in customer email")(signInOutput.customer.email)(customerEmail);

  // 3. Create a new customer cart (as the authenticated customer)
  const createCartInput = {
    status: "active",
    session_token: RandomGenerator.alphaNumeric(12),
  } satisfies IShoppingMallAiBackendCart.ICreate;
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: createCartInput,
  });
  typia.assert(cart);
  TestValidator.equals("cart status after create")(cart.status)("active");
  TestValidator.equals("cart session_token after create")(cart.session_token)(createCartInput.session_token);

  // 4. Update: change status and session_token (as owner, should succeed)
  const updateInput = {
    status: "checked_out",
    session_token: RandomGenerator.alphaNumeric(16),
  } satisfies IShoppingMallAiBackendCart.IUpdate;
  const updatedCart = await api.functional.shoppingMallAiBackend.customer.carts.update(connection, {
    cartId: cart.id,
    body: updateInput,
  });
  typia.assert(updatedCart);
  TestValidator.equals("updated cart id")(updatedCart.id)(cart.id);
  TestValidator.equals("updated status")(updatedCart.status)(updateInput.status);
  TestValidator.equals("updated session_token")(updatedCart.session_token)(updateInput.session_token);

  // 5. Register another customer (non-owner)
  const anotherCustomerEmail = typia.random<string & tags.Format<"email">>();
  const anotherCustomerPassword = "OtherPassword456!";
  const anotherCustomerNickname = RandomGenerator.alphaNumeric(8);
  const anotherCustomerName = RandomGenerator.name();
  const anotherCustomerPhone = RandomGenerator.mobile();

  const anotherSignUpOutput = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: anotherCustomerEmail,
      password: anotherCustomerPassword,
      name: anotherCustomerName,
      nickname: anotherCustomerNickname,
      phone: anotherCustomerPhone,
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(anotherSignUpOutput);

  // Log in as the other customer
  const anotherSignInOutput = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: anotherCustomerEmail,
      password: anotherCustomerPassword,
    } satisfies ICustomerSignIn.Request,
  });
  typia.assert(anotherSignInOutput);

  // Try to update the first customer's cart as a non-owner (should error)
  await TestValidator.error("non-owner should not update cart")(() =>
    api.functional.shoppingMallAiBackend.customer.carts.update(connection, {
      cartId: cart.id,
      body: {
        status: "abandoned",
        session_token: RandomGenerator.alphaNumeric(16),
      } satisfies IShoppingMallAiBackendCart.IUpdate,
    })
  );
}

