 *
 * Steps:
 * 1. Register and authenticate primary customer.
 * 2. Primary customer creates a cart.
 * 3. Register and authenticate a secondary customer.
 * 4. Attempt to update the primary customer's cart as the secondary customer (should fail).
 * 5. Confirm that permission is denied using TestValidator.error().
 */
export async function test_api_cart_update_permission_denied_non_owner(
  connection: api.IConnection,
) {
  // 1. Register the primary customer (cart owner)
  const primaryEmail = typia.random<string & tags.Format<"email">>();
  const primaryPassword = "TestP@ssw0rd1";
  const primarySignUp = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email: primaryEmail,
        password: primaryPassword,
        name: RandomGenerator.name(),
        nickname: RandomGenerator.name(),
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request,
    },
  );
  typia.assert(primarySignUp);

  // 2. Authenticate as the primary customer
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: primaryEmail,
      password: primaryPassword,
    } satisfies ICustomerSignIn.Request,
  });

  // 3. Create a cart as primary customer
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
