  });
  typia.assert(cart);

  // 4. Register the secondary customer (non-owner)
  const secondaryEmail = typia.random<string & tags.Format<"email">>();
  const secondaryPassword = "TestP@ssw0rd2";
  const secondarySignUp = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email: secondaryEmail,
        password: secondaryPassword,
        name: RandomGenerator.name(),
        nickname: RandomGenerator.name(),
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request,
    },
  );
  typia.assert(secondarySignUp);

  // 5. Authenticate as the secondary customer
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: secondaryEmail,
      password: secondaryPassword,
    } satisfies ICustomerSignIn.Request,
  });

  // 6. Attempt to update the primary customer's cart as secondary (should fail)
  TestValidator.error("non-owner cannot update cart")(async () => {
    await api.functional.shoppingMallAiBackend.customer.carts.update(connection, {
      cartId: cart.id,
      body: {
        status: "abandoned",
      } satisfies IShoppingMallAiBackendCart.IUpdate,
