import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponTemplate";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that an authenticated admin can update all allowed fields of a coupon template and that changes persist as expected, as well as business rule failures.
 *
 * This test confirms:
 * - Only authenticated admins can update coupon templates
 * - All updateable fields (name, description, discount logic, min purchase, validity window, issuance & status) reflect changes
 * - Invalid update scenarios (date consistency) are rejected
 * - Some negative/edge cases (update after delete, update code field) cannot be tested as API does not permit those actions
 *
 * **Steps:**
 * 1. Register a new admin
 * 2. Login as that admin
 * 3. Create a complete coupon template as test subject
 * 4. Update all allowed fields using the update API
 * 5. Check that the changed fields match the update payload
 * 6. Attempt to update the template with invalid date window and confirm failure
 * 7. Note: Skipped testing updating a deleted template (no delete API) and code duplication (code is not updatable)
 */
export async function test_api_coupon_template_update_success_and_strict_validation(
  connection: api.IConnection,
) {
  // 1. Register Admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const registration = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(registration);

  // 2. Login as Admin (JWT should be set in headers automatically)
  const login = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(login);

  // 3. Create Coupon Template to be updated
  const origTemplate = await api.functional.shoppingMallAiBackend.admin.couponTemplates.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      name: "Winter Sale " + RandomGenerator.alphabets(5),
      description: RandomGenerator.paragraph()(),
      type: "discount",
      discount_amount: 1500,
      discount_percent: null,
      min_purchase_amount: 10000,
      valid_from: new Date(Date.now() + 60 * 60 * 1000).toISOString(), // +1h
      valid_until: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // +1w
      max_issue_count: 50,
      is_active: true,
    } satisfies IShoppingMallAiBackendCouponTemplate.ICreate,
  });
  typia.assert(origTemplate);

  // 4. Update all allowed fields on the template
  const updatePayload: IShoppingMallAiBackendCouponTemplate.IUpdate = {
    name: origTemplate.name + " Updated",
    description: origTemplate.description ? origTemplate.description + " (edited)" : "Update Desc",
    discount_amount: origTemplate.discount_amount ? origTemplate.discount_amount + 500 : 1000,
    discount_percent: 10,
    min_purchase_amount: origTemplate.min_purchase_amount ? origTemplate.min_purchase_amount + 5000 : 5000,
    valid_from: origTemplate.valid_from,
    valid_until: new Date(new Date(origTemplate.valid_until).getTime() + 60 * 60 * 1000).toISOString(), // +1h
    max_issue_count: origTemplate.max_issue_count ? origTemplate.max_issue_count + 25 : 25,
    is_active: !origTemplate.is_active,
  };
  const updated = await api.functional.shoppingMallAiBackend.admin.couponTemplates.update(connection, {
    couponTemplateId: origTemplate.id,
    body: updatePayload,
  });
  typia.assert(updated);
  // Assert all updateable fields match expected
  TestValidator.equals("name change")(updated.name)(updatePayload.name);
  TestValidator.equals("description change")(updated.description)(updatePayload.description);
  TestValidator.equals("discount_amount change")(updated.discount_amount)(updatePayload.discount_amount);
  TestValidator.equals("discount_percent change")(updated.discount_percent)(updatePayload.discount_percent);
  TestValidator.equals("min_purchase_amount change")(updated.min_purchase_amount)(updatePayload.min_purchase_amount);
  TestValidator.equals("valid_from")(updated.valid_from)(updatePayload.valid_from);
  TestValidator.equals("valid_until")(updated.valid_until)(updatePayload.valid_until);
  TestValidator.equals("max_issue_count")(updated.max_issue_count)(updatePayload.max_issue_count);
  TestValidator.equals("is_active")(updated.is_active)(updatePayload.is_active);

  // 5. Error: Attempt to update template with invalid date window
  await TestValidator.error("inconsistent date range should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.couponTemplates.update(connection, {
      couponTemplateId: origTemplate.id,
      body: {
        ...updatePayload,
        valid_until: new Date(new Date(updatePayload.valid_from).getTime() - 60 * 60 * 1000).toISOString(), // 1hr before from
      },
    });
  });

  // 6. SKIPPED: Update after delete (soft-delete not available in API) and duplicate code (code not in update schema)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponTemplate";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test the soft deletion (logical removal without hard delete) of a coupon template by admin and ensure idempotency and compliance/audit behavior.
 *
 * Business Context:
 * Coupon templates define rules and validity for mass coupon campaigns. Admins may mark them as deleted when no longer needed. Deletion should be logical (soft): templates are excluded from issuance but remain for audit.
 *
 * Steps performed:
 * 1. Register and login as new admin (establish JWT for protected endpoints)
 * 2. Create a new coupon template as admin
 * 3. Soft-delete the coupon template via admin endpoint
 * 4. (Business-facing listing/search endpoint unavailable – exclusion from search not directly validated)
 * 5. Attempt to delete the template again to confirm correct error/idempotent error is thrown
 * 6. Note: Compliance/audit log and business-rules blocking deletion not testable via public API; omitted
 */
export async function test_api_coupon_template_soft_delete_success_and_idempotency(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResult = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(signUpResult);

  // Login again to apply token (SDK manages token/headers)
  const signInResult = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(signInResult);

  // 2. Create coupon template to be deleted
  const ctCreate: IShoppingMallAiBackendCouponTemplate.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.paragraph()(),
    type: "discount", // One valid coupon type
    discount_amount: 5000,
    discount_percent: null,
    min_purchase_amount: 20000,
    valid_from: new Date(Date.now() - 60 * 1000).toISOString(),
    valid_until: new Date(Date.now() + 86400 * 1000).toISOString(),
    max_issue_count: 100,
    is_active: true,
  };
  const couponTemplate = await api.functional.shoppingMallAiBackend.admin.couponTemplates.create(connection, {
    body: ctCreate,
  });
  typia.assert(couponTemplate);
  TestValidator.equals("coupon template not deleted on create")(couponTemplate.deleted_at)(null);

  // 3. Soft-delete the template
  await api.functional.shoppingMallAiBackend.admin.couponTemplates.erase(connection, {
    couponTemplateId: couponTemplate.id,
  });

  // 4. Coupon template exclusion from list is not testable (list API unavailable)

  // 5. Ensure idempotency or 'not found' error when deleting already deleted template
  await TestValidator.error("second deletion returns not found or idempotency error")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.couponTemplates.erase(connection, {
        couponTemplateId: couponTemplate.id,
      });
    },
  );

  // 6. Compliance/audit log and deletion-block business rules are not testable (skipped)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendComplianceEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceEvent";

/**
 * Validate updating of an existing compliance event record as an admin.
 *
 * This test verifies that a compliance event, once created, can be updated correctly via the admin endpoint. The process mimics a real compliance/audit edit operation:
 *
 * 1. Create a new compliance event to obtain a valid complianceEventId (using admin privileges).
 * 2. Update the compliance event's fields—metadata or payload, such as event_type, actor_type, target_type, event_payload.
 * 3. Confirm that the response reflects the updates (event type and payload are modified).
 * 4. Assert that traceability and audit trail are preserved after update (ID and created_at remain unchanged, updated fields are as expected).
 */
export async function test_api_compliance_event_update_successful(connection: api.IConnection) {
  // 1. Create a compliance event as a dependency (simulate admin action)
  const originalCreate = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
    body: {
      event_type: "policy_update",
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      actor_type: "admin",
      target_type: "user_account",
      target_id: typia.random<string & tags.Format<"uuid">>(),
      event_payload: JSON.stringify({ before: "old-policy-content" })
    } satisfies IShoppingMallAiBackendComplianceEvent.ICreate
  });
  typia.assert(originalCreate);

  // 2. Prepare updated fields for the event (change event type, payload, and context)
  const updateBody: IShoppingMallAiBackendComplianceEvent.IUpdate = {
    event_type: "data_erasure_request",
    actor_type: "admin",
    target_type: "customer_profile",
    event_payload: JSON.stringify({ before: "old-policy-content", after: "deleted-customer-data" })
  };

  // 3. Issue the update as admin
  const updated = await api.functional.shoppingMallAiBackend.admin.complianceEvents.update(connection, {
    complianceEventId: originalCreate.id,
    body: updateBody
  });
  typia.assert(updated);

  // 4. Validation
  // ID and created_at must be unchanged, relevant fields updated
  TestValidator.equals("event id is unchanged")(updated.id)(originalCreate.id);
  TestValidator.equals("created_at is unchanged")(updated.created_at)(originalCreate.created_at);
  TestValidator.equals("event_type updated")(updated.event_type)(updateBody.event_type);
  TestValidator.equals("actor_type updated")(updated.actor_type)(updateBody.actor_type);
  TestValidator.equals("target_type updated")(updated.target_type)(updateBody.target_type);
  TestValidator.equals("event_payload updated")(updated.event_payload)(updateBody.event_payload);
}

