/**
 * Validate that access to product review snapshots is properly restricted based on review ownership (customer privacy).
 *
 * This test checks that a customer (Customer B, the unauthorized party) is unable to view the snapshot history of a product review written by another customer (Customer A).
 * This is essential for e-commerce privacy and regulatory compliance, ensuring users' histories and audit trails are never exposed to unrelated customers.
 *
 * Steps:
 * 1. Register Customer A (review author) and Customer B (unauthorized user).
 * 2. With Customer A's session, create a product review for some product+order combination.
 * 3. Switch authentication to Customer B (using their credentials).
 * 4. Attempt to access the snapshots of Customer A's review via the snapshots search endpoint.
 * 5. Confirm that an access denied error (authorization failure) occurs, preventing Customer B from viewing details of Customer A's review snapshots.
 */
export async function test_api_customer_review_snapshots_access_permission_denied(
  connection: api.IConnection,
) {
  // 1. Register Customer A (review author)
  const customerAEmail = typia.random<string & tags.Format<"email">>();
  const customerARegister = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerAEmail,
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerARegister);
  const customerAId = customerARegister.customer.id;
  const customerAToken = customerARegister.setHeaders.Authorization;

  // 2. Register Customer B (unauthorized user)
  const customerBEmail = typia.random<string & tags.Format<"email">>();
  const customerBRegister = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerBEmail,
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerBRegister);
  const customerBToken = customerBRegister.setHeaders.Authorization;

  // 3. Switch authentication back to Customer A for product review creation
  connection.headers ??= {};
  connection.headers.Authorization = customerAToken;

  // 4. Customer A creates a product review
  const review = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      order_item_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(),
      rating: 5,
      status: "normal",
      ai_sentiment_score: 0.5,
      ai_spam_score: 0.01,
    } satisfies IShoppingMallAiBackendProductReview.ICreate,
  });
  typia.assert(review);
  const reviewId = review.id;

  // 5. Switch to Customer B and attempt to access snapshots for Customer A's review
  connection.headers ??= {};
  connection.headers.Authorization = customerBToken;

  await TestValidator.error("Customer B should be denied access to Customer A's review snapshots")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.productReviews.reviewSnapshots.search(connection, {
        productReviewId: reviewId,
        body: {
          review_id: reviewId,
        } satisfies IShoppingMallAiBackendReviewSnapshot.IRequest,
      });
    },
  );
}

