  TestValidator.predicate("should return at least one snapshot")(snapshotsPage.data.length >= 1);
  snapshotsPage.data.forEach(snapshot =>
    TestValidator.equals("snapshot.review_id matches")(snapshot.review_id)(initialReview.id));
  const latest = snapshotsPage.data.reduce((a, b) => a.changed_at > b.changed_at ? a : b);
  TestValidator.equals("latest snapshot reflects update")(latest.body)("Edited review body for audit.");
}

