import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that a seller cannot access review snapshots for a product they do not own.
 *
 * Business context:
 * Seller review snapshots are allowed only for reviews on products owned by the authenticating seller. This test ensures access control and compliance with data isolation principles, preventing disclosure of other sellers’ product review history. If a seller attempts to access review snapshots for another seller’s product, the system must deny permission (typically an HTTP 403 Forbidden or equivalent error).
 *
 * Steps:
 * 1. Register two sellers (Seller A and Seller B) with distinct emails and realistic "company" information.
 * 2. (Assume) Both sellers will have at least one product in the system due to dependency; however, the explicit product creation endpoint is not exposed in SDK, so test will use review creation to simulate a product "owned" by Seller A.
 * 3. Simulate a customer review for Seller A’s product (so, a known valid review for a known product ID).
 * 4. As Seller B, attempt to retrieve review snapshots for the review on Seller A’s product via the PATCH /shoppingMallAiBackend/seller/productReviews/{productReviewId}/reviewSnapshots endpoint.
 * 5. Validate that the API responds with an error (forbidden access due to lack of ownership).
 *
 * This test validates negative access control (security) around the review snapshots API (seller scope), catching accidental or malicious exposure of audit trail data across seller boundaries.
 */
export async function test_api_seller_review_snapshot_access_for_unowned_product(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerA = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "strongpasswordA!", // Strong password for testing
      companyName: RandomGenerator.name(),
      businessNumber: typia.random<string>(),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(20),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerA);

  // 2. Register Seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerB = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "strongpasswordB!",
      companyName: RandomGenerator.name(),
      businessNumber: typia.random<string>(),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(20),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerB);

  // 3. Create a review (simulate customer review on Seller A's product)
  const productId = typia.random<string & tags.Format<"uuid">>();
  const orderItemId = typia.random<string & tags.Format<"uuid">>();
  const reviewInput = {
    product_id: productId,
    order_item_id: orderItemId,
    title: "Good Product",
    body: "Nice product and fast shipping!",
    rating: 5,
    status: "normal",
  } satisfies IShoppingMallAiBackendProductReview.ICreate;
  const review = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, { body: reviewInput });
  typia.assert(review);

  // 4. As Seller B, attempt to fetch review snapshots for Seller A's product's review
  // Switch the connection to Seller B's credentials, simulating authorization as Seller B
  connection.headers = { ...connection.headers, Authorization: sellerB.setHeaders.Authorization };
  await TestValidator.error("seller cannot access another seller's review snapshot")(async () => {
    await api.functional.shoppingMallAiBackend.seller.productReviews.reviewSnapshots.search(connection, {
      productReviewId: review.id,
      body: {
        review_id: review.id,
      } satisfies IShoppingMallAiBackendReviewSnapshot.IRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";
import type { IShoppingMallAiBackendReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendReviewSnapshot";
import type { IPageIShoppingMallAiBackendReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendReviewSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that an admin can fully search and list all review snapshots for any product review in the system.
 *
 * This test scenario covers a full workflow from customer registration, review creation, review updating (to generate snapshots), and admin-search for review snapshots. It ensures that admins have unrestricted access and that pagination & filtering of snapshots work as expected.
 *
 * Steps:
 * 1. Register two unique customers.
 * 2. Each customer writes a review for different products (simulate with random product/order_item IDs).
 * 3. Perform at least two updates to each review to generate multiple snapshots per review.
 * 4. As an admin, perform search of snapshots for each review via the admin endpoint, including paginated and filtered requests.
 * 5. Validate that all expected snapshots are returned, that admin access is unrestricted, and test representative filters (e.g., by status or rating).
 */
export async function test_api_admin_review_snapshot_search_all_reviews(connection: api.IConnection) {
  // 1. Register two customers
  const customer1Req: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password1!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  };
  const cust1Res = await api.functional.auth.customer.register.signUp(connection, { body: customer1Req });
  typia.assert(cust1Res);
  const customer1 = cust1Res.customer;

  const customer2Req: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password2!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  };
  const cust2Res = await api.functional.auth.customer.register.signUp(connection, { body: customer2Req });
  typia.assert(cust2Res);
  const customer2 = cust2Res.customer;

  // 2. Each customer writes a review (simulate with random product/order_item IDs)
  const review1Create: IShoppingMallAiBackendProductReview.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
    order_item_id: typia.random<string & tags.Format<"uuid">>(),
    title: "User1 Initial Review",
    body: "Body 1 - initial.",
    rating: 4,
    status: "normal",
  };
  const review1 = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, { body: review1Create });
  typia.assert(review1);

  const review2Create: IShoppingMallAiBackendProductReview.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
    order_item_id: typia.random<string & tags.Format<"uuid">>(),
    title: "User2 Initial Review",
    body: "Body 2 - initial.",
    rating: 5,
    status: "normal",
  };
  const review2 = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, { body: review2Create });
  typia.assert(review2);

  // 3. Perform at least two updates to each review to generate snapshots
  await api.functional.shoppingMallAiBackend.customer.productReviews.update(connection, {
    productReviewId: review1.id,
    body: {
      title: "User1 Update1",
      body: "Body 1 - update 1.",
      rating: 3,
      status: "normal",
    },
  });
  await api.functional.shoppingMallAiBackend.customer.productReviews.update(connection, {
    productReviewId: review1.id,
    body: {
      title: "User1 Update2",
      body: "Body 1 - update 2.",
      rating: 2,
      status: "blocked",
    },
  });
  await api.functional.shoppingMallAiBackend.customer.productReviews.update(connection, {
    productReviewId: review2.id,
    body: {
      title: "User2 Update1",
      body: "Body 2 - update 1.",
      rating: 4,
      status: "normal",
    },
  });
  await api.functional.shoppingMallAiBackend.customer.productReviews.update(connection, {
    productReviewId: review2.id,
    body: {
      title: "User2 Update2",
      body: "Body 2 - update 2.",
      rating: 1,
      status: "deleted",
    },
  });

  // 4. As an admin, search review snapshots for each review
  // Unfiltered, all snapshots
  const snaps1all = await api.functional.shoppingMallAiBackend.admin.productReviews.reviewSnapshots.search(connection, {
    productReviewId: review1.id,
    body: {
      review_id: review1.id,
      page: 1,
      limit: 20,
    },
  });
  typia.assert(snaps1all);
  TestValidator.predicate("review1 has multiple snapshots")(snaps1all.data.length >= 3);

  // Filtered by status (blocked)
  const snaps1Blocked = await api.functional.shoppingMallAiBackend.admin.productReviews.reviewSnapshots.search(connection, {
    productReviewId: review1.id,
    body: {
      review_id: review1.id,
      status: "blocked",
      page: 1,
      limit: 10,
    },
  });
  typia.assert(snaps1Blocked);
  TestValidator.predicate("review1 blocked snapshot exists")(snaps1Blocked.data.some(s => s.status === "blocked"));

  // Paginated list (page 1, limit 1)
  const snaps2paginated = await api.functional.shoppingMallAiBackend.admin.productReviews.reviewSnapshots.search(connection, {
    productReviewId: review2.id,
    body: {
      review_id: review2.id,
      page: 1,
      limit: 1,
    },
  });
  typia.assert(snaps2paginated);
  TestValidator.equals("paginated size 1")(snaps2paginated.pagination.limit)(1);
  TestValidator.predicate("paginated returns nonzero")(snaps2paginated.data.length >= 1);

  // Filter by rating (1)
  const snaps2rating = await api.functional.shoppingMallAiBackend.admin.productReviews.reviewSnapshots.search(connection, {
    productReviewId: review2.id,
    body: {
      review_id: review2.id,
      rating: 1,
      page: 1,
      limit: 5,
    },
  });
  typia.assert(snaps2rating);
  TestValidator.predicate("review2 snapshot with rating=1")(snaps2rating.data.some(s => s.rating === 1));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";
import type { IShoppingMallAiBackendReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendReviewSnapshot";
import type { IPageIShoppingMallAiBackendReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendReviewSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that a customer can retrieve the full detail of a specific review snapshot for their own review.
 *
 * This test simulates a real user journey where a customer:
 * 1. Registers a new account
 * 2. Creates a product review
 * 3. Updates the review multiple times to generate snapshots
 * 4. Lists all snapshots and picks one
 * 5. Fetches detail of that snapshot and asserts data validity
 *
 * Key strategy: Instead of trying to infer expected state for the snapshot via unsafe object merges (which breaks assignability and type safety), only validate those fields which are (a) known, (b) deterministic from our test input, or (c) type-predictable (such as linkage, types, author, and presence of body/status/rating fields). Non-deterministic fields (timestamps, system-side AI scores, etc.) should only be presence/type tested, not value-asserted. Always use TestValidator and typia.assert on fetched DTOs.
 */
export async function test_api_customer_get_specific_review_snapshot_detail(connection: api.IConnection) {
  // 1. Register customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "testPassword123";
  const signUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpResponse);

  // 2. Prepare product/order references
  const product_id = typia.random<string & tags.Format<"uuid">>();
  const order_item_id = typia.random<string & tags.Format<"uuid">>();

  // 3. Create review
  const reviewInput = {
    product_id,
    order_item_id,
    title: "Initial Review Title",
    body: "Initial body.",
    rating: 3,
    status: "normal" as const,
    ai_sentiment_score: 0,
    ai_spam_score: 0,
  } satisfies IShoppingMallAiBackendProductReview.ICreate;
  const review = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, { body: reviewInput });
  typia.assert(review);

  // 4. Update the review multiple times
  const updateInputs: IShoppingMallAiBackendProductReview.IUpdate[] = [
    { title: "First edit title", body: "First edit body.", rating: 4, status: "normal" },
    { body: "Second edit body.", status: "normal" },
    { title: "Final edit title", rating: 2, status: "blocked" },
  ];
  for (const input of updateInputs) {
    const updateResult = await api.functional.shoppingMallAiBackend.customer.productReviews.update(connection, {
      productReviewId: review.id,
      body: input,
    });
    typia.assert(updateResult);
  }

  // 5. List all snapshots
  const snapshotsPage = await api.functional.shoppingMallAiBackend.customer.productReviews.reviewSnapshots.search(connection, {
    productReviewId: review.id,
    body: { review_id: review.id },
  });
  typia.assert(snapshotsPage);
  TestValidator.predicate("at least 2 snapshots exist")(snapshotsPage.data.length >= 2);

  // 6. Select a random snapshot and fetch its details
  const snapshotToFetch = RandomGenerator.pick(snapshotsPage.data);
  const snapshotDetail = await api.functional.shoppingMallAiBackend.customer.productReviews.reviewSnapshots.at(connection, {
    productReviewId: review.id,
    reviewSnapshotId: snapshotToFetch.id,
  });
  typia.assert(snapshotDetail);
  // Validate linkage and core fields
  TestValidator.equals("review id linkage")(snapshotDetail.review_id)(review.id);
  TestValidator.equals("actor id matches customer")(snapshotDetail.actor_id)(signUpResponse.customer.id);
  TestValidator.predicate("snapshot body present")(typeof snapshotDetail.body === "string" && snapshotDetail.body.length >= 0);
  TestValidator.predicate("rating is valid")(snapshotDetail.rating >= 1 && snapshotDetail.rating <= 5);
  TestValidator.predicate("status is string")(typeof snapshotDetail.status === "string");
  TestValidator.predicate("timestamp is string")(typeof snapshotDetail.changed_at === "string" && snapshotDetail.changed_at.length > 0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";
import type { IShoppingMallAiBackendReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendReviewSnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that a customer is denied access when attempting to view a review snapshot that does not belong to them.
 *
 * Business context: In an AI-powered shopping mall backend, customers may make product reviews, and these reviews generate immutable snapshots when updated (for compliance and legal audit). However, customers must not have access to review snapshots of reviews they do not own—this is essential for privacy, security, and compliance requirements.
 *
 * Test necessity: To ensure that the API enforces review snapshot access controls and does not leak information about review edits/contents across customers, protecting business and user privacy.
 *
 * Step-by-step process:
 * 1. Register two different customers (customerA and customerB).
 * 2. Login as customerA and create a product review (for productX/orderY).
 * 3. (Snapshot creation is implicit or system-managed.).
 * 4. Capture the review id (customerA's review).
 * 5. Switch to customerB (re-authenticate as customerB).
 * 6. Attempt to access the review snapshot using the snapshot id and review id owned by customerA.
 * 7. Confirm that the API throws an authorization error (HTTP 403 forbidden) and does not return any snapshot details.
 */
export async function test_api_customer_get_review_snapshot_access_denied(
  connection: api.IConnection,
) {
  // 1. Register customerA
  const customerAEmail = typia.random<string & tags.Format<"email">>();
  const customerARes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerAEmail,
      password: "Password123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerARes);
  const customerA = customerARes.customer;

  // 2. Register customerB
  const customerBEmail = typia.random<string & tags.Format<"email">>();
  const customerBRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerBEmail,
      password: "Password123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerBRes);
  const customerB = customerBRes.customer;

  // 3. Login as customerA is done by signUp (auto-auth)
  // 4. Create a product review as customerA
  const reviewCreateInput = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
    order_item_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(8),
    body: RandomGenerator.alphabets(30),
    rating: 5,
    status: "normal",
    ai_sentiment_score: null,
    ai_spam_score: null,
  } satisfies IShoppingMallAiBackendProductReview.ICreate;
  const review = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: reviewCreateInput,
  });
  typia.assert(review);
  const productReviewId = review.id;

  // 5. Switch to customerB by re-authenticating using their credentials (signUp auto-auth's as last registered)
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerBEmail,
      password: "Password123!",
      name: customerB.name,
      nickname: customerB.nickname,
      phone: customerB.phone,
    },
  });

  // 6. Attempt to get the snapshot as customerB using a random snapshotId (should simulate forbidden access)
  const forbiddenSnapshotId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("customer B must not access customer A's review snapshot")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.productReviews.reviewSnapshots.at(connection, {
        productReviewId,
        reviewSnapshotId: forbiddenSnapshotId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendChannel";
import type { IPageIShoppingMallAiBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendChannel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate the admin channel list search endpoint with authentication, diversified data setup, filter/pagination assertions, and soft delete exclusion.
 *
 * This test ensures admin users can retrieve and filter a paginated list of channels, validating business, RBAC, and search criteria for enterprise compliance.
 *
 * Steps:
 * 1. Admin login (JWT in headers)
 * 2. Create several diverse channels
 * 3. Search with various filters & pagination; verify results match filters and metadata is intact
 * 4. (Soft delete exclusion cannot be directly confirmed due to lack of delete API)
 */
export async function test_api_channel_list_search_admin_success(connection: api.IConnection) {
  // 1. Admin login to get credentials and adminId for test - ensure JWT syncs into connection headers
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPW123!";
  // Assumes this admin is present according to test scenario setup/guidance
  const adminJwt = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminJwt);
  connection.headers = { ...connection.headers, Authorization: adminJwt.setHeaders.Authorization };

  // 2. Create several channels (with different names, codes, status)
  const channelA = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: "PARTNER001",
      name: "Blue Part Channel",
      created_by_admin_id: adminJwt.adminId,
      description: "Blue partner's sales channel",
      logo_url: "https://brand.example.com/logo-blue.png",
      active: true,
    },
  });
  typia.assert(channelA);

  const channelB = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: "PARTNER002",
      name: "Red Part Channel",
      created_by_admin_id: adminJwt.adminId,
      description: "Red partner's sales arm",
      logo_url: "https://brand.example.com/logo-red.png",
      active: false,
    },
  });
  typia.assert(channelB);

  const channelC = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: "UNIQUE003",
      name: "Green Vert Channel",
      created_by_admin_id: adminJwt.adminId,
      description: null,
      logo_url: null,
      active: true,
    },
  });
  typia.assert(channelC);

  // 3a. Search by partial name
  const nameRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { name: "Part", page: 1, limit: 10 },
  });
  typia.assert(nameRes);
  for (const s of nameRes.data) TestValidator.predicate("name contains 'Part'")(s.name.includes("Part"));

  // 3b. Filter by code (exact)
  const codeRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { code: "PARTNER002" },
  });
  typia.assert(codeRes);
  TestValidator.equals("one PARTNER002 result")(codeRes.data.length)(1);
  TestValidator.equals("code matches")(codeRes.data[0].code)("PARTNER002");

  // 3c. Filter by activation status (inactive)
  const inactiveRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { active: false },
  });
  typia.assert(inactiveRes);
  for (const s of inactiveRes.data) TestValidator.equals("inactive only")(s.active)(false);

  // 3d. Filter by creator (adminId), but result rows do NOT contain creator_admin_id; instead, validate by expected test codes
  const creatorRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { created_by_admin_id: adminJwt.adminId },
  });
  typia.assert(creatorRes);
  // Instead of checking a missing property, validate that all rows are from known test data
  const expectedCodes = ["PARTNER001", "PARTNER002", "UNIQUE003"];
  for (const s of creatorRes.data) TestValidator.predicate("summary from creator")(expectedCodes.includes(s.code));

  // 3e. Combine filters (active + name partial)
  const combineRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { active: true, name: "Vert" },
  });
  typia.assert(combineRes);
  for (const s of combineRes.data) {
    TestValidator.equals("active & Vert")(s.active)(true);
    TestValidator.predicate("name contains 'Vert'" )(s.name.includes("Vert"));
  }

  // 3f. Pagination (limit=2)
  const pagedRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { limit: 2, page: 1 },
  });
  typia.assert(pagedRes);
  TestValidator.predicate("limit respected")(pagedRes.data.length <= 2);
  TestValidator.predicate("pagination object")(typeof pagedRes.pagination.current === "number");

