 * Ensures that an admin can update editable channel fields (name, logo_url, description, active flag)
 * but NOT the code, which is system immutable after creation.
 *
 * Test steps:
 * 1. Log in as admin and obtain credentials/JWT
 * 2. Create a new business channel (code, name, branding, active state)
 * 3. Update editable fields via PUT, ensuring updated_at and returned fields reflect changes
 * 4. Confirm code is immutable, and attempts to mutate it fail
 * 5. Assert correct behavior for a valid, non-deleted channel
 */
export async function test_api_channel_update_admin_success(connection: api.IConnection) {
  // 1. Log in as admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword1!";
  // The scenario doesn't specify registering an admin; we simulate login assuming this account exists
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);
  TestValidator.predicate("admin JWT present")(typeof adminLogin.jwt === "string" && adminLogin.jwt.length > 0);
  const adminId = adminLogin.adminId;

  // 2. Create a new channel for this admin
  const initialCode = `ch-${RandomGenerator.alphaNumeric(8)}`;
  const createChannelInput = {
    code: initialCode,
    name: "Original Channel Name",
    created_by_admin_id: adminId,
    description: "Original channel description.",
    logo_url: `https://logo.img/${RandomGenerator.alphaNumeric(10)}`,
    active: true,
  } satisfies IShoppingMallAiBackendChannel.ICreate;
  const createdChannel = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: createChannelInput,
  });
  typia.assert(createdChannel);
  TestValidator.equals("code after create")(createdChannel.code)(initialCode);
  TestValidator.equals("created_by_admin_id matches")(createdChannel.created_by_admin_id)(adminId);

  // 3. Update editable fields (name, description, logo_url, active)
  await new Promise((resolve) => setTimeout(resolve, 1200)); // Ensure updated_at changes
  const updateInput: IShoppingMallAiBackendChannel.IUpdate = {
    name: "Updated Channel Name",
    description: "Updated description after edit.",
    logo_url: `https://logo.img/${RandomGenerator.alphaNumeric(12)}`,
    active: false,
  };
  const updatedChannel = await api.functional.shoppingMallAiBackend.admin.channels.update(connection, {
