  TestValidator.equals("logo_url")(updatedChannel.logo_url)(updateInput.logo_url);
  TestValidator.equals("active")(updatedChannel.active)(updateInput.active);
  // Confirm code has not changed
  TestValidator.equals("code immutable after update")(updatedChannel.code)(createdChannel.code);
  // Confirm updated_at has advanced
  TestValidator.predicate("updated_at is more recent")(updatedChannel.updated_at > createdChannel.updated_at);

  // 4. Attempt to update code (should be rejected)
  await TestValidator.error("should fail to update code")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.channels.update(connection, {
        channelId: createdChannel.id,
        body: { ...(updateInput as any), code: "FORBIDDEN_CODE" }, // At runtime, API should reject this
      });
    },
  );
}

