import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendModerationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendModerationEvent";
import type { IShoppingMallAiBackendAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAppeal";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * 验证管理员针对任意审核事件直接创建申诉（appeal）的能力。
 *
 * 本测试用例验证管理员可以针对自己或其他人产生的审核事件提交申诉，涵盖正向流程和多种错误路径：
 * 1. 新增管理员账号并登录，获取鉴权上下文。
 * 2. 创建两个审核事件，一个由自己操作，一个由其他人（随机 UUID）操作。
 * 3. 针对自己产生的审核事件发起申诉，并校验字段关联关系。
 * 4. 针对他人产生的审核事件发起申诉，并确认业务是否允许及数据链路。
 * 5. 尝试对不存在的审核事件创建申诉，断言报错。
 * 6. 针对同一审核事件重复发起申诉，应触发主键/唯一约束报错。
 * 7. 使用非法 event/actor id 尝试，验证相关错误。
 * 8. 缺失必填字段（如 status）或非法 status，校验约束触发。
 *
 * 所有合法操作均需 typia.assert 校验返回类型与字段内容；错误分支均用 TestValidator.error 断言。
 */
export async function test_api_admin_appeal_creation_for_any_moderation_event(connection: api.IConnection) {
  // 1. 注册新管理员并登录
  const email = typia.random<string & tags.Format<'email'>>();
  const password = "P@ssw0rd!";
  const admin = await api.functional.auth.admin.register.signUp(connection, { body: { email, password } satisfies IAdminAuth.SignUp });
  typia.assert(admin);

  await api.functional.auth.admin.login.signIn(connection, { body: { email, password } satisfies IAdminAuth.SignIn });

  // 2. 创建两个审核事件：一个为自己作为 actor，一个为随机 actor
  const modEvent1 = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, {
    body: {
      actor_id: admin.adminId,
      event_type: "block",
      target_inquiry_id: typia.random<string & tags.Format<'uuid'>>(),
      target_review_id: null,
      reason: "测试管理员本人产生的审核事件",
      attached_ai_evidence_id: null,
      referenced_event_id: null,
    } satisfies IShoppingMallAiBackendModerationEvent.ICreate,
  });
  typia.assert(modEvent1);

  const randomActorId = typia.random<string & tags.Format<'uuid'>>();
  const modEvent2 = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, {
    body: {
      actor_id: randomActorId,
      event_type: "warn",
      target_inquiry_id: null,
      target_review_id: typia.random<string & tags.Format<'uuid'>>(),
      reason: "测试其他人产生的审核事件",
      attached_ai_evidence_id: null,
      referenced_event_id: null,
    } satisfies IShoppingMallAiBackendModerationEvent.ICreate,
  });
  typia.assert(modEvent2);

  // 3. 针对自己操作的事件申诉
  const appeal1 = await api.functional.shoppingMallAiBackend.admin.appeals.create(connection, {
    body: {
      moderation_event_id: modEvent1.id,
      appellant_id: admin.adminId,
      status: "pending",
      decision_comment: "管理员对自身事件申诉",
    } satisfies IShoppingMallAiBackendAppeal.ICreate,
  });
  typia.assert(appeal1);
  TestValidator.equals("appeal 事件关联正确")(appeal1.moderation_event_id)(modEvent1.id);
  TestValidator.equals("申诉人正确")(appeal1.appellant_id)(admin.adminId);
  TestValidator.equals("申诉状态")(appeal1.status)("pending");

  // 4. 针对他人操作事件申诉
  const appeal2 = await api.functional.shoppingMallAiBackend.admin.appeals.create(connection, {
    body: {
      moderation_event_id: modEvent2.id,
      appellant_id: admin.adminId,
      status: "pending",
      decision_comment: "管理员为他人申诉",
    } satisfies IShoppingMallAiBackendAppeal.ICreate,
  });
  typia.assert(appeal2);
  TestValidator.equals("appeal 事件2 关联正确")(appeal2.moderation_event_id)(modEvent2.id);
  TestValidator.equals("申诉人仍为管理员")(appeal2.appellant_id)(admin.adminId);
  TestValidator.equals("申诉状态")(appeal2.status)("pending");

  // 5. 对不存在的事件申诉，应错误
  TestValidator.error("不存在事件申诉应报错")(() =>
    api.functional.shoppingMallAiBackend.admin.appeals.create(connection, {
      body: {
        moderation_event_id: typia.random<string & tags.Format<'uuid'>>(),
        appellant_id: admin.adminId,
        status: "pending",
        decision_comment: "应当失败（事件不存在）",
      } satisfies IShoppingMallAiBackendAppeal.ICreate,
    }),
  );

  // 6. 同一事件重复申诉，应错误
  TestValidator.error("重复申诉同一审核事件应报错")(() =>
    api.functional.shoppingMallAiBackend.admin.appeals.create(connection, {
      body: {
        moderation_event_id: modEvent1.id,
        appellant_id: admin.adminId,
        status: "pending",
        decision_comment: "重复申诉同事件-应失败",
      } satisfies IShoppingMallAiBackendAppeal.ICreate,
    }),
  );

  // 7. 非法事件ID、actor ID 校验
  TestValidator.error("非法 event ID 应报错")(() =>
    api.functional.shoppingMallAiBackend.admin.appeals.create(connection, {
      body: {
        moderation_event_id: "invalid-uuid",
        appellant_id: admin.adminId,
        status: "pending",
        decision_comment: "非法事件 ID",
      } as any,
    }),
  );
  TestValidator.error("非法 appellant ID 应报错")(() =>
    api.functional.shoppingMallAiBackend.admin.appeals.create(connection, {
      body: {
        moderation_event_id: modEvent1.id,
        appellant_id: "invalid-uuid",
        status: "pending",
        decision_comment: "非法 actor id",
      } as any,
    }),
  );

  // 8. 缺失必填字段（status）和非法 status 值校验
  TestValidator.error("缺失 status 应报错")(() =>
    api.functional.shoppingMallAiBackend.admin.appeals.create(connection, {
      body: {
        moderation_event_id: modEvent1.id,
        appellant_id: admin.adminId,
        // 未提供 status
        decision_comment: "缺少 status",
      } as any,
    }),
  );
  TestValidator.error("非法 status 应报错")(() =>
    api.functional.shoppingMallAiBackend.admin.appeals.create(connection, {
      body: {
        moderation_event_id: modEvent1.id,
        appellant_id: admin.adminId,
        status: "invalid_status",
        decision_comment: "非法 status 值",
      } as any,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendModerationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendModerationEvent";
import type { IShoppingMallAiBackendAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAppeal";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate updating the status and decision comment of an existing appeal as an admin, including business rules enforcement and post-outcome immutability.
 *
 * This test covers end-to-end workflow for appeal record updates by an authorized admin in the shopping mall AI backend. The appeal status is changed (e.g., to 'approved'), and a resolution/decision comment is set. The test verifies that only admins can update, and that once an appeal reaches a terminal status (such as 'approved' or 'rejected'), further modification attempts are rejected as per compliance rules. Error handling is checked for post-closure update attempts. Creation and update events also serve as audit logs, helping ensure traceability, though audit logs are not directly asserted.
 *
 * 1. Register a new admin and login to get authorization (JWT).
 * 2. Create a moderation event (actor is the admin) to associate with the new appeal.
 * 3. Create an appeal against this moderation event by the admin.
 * 4. As authorized admin, update the appeal: change status to 'approved', add a decision_comment.
 * 5. Validate the update by checking status and decision_comment fields.
 * 6. Attempt to update the already-approved appeal again (should fail, trigger an error for updating a closed appeal).
 * 7. Appeal creation/update actions serve as audit log events (not directly asserted here, but contractually expected).
 */
export async function test_api_admin_appeal_update_status_and_decision(
  connection: api.IConnection,
) {
  // 1. Register and login as admin (obtain admin JWT for authorization)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword123!";
  const adminRegister = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminRegister);

  // Re-login as admin to assert correct authentication lifecycle
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminLogin);

  // 2. Create a moderation event linked to this admin
  const moderationEvent = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, {
    body: {
      actor_id: adminLogin.adminId,
      event_type: "escalate",
      target_inquiry_id: null,
      target_review_id: null,
      reason: "Initial moderation event for appeal workflow.",
      attached_ai_evidence_id: null,
      referenced_event_id: null,
    },
  });
  typia.assert(moderationEvent);

  // 3. Create an appeal pointing to the moderation event (appellant is the same admin)
  const appeal = await api.functional.shoppingMallAiBackend.admin.appeals.create(connection, {
    body: {
      moderation_event_id: moderationEvent.id,
      appellant_id: adminLogin.adminId,
      status: "pending",
      decision_comment: null,
    },
  });
  typia.assert(appeal);

  // 4. As authorized admin, update the appeal: approve it and set decision comment
  const updatedAppeal = await api.functional.shoppingMallAiBackend.admin.appeals.update(connection, {
    appealId: appeal.id,
    body: {
      status: "approved",
      decision_comment: "Appeal approved after full admin review.",
    },
  });
  typia.assert(updatedAppeal);
  TestValidator.equals("appeal id matches")(updatedAppeal.id)(appeal.id);
  TestValidator.equals("appeal status is approved")(updatedAppeal.status)("approved");
  TestValidator.equals("decision comment set")(updatedAppeal.decision_comment)("Appeal approved after full admin review.");

  // 5. Attempt to update closed (approved) appeal again — should error
  await TestValidator.error("cannot update closed appeal")(async () => {
    await api.functional.shoppingMallAiBackend.admin.appeals.update(connection, {
      appealId: appeal.id,
      body: {
        status: "rejected",
        decision_comment: "Should not update after final approval.",
      },
    });
  });

  // 6. By API contract, appeal create/update events are audit-logged (not directly asserted).
}

