/**
 * Validate retrieval of a specific product-to-channel mapping by its ID for a seller's product.
 *
 * Business Context:
 * Sellers may map their products to different channels/platforms. Retrieving these mappings is crucial for managing listings and channel synchronization.
 *
 * Test Workflow:
 * 1. Create a product under the seller context (simulated as already authenticated seller connection).
 * 2. Create a channel mapping for that product, using a generated channel_id (uuid).
 * 3. Retrieve the mapping using productId and the returned productChannelMapId.
 * 4. Validate that the returned mapping matches what was created (ids, status, channel, timestamps).
 * 5. Validate that all essential fields are present and match expectations (owner, mapping-link, audit fields).
 */
export async function test_api_product_channel_map_detail_retrieval_success(
  connection: api.IConnection,
) {
  // 1. Create a product as seller
  const productInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    description: RandomGenerator.content()()(),
    main_image_uri: null,
    status: "draft",
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: productInput });
  typia.assert(product);
  TestValidator.equals("product name")(product.name)(productInput.name);
  TestValidator.equals("product status")(product.status)(productInput.status);

  // 2. Create a channel mapping for this product
  const channelId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const mappingInput: IShoppingMallAiBackendProductChannelMap.ICreate = {
    product_id: product.id,
    channel_id: channelId,
    status: "active",
  };
  const productChannelMap = await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.createProductChannelMap(connection, {
    productId: product.id,
    body: mappingInput,
  });
