import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductChannelMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductChannelMap";

/**
 * Validate seller update of product-channel mappings.
 *
 * Ensures that:
 *    - Sellers can update product-channel mappings (e.g., change status) for their own products
 *    - Only allowed fields (status) can be changed during update
 *    - Updating mapping on a product not owned by the seller is forbidden
 *    - Duplicate mapping to same channel is not allowed
 *    - Invalid product ID or channel mapping ID triggers errors
 *    - Upon update, audit fields (updated_at, status) reflect the change
 *
 * Steps:
 * 1. Create a seller-owned product
 * 2. Create a product-channel mapping for that product
 * 3. Successfully update status for the mapping and verify result
 * 4. Attempt to update a mapping belonging to a different product (should fail)
 * 5. Attempt to update mapping using invalid mapping ID (should fail)
 * 6. Ensure only 'status' can be changed, not other fields
 * 7. Attempt duplicate mapping to same channel and verify error (indirectly, covers channel uniqueness if system-level restriction applies on update)
 */
export async function test_api_product_channel_map_update_by_seller(connection: api.IConnection) {
  // 1. Create a seller-owned product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(3),
      main_image_uri: null,
      status: "draft",
    },
  });
  typia.assert(product);

  // 2. Create a product-channel mapping for that product
  const mapping = await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.createProductChannelMap(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      channel_id: typia.random<string & tags.Format<"uuid">>(),
      status: "active",
    },
  });
  typia.assert(mapping);

  // 3. Successfully update status for the mapping and verify result
  const updated = await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.updateProductChannelMap(connection, {
    productId: product.id,
    productChannelMapId: mapping.id,
    body: {
      status: "inactive",
    },
  });
  typia.assert(updated);
  TestValidator.equals("updated mapping id")(updated.id)(mapping.id);
  TestValidator.equals("status updated")(updated.status)("inactive");
  TestValidator.notEquals("updated_at should change")(updated.updated_at)(mapping.updated_at);

  // 4. Attempt update on mapping using different product id (should fail)
  await TestValidator.error("Cannot update mapping using wrong product id")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.updateProductChannelMap(connection, {
      productId: typia.random<string & tags.Format<"uuid">>(), // not owner
      productChannelMapId: mapping.id,
      body: {
        status: "active",
      },
    });
  });

  // 5. Attempt update using invalid mapping id (should fail)
  await TestValidator.error("Invalid mapping id triggers error")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.updateProductChannelMap(connection, {
      productId: product.id,
      productChannelMapId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        status: "active",
      },
    });
  });

  // 6. Ensure only 'status' can be changed; try updating with empty object (legal: should not fail, expect no change)
  const updatedNoop = await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.updateProductChannelMap(connection, {
    productId: product.id,
    productChannelMapId: mapping.id,
    body: {},
  });
  typia.assert(updatedNoop);
  TestValidator.equals("mapping id unchanged")(updatedNoop.id)(mapping.id);

  // 7. Attempt duplicate mapping to the same channel (should fail if not allowed)
  //    Create new product, new mapping, then attempt to update to existing channel id (should fail)
  const product2 = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: product.seller_id, // same seller
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(3),
      main_image_uri: null,
      status: "draft",
    },
  });
  typia.assert(product2);

  const mapping2 = await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.createProductChannelMap(connection, {
    productId: product2.id,
    body: {
      product_id: product2.id,
      channel_id: mapping.channel_id, // intentional duplicate
      status: "active",
    },
  });
  typia.assert(mapping2);

  // Now attempt to update mapping2 to use the same channel id (if system prohibits this, error)
  await TestValidator.error("Duplicate channel mapping forbidden")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.updateProductChannelMap(connection, {
      productId: product2.id,
      productChannelMapId: mapping2.id,
      body: { status: "active" },
    });
  });
}

