import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendErrorLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendErrorLog";
import type { IPageIShoppingMallAiBackendErrorLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendErrorLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for searching error logs with filter conditions and pagination in the admin backend.
 *
 * This test ensures that admins can retrieve error logs filtered by various criteria such as error code,
 * severity, root cause entity, time window, and pagination. Edge cases are checked for invalid parameters,
 * insufficient privileges, and empty sets.
 *
 * Steps:
 * 1. Authenticate as admin and obtain a JWT token for privileged access.
 * 2. Perform a PATCH search on error logs with representative filters (error code, severity, entity, timestamps, pagination).
 * 3. Validate that the data, pagination fields, and filters are respected in results.
 * 4. Perform a search with impossible filters and confirm an empty result set is returned.
 * 5. Attempt search with invalid parameters (e.g., negative limit) and expect an error.
 * 6. Attempt search without authentication and verify that authorization error is thrown.
 */
export async function test_api_error_log_search_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Admin login to obtain authentication for the subsequent error log search
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminTestPassword123!";
  // (Assume admin account pre-exists due to lack of admin signup endpoint)
  const loginOutput = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(loginOutput);
  // Set Authorization header for admin
  connection.headers = {
    ...connection.headers,
    Authorization: loginOutput.setHeaders.Authorization,
  };

  // 2. Search error logs with representative filter criteria
  const now = new Date();
  const fromDate = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 30).toISOString(); // 30 days ago
  const toDate = now.toISOString();
  const filterRequest: IShoppingMallAiBackendErrorLog.IRequest = {
    error_code: "API_ERR_001",
    severity_level: "error",
    root_cause_entity_type: "order",
    occurred_at_from: fromDate,
    occurred_at_to: toDate,
    sort_by: "occurred_at",
    order: "desc",
    page: 0,
    limit: 10,
  };
  const result = await api.functional.shoppingMallAiBackend.admin.errorLogs.search(connection, {
    body: filterRequest,
  });
  typia.assert(result);
  // 3. Validate the returned results
  TestValidator.predicate("pagination matches page/limit")(
    result.pagination.limit === 10,
  );
  TestValidator.equals("page number is 1-based")(result.pagination.current)(1); // 1-based per contract
  TestValidator.predicate("summary rows match error_code & severity")(
    result.data.every(
      (item) => item.error_code === filterRequest.error_code && item.severity_level === filterRequest.severity_level,
    ),
  );

  // 4. Edge case: filter returns no results
  const emptyFilter = { ...filterRequest, error_code: "NON_EXISTENT_CODE" };
  const emptyResult = await api.functional.shoppingMallAiBackend.admin.errorLogs.search(connection, {
    body: emptyFilter,
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty data")(emptyResult.data.length)(0);

  // 5. Edge case: search with invalid parameter (negative limit)
  const invalidFilter = { ...filterRequest, limit: -10 };
  await TestValidator.error("invalid limit")(async () => {
    await api.functional.shoppingMallAiBackend.admin.errorLogs.search(connection, {
      body: invalidFilter,
    });
  });

  // 6. Edge case: missing privileges (no admin Authorization header)
  const { Authorization, ...headersNoAuth } = connection.headers ?? {};
  const connNoAuth: api.IConnection = {
    ...connection,
    headers: headersNoAuth,
  };
  await TestValidator.error("authorization required")(async () => {
    await api.functional.shoppingMallAiBackend.admin.errorLogs.search(connNoAuth, {
      body: filterRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendErrorLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendErrorLog";
import type { IPageIShoppingMallAiBackendErrorLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendErrorLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for error log detail retrieval (success and error cases)
 *
 * This test covers the retrieval of detailed error log information for administrators using the /shoppingMallAiBackend/admin/errorLogs/{errorLogId} API. It validates that admins can fetch valid records, that the system returns all fields (code, message, context, severity, root cause, timestamps), and that proper business errors are returned for nonexistent or unauthorized access. Also ensures that audit controls are in place for access attempts.
 *
 * #### Steps:
 * 1. Authenticate as admin (POST /auth/admin/login) to get JWT and store it in the connection
 * 2. Search for an existing error log (PATCH /shoppingMallAiBackend/admin/errorLogs) and select an available errorLogId
 * 3. Fetch error log detail for found errorLogId (GET /shoppingMallAiBackend/admin/errorLogs/{errorLogId}) as admin and validate all fields are present and type-correct
 * 4. Try to fetch an error log with a random UUID (not present), check that a not-found error is returned
 * 5. Simulate non-admin by clearing the Authorization header from the connection and retry GET; an unauthorized error should be returned
 * 6. (Access audit logging is mentioned as in scope but cannot be programmatically validated via API—note this as a limitation)
 */
export async function test_api_error_log_detail_retrieval_for_existing_and_nonexistent_id(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin-password";
  // NOTE: In real test, you would register admin if system supports sign-up; here we sign in
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminLogin);
  // Store the Authorization header for admin session
  connection.headers = {
    ...connection.headers,
    Authorization: adminLogin.setHeaders.Authorization,
  };

  // Step 2: Search for existing error logs
  const searchResponse = await api.functional.shoppingMallAiBackend.admin.errorLogs.search(connection, {
    body: {}, // empty means no filter, get recent logs
  });
  typia.assert(searchResponse);

  // Select a valid errorLogId if available
  const summaries = searchResponse.data;
  TestValidator.predicate("at least one error log exists")(summaries.length > 0);
  const validErrorLogId = summaries[0].id;

  // Step 3: Fetch error log detail for found errorLogId
  const logDetail = await api.functional.shoppingMallAiBackend.admin.errorLogs.at(connection, {
    errorLogId: validErrorLogId,
  });
  typia.assert(logDetail);
  // Validate required fields
  TestValidator.equals("log id matches")(logDetail.id)(validErrorLogId);
  TestValidator.predicate("error_code present")(typeof logDetail.error_code === "string" && logDetail.error_code.length > 0);
  TestValidator.predicate("error_message present")(typeof logDetail.error_message === "string" && logDetail.error_message.length > 0);
  TestValidator.predicate("error_context present")(typeof logDetail.error_context === "string");
  TestValidator.predicate("severity_level present")(typeof logDetail.severity_level === "string" && logDetail.severity_level.length > 0);
  TestValidator.predicate("occurred_at present")(typeof logDetail.occurred_at === "string" && logDetail.occurred_at.length > 0);
  // Optional fields
  if ("root_cause_entity_type" in logDetail) {
    TestValidator.predicate("root_cause_entity_type string or null")(
      logDetail.root_cause_entity_type === null || typeof logDetail.root_cause_entity_type === "string"
    );
  }
  if ("root_cause_entity_id" in logDetail) {
    TestValidator.predicate("root_cause_entity_id string or null")(
      logDetail.root_cause_entity_id === null || typeof logDetail.root_cause_entity_id === "string"
    );
  }

  // Step 4: Try fetching nonexistent error log (random UUID)
  const randomErrorLogId = typia.random<string & tags.Format<"uuid">>();
  // Ensure it's not in the list of existing IDs
  if (!summaries.some((s) => s.id === randomErrorLogId)) {
    await TestValidator.error("not found for nonexistent error log id")(
      () => api.functional.shoppingMallAiBackend.admin.errorLogs.at(connection, { errorLogId: randomErrorLogId })
    );
  }

  // Step 5: Simulate non-admin/no-token
  // Remove Authorization header
  const nonAdminConnection = { ...connection, headers: { ...connection.headers } };
  delete nonAdminConnection.headers?.Authorization;
  await TestValidator.error("unauthorized for non-admin or no token")(
    () => api.functional.shoppingMallAiBackend.admin.errorLogs.at(nonAdminConnection, { errorLogId: validErrorLogId })
  );
  // Step 6: Documentation: Access logging was not validated, as not checkable from API
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAuditLog";
import type { IPageIShoppingMallAiBackendAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAuditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate advanced audit log search by multiple filters as authorized and unauthorized users, including edge validation and empty result.
 *
 * Business context: Audit log review is critical for compliance monitoring, incident review, and platform security oversight. Only system admins may access audit log history. The test checks that an authenticated admin can filter/search audit logs using various criteria, and that input validation and access control function as required.
 *
 * Steps:
 * 1. Log in as an admin user to obtain a valid JWT for authentication.
 * 2. Ensure the backend has several audit log entries with diverse action types ("create", "update", "delete"), multiple actor IDs, and various entities, times, and descriptions. (In real environments, setup/fixtures are required. This test assumes some logs are present.)
 * 3. Execute a PATCH search using a filter set (e.g., action_type="create", actor_id=adminId, actor_type, etc.).
 * 4. Assert that results in output.data match filter, and output.pagination matches the request.
 * 5. Attempt requests with invalid params (limit too high, bad date/time, bad page) and assert error occurs.
 * 6. Search with filters that intentionally yield no results and confirm empty result and zero records.
 * 7. Attempt search with no JWT (unauthorized access) and verify access is denied.
 */
export async function test_api_audit_log_advanced_search_by_action_and_actor(
  connection: api.IConnection,
) {
  // 1. Admin login for authorization
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Test!234";
  /*
   * NOTE: This test uses random admin credentials for demonstration.
   * In production E2E, ensure account/fixture creation or use a seeded test admin user.
   */
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminAuth);

  // 2. Prepare valid filter for audit log search (assume logs populated by platform events)
  const filter: IShoppingMallAiBackendAuditLog.IRequest = {
    action_type: "create",
    actor_id: adminAuth.adminId,
    actor_type: "admin",
    target_type: null,
    target_id: null,
    description: null,
    from: null,
    to: null,
    page: 1,
    limit: 10,
    sort: null,
    direction: null,
  };

  // 3. Perform valid multi-filter search as admin
  const page = await api.functional.shoppingMallAiBackend.admin.auditLogs.search(
    connection,
    { body: filter },
  );
  typia.assert(page);
  TestValidator.equals("pagination current matches")(page.pagination.current)(1);
  TestValidator.equals("pagination limit matches")(page.pagination.limit)(10);
  if (page.data.length) {
    for (const row of page.data) {
      TestValidator.equals("action_type matches")(row.action_type)("create");
      TestValidator.equals("actor_type matches")(row.actor_type)("admin");
      // Description content may or may not contain admin email depending on backend log format; skip strict string check.
    }
  }

  // 4. Error scenarios: invalid limit, page, and date/time formats
  for (const bad of [
    { ...filter, limit: 101 },
    { ...filter, page: 0 },
    { ...filter, from: "invalid-date" as any },
    { ...filter, to: "not-datetime" as any },
  ]) {
    await TestValidator.error("invalid search rejects")(() =>
      api.functional.shoppingMallAiBackend.admin.auditLogs.search(connection, {
        body: bad,
      }),
    );
  }

  // 5. No results (filters intentionally select nonexistent action_type)
  const none = await api.functional.shoppingMallAiBackend.admin.auditLogs.search(
    connection,
    {
      body: {
        ...filter,
        action_type: "NO_SUCH_ACTION_TYPE_EXPECTED_TO_MATCH_NOTHING",
      },
    },
  );
  typia.assert(none);
  TestValidator.equals("empty list when no match")(none.data.length)(0);
  TestValidator.equals("pagination.records is zero")(none.pagination.records)(0);

  // 6. Access control: search with no authentication (missing Authorization header)
  const noAuthConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized user cannot search logs")(() =>
    api.functional.shoppingMallAiBackend.admin.auditLogs.search(noAuthConnection, {
      body: filter,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAuditLog";
import type { IPageIShoppingMallAiBackendAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAuditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Comprehensive E2E test for retrieving audit log detail as admin and verifying access & permissions.
 *
 * This test validates that:
 * 1. Admin can retrieve a specific audit log by its ID and that all expected detail fields are present and correct.
 * 2. Error conditions are returned if a non-existent or deleted audit log ID is requested, or unauthorized access is attempted.
 * 3. Data integrity is maintained—the retrieved log fields match the summary returned by the listing/search endpoint.
 * 4. Requests are properly logged (by the nature of these endpoints, their own accesses should be compliant/audited).
 *
 * Steps:
 * 1. Admin user authenticates via login with valid credentials.
 * 2. Admin searches for audit logs (using generic filter: page=1, limit=1) to fetch at least one valid existing row.
 * 3. If a log is found, fetch detail by its ID via the 'at' endpoint.
 * 4. Verify all fields (id, action_type, actor_id, actor_type, target_type, target_id, occurred_at, description) match the values from the list summary and detail model.
 * 5. Test error path: fetch a detail using a random UUID (not present in search results), and verify error is returned (permission denied or not found).
 * 6. (Optional: as negative test, skip login and try direct detail fetch, verify access denied—out of scope due to stepwise dependency and system ownership of /auth/admin/login).
 */
export async function test_api_audit_log_detail_access_and_permission(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as admin
  // NOTE: This test assumes an existing admin credential in the system. If admin sign-up is unavailable,
  // test coverage is limited to systems where the test login is valid.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongP@ssw0rd";
  const adminLoginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLoginResponse);

  // Step 2: Search existing audit logs (paginate: first page, 1 row)
  const searchResult = await api.functional.shoppingMallAiBackend.admin.auditLogs.search(connection, {
    body: { page: 1, limit: 1 } satisfies IShoppingMallAiBackendAuditLog.IRequest,
  });
  typia.assert(searchResult);

  // Step 3: If found, fetch detail by ID and verify field match
  const logSummary = searchResult.data[0];
  if (logSummary) {
    const detail = await api.functional.shoppingMallAiBackend.admin.auditLogs.at(connection, {
      auditLogId: logSummary.id,
    });
    typia.assert(detail);
    TestValidator.equals("audit log id matches")(detail.id)(logSummary.id);
    TestValidator.equals("action type matches")(detail.action_type)(logSummary.action_type);
    TestValidator.equals("actor type matches")(detail.actor_type)(logSummary.actor_type);
    TestValidator.equals("target type matches")(detail.target_type)(logSummary.target_type);
    TestValidator.equals("description matches")(detail.description)(logSummary.description);
    TestValidator.equals("occurred_at matches")(detail.occurred_at)(logSummary.occurred_at);
    // Optionally check for existence of before/after/audit_payload, if present
  }

  // Step 4: Attempt fetching non-existent (random) audit log ID
  await TestValidator.error("non-existent auditLogId returns error")(async () => {
    await api.functional.shoppingMallAiBackend.admin.auditLogs.at(connection, {
      auditLogId: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test full customer registration flow and enforce email uniqueness and business password rules.
 *
 * Business context: Ensures customer onboarding via public sign-up API meets
 * required identity, uniqueness, and password policy expectations. Validates
 * correct API response shape (including JWT issuance, excluding password data),
 * business/DB constraints (unique email), and schema validation (required fields,
 * password policy enforcement). Error scenarios for duplicates, missing fields,
 * and weak/invalid passwords are all checked. This helps guarantee that both
 * successful and failed customer registrations follow expected business and audit
 * compliance.
 *
 * Steps:
 * 1. Register a new unique customer (valid input). Assert JWT token is returned and customer profile is correct. Password data must not be present at all in any response.
 * 2. Attempt to register with identical email (should fail with unique constraint error).
 * 3. Attempt to register omitting each required field; expect validation error on each.
 * 4. Attempt to register with a weak/invalid password; expect error.
 */
export async function test_api_customer_registration_and_email_uniqueness(
  connection: api.IConnection,
) {
  // 1. Register a new customer with unique, valid data
  const uniqueEmail = typia.random<string & tags.Format<"email">>();
  const nickname = RandomGenerator.alphabets(12);
  const phone = RandomGenerator.mobile();
  const name = RandomGenerator.name();
  const password = "ValidPW2025!";

  const response = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email: uniqueEmail,
        password,
        name,
        nickname,
        phone,
      } satisfies ICustomerSignUp.Request,
    },
  );
  typia.assert(response);
  // Assert Authorization header is returned and shape is correct
  TestValidator.predicate("JWT token is set in Authorization header")(
    typeof response.setHeaders === "object" &&
      typeof response.setHeaders.Authorization === "string" &&
      response.setHeaders.Authorization.length > 10,
  );
  // Assert returned customer profile matches input and password fields are NOT present
  TestValidator.equals("registered customer email matches")(response.customer.email)(uniqueEmail);
  TestValidator.equals("registered customer name matches")(response.customer.name)(name);
  TestValidator.equals("registered customer nickname matches")(response.customer.nickname)(nickname);
  TestValidator.equals("registered customer phone matches")(response.customer.phone)(phone);
  // Confirm NO password or hash field leaks to client
  if (Object.keys(response.customer).some((k) => k.toLowerCase().includes("pass")))
    throw new Error("Response customer exposes a password/hash field!");

  // 2. Attempt to register a second customer using identical email; should throw (duplicate email)
  await TestValidator.error("duplicate customer email should be rejected")(
    async () => {
      await api.functional.auth.customer.register.signUp(
        connection,
        {
          body: {
            email: uniqueEmail,
            password: "AnotherPW1!",
            name: RandomGenerator.name(),
            nickname: RandomGenerator.alphabets(10),
            phone: RandomGenerator.mobile(),
          } satisfies ICustomerSignUp.Request,
        },
      );
    },
  );

  // 3. Missing required fields (each omitted one-by-one)
  const validBase = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "ValidPW2025!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(10),
    phone: RandomGenerator.mobile(),
  };
  for (const field of ["email", "password", "name", "nickname", "phone"] as const) {
    // Create shallow copy and delete the required field
    const body = { ...validBase };
    // Without this property, TypeScript will not allow the type; to test, forcibly cast through subtyping
    delete (body as any)[field];
    await TestValidator.error(`registration fails when missing required field: ${field}`)(
      async () => {
        await api.functional.auth.customer.register.signUp(connection, {
          body: body as ICustomerSignUp.Request,
        });
      },
    );
  }

  // 4. Invalid/weak password ("123")
  await TestValidator.error("registration should fail due to weak/short password")(
    async () => {
      await api.functional.auth.customer.register.signUp(connection, {
        body: {
          ...validBase,
          password: "123",
        } satisfies ICustomerSignUp.Request,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * End-to-end validation for the admin login (sign in) API, covering both successful and failure authentication cases.
 *
 * Business context:
 * This test simulates admin login attempts to ensure the authentication endpoint behaves securely and as intended. It covers success, credential error, and user not found flows. Negative scenarios such as login for a locked/deleted user are noted but skipped as they require access not possible via public API.
 *
 * Steps:
 * 1. Register an admin with random, valid credentials
 * 2. Login with the correct credentials and validate the JWT and profile response
 * 3. Attempt to login with the correct email but wrong password (expect error, no JWT)
 * 4. Attempt to login with a non-existent email (expect error, no JWT)
 * 5. (Skipped) Attempt to login for a locked/deleted admin (not possible with current API)
 *
 * Audit and compliance guarantees (as per API/business contract) are automatically covered, as every login attempt triggers appropriate system audit, even if not observable directly in this test.
 */
export async function test_api_admin_login_success_and_failure_scenarios(
  connection: api.IConnection,
) {
  // 1. Register admin with random business-compliant credentials
  const email = typia.random<string & tags.Format<"email">>();
  const password = `P@ss${typia.random<string>().slice(0, 5)}`;
  const signUpOutput = await api.functional.auth.admin.register.signUp(connection, {
    body: { email, password } satisfies IAdminAuth.SignUp,
  });
  typia.assert(signUpOutput);

  // 2. Login with correct credentials, expect JWT, profile, status fields
  const successLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: { email, password } satisfies IAdminAuth.SignIn,
  });
  typia.assert(successLogin);
  TestValidator.predicate("JWT should be present")(
    typeof successLogin.jwt === "string" && !!successLogin.jwt.length,
  );
  TestValidator.equals("profile email matches")(successLogin.email)(email);
  TestValidator.predicate("Authorization header should be set")(
    typeof successLogin.setHeaders?.Authorization === "string" &&
      !!successLogin.setHeaders.Authorization.length,
  );

  // 3. Login with correct email and wrong password, expect error (no JWT, no profile)
  await TestValidator.error("login fails with incorrect password")(
    async () => {
      await api.functional.auth.admin.login.signIn(connection, {
        body: { email, password: password + "bad" } satisfies IAdminAuth.SignIn,
      });
    },
  );

  // 4. Login with a non-existent admin email, expect authentication error (no JWT, no profile)
  await TestValidator.error("login fails with non-existent email")(
    async () => {
      await api.functional.auth.admin.login.signIn(connection, {
        body: {
          email: `nonexist+${typia.random<string & tags.Format<"email">>()}`,
          password,
