import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
import type { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";

/**
 * Validate the admin's ability to soft-delete a mileage transaction from a specific wallet.
 *
 * This test verifies the following workflow:
 * 1. Create a new mileage wallet for a test customer
 * 2. Create a mileage transaction inside this wallet
 * 3. Soft-delete the mileage transaction using the admin API
 * 4. Attempt to delete the already deleted transaction again, expecting an error
 * 5. Attempt to delete a non-existent transaction, expecting an error
 *
 * Note: As there is no API to read deleted transactions or access audit logs, test validation focuses on deletion API behavior and error conditions.
 */
export async function test_api_mileage_transaction_soft_delete_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a mileage wallet as prerequisite for transactions
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      wallet_program: "brand",
      wallet_status: "active",
      wallet_label: "Test Wallet",
      security_code: null,
    } satisfies IShoppingMallAiBackendMileageWallet.ICreate,
  });
  typia.assert(wallet);

  // 2. Create a mileage transaction in the wallet
  const transaction = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.create(connection, {
    mileageWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      transaction_type: "accumulate",
      mileage_amount: 500,
      reference_id: null,
      transaction_reason: "Test case initial points",
    } satisfies IShoppingMallAiBackendMileageTransaction.ICreate,
  });
  typia.assert(transaction);

  // 3. Soft-delete the transaction (should succeed)
  await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.erase(connection, {
    mileageWalletId: wallet.id,
    mileageTransactionId: transaction.id,
  });

  // 4. Attempt to soft-delete the same transaction again; expect an error
  await TestValidator.error("deleting already deleted transaction must fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.erase(connection, {
        mileageWalletId: wallet.id,
        mileageTransactionId: transaction.id,
      });
    }
  );

  // 5. Attempt to delete a non-existent transaction; expect an error
  await TestValidator.error("deleting a non-existent transaction must fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.erase(connection, {
        mileageWalletId: wallet.id,
        mileageTransactionId: typia.random<string & tags.Format<"uuid">>(),
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IPageIShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductInquiry";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test advanced product inquiry search for a customer.
 *
 * This test ensures an authenticated customer can retrieve only their own product inquiries using advanced search, full-text, and pagination filters. It covers:
 * - Ownership enforcement: only own inquiries are visible, even with direct filters.
 * - Advanced filters: product_id, status, public/private, date range.
 * - Full-text keyword search in inquiry title/body.
 * - Pagination and summary data are validated.
 * - Attempts to use unauthorized filters (such as another user's customer_id) or invalid filters are prevented or constrained.
 *
 * Steps:
 * 1. Register a customer and auto-authenticate.
 * 2. Create several product inquiries for two products (mixing public/private, titles containing test keywords, different creation dates).
 * 3. Register a second customer and create their inquiry.
 * 4. Search for own inquiries and check that only the authenticated customer's data appears.
 * 5. Apply a filter by product_id and verify only those inquiries are returned.
 * 6. Do a keyword search on title/body and check correct matching.
 * 7. Filter by status (acquired from a created inquiry for realism).
 * 8. Filter by creation date range.
 * 9. Apply pagination and check pagination info and counts.
 * 10. Attempt to filter/search as another customer—confirm only own data is accessible.
 * 11. Try using an invalid filter (e.g., status with nonsense value) and ensure error or no results.
 */
export async function test_api_product_inquiry_advanced_filter_search_customer(
  connection: api.IConnection,
) {
  // 1. Register a customer (auto-authentication, JWT header set)
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerPassword = "TestPw@32145";
  const signUpRes = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email: customerEmail,
        password: customerPassword,
        name: RandomGenerator.name(),
        nickname: RandomGenerator.alphaNumeric(8),
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request,
    },
  );
  typia.assert(signUpRes);
  const customerId = signUpRes.customer.id;

  // 2. Create inquiries under this customer
  const productIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const inquiries: IShoppingMallAiBackendProductInquiry[] = [];
  for (const idx of [0, 1, 2, 3, 4]) {
    const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(
      connection,
      {
        body: {
          customer_id: customerId,
          product_id: productIds[idx % 2],
          title: idx === 2 ? "Alpha keyword inquiry" : `Standard Query #${idx}`,
          body: idx === 3 ? "Body mentioning Alpha string." : RandomGenerator.paragraph()(),
          public: idx % 2 === 1,
        } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
      },
    );
    typia.assert(inquiry);
    inquiries.push(inquiry);
  }

  // 3. Register a second customer and create their inquiry
  const otherEmail: string = typia.random<string & tags.Format<"email">>();
  const otherPassword = "TestOther@12345";
  const secondSignUp = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email: otherEmail,
        password: otherPassword,
        name: RandomGenerator.name(),
        nickname: RandomGenerator.alphaNumeric(8),
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request,
    },
  );
  typia.assert(secondSignUp);
  const otherCustomerId = secondSignUp.customer.id;

  const otherInquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(
    connection,
    {
      body: {
        customer_id: otherCustomerId,
        product_id: productIds[0],
        title: "Someone else's inquiry",
        body: "Non-related content.",
        public: true,
      } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
    },
  );
  typia.assert(otherInquiry);

  // Switch back to original customer by registering anew (token will be replaced)
  await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email: customerEmail,
        password: customerPassword,
        name: RandomGenerator.name(),
        nickname: RandomGenerator.alphaNumeric(8),
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request,
    },
  );

  // 4. Search for own inquiries (filter = none)
  const allOwn = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: {},
    },
  );
  typia.assert(allOwn);
  for (const i of allOwn.data)
    TestValidator.equals("customer id is self")(i.customer_id)(customerId);

  // 5. Filter by product_id
  const prodIdx = productIds[1];
  const byProduct = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: { product_id: prodIdx },
    },
  );
  typia.assert(byProduct);
  for (const i of byProduct.data) {
    TestValidator.equals("ownership")(i.customer_id)(customerId);
    TestValidator.equals("product id")(i.product_id)(prodIdx);
  }

  // 6. Full-text search (title/body contains "Alpha")
  const alphaSearch = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: { search: "Alpha" },
    },
  );
  typia.assert(alphaSearch);
  for (const i of alphaSearch.data) {
    TestValidator.equals("ownership")(i.customer_id)(customerId);
    TestValidator.predicate("contains Alpha in title or body")(
      i.title.includes("Alpha") || (!!i.body && i.body.includes("Alpha")),
    );
  }

  // 7. Filter by status
  const testStatus = inquiries[0].status;
  const byStatus = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: { status: testStatus },
    },
  );
  typia.assert(byStatus);
  for (const i of byStatus.data) {
    TestValidator.equals("ownership")(i.customer_id)(customerId);
    TestValidator.equals("status")(i.status)(testStatus);
  }

  // 8. Date range filter
  const rangeFrom = inquiries[0].created_at;
  const rangeTo = inquiries[inquiries.length - 1].created_at;
  const byRange = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: { created_from: rangeFrom, created_to: rangeTo },
    },
  );
  typia.assert(byRange);
  for (const i of byRange.data) {
    TestValidator.equals("ownership")(i.customer_id)(customerId);
  }

  // 9. Pagination check
  const paged = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: {
        page: 1,
        page_size: 2,
        sort_by: "created_at",
        sort_order: "asc",
      },
    },
  );
  typia.assert(paged);
  TestValidator.equals("page limit")(paged.pagination.limit)(2);
  TestValidator.equals("page current")(paged.pagination.current)(1);
  TestValidator.predicate("page size at most 2")(paged.data.length <= 2);

  // 10. Attempt to search as other customer (should return only own data)
  const bogus = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: { customer_id: otherCustomerId },
    },
  );
  typia.assert(bogus);
  for (const i of bogus.data)
    TestValidator.equals("customer always filtered to self")(i.customer_id)(customerId);

  // 11. Invalid status filter (should error or return zero results)
  await TestValidator.error("invalid status triggers error or empty result")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
        connection,
        {
          body: { status: "not_a_real_status_value" },
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IPageIShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductInquiry";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate advanced product inquiry search for seller context.
 *
 * Seller must only see product inquiries for their products, filtered by product_id, keywords, public/private, AI thresholds, date, etc. Unowned searches are rejected/empty. Pagination, sorting, access control, edge cases are all verified.
 * Steps:
 * 1. Register a new seller and simulate two products tied to this seller
 * 2. Register a customer
 * 3. Customer creates inquiries for each product and for unrelated product
 * 4. Seller runs advanced search with various filters; validate only correct queries are returned and errors/edge cases are handled.
 */
export async function test_api_product_inquiry_advanced_filter_search_seller(connection: api.IConnection) {
  // 1. Seller sign up
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const signUpBody: ISellerAuth.SignUp = {
    email: sellerEmail,
    password: "Password123!",
    companyName: RandomGenerator.alphabets(8) + " Inc.",
    businessNumber: ArrayUtil.repeat(10)(() => String(typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<9>>())).join(""),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(10),
    phone: RandomGenerator.mobile()
  };
  const sellerResp = await api.functional.auth.seller.register.signUp(connection, { body: signUpBody });
  typia.assert(sellerResp);
  // Use the auth token in all subsequent API calls
  connection.headers = { ...(connection.headers ?? {}), Authorization: sellerResp.setHeaders.Authorization };
  // 2. Simulate two products 'owned' by this seller
  const sellerProduct1 = typia.random<string & tags.Format<"uuid">>();
  const sellerProduct2 = typia.random<string & tags.Format<"uuid">>();
  // 3. Register a customer and simulate their UUID
  const customerId = typia.random<string & tags.Format<"uuid">>();
  // 4. Customer creates inquiries for each product (mix public/private), and one for unrelated product
  const inquiries = await ArrayUtil.asyncRepeat(5)(async index =>
    await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
      body: {
        customer_id: customerId,
        product_id: index < 3 ? sellerProduct1 : sellerProduct2,
        title: `Inquiry Title ${index}`,
        body: `Details about inquiry ${index} for product`,
        public: index % 2 === 0
      }
    })
  );
  // Also create an inquiry for a product this seller does NOT own
  const unrelatedProductId = typia.random<string & tags.Format<"uuid">>();
  await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: unrelatedProductId,
      title: "Unrelated Inquiry",
      body: "This product does not belong to the seller.",
      public: true
    }
  });
  // 5a. Seller searches for product1 inquiries
  const resProduct1 = await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { product_id: sellerProduct1, page: 1, page_size: 10 }
  });
  typia.assert(resProduct1);
  TestValidator.predicate("Only inquiries for product 1")(resProduct1.data.every(q => q.product_id === sellerProduct1));
  // 5b. Seller searches for product2 inquiries
  const resProduct2 = await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { product_id: sellerProduct2, page: 1, page_size: 10 }
  });
  typia.assert(resProduct2);
  TestValidator.predicate("Only inquiries for product 2")(resProduct2.data.every(q => q.product_id === sellerProduct2));
  // 5c. Filter by keyword present in a title
  const keyword = "Title 2";
  const resKeyword = await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { search: keyword, page: 1, page_size: 5 }
  });
  typia.assert(resKeyword);
  TestValidator.predicate("Title/body filter")(resKeyword.data.some(q => q.title.includes(keyword) || q.body.includes(keyword)));
  // 5d. Filter by AI sentiment (filter for likely positive inquiries; may yield 0 results if test data is random)
  await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { min_ai_sentiment_score: 0.5 }
  });
  // 5e. Filter by "public" status
  const resPublic = await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { public: true, page: 1, page_size: 10 }
  });
  typia.assert(resPublic);
  TestValidator.predicate("All inquiries public")(resPublic.data.every(q => q.public === true));
  // 5f. Sort by creation date descending
  const resSorted = await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { sort_by: "created_at", sort_order: "desc", page: 1, page_size: 10 }
  });
  typia.assert(resSorted);
  for (let i = 1; i < resSorted.data.length; ++i) {
    TestValidator.predicate(`Sort order desc`)(resSorted.data[i - 1].created_at >= resSorted.data[i].created_at);
  }
  // 5g. Try to search for a product the seller does NOT own
  const resUnowned = await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { product_id: unrelatedProductId }
  });
  typia.assert(resUnowned);
  TestValidator.equals("Inquiries for unowned product")(resUnowned.data.length)(0);
  // 5h. Try forbidden filter (customer_id as seller); must error
  await TestValidator.error("Customer ID filter forbidden for seller context")(
    async () => 
      await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, { body: { customer_id: customerId } })
  );
  // 5i. Not implementable: audit log/history endpoints, so skip.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IPageIShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductInquiry";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for admin's advanced filter and search functionality over product inquiries.
 *
 * Validates that:
 * - The admin can search system-wide by status (e.g. 'waiting', 'answered', 'blocked'), product_id, customer_id, full-text, AI moderation (sentiment/spam), date windows, public/private.
 * - Admin can retrieve paginated, sorted results and get deterministic paging.
 * - Runtime validation errors occur for illegal filter values (e.g., invalid status or page).
 *
 * Steps:
 * 1. Register and authenticate an admin user.
 * 2. Create diverse product inquiries as customers with various parameters.
 * 3. As admin, search/filter for various combinations and edge cases.
 * 4. Verify error cases for illegal/malformed filters.
 */
export async function test_api_product_inquiry_advanced_filter_search_admin(
  connection: api.IConnection,
) {
  // 1. Register an admin to get search privileges
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "A1strongPW!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminAuth);

  // 2. Seed product/customer/inquiry data
  const customerAId = typia.random<string & tags.Format<"uuid">>();
  const productAId = typia.random<string & tags.Format<"uuid">>();
  const productBId = typia.random<string & tags.Format<"uuid">>();

  // Inquiry 1: customerA about productA, public, expecting status 'waiting' by default
  const inquiryWaiting = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerAId,
      product_id: productAId,
      title: "Shipping?",
      body: "How soon can I expect delivery if I order productA?",
      public: true,
    },
  });
  typia.assert(inquiryWaiting);

  // Inquiry 2: customerA about productB, private
  const inquiryPrivate = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerAId,
      product_id: productBId,
      title: "Materials & eco?",
      body: "Is productB made from sustainable materials?",
      public: false,
    },
  });
  typia.assert(inquiryPrivate);

  // Inquiry 3: customerB about productA, private
  const customerBId = typia.random<string & tags.Format<"uuid">>();
  const inquiryBlocked = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerBId,
      product_id: productAId,
      title: "Blocked Post",
      body: "This inquiry will emulate a blocked state.",
      public: false,
    },
  });
  typia.assert(inquiryBlocked);

  // 3. As admin, search/filter for various criteria
  // (a) By product ID, public, and status
  const result1 = await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
    body: {
      product_id: productAId,
      status: inquiryWaiting.status,
      public: true,
      page: 1,
      page_size: 10,
      sort_by: "created_at",
      sort_order: "desc",
    },
  });
  typia.assert(result1);
  TestValidator.predicate("status+product_id+public finds expected")(result1.data.some(x => x.id === inquiryWaiting.id));

  // (b) By customer, private, keyword search
  const result2 = await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
    body: {
      customer_id: customerAId,
      public: false,
      search: "eco",
      page: 1,
      page_size: 10,
      sort_by: "title",
      sort_order: "asc",
    },
  });
  typia.assert(result2);
  TestValidator.predicate("customer+private+keyword finds expected")(result2.data.some(x => x.id === inquiryPrivate.id));

  // (c) Pagination deterministic test
  const pagedOne = await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
    body: {
      page: 1,
      page_size: 1,
      sort_by: "created_at",
      sort_order: "asc",
    },
  });
  const pagedTwo = await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
    body: {
      page: 2,
      page_size: 1,
      sort_by: "created_at",
      sort_order: "asc",
    },
  });
  typia.assert(pagedOne);
  typia.assert(pagedTwo);
  TestValidator.notEquals("paging delivers diff data")(pagedOne.data[0]?.id)(pagedTwo.data[0]?.id);

  // (d) Date window filter
  const winFrom = new Date(Date.now() - 1_000 * 60 * 10).toISOString();
  const winTo = new Date(Date.now() + 1_000 * 60 * 10).toISOString();
  const resultWin = await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
    body: {
      created_from: winFrom,
      created_to: winTo,
      page: 1,
      page_size: 10,
    },
  });
  typia.assert(resultWin);
  TestValidator.predicate("date window returns data")(resultWin.data.length > 0);

  // (e) AI moderation filter
  const resultAi = await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
    body: {
      min_ai_sentiment_score: -1,
      max_ai_sentiment_score: 1,
      page: 1,
      page_size: 10,
    },
  });
  typia.assert(resultAi);
  TestValidator.predicate("AI filter returns data")(resultAi.data.length > 0);

  // (f) Error: illegal status
  await TestValidator.error("illegal status rejected")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
      body: {
        status: "$illegal_status$",
        page: 1,
        page_size: 2,
      },
    });
  });
  // (g) Error: negative page
  await TestValidator.error("negative page rejected")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
      body: {
        page: -1,
        page_size: 10,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
