 *
 * This test covers the full lifecycle of admin JWT validation:
 * 1. Register a new admin (random email/password)
 * 2. Login as the same admin and get a JWT
 * 3. Validate the JWT with the /auth/admin/validate endpoint
 *
 * It verifies:
 * - Registration, login, and validation work as expected
 * - All profile, RBAC, and session expiry fields are included and match
 * - Token validation API confirms validity, matches admin claims, and follows session policy
 * - Side effect: Audit logs are created by backend (not directly checked here)
 */
export async function test_api_admin_auth_token_validation_success(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const email: string & tags.Format<"email"> = typia.random<string & tags.Format<"email">>();
  const password: string = RandomGenerator.alphaNumeric(12);

  const registration = await api.functional.auth.admin.register.signUp(connection, {
