/**
 * Validate adding products to the authenticated customer’s favorite list and duplicate/invalid case handling.
 *
 * This test verifies that:
 *   - A customer can favorite a new product by providing a valid productId;
 *   - The returned record correctly links to the customer and product, and is not marked deleted;
 *   - Favoriting the same product again handles the duplicate gracefully (by returning the same link or an error);
 *   - Invalid productId (non-existent or logically deleted products) results in a validation error;
 *   - The customer’s favoriteProducts list is queried as a prerequisite to assert the expected state before and after;
 *
 * Step-by-step process:
 * 1. Query favorite products with PATCH to ensure the customer has not yet favorited a test productId
 * 2. Attempt to favorite a new productId with POST: expect success and correct reference
 * 3. Re-query favoriteProducts to assert the new entry exists (by productId and customer_id)
 * 4. Attempt to favorite the same productId again: expect either the same resource or a handled duplicate error
 * 5. Try POST with an obviously invalid UUID (malformed): expect a validation error
 * 6. Try POST with a random but well-formed productId (assuming non-existent or deleted): expect a validation error
 */
export async function test_api_favorite_product_creation_and_duplicate_handling(connection: api.IConnection) {
  // 1. Setup: Choose a new product ID not already favorited
  const productId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 1.1 Query current favorites to confirm productId is not yet favorited
  const before: IPageIShoppingMallAiBackendFavoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
    body: { product_id: productId } satisfies IShoppingMallAiBackendFavoriteProduct.IRequest,
  });
  typia.assert(before);
  TestValidator.equals("product not yet favorited - precondition")(before.data.length)(0);

  // 2. POST a new favorite
  const favorite: IShoppingMallAiBackendFavoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: { product_id: productId } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate,
  });
  typia.assert(favorite);
  TestValidator.equals("link is for correct product")(favorite.product_id)(productId);
  TestValidator.predicate("not deleted")(favorite.deleted_at == null);

  // 3. Query favorites again to confirm new entry
  const after: IPageIShoppingMallAiBackendFavoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
    body: { product_id: productId } satisfies IShoppingMallAiBackendFavoriteProduct.IRequest,
  });
  typia.assert(after);
  TestValidator.equals("favorite appears now")(after.data.length)(1);
  TestValidator.equals("favorite matches created")(after.data[0].id)(favorite.id);

  // 4. Attempt duplicate creation: expect handled duplicate (same record or error)
  try {
    const duplicate: IShoppingMallAiBackendFavoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
      body: { product_id: productId } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate,
    });
    typia.assert(duplicate);
    TestValidator.equals("duplicate record, should match first one")(duplicate.id)(favorite.id);
  } catch (err) {
    // Acceptable: error due to already favorited
    TestValidator.predicate("duplicate favorite throws error")(true);
  }

  // 5. Attempt to favorite with an invalid/malformed UUID
  TestValidator.error("malformed UUID should throw")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
      body: { product_id: "not-a-uuid" as any },
    })
  );

  // 6. Attempt to favorite a random (well-formed but likely non-existent) productId
  const nonExistentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("favoriting non-existent product should fail")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
      body: { product_id: nonExistentId } as IShoppingMallAiBackendFavoriteProduct.ICreate,
    })
  );
}

