/**
 * Test successful retrieval of a specific order item detail by the owning customer.
 *
 * This test covers a full workflow where a customer account is created and authenticated. It then creates a new order for that customer, adds an order item, and finally retrieves the specific detail of the added order item with proper authorization. The test validates that the returned item fields (such as product_id, order_id, quantity, price, and timestamps) match the data submitted, and ensures the customer has access to their own orders.
 *
 * Steps:
 * 1. Register a new customer
 * 2. Log in the customer (so connection has Authorization header)
 * 3. Create a new order for this customer
 * 4. Add an item to this order (random product id, snapshot id, price, etc.)
 * 5. Retrieve the item details using GET and validate fields
 */
export async function test_api_order_item_detail_success_customer_access(
  connection: api.IConnection,
) {
  // 1. Register a customer
  const password = "password123!";
  const email = typia.random<string & tags.Format<"email">>();
  const signUpResp = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email,
        password,
        name: RandomGenerator.name(),
        nickname: RandomGenerator.alphaNumeric(8),
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request,
    },
  );
  typia.assert(signUpResp);
  const customerId = signUpResp.customer.id;

  // 2. Log in the customer
  const loginResp = await api.functional.auth.customer.login.signIn(
    connection,
    {
      body: {
        email,
        password,
      } satisfies ICustomerSignIn.Request,
    },
  );
  typia.assert(loginResp);
  TestValidator.equals("customer id matches after login")(
    loginResp.customer.id,
  )(customerId);

  // 3. Create a new order for this customer
  const orderCreate: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customerId,
    order_number: RandomGenerator.alphaNumeric(16),
    total_amount: 10000,
    currency_code: "KRW",
    current_status: "created",
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(
    connection,
    { body: orderCreate },
  );
  typia.assert(order);
  TestValidator.equals("customer id for order")(order.customer_id)(customerId);
  TestValidator.equals("order_number")(order.order_number)(
    orderCreate.order_number,
  );

  // 4. Add an item to this order
  const itemCreate: IShoppingMallAiBackendOrderItem.ICreate = {
    order_id: order.id,
    product_id: typia.random<string & tags.Format<"uuid">>(),
    product_snapshot_id: typia.random<string & tags.Format<"uuid">>(),
    quantity: 2,
    unit_price: 5000,
    currency_code: "KRW",
  };
  const orderItem =
    await api.functional.shoppingMallAiBackend.customer.orders.orderItems.create(
      connection,
      {
        orderId: order.id,
        body: itemCreate,
      },
    );
