/**
 * Validate that one customer cannot access another customer's order item detail (forbidden error test).
 *
 * Business Context:
 * Order item details are strictly accessible only by the customer that owns/placed the related order. This test verifies that access controls are enforced by the backend—ensuring data privacy.
 *
 * Test Steps:
 * 1. Register two different customers with unique emails and identities.
 * 2. Log in as Customer A (the first customer; get/set jwt for further requests).
 * 3. Customer A creates an order with valid required fields.
 * 4. Customer A adds a new order item to the order (using product/sample data).
 * 5. Log out/switch to Customer B by authenticating as Customer B (second customer).
 * 6. Customer B attempts to fetch the order item details belonging to Customer A's order and order item.
 * 7. Validate that a forbidden (authorization) error is thrown, confirming access control enforcement.
 */
export async function test_api_order_item_detail_forbidden_other_customer(
  connection: api.IConnection,
) {
  // 1. Register Customer A
  const emailA: string = typia.random<string & tags.Format<"email">>();
  const passwordA = "TestPasswordA1!";
  const regA = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: emailA,
      password: passwordA,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(regA);
  const customerA = regA.customer;

  // 2. Register Customer B
  const emailB: string = typia.random<string & tags.Format<"email">>();
  const passwordB = "TestPasswordB1!";
  const regB = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: emailB,
      password: passwordB,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(regB);
  const customerB = regB.customer;

  // 3. Log in as Customer A
  await api.functional.auth.customer.login.signIn(connection, {
    body: { email: emailA, password: passwordA } satisfies ICustomerSignIn.Request,
  });

  // 4. Customer A creates order
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerA.id,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 10000,
      currency_code: "USD",
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(order);

  // 5. Customer A adds order item
  const orderItem = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      product_id: typia.random<string & tags.Format<"uuid">>(),
      product_snapshot_id: typia.random<string & tags.Format<"uuid">>(),
      quantity: 1,
      unit_price: 10000,
      currency_code: "USD",
    } satisfies IShoppingMallAiBackendOrderItem.ICreate,
  });
  typia.assert(orderItem);

  // 6. Log in as Customer B
  await api.functional.auth.customer.login.signIn(connection, {
    body: { email: emailB, password: passwordB } satisfies ICustomerSignIn.Request,
  });

  // 7. Attempt to fetch Customer A's order item as Customer B; should throw forbidden error
  await TestValidator.error("forbidden for non-owner")(() =>
    api.functional.shoppingMallAiBackend.customer.orders.orderItems.at(connection, {
      orderId: order.id,
      orderItemId: orderItem.id,
    })
  );
}

