import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteSnapshot";
import type { IPageIShoppingMallAiBackendFavoriteSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendFavoriteSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate advanced admin search for favorite snapshot records.
 *
 * This test ensures that only authorized admin users (registered and logged in) can access paginated favorite snapshot history using detailed filtering and pagination options. It covers queries using time windows, object type (PRODUCT, INQUIRY, ADDRESS), filtering by customer and object associations, and handling of empty, boundary, and invalid searches. Appropriate error handling for unauthorized and unauthenticated requests is also checked. Pagination and edge case scenarios such as requesting pages outside the result set are included for comprehensive coverage.
 *
 * 1. Register and login as an admin to obtain a JWT.
 * 2. Search with no filters: expect paginated result, possibly empty if database is fresh.
 * 3. Search by each target_type (PRODUCT, INQUIRY, ADDRESS) individually; validate type filter works.
 * 4. Search with impossible time window (from > to): expect empty result or appropriate error.
 * 5. Search using realistic created_at_from and created_at_to dates; expect valid records if present, or empty set.
 * 6. Use pagination (limit=1, page=1 and large page number out of range) to test boundary behavior.
 * 7. Attempt to search with a non-admin/without JWT: expect access denied.
 * 8. Try with invalid filter formats (e.g., negative page/limit): expect validation errors.
 */
export async function test_api_favorite_snapshot_search_with_filters(connection: api.IConnection) {
  // 1. Register admin and log in for access token
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "adm!nPass123$";

  // Step 1: Register admin
  const registerResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(registerResponse);

  // Step 2: Login as admin to refresh JWT (ensure full auth coverage)
  const loginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(loginResponse);

  // Admin JWT will be set automatically in connection.headers

  // 3. Search with no filters (get defaults)
  const emptySearch = await api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.search(connection, {
    body: {},
  });
  typia.assert(emptySearch);
  TestValidator.equals("pagination page=1")(emptySearch.pagination.current)(1);

  // 4. Search by each target_type
  for (const type of ["PRODUCT", "INQUIRY", "ADDRESS"] as const) {
    const res = await api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.search(connection, {
      body: { target_type: type },
    });
    typia.assert(res);
    // All results must have matching type, if data returned
    for (const snapshot of res.data) {
      TestValidator.equals(`target_type matches (${type})`)(snapshot.target_type)(type);
    }
  }

  // 5. Impossible time window: from after to
  const now = new Date();
  const from = new Date(now.valueOf() + 10000).toISOString(); // 10 sec ahead
  const to = now.toISOString();
  const badWindow = await api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.search(connection, {
    body: {
      created_at_from: from,
      created_at_to: to,
    },
  });
  typia.assert(badWindow);
  TestValidator.equals("bad window returns empty")(badWindow.data.length)(0);

  // 6. Valid time window (just use from = to = now, usually empty)
  const tightWindow = await api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.search(connection, {
    body: {
      created_at_from: now.toISOString(),
      created_at_to: now.toISOString(),
    },
  });
  typia.assert(tightWindow);

  // 7. Pagination boundary checks
  const paged = await api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.search(connection, {
    body: {
      limit: 1,
      page: 1,
    },
  });
  typia.assert(paged);
  TestValidator.equals("limit 1")(paged.pagination.limit)(1);
  // Query page far beyond dataset
  const megaPaged = await api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.search(connection, {
    body: {
      page: 9999,
      limit: 10,
    },
  });
  typia.assert(megaPaged);
  // Either empty or some error, check data or zero records
  TestValidator.predicate("high page = empty or last page")(
    megaPaged.data.length === 0 || megaPaged.pagination.current === megaPaged.pagination.pages
  );

  // 8. Unauthorized: try access without admin JWT
  const nonAdminConnection = { ...connection, headers: { ...connection.headers } };
  delete nonAdminConnection.headers.Authorization;
  await TestValidator.error("unauthorized access")(async () => {
    await api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.search(nonAdminConnection, {
      body: {},
    });
  });

  // 9. Invalid parameter: negative page/limit
  await TestValidator.error("negative page invalid")(async () => {
    await api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.search(connection, {
      body: { page: -1, limit: 10 },
    });
  });
  await TestValidator.error("zero/negative limit invalid")(async () => {
    await api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.search(connection, {
      body: { page: 1, limit: 0 },
    });
  });
}

