import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteProduct";
import type { IShoppingMallAiBackendFavoriteSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteSnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Validate updating permitted metadata of a favorite snapshot record as its owner customer.
 *
 * This scenario verifies correct business rules for editing favorite snapshot entries:
 * - Only permitted fields (serialized_object) are updateable. Immutable fields like created_at, favorite_product_id, and target_type must be prohibited from modification.
 * - Attempts to update non-existent, deleted, or not-owned-by-the-user snapshot IDs must fail with runtime error.
 * - Success updates must reflect changes for allowed properties, while restricted properties (even if sent) remain unchanged in the API response.
 * - Security/ownership enforcement is required: only the snapshot's owning customer may update the record.
 *
 * Scenario steps:
 * 1. Register and login as a customer (capture credentials and token for persistent testing).
 * 2. Create a favorite product record (generate new product_id for favorite).
 * 3. Create a favorite snapshot linked to the favorite product (setting realistic serialized_object, etc).
 * 4. Update the snapshot using its ID, changing only serialized_object (the only allowed field). Assert that the change is applied, and all immutable fields are unchanged.
 * 5. Attempt to update forbidden fields (e.g., created_at, favorite_product_id, target_type) via the update API, and confirm these changes are NOT applied to the entity (or cause error if explicitly attempted).
 * 6. Try to update a non-existent favoriteSnapshotId, expect error.
 * 7. Try to update a snapshot as a different/non-owner customer, expect permission error.
 */
export async function test_api_favorite_snapshot_update_metadata_by_owner(connection: api.IConnection) {
  // 1. Register a new customer and obtain credentials
  const email = typia.random<string & tags.Format<"email">>();
  const password = "StrongP@ssw0rd!";
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignUp);

  // Authenticate session as this customer
  await api.functional.auth.customer.login.signIn(connection, {
    body: { email, password },
  });

  // 2. Create a favorite product (simulate a product to favorite)
  const productId = typia.random<string & tags.Format<"uuid">>();
  const favoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: { product_id: productId },
  });
  typia.assert(favoriteProduct);

  // 3. Create a favorite snapshot referencing the favorite product
  const originalSerialized = JSON.stringify({ foo: "bar", product_id: productId });
  const snapshot = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: {
      favorite_product_id: favoriteProduct.id,
      favorite_inquiry_id: null,
      favorite_address_id: null,
      target_type: "PRODUCT",
      snapshot_object_id: productId,
      serialized_object: originalSerialized,
    },
  });
  typia.assert(snapshot);

  // 4. Update allowed field (serialized_object) and confirm only this field changes
  const updatedSerialized = JSON.stringify({ foo: "baz", product_id: productId });
  const updated = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.update(connection, {
    favoriteSnapshotId: snapshot.id,
    body: {
      serialized_object: updatedSerialized,
    },
  });
  typia.assert(updated);
  TestValidator.equals("serialized_object updated")(updated.serialized_object)(updatedSerialized);
  TestValidator.equals("id remains unchanged")(updated.id)(snapshot.id);
  TestValidator.equals("created_at unchanged")(updated.created_at)(snapshot.created_at);
  TestValidator.equals("favorite_product_id unchanged")(updated.favorite_product_id)(snapshot.favorite_product_id);
  TestValidator.equals("target_type unchanged")(updated.target_type)(snapshot.target_type);
  TestValidator.equals("snapshot_object_id unchanged")(updated.snapshot_object_id)(snapshot.snapshot_object_id);

  // 5. Attempt to update forbidden/immutable fields (these props are not allowed in IUpdate)
  const forbiddenAttempt = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.update(connection, {
    favoriteSnapshotId: snapshot.id,
    body: {
      serialized_object: JSON.stringify({ foo: "bar", product_id: productId, extra: "not allowed" }),
    },
  });
  typia.assert(forbiddenAttempt);
  TestValidator.equals("forbidden fields not changed, id")(forbiddenAttempt.id)(snapshot.id);
  TestValidator.equals("forbidden fields not changed, target_type")(forbiddenAttempt.target_type)(snapshot.target_type);
  TestValidator.equals("forbidden fields not changed, created_at")(forbiddenAttempt.created_at)(snapshot.created_at);

  // 6. Attempt to update a non-existent snapshot ID (should throw)
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("updating non-existent id should fail")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.update(connection, {
      favoriteSnapshotId: nonExistentId,
      body: { serialized_object: JSON.stringify({ test: true }) },
    });
  });

  // 7. Register and login as a different customer
  const anotherEmail = typia.random<string & tags.Format<"email">>();
  const anotherPassword = "DifferentP@ss1";
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: anotherEmail,
      password: anotherPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
  });
  await api.functional.auth.customer.login.signIn(connection, {
    body: { email: anotherEmail, password: anotherPassword },
  });
  // Attempt to update another user's snapshot
  await TestValidator.error("non-owner cannot update snapshot")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.update(connection, {
      favoriteSnapshotId: snapshot.id,
      body: { serialized_object: JSON.stringify({ hacked: true }) },
    });
  });
}

