  // Switch to customer's JWT for review creation
  connection.headers = { ...connection.headers, Authorization: customerLogin.setHeaders.Authorization };

  // 4. Customer creates a product review
  const review = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      order_item_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
