import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendModerationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendModerationEvent";
import type { IPageIShoppingMallAiBackendModerationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendModerationEvent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate advanced search and filtering for moderation events as an admin.
 * 
 * Business context:
 * - Admins regularly audit, trace, or analyze moderation actions (block, unblock, edit, escalate, etc.) for reviews and inquiries across the shopping mall platform.
 * - Legal/audit requirements mean all events must be searchable by event type, actor, evidence, reason, and by target inquiry or review, including broad and fine-grained queries over long time windows.
 * - This test ensures admin search operates correctly: returns only matching data, supports empty and precise filters, honors pagination, and exposes the correct level of detail for admin.
 * 
 * Step-by-step process:
 * 1. Register an admin and gain an authenticated session.
 * 2. Create multiple moderation event records (simulate different event_types, actors, review/inquiry references, plausible time ranges, etc.).
 * 3. Search with empty filter (should return all, up to limit).
 * 4. Filter by event_type (should return only matching types).
 * 5. Filter by actor_type (should return only actor_type-matched events).
 * 6. Filter by a real and a non-existent actor_id (should return matching, and empty where none exists).
 * 7. Filter by review and by inquiry (target_review_id/target_inquiry_id).
 * 8. Filter by reason (exact string match or partial text in at least one record).
 * 9. Range search by created_at (from_date/to_date).
 * 10. Filter or paginate with limit (page size) and check correct subset/pagination meta.
 * 11. Edge: Search with non-existent criteria (should return empty).
 * 12. All responses are correctly typed, paginated, and return only permissible admin-level data.
 */
export async function test_api_moderation_event_advanced_search_success(connection: api.IConnection) {
  // 1. Register admin for session
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'Admin!1234';
  const adminSession = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSession);

  // 2. Create multiple diverse moderation events
  const baseDate = new Date();
  const actors = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<'uuid'>>());
  const events: IShoppingMallAiBackendModerationEvent[] = [];
  const eventTypes = ["block", "unblock", "edit", "escalate"];
  const targetInquiryIds = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<'uuid'>>());
  const targetReviewIds = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<'uuid'>>());
  const reasons = [
    "Spam content, auto-detected",
    "Manual audit: offensive language",
    "Automated escalation: repeat offense",
    "Policy compliance - minor violation"
  ];
  for (let i = 0; i < 12; ++i) {
    const event = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, {
      body: {
        actor_id: actors[i % actors.length],
        event_type: eventTypes[i % eventTypes.length],
        reason: reasons[i % reasons.length],
        target_inquiry_id: i % 2 === 0 ? targetInquiryIds[0] : null,
        target_review_id: i % 2 === 1 ? targetReviewIds[1] : null,
        attached_ai_evidence_id: null,
        referenced_event_id: null,
      } satisfies IShoppingMallAiBackendModerationEvent.ICreate,
    });
    typia.assert(event);
    events.push(event);
    // Artificially control dates for date-range testing (simulate time windows).
    event.created_at = new Date(baseDate.getTime() - i * 86400000).toISOString();
  }

  // --- SEARCH/VALIDATE CASES ---

  // 3. Search with empty filter: returns all (up to default/page limit)
  const resAll = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: {}
  });
  typia.assert(resAll);
  TestValidator.predicate("empty filter returns results")(
    resAll.data.length > 0
  );

  // 4. Filter by event_type
  const typeQuery = eventTypes[0];
  const resType = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { event_type: typeQuery }
  });
  typia.assert(resType);
  TestValidator.predicate("event_type results only matching")(
    resType.data.every(ev => ev.event_type === typeQuery)
  );

  // 5. Filter by actor_type (simulate with actor_type=null, no actor profile table, so should not restrict output)
  const resActorType = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { actor_type: null }
  });
  typia.assert(resActorType);

  // 6. Filter by a real and non-existent actor_id
  const realActorId = actors[0];
  const resActor = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { actor_id: realActorId }
  });
  typia.assert(resActor);
  TestValidator.predicate("actor_id result matches only actor")(
    resActor.data.every(ev => ev.actor_id === realActorId)
  );
  const resFakeActor = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { actor_id: typia.random<string & tags.Format<'uuid'>>() }
  });
  typia.assert(resFakeActor);
  TestValidator.equals("fake actor_id yields empty")(resFakeActor.data.length)(0);

  // 7. Filter by review/inquiry
  const resReview = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { target_review_id: targetReviewIds[1] }
  });
  typia.assert(resReview);
  TestValidator.predicate("review filter matches")(
    resReview.data.every(ev => ev.target_review_id === targetReviewIds[1])
  );
  const resInquiry = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { target_inquiry_id: targetInquiryIds[0] }
  });
  typia.assert(resInquiry);
  TestValidator.predicate("inquiry filter matches")(
    resInquiry.data.every(ev => ev.target_inquiry_id === targetInquiryIds[0])
  );

  // 8. Filter by reason (partial match, as system may match substrings, but here we require full match for assertion)
  const reasonQuery = reasons[0];
  const resReason = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { reason: reasonQuery }
  });
  typia.assert(resReason);
  TestValidator.predicate("reason filter matches")(
    resReason.data.every(ev => ev.reason === reasonQuery)
  );

  // 9. Date-range: filter from baseDate - 5 days to baseDate inclusive
  const fromDate = new Date(baseDate.getTime() - 5 * 86400000).toISOString();
  const toDate = baseDate.toISOString();
  const resDateRange = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: {
      from_date: fromDate,
      to_date: toDate
    }
  });
  typia.assert(resDateRange);
  TestValidator.predicate("date-range results in correct window")(
    resDateRange.data.every(ev => ev.created_at >= fromDate && ev.created_at <= toDate)
  );

  // 10. Paginate with limit (page size)
  const resPaginate = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: {
      page: 1,
      limit: 5
    }
  });
  typia.assert(resPaginate);
  TestValidator.equals("pagination matches page size")(resPaginate.data.length)(5);
  TestValidator.equals("pagination meta limit")(resPaginate.pagination.limit)(5);
  TestValidator.equals("pagination meta page")(resPaginate.pagination.current)(1);

  // 11. Edge: Search with non-existent criteria yields empty
  const resNone = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { event_type: "___NON_EXISTENT___" }
  });
  typia.assert(resNone);
  TestValidator.equals("non-existent filter yields empty")(resNone.data.length)(0);

  // 12. All responses are paginated and only permissible admin-level data returns (type assertions done above)
}

