import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPayment";
import type { IPageIShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderPayment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for admin search and audit of order payment records with authorization and filtering control.
 *
 * This test simulates a realistic admin workflow for payment auditing and compliance:
 * 1. Admin login to obtain privileges
 * 2. Create a customer order (using customer flows to ensure business-compliant IDs)
 * 3. Use the admin endpoint to create multiple payment records for the order, using different payment providers and results
 * 4. Search payments for this order as admin, with different filters:
 *    a. No filter (should return all records, paginated)
 *    b. Filter by payment_method and payment_result (should filter correctly)
 *    c. Filter by created_at_from/created_at_to (date range)
 *    d. Paginate (limit, page) and verify counts
 * 5. Attempt search for non-existent order (should 404 or empty)
 * 6. Attempt search as unauthorized user (should be rejected)
 * 7. Validate all assertions via TestValidator and typia.assert for type safety and business rules
 */
export async function test_api_admin_order_payment_search_with_audit_and_access_control(
  connection: api.IConnection,
) {
  // 1. Admin login
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Password123!"; // simulate known password
  // Admin user must pre-exist with these credentials
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 2. Create order as customer (simulate with random customer id)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const orderCreateInput = {
    customer_id: customerId,
    order_group_id: null,
    order_number: RandomGenerator.alphaNumeric(12),
    total_amount: 10000 + Math.floor(Math.random() * 99999),
    currency_code: "KRW",
    note: "Test order for payment search",
    current_status: "created",
  } satisfies IShoppingMallAiBackendOrder.ICreate;
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: orderCreateInput,
  });
  typia.assert(order);

  // 3. Create multiple payment records for the order (simulate different methods & results)
  const providerId1 = typia.random<string & tags.Format<"uuid">>();
  const providerId2 = typia.random<string & tags.Format<"uuid">>();
  const pay1 = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_provider_id: providerId1,
      payment_method: "card",
      transaction_id: RandomGenerator.alphaNumeric(20),
      amount: 5000,
      currency_code: "KRW",
      payment_result: "completed",
      payment_context: null,
    },
  });
  typia.assert(pay1);
  const pay2 = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_provider_id: providerId2,
      payment_method: "bank_transfer",
      transaction_id: RandomGenerator.alphaNumeric(20),
      amount: 5500,
      currency_code: "KRW",
      payment_result: "pending",
      payment_context: null,
    },
  });
  typia.assert(pay2);

  // 4a. Search all payments for this order as admin
  const resAll = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.search(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
    },
  });
  typia.assert(resAll);
  TestValidator.equals("should find 2 payments")(resAll.data.length)(2);

  // 4b. Filter by payment_method
  const filteredCard = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.search(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_method: "card",
    },
  });
  typia.assert(filteredCard);
  TestValidator.equals("card payments only")(filteredCard.data.length)(1);
  TestValidator.equals("method")(filteredCard.data[0].payment_method)("card");

  // 4c. Filter by payment_result
  const filteredPending = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.search(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_result: "pending",
    },
  });
  typia.assert(filteredPending);
  TestValidator.equals("pending payments only")(filteredPending.data.length)(1);
  TestValidator.equals("status")(filteredPending.data[0].payment_result)("pending");

  // 4d. Filter by date range (created_at_from/to)
  const now = new Date();
  const fromDate = new Date(now.getTime() - 60 * 1000).toISOString();
  const toDate = new Date(now.getTime() + 60 * 1000).toISOString();
  const resDateWindow = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.search(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      created_at_from: fromDate,
      created_at_to: toDate,
    },
  });
  typia.assert(resDateWindow);
  TestValidator.predicate("date window covers both")(resDateWindow.data.length >= 2);

  // 4e. Paginate payments
  const paged1 = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.search(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      limit: 1,
      page: 1,
    },
  });
  typia.assert(paged1);
  TestValidator.equals("1 payment per page")(paged1.data.length)(1);
  TestValidator.equals("pagination page 1")(paged1.pagination.current)(1);

  const paged2 = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.search(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      limit: 1,
      page: 2,
    },
  });
  typia.assert(paged2);
  TestValidator.equals("1 payment per page page 2")(paged2.data.length)(1);
  TestValidator.equals("pagination page 2")(paged2.pagination.current)(2);

  // 5. Search for non-existent orderId
  TestValidator.error("not found for bogus order")(async () => {
    await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.search(connection, {
      orderId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        order_id: typia.random<string & tags.Format<"uuid">>(),
      },
    });
  });

  // 6. Search as unauthorized user (simulate by removing admin JWT if possible, or skip if cannot logout)
  // This will only work if API supports session removal; if not, this step can be skipped or adapted
  const noAuthConnection = { ...connection, headers: { ...connection.headers } };
  delete noAuthConnection.headers.Authorization;
  TestValidator.error("unauthorized search fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.search(noAuthConnection, {
      orderId: order.id,
      body: { order_id: order.id },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPayment";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test viewing a specific order payment record as a customer and validate access control.
 *
 * This test ensures that a customer can view details of an order payment only if they own the order and tests access denial or not-found errors for other scenarios.
 *
 * Step-by-step process:
 * 1. Register the first customer (customer1) and keep authentication.
 * 2. Create a new order belonging to customer1.
 * 3. Add a payment to that order as customer1.
 * 4. Retrieve the payment details using its ID and validate the returned record matches what was created.
 * 5. Register a different customer (customer2) and attempt to view customer1's payment – this should result in access denied or not found.
 * 6. Attempt to fetch a payment using a non-existent orderPaymentId – expect a not found error.
 */
export async function test_api_customer_order_payment_detail_view_and_access_control(connection: api.IConnection) {
  // 1. Register and authenticate as customer1
  const customer1Email = typia.random<string & tags.Format<"email">>();
  const customer1Password = "Abc!12345";
  const customer1Resp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer1Email,
      password: customer1Password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customer1Resp);
  const customer1 = customer1Resp.customer;

  // 2. Create an order for customer1
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customer1.id,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 15000,
      currency_code: "USD",
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(order);

  // 3. Add a payment to that order as customer1
  const payment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
      payment_method: "card",
      transaction_id: RandomGenerator.alphaNumeric(16),
      amount: order.total_amount,
      currency_code: order.currency_code,
      payment_result: "completed",
    } satisfies IShoppingMallAiBackendOrderPayment.ICreate,
  });
  typia.assert(payment);

  // 4. Retrieve the payment by its ID as customer1 (should succeed and match)
  const fetched = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.at(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
  });
  typia.assert(fetched);
  TestValidator.equals("payment returned matches created")(fetched)(payment);

  // 5. Register customer2
  const customer2Email = typia.random<string & tags.Format<"email">>();
  const customer2Password = "Def!67890";
  const customer2Resp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer2Email,
      password: customer2Password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customer2Resp);

  // Simulate switching authentication to customer2 via token
  connection.headers = { ...connection.headers, Authorization: customer2Resp.setHeaders.Authorization };

  // 6. Attempt to fetch the payment as customer2 – expect error (access denied/not found)
  await TestValidator.error("customer2 cannot access payment of customer1")(() =>
    api.functional.shoppingMallAiBackend.customer.orders.orderPayments.at(connection, {
      orderId: order.id,
      orderPaymentId: payment.id,
    })
  );

  // 7. Attempt to fetch a payment with a non-existent payment ID – expect not found error
  await TestValidator.error("not found for non-existent payment")(() =>
    api.functional.shoppingMallAiBackend.customer.orders.orderPayments.at(connection, {
      orderId: order.id,
      orderPaymentId: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
