/**
 * Test that an admin can add a cart item to any customer's shopping cart (admin on-behalf-of-customer logic).
 *
 * This test covers the following e-commerce customer support scenario:
 *
 * 1. Register a new admin (admin registration endpoint). The returned JWT should be set in the Authorization header, representing the admin session context for privileged operations.
 * 2. Register a new customer, capturing the unique customer id/profile for use in cart creation.
 * 3. As an authenticated customer, create a new cart (via /shoppingMallAiBackend/customer/carts endpoint). Session context must be switched to the customer (set Authorization header to customer's JWT) for this operation.
 * 4. Switch the session context back to the admin by restoring admin JWT in the Authorization header. All subsequent privileged API calls should operate in the admin security context.
 * 5. As the admin, use the admin endpoint to add a new cart item to the customer's cart—providing valid product id, quantity, unit price, and currency code as required by the IShoppingMallAiBackendCartItem.ICreate DTO. The note field contains an admin-side remark for auditability.
 * 6. Validate the response: assert that the returned cart item has the expected product id, quantity, option id, price, currency, and note (using TestValidator and typia.assert). This validates business, permission, and security rules for admin-mediated cart updates.
 *
 * This scenario confirms that platform security and business logic allow an admin to add cart items on behalf of any customer, so customer service/support flows are unblocked.
 */
export async function test_api_cart_item_create_admin_on_behalf_success(connection: api.IConnection) {
  // 1. Register a new admin; Authorization header will reflect admin session
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin!12345";
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminReg);

  // 2. Register a new customer and capture the customer id
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Customer!12345";
  const customerReg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerReg);
  const customerId = customerReg.customer.id;

  // 3. Switch Authorization context to customer (set JWT)
  connection.headers = { ...connection.headers, Authorization: customerReg.setHeaders.Authorization };
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      session_token: null,
    } satisfies IShoppingMallAiBackendCart.ICreate
  });
  typia.assert(cart);
  const cartId = cart.id;

  // 4. Restore admin session (re-set Authorization header to admin JWT)
  connection.headers = { ...connection.headers, Authorization: adminReg.setHeaders.Authorization };

  // 5. As admin, add a cart item to the customer's cart
  const productId = typia.random<string & tags.Format<"uuid">>();
  const productOptionId = null; // Simulate no option/variant selected
  const quantity = typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>();
  const unitPrice = 10000 + typia.random<number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<90000>>();
  const currencyCode = "KRW";
  const note = "Added by admin intervention";

  const cartItem = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.create(connection, {
    cartId: cartId,
    body: {
      product_id: productId,
      product_option_id: productOptionId,
      quantity: quantity,
      unit_price: unitPrice,
      currency_code: currencyCode,
      note: note,
    } satisfies IShoppingMallAiBackendCartItem.ICreate,
  });
  typia.assert(cartItem);

  // 6. Validate cart item returned by API matches expectations
  TestValidator.equals("product_id")(cartItem.product_id)(productId);
  TestValidator.equals("product_option_id")(cartItem.product_option_id)(productOptionId);
  TestValidator.equals("quantity")(cartItem.quantity)(quantity);
  TestValidator.equals("unit_price")(cartItem.unit_price)(unitPrice);
  TestValidator.equals("currency_code")(cartItem.currency_code)(currencyCode);
  TestValidator.equals("note")(cartItem.note)(note);
}

