import type { IShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductContent";

/**
 * Validate admin update of product content attributes.
 *
 * This test simulates an administrator workflow where product content is created and then updated. It follows these steps:
 * 1. Create a new product as admin, receiving a unique productId.
 * 2. Create a product content for the above product, receiving productContentId.
 * 3. Update that product content with new valid values for content_type, content_uri, content_order, and content_description.
 * 4. Assert that all updated fields are reflected in the response, unchanged fields remain the same, and audit fields (updated_at, created_at) are handled correctly.
 */
export async function test_api_product_content_update_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a new product as admin
  const productInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    code: `SKU-${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.content()()(),
    main_image_uri: RandomGenerator.alphaNumeric(24),
    status: "draft",
  };
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: productInput,
  });
  typia.assert(product);

  // 2. Create a product content for the above product
  const contentInput: IShoppingMallAiBackendProductContent.ICreate = {
    product_id: product.id,
    content_type: "main_image",
    content_uri: `https://cdn.acme.com/assets/${RandomGenerator.alphaNumeric(24)}`,
    content_order: 0,
    content_description: "Initial main image for the product.",
    status: "active",
  };
  const content = await api.functional.shoppingMallAiBackend.admin.products.productContents.create(connection, {
    productId: product.id,
    body: contentInput,
  });
  typia.assert(content);

  // 3. Prepare new update values for several fields (simulate admin edit)
  const updateInput: IShoppingMallAiBackendProductContent.IUpdate = {
    content_type: "gallery_image",
    content_uri: `https://cdn.acme.com/assets/${RandomGenerator.alphaNumeric(24)}`,
    content_order: 1,
    content_description: "Gallery image showing alternate view.",
  };

  // 4. Update the product content
  const updatedContent = await api.functional.shoppingMallAiBackend.admin.products.productContents.update(connection, {
    productId: product.id,
    productContentId: content.id,
    body: updateInput,
  });
  typia.assert(updatedContent);

  // 5. Assert all updated fields reflect new input values
  TestValidator.equals("updated content_type")(updatedContent.content_type)(updateInput.content_type);
  TestValidator.equals("updated content_uri")(updatedContent.content_uri)(updateInput.content_uri);
  TestValidator.equals("updated content_order")(updatedContent.content_order)(updateInput.content_order);
  TestValidator.equals("updated content_description")(updatedContent.content_description)(updateInput.content_description);

  // 6. Unchanged fields remain the same
  TestValidator.equals("unchanged id")(updatedContent.id)(content.id);
  TestValidator.equals("unchanged product_id")(updatedContent.product_id)(content.product_id);
  TestValidator.equals("unchanged status")(updatedContent.status)(content.status);

  // 7. Audit field updated_at is refreshed
  TestValidator.predicate("updated_at refreshed")(updatedContent.updated_at !== content.updated_at);
  // created_at should not change
  TestValidator.equals("created_at unchanged")(updatedContent.created_at)(content.created_at);
  // Optionally: deleted_at remains unchanged
  TestValidator.equals("deleted_at unchanged")(updatedContent.deleted_at)(content.deleted_at);
}

