  const orderY = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customer2,
      order_number: `ORD-E2E-Y-${Date.now()}`,
      total_amount: 12000,
      currency_code: "KRW",
      note: "Order Y for negative test",
      current_status: "pending",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(orderY);

  // Order Z (should NOT match any test filter—different amount/status entirely)
  const orderZ = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      order_number: `ORD-E2E-Z-${Date.now()}`,
      total_amount: 3500,
      currency_code: "KRW",
      note: "Order Z negative control",
      current_status: "cancelled",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(orderZ);

  // 4. Advanced filtered search as the seller
  //    Use filters that narrowly select only orderX (customer1, status 'created', amount in range)
  const now = Date.now();
  const dateFrom = new Date(now - 1000 * 60 * 60).toISOString();
  const dateTo = new Date(now + 1000 * 60 * 60).toISOString();

  const searchRes = await api.functional.shoppingMallAiBackend.seller.orders.search(connection, {
    body: {
      page: 1,
      pageSize: 10,
      customer_id: customer1,
      status_in: ["created", "pending"],
      total_amount_gte: 8000,
      total_amount_lte: 15000,
      currency_code: "KRW",
      created_at_gte: dateFrom,
      created_at_lte: dateTo,
      sort: "-created_at",
    } satisfies IShoppingMallAiBackendOrder.IRequest,
  });
  typia.assert(searchRes);

  // Assert that only orderX is present
  const foundX = searchRes.data.find((o) => o.id === orderX.id);
  TestValidator.predicate("orderX (main match) present")(!!foundX);
  TestValidator.equals("orderX status matches")(foundX?.current_status)(orderX.current_status);
  TestValidator.equals("orderX total matches")(foundX?.total_amount)(orderX.total_amount);
  TestValidator.equals("orderX customer matches")(foundX?.customer_id)(orderX.customer_id);

  // Assert orderY and orderZ are not present
  TestValidator.predicate("orderY is not present")(searchRes.data.every((o) => o.id !== orderY.id));
  TestValidator.predicate("orderZ is not present")(searchRes.data.every((o) => o.id !== orderZ.id));

  // Assert pagination meta
  TestValidator.equals("page is 1")(searchRes.pagination.current)(1);
  TestValidator.equals("pageSize")(searchRes.pagination.limit)(10);
  TestValidator.predicate("results not exceeding pageSize")(searchRes.data.length <= searchRes.pagination.limit);

  // 5. Negative case: query for cancelled orders/amounts (should not include X or Y)
  const negativeRes = await api.functional.shoppingMallAiBackend.seller.orders.search(connection, {
    body: {
      page: 1,
      pageSize: 10,
      status_in: ["cancelled"],
      total_amount_gte: 4000,
      total_amount_lte: 8000,
      currency_code: "KRW",
      created_at_gte: dateFrom,
      created_at_lte: dateTo,
      sort: "-created_at",
    } satisfies IShoppingMallAiBackendOrder.IRequest,
  });
  typia.assert(negativeRes);
  TestValidator.equals("no cancelled orders found")(negativeRes.data.length)(0);
}

