import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponHistory";
import type { IPageIShoppingMallAiBackendCouponHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCouponHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for searching and filtering coupon history records as an admin.
 *
 * Business context: Coupon histories are sensitive audit records for compliance. Only authorized (admin) users may access this endpoint. This test ensures that filter/search functionality and pagination operate correctly and securely.
 *
 * Validates:
 * - Admin authentication is required (dependency: login)
 * - Coupon history search returns accurate, filtered results when various filters are applied (coupon, issued_coupon_id, actor_id/type, action, date range, sort, pagination)
 * - Edge cases: (a) no filters (should return paginated unfiltered records); (b) all filters combined; (c) invalid filter parameters (should be error); (d) unauthorized user access (should be rejected)
 * - Pagination details are correct (page, limit, total records, data ordering)
 *
 * Steps:
 * 1. Attempt search as unauthenticated user (expect forbidden)
 * 2. Authenticate as admin using valid credentials
 * 3. Search without any filters, validate paginated result structure
 * 4. Search with combination of filters (issued_coupon_id, actor_id, action, date range, sort), validate only relevant records returned
 * 5. Attempt search with invalid filter (invalid uuid, negative page/limit, nonsensical sort), expect error
 */
export async function test_api_coupon_history_search_filter_pagination(
  connection: api.IConnection,
) {
  // Step 1: Attempt search as UNauthenticated user: should be rejected
  await TestValidator.error("unauthorized user is rejected")(
    () => api.functional.shoppingMallAiBackend.admin.couponHistories.search(connection, {
      body: {
        page: 1,
        limit: 1,
      } satisfies IShoppingMallAiBackendCouponHistory.IRequest,
    })
  );

  // Step 2: Admin authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "correct-password";
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // Step 3: Search with NO filters (required fields: page + limit only)
  const unfiltered = await api.functional.shoppingMallAiBackend.admin.couponHistories.search(connection, {
    body: {
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendCouponHistory.IRequest,
  });
  typia.assert(unfiltered);
  TestValidator.predicate("pagination structure")(!!unfiltered.pagination && Array.isArray(unfiltered.data));

  // Step 4: Search with COMBINED filters (using random valid values)
  const filters = {
    issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    actor_type: "admin",
    action: "used",
    action_at_from: new Date(Date.now() - 7*24*3600*1000).toISOString(),
    action_at_to: new Date().toISOString(),
    page: 1,
    limit: 5,
    sort: "action_at desc",
  } satisfies IShoppingMallAiBackendCouponHistory.IRequest;
  const filtered = await api.functional.shoppingMallAiBackend.admin.couponHistories.search(connection, {
    body: filters,
  });
  typia.assert(filtered);
  if (filtered.data.length > 0) {
    TestValidator.equals("issued_coupon_id filtered correctly")(filtered.data[0].issued_coupon_id)(filters.issued_coupon_id);
    TestValidator.equals("actor_type filtered correctly")(filtered.data[0].actor_type)(filters.actor_type);
    TestValidator.equals("action filtered correctly")(filtered.data[0].action)(filters.action);
  }
  TestValidator.predicate("filtered results page")(filtered.pagination.current === 1 && filtered.pagination.limit === 5);

  // Step 5: Error on INVALID filters—should trigger error (invalid uuid, negative page, etc)
  await TestValidator.error("invalid filter params should error")(
    () => api.functional.shoppingMallAiBackend.admin.couponHistories.search(connection, {
      body: {
        issued_coupon_id: "not-a-uuid" as string & tags.Format<"uuid">,
        page: -1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 0 as number & tags.Type<"int32"> & tags.Minimum<1>,
      } satisfies IShoppingMallAiBackendCouponHistory.IRequest,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponHistory";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin coupon history detail retrieval and error scenarios.
 *
 * 1. Admin login with valid credentials (dependency requirement)
 * 2. Create a coupon history record to ensure a fetchable test record exists
 * 3. Fetch coupon history detail by valid id – assert response shape matches full audit schema
 * 4. Attempt to fetch with random non-existent UUID – expect not found error
 * 5. Attempt fetch with obviously malformed UUID – expect validation error (runtime error)
 * 6. Simulate unauthorized – remove JWT and try fetch – expect permission/authorization error
 * 7. (Soft-delete not supported by API, so skip unless delete supported)
 *
 * Edge cases: non-existent UUID, malformed UUID, unauthorized access
 */
export async function test_api_coupon_history_detail_fetch_and_error(connection: api.IConnection) {
  // 1. Login as admin
  const email = typia.random<string & tags.Format<"email">>();
  const password = "Admin123$";
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 2. Create a valid coupon history record to fetch
  const couponHistoryInput: IShoppingMallAiBackendCouponHistory.ICreate = {
    issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
    actor_id: adminLogin.adminId,
    actor_type: adminLogin.role,
    action: "issued",
    action_at: new Date().toISOString() as string & tags.Format<"date-time">,
    remarks: "Test issue event",
  };
  const createdHistory = await api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, {
    body: couponHistoryInput,
  });
  typia.assert(createdHistory);

  // 3. Fetch the coupon history detail with valid id
  const detail = await api.functional.shoppingMallAiBackend.admin.couponHistories.at(connection, {
    couponHistoryId: createdHistory.id,
  });
  typia.assert(detail);
  TestValidator.equals("id matches")(detail.id)(createdHistory.id);
  TestValidator.equals("issued_coupon_id matches")(detail.issued_coupon_id)(createdHistory.issued_coupon_id);
  TestValidator.equals("actor_id matches")(detail.actor_id)(createdHistory.actor_id);
  TestValidator.equals("remarks matches")(detail.remarks)(createdHistory.remarks);

  // 4. Attempt to fetch with a random (non-existent) UUID – expect not found error
  await TestValidator.error("Non-existent couponHistoryId returns not found")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.couponHistories.at(connection, {
        couponHistoryId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 5. Attempt fetch with malformed UUID – expect validation error
  await TestValidator.error("Invalid UUID format returns validation error")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.couponHistories.at(connection, {
        couponHistoryId: "BAD-UUID" as any,
      });
    },
  );

  // 6. Simulate unauthorized access (remove Authorization header)
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthConnection.headers.Authorization;
  await TestValidator.error("Unauthorized fetch returns permission error")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.couponHistories.at(unauthConnection, {
        couponHistoryId: createdHistory.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponHistory";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate updating coupon history records by an admin, ensuring only permitted fields are changeable.
 *
 * This E2E test ensures admin users can update ONLY the allowed 'remarks' field for audit compliance
 * while all other fields remain immutable. It confirms update persistence, proper error handling for
 * unauthorized and not-found scenarios, and checks data validation for remarks input.
 *
 * Steps:
 * 1. Authenticate as admin with valid credentials
 * 2. Create a coupon history record for testing
 * 3. Successfully update the "remarks" field—verify changes persist
 * 4. Attempt update as unauthorized user—expect rejection
 * 5. Attempt to update non-existent coupon history—expect not-found error
 */
export async function test_api_coupon_history_update_content_and_policies(
  connection: api.IConnection,
) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234";
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 2. Create a coupon history record for updating
  const couponHistoryCreate: IShoppingMallAiBackendCouponHistory.ICreate = {
    issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    actor_type: "admin",
    action: "issued",
    action_at: new Date().toISOString(),
    remarks: "Initial test remark",
  };
