import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponTemplate";
import type { IShoppingMallAiBackendIssuedCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendIssuedCoupon";
import type { IPageIShoppingMallAiBackendIssuedCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendIssuedCoupon";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates admin-issued coupon search with filters and pagination.
 *
 * This test verifies an administrator can:
 * - Create a coupon template
 * - Issue several coupons to customers with varied attributes
 * - Search issued coupons using flexible filters (code, status, customer_id, expiry range)
 * - Validate pagination and metadata correctness
 * - Confirm errors for invalid/unexpected filter fields
 *
 * Steps:
 * 1. Create a valid coupon template
 * 2. Issue four coupons to different (fake) customers with different codes, expiry dates, and statuses
 * 3. Search by code: verify correct coupon appears
 * 4. Search by customer_id: verify correct coupon appears
 * 5. Search by status: verify correct coupon appears
 * 6. Search by expiry date range: more than one coupon appears
 * 7. Pagination: retrieve first two coupons and verify count
 * 8. Pass unsupported field to filter: expect schema validation error
 *
 * Note: No soft-delete filter exists in the DTO, so deleted/hidden coupons cannot be separately tested.
 */
export async function test_api_issued_coupon_search_pagination_and_filters(connection: api.IConnection) {
  // 1. Create a coupon template
  const now = new Date();
  const valid_from = new Date(now.getTime() - 5 * 60000).toISOString();
  const valid_until = new Date(now.getTime() + 2 * 86400000).toISOString(); // +2 days
  const couponTemplate = await api.functional.shoppingMallAiBackend.admin.couponTemplates.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.paragraph()(2),
      type: "discount",
      valid_from,
      valid_until,
      is_active: true,
    } satisfies IShoppingMallAiBackendCouponTemplate.ICreate
  });
  typia.assert(couponTemplate);

  // 2. Issue coupons to several customers
  const customerIds = ArrayUtil.repeat(4)(() => typia.random<string & tags.Format<"uuid">>());
  const codes = [RandomGenerator.alphaNumeric(8), RandomGenerator.alphaNumeric(8), RandomGenerator.alphaNumeric(8), RandomGenerator.alphaNumeric(8)];
  const expires = [
    new Date(now.getTime() + 86400000).toISOString(),   // +1 day
    new Date(now.getTime() + 86400000 * 2).toISOString(), // +2 days
    new Date(now.getTime() + 86400000 * 3).toISOString(), // +3 days
    new Date(now.getTime() + 86400000 * 4).toISOString(), // +4 days
  ];
  const statuses = ["issued", "used", "expired", "cancelled"];

  const issuedCoupons = await ArrayUtil.asyncMap([0, 1, 2, 3])(async i => {
    const issued = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.create(connection, {
      body: {
        coupon_template_id: couponTemplate.id,
        customer_id: customerIds[i],
        code: codes[i],
        expires_at: expires[i],
        status: statuses[i]
      } satisfies IShoppingMallAiBackendIssuedCoupon.ICreate
    });
    typia.assert(issued);
    return issued;
  });

  // 3. Search with various filters -- single filter by code
  const searchByCode = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.search(connection, {
    body: {
      code: codes[0]
    } satisfies IShoppingMallAiBackendIssuedCoupon.IRequest
  });
  typia.assert(searchByCode);
  TestValidator.predicate("should find one with code")(searchByCode.data.length === 1 && searchByCode.data[0].code === codes[0]);

  // 4. Search filter by customer_id returns one
  const searchByCustomer = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.search(connection, {
    body: {
      customer_id: customerIds[2]
    } satisfies IShoppingMallAiBackendIssuedCoupon.IRequest
  });
  typia.assert(searchByCustomer);
  TestValidator.predicate("should find one for customer")(searchByCustomer.data.length === 1 && searchByCustomer.data[0].customer_id === customerIds[2]);

  // 5. Search filter by status
  const searchByStatus = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.search(connection, {
    body: {
      status: statuses[1]
    } satisfies IShoppingMallAiBackendIssuedCoupon.IRequest
  });
  typia.assert(searchByStatus);
  TestValidator.predicate("should find coupon with status")(searchByStatus.data.length === 1 && searchByStatus.data[0].status === statuses[1]);

  // 6. Filter by expiration range (should catch >1)
  const rangeStart = new Date(now.getTime() + 15000).toISOString();
  const rangeEnd = new Date(now.getTime() + 86400000 * 3 + 1).toISOString();
  const searchByExpiry = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.search(connection, {
    body: {
      expires_from: rangeStart,
      expires_until: rangeEnd
    } satisfies IShoppingMallAiBackendIssuedCoupon.IRequest
  });
  typia.assert(searchByExpiry);
  TestValidator.predicate("should find coupons in expiry range")(searchByExpiry.data.length > 1);

  // 7. Pagination check (limit = 2)
  const paged = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.search(connection, {
    body: { limit: 2 } satisfies IShoppingMallAiBackendIssuedCoupon.IRequest
  });
  typia.assert(paged);
  TestValidator.equals("pagination page size")(paged.pagination.limit)(2);
  TestValidator.predicate("pagination count >=2")(paged.data.length <= 2);
  TestValidator.equals("pagination total count")(paged.pagination.records)(4);

  // 8. Invalid filter (unsupported property) triggers error
  await TestValidator.error("should throw validation error for unsupported filter")(async () => {
    // Violates schema (add unknown property)
    await api.functional.shoppingMallAiBackend.admin.issuedCoupons.search(connection, {
      body: Object.assign({ code: codes[0] }, { UNKNOWN_FIELD: "x" })
    } as any);
  });
}

