import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendIssuedCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendIssuedCoupon";

/**
 * Validate updating mutable fields and business rule enforcement for issued coupons.
 *
 * This test verifies that updates to issued coupon records via the admin API only allow permitted state mutations (status, expiry) and that forbidden operations (illegal status transitions, updates to cancelled or soft-deleted coupons) are correctly rejected. Test flows include successful mutation, audit compliance via updated_at, and negative cases with business rule violation.
 *
 * Steps:
 *   1. Issue a new coupon with distinct data (precondition for update)
 *   2. Update status to 'used' and set used_at; check state and audit
 *   3. Update expires_at to a new date and validate mutation
 *   4. Cancel the coupon; confirm status is changed
 *   5. Attempt illegal status update after cancellation (expect error)
 *   6. Simulate soft-delete by local object, try update (expect error)
 *
 * Note: Direct soft-delete/update on deleted data is not supported by the SDK/API. Step 6 is a business logic simulation (assert behaviour when deleted_at present) rather than a true API test.
 */
export async function test_api_issued_coupon_update_state_expiry_and_error_conditions(connection: api.IConnection) {
  // 1. Issue a new coupon for test
  const issueInput: IShoppingMallAiBackendIssuedCoupon.ICreate = {
    coupon_template_id: typia.random<string & tags.Format<"uuid">>(),
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(10),
    expires_at: new Date(Date.now() + 14 * 86400000).toISOString(),
    status: "issued",
  };
  const issued = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.create(connection, { body: issueInput });
  typia.assert(issued);

  // 2. Update: Mark coupon as used
  const usedAt = new Date(Date.now() + 1 * 3600000).toISOString();
  const used = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.update(connection, {
    issuedCouponId: issued.id,
    body: {
      status: "used",
      used_at: usedAt,
    },
  });
  typia.assert(used);
  TestValidator.equals("status -> used")(used.status)("used");
  TestValidator.equals("used_at set")(used.used_at)(usedAt);
  TestValidator.predicate("updated_at advanced")(used.updated_at > issued.updated_at);

  // 3. Update: Update expires_at
  const newExpiry = new Date(Date.now() + 21 * 86400000).toISOString();
  const expiryUpd = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.update(connection, {
    issuedCouponId: issued.id,
    body: {
      status: "used",
      expires_at: newExpiry,
    },
  });
  typia.assert(expiryUpd);
