 * 1. Register Customer A via /auth/customer/register.
 * 2. Register Customer B via /auth/customer/register.
 * 3. As admin, create a mileage wallet for Customer A via /shoppingMallAiBackend/admin/mileageWallets.
 * 4. As Customer A, successfully create a mileage transaction on their own wallet (for baseline demonstration).
 * 5. As Customer B, attempt to create a mileage transaction on Customer A's wallet. Expect an authorization/permission error, and ensure no transaction is recorded.
 */
export async function test_api_mileage_transaction_create_insufficient_permission_customer(
  connection: api.IConnection,
) {
  // 1. Register Customer A
  const customerA_email = typia.random<string & tags.Format<"email">>();
  const customerA_password = "Passw0rd!";
  const customerA_signup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
