import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartSnapshot";
import type { IPageIShoppingMallAiBackendCartSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCartSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate admin paginated/filtered retrieval of cart snapshot records for a target cart.
 *
 * This test simulates an end-to-end business flow for a single cart, across customer and admin roles, including:
 * 1. Customer registration (uniquely identifies a customer and provides JWT for cart activities)
 * 2. Cart creation (new cart linked to the customer)
 * 3. Simulate several cart states by creating 3 unique snapshots (with different 'snapshot_reason' and timestamps)
 * 4. As admin, search the cart snapshot history using the PATCH endpoint:
 *    - Filter by cart id (required)
 *    - Partial reason string
 *    - Date range (created_at_from/to)
 *    - Pagination (page/limit)
 * 5. Validate all results are for the correct cart; filters and pagination are properly enforced; all snapshot details are present for admin
 *
 * Steps:
 * - Register a new customer
 * - Create a new cart (status 'active')
 * - Simulate and create 3 snapshot records for the cart with different reasons/timestamps
 * - As admin, PATCH search for all snapshots by cartId
 * - Search filtered by partial reason
 * - Search with created_at_from/to
 * - Search with page/limit
 * - Each time, assert correct data contract (all cart_id fields correct, reason/date filters applied, pagination info accurate)
 */
export async function test_api_cart_snapshot_admin_search_pagination_filtering(connection: api.IConnection) {
  // 1. Customer registration (unique email, phone, etc)
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerNick: string = RandomGenerator.alphaNumeric(8);
  const customerPhone: string = RandomGenerator.mobile();
  const customerPassword: string = RandomGenerator.alphaNumeric(10);
  const signUpOut = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: customerNick,
      phone: customerPhone,
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpOut);
  // JWT is set in connection.headers automatically. Move on as authenticated customer.

  // 2. Cart creation (status 'active')
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      session_token: null,
    } satisfies IShoppingMallAiBackendCart.ICreate,
  });
  typia.assert(cart);

  // 3. Simulate 3 cart snapshots for the same cart, with unique reasons and timestamps
  const reasons = ["add_items", "manual_save", "update_quantities"];
  // We'll use ISO timestamp shifting for date-range filter validation
  const baseDate = new Date();
  const createdSnapshots: IShoppingMallAiBackendCartSnapshot[] = [];
  for (let i = 0; i < reasons.length; ++i) {
    // Simulated cart state as serialized JSON (could be full cart, here just minimal per spec)
    const fakeCartState = {
      id: cart.id,
      status: `state_${i}`,
      updated_at: new Date(baseDate.getTime() + i * 60000).toISOString(),
    };
    const snapshot = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.create(connection, {
      cartId: cart.id,
      body: {
        cart_id: cart.id,
        snapshot_json: JSON.stringify(fakeCartState),
        snapshot_reason: reasons[i],
      } satisfies IShoppingMallAiBackendCartSnapshot.ICreate,
    });
    typia.assert(snapshot);
    // Patch creation time for each snapshot for later date-range filtering
    createdSnapshots.push({ ...snapshot, created_at: new Date(baseDate.getTime() + i * 60000).toISOString() });
  }

  // For test filtering, we'll need actual created_at times from the returned objects
  // ---
  // 4. As admin, search all snapshots for cartId (unfiltered)
  const allResult = await api.functional.shoppingMallAiBackend.admin.carts.cartSnapshots.search(connection, {
    cartId: cart.id,
    body: {
      cart_id: cart.id,
    } satisfies IShoppingMallAiBackendCartSnapshot.IRequest,
  });
  typia.assert(allResult);
  TestValidator.equals("all results for correct cartId")(
    allResult.data.every(s => s.cart_id === cart.id)
  )(true);
  TestValidator.equals("at least 3 results for 3 inserted")(
    allResult.data.length >= 3
  )(true);

  // 5. Filter by snapshot_reason substring (e.g., 'manual')
  const reasonSub = "manual";
  const reasonResult = await api.functional.shoppingMallAiBackend.admin.carts.cartSnapshots.search(connection, {
    cartId: cart.id,
    body: {
      cart_id: cart.id,
      snapshot_reason: reasonSub,
    } satisfies IShoppingMallAiBackendCartSnapshot.IRequest,
  });
  typia.assert(reasonResult);
  TestValidator.predicate("reason substring filter applies correctly")(
    reasonResult.data.every(s => s.snapshot_reason.includes(reasonSub))
  );

  // 6. Search using created_at_from/created_at_to to select a time window containing only the 2nd snapshot
  const fromDate = createdSnapshots[1].created_at;
  const toDate = createdSnapshots[1].created_at;
  const dateFilterResult = await api.functional.shoppingMallAiBackend.admin.carts.cartSnapshots.search(connection, {
    cartId: cart.id,
    body: {
      cart_id: cart.id,
      created_at_from: fromDate,
      created_at_to: toDate,
    } satisfies IShoppingMallAiBackendCartSnapshot.IRequest,
  });
  typia.assert(dateFilterResult);
  TestValidator.equals("date filter isolates correct record count")(
    dateFilterResult.data.length
  )(1);
  TestValidator.equals("date filter correct record")(
    dateFilterResult.data[0].snapshot_reason
  )(reasons[1]);

  // 7. Pagination test: set limit=2, assert only 2 returned in data, pages correct
  const pageLimitResult = await api.functional.shoppingMallAiBackend.admin.carts.cartSnapshots.search(connection, {
    cartId: cart.id,
    body: {
      cart_id: cart.id,
      limit: 2,
      page: 1,
    } satisfies IShoppingMallAiBackendCartSnapshot.IRequest,
  });
  typia.assert(pageLimitResult);
  TestValidator.equals("pagination: limit 2 on first page")(
    pageLimitResult.data.length <= 2
  )(true);
  TestValidator.equals("pagination: page meta")(
    pageLimitResult.pagination.limit
  )(2);
  TestValidator.equals("pagination: current page")(
    pageLimitResult.pagination.current
  )(1);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartSnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that a customer can fetch their own cart snapshot detail, and access controls for foreign/nonexistent records.
 *
 * This test exercises end-to-end ability for a customer to retrieve the detail view of a shopping cart snapshot they own. It covers the workflow from registration, cart creation, snapshot creation, and retrieval, and validates schema correctness and data consistency. It also attempts negative access (nonexistent or unauthorized snapshot).
 *
 * 1. Register a new customer via /auth/customer/register. (Capture credentials & token)
 * 2. Create a new cart for this customer through /shoppingMallAiBackend/customer/carts (store cartId).
 * 3. Create a cart snapshot on this cart via /shoppingMallAiBackend/customer/carts/{cartId}/cartSnapshots, storing the returned cartSnapshotId.
 * 4. Fetch the snapshot detail using /shoppingMallAiBackend/customer/carts/{cartId}/cartSnapshots/{cartSnapshotId}.
 *    - Validate all schema fields are present and correct.
 *    - Confirm the snapshot's serialized cart state is consistent with the cart at snapshot time (using snapshot_json, check reasonable structure/fields).
 * 5. (Negative) Attempt to GET a non-existent cartSnapshotId under this cartId -- expect forbidden/not found error.
 * 6. (Negative) Register a second customer, then attempt to access the original customer's cart snapshot using their own credentials -- must get forbidden/unauthorized error.
 */
export async function test_api_cart_snapshot_customer_access_detail(connection: api.IConnection) {
  // 1. Register a customer and capture token & profile
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpResponse);
  const customer = signUpResponse.customer;
  // Token is set in connection.headers

  // 2. Create a cart for this customer
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      session_token: null,
    } satisfies IShoppingMallAiBackendCart.ICreate,
  });
  typia.assert(cart);

  // 3. Take a snapshot of the cart
  const cartSerialized = JSON.stringify(cart);
  const snapshotReason = "manual";
  const cartSnapshot = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.create(connection, {
    cartId: cart.id,
    body: {
      cart_id: cart.id,
      snapshot_json: cartSerialized,
      snapshot_reason: snapshotReason,
    } satisfies IShoppingMallAiBackendCartSnapshot.ICreate,
  });
  typia.assert(cartSnapshot);

  // 4. Retrieve cart snapshot details by ID
  const snapshotDetail = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.at(connection, {
    cartId: cart.id,
    cartSnapshotId: cartSnapshot.id,
  });
  typia.assert(snapshotDetail);

  // Validate fields
  TestValidator.equals("cart_id matches")(snapshotDetail.cart_id)(cart.id);
  TestValidator.equals("snapshot id matches")(snapshotDetail.id)(cartSnapshot.id);
  TestValidator.equals("snapshot reason matches")(snapshotDetail.snapshot_reason)(snapshotReason);
  // Confirm snapshot_json round-trip encodes cart
  const snapshotCart = JSON.parse(snapshotDetail.snapshot_json) as IShoppingMallAiBackendCart;
  TestValidator.equals("snapshot json id")(snapshotCart.id)(cart.id);

  // 5. Negative: Try fetch with nonexistent snapshot ID
  await TestValidator.error("non-existent snapshot error")(() =>
    api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.at(connection, {
      cartId: cart.id,
      cartSnapshotId: typia.random<string & tags.Format<"uuid">>(), // random uuid not matching
    })
  );

  // 6. Negative: Register a new customer and try to fetch original snapshot
  const attackerEmail = typia.random<string & tags.Format<"email">>();
  const attackerPassword = RandomGenerator.alphaNumeric(12);
  const attackerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: attackerEmail,
      password: attackerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(attackerSignUp);
  // token will switch automatically to attacker

  await TestValidator.error("attacker forbidden to access snapshot")(() =>
    api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.at(connection, {
      cartId: cart.id,
      cartSnapshotId: cartSnapshot.id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartSnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that an admin can retrieve any cart snapshot for any customer using GET, and proper error handling for invalid access and IDs.
 *
 * This test covers the following business scenario:
 * 1. Register a new customer, create a shopping cart as that customer.
 * 2. Create a cart snapshot for audit trail purposes.
 * 3. Register a new admin account and switch the authorization context to the admin.
 * 4. Fetch the snapshot as the admin and verify all returned fields for integrity, compliance, and auditability.
 * 5. Attempt unauthorized admin access (invalid JWT) and expect error.
 * 6. Attempt fetching a non-existent cartSnapshotId and expect error.
 *
 * Test ensures admin access control works, all snapshot fields return correctly,
 * and both permission and not-found error logic is enforced.
 */
export async function test_api_cart_snapshot_admin_access_detail(connection: api.IConnection) {
  // Step 1: Register customer
  const customerSignup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Cust0mer!" + typia.random<string>(),
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignup);
  const customerJwt = customerSignup.setHeaders.Authorization;

  // Step 2: As customer, create cart
  const customerConnection = { ...connection, headers: { ...connection.headers, Authorization: customerJwt } };
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(customerConnection, {
    body: {
      status: "active",
      session_token: null,
    },
  });
  typia.assert(cart);
  const cartId = cart.id;

  // Step 3: As customer, create cart snapshot
  const snapshotInput = {
    cart_id: cartId,
    snapshot_json: JSON.stringify(cart),
    snapshot_reason: "manual",
  };
  const snapshot = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.create(customerConnection, {
    cartId,
    body: snapshotInput,
  });
  typia.assert(snapshot);
  const cartSnapshotId = snapshot.id;

  // Step 4: Register admin
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Adm1n!" + typia.random<string>(),
    },
  });
  typia.assert(adminSignUp);
  const adminJwt = adminSignUp.setHeaders.Authorization;
  const adminConnection = { ...connection, headers: { ...connection.headers, Authorization: adminJwt } };

  // Step 5: As admin, fetch the cart snapshot detail for compliance
  const fetched = await api.functional.shoppingMallAiBackend.admin.carts.cartSnapshots.at(adminConnection, {
    cartId,
    cartSnapshotId,
  });
  typia.assert(fetched);
  TestValidator.equals("cart snapshot ID matches")(fetched.id)(cartSnapshotId);
  TestValidator.equals("cart ID matches")(fetched.cart_id)(cartId);
  TestValidator.equals("snapshot_json matches original cart")(fetched.snapshot_json)(snapshotInput.snapshot_json);
  TestValidator.equals("snapshot_reason matches")(fetched.snapshot_reason)(snapshotInput.snapshot_reason);
  TestValidator.predicate("created_at is ISO date-time")(!!Date.parse(fetched.created_at));

  // Step 6: Attempt to fetch with invalid admin JWT - should fail
  const invalidAdminConnection = { ...connection, headers: { ...connection.headers, Authorization: "Bearer invalidtoken" } };
  await TestValidator.error("unauthorized admin fetch fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.carts.cartSnapshots.at(invalidAdminConnection, {
      cartId,
      cartSnapshotId,
    });
  });

  // Step 7: Attempt to fetch with non-existent cartSnapshotId - should 404/error
  const bogusId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found error for missing snapshotId")(async () => {
    await api.functional.shoppingMallAiBackend.admin.carts.cartSnapshots.at(adminConnection, {
      cartId,
      cartSnapshotId: bogusId,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartSnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test the successful and unsuccessful creation of a shopping cart snapshot by a customer.
 *
 * This test simulates the core customer workflow for cart snapshotting. It covers:
 *   - Self-service registration of a unique customer account
 *   - Cart creation for the new customer
 *   - (Optionally) cart population - omitted because no item/cart product APIs are present
 *   - Snapshotting the cart state with explicit JSON structure and reason
 *   - Verifying the resulting snapshot record matches the current cart state and snapshot rationale
 *   - Negative test: attempting to create a snapshot for a cart owned by another user, confirming permission is denied
 *
 * Workflow:
 * 1. Register a new customer and extract credentials/JWT
 * 2. Create a new cart as that customer
 * 3. Serialize the cart state and build a snapshot request
 * 4. Create a cart snapshot and validate the result
 * 5. Attempt snapshot of a cart not owned by the current customer and expect a permission error
 */
export async function test_api_cart_snapshot_customer_create_successful(
  connection: api.IConnection,
) {
  // 1. Register a new customer (will receive an auth token)
  const customerSignUpReq: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassword123!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(12),
    phone: RandomGenerator.mobile(),
  };
  const customerSignUpResp: ICustomerSignUp.Response =
    await api.functional.auth.customer.register.signUp(connection, {
      body: customerSignUpReq,
    });
  typia.assert(customerSignUpResp);

  // 2. Create a new cart for that customer
  const cartReq: IShoppingMallAiBackendCart.ICreate = {
    status: "active",
    session_token: null,
  };
  const cart: IShoppingMallAiBackendCart =
    await api.functional.shoppingMallAiBackend.customer.carts.create(
      connection,
      { body: cartReq },
    );
  typia.assert(cart);

  // 3. Serialize the cart state (as per snapshot requirements), snapshot rationale
  //    Cart items are omitted as there are no APIs to support them
  const cartSnapshotReq: IShoppingMallAiBackendCartSnapshot.ICreate = {
    cart_id: cart.id,
    snapshot_json: JSON.stringify(cart),
    snapshot_reason: "manual",
  };

  // 4. Create a cart snapshot
  const snapshot: IShoppingMallAiBackendCartSnapshot =
    await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.create(
      connection,
      {
        cartId: cart.id,
        body: cartSnapshotReq,
      },
    );
  typia.assert(snapshot);
  // Validate that the returned snapshot matches request values
  TestValidator.equals("cart id matches")(snapshot.cart_id)(cart.id);
  TestValidator.equals("snapshot reason matches")(snapshot.snapshot_reason)(
    cartSnapshotReq.snapshot_reason,
  );
  TestValidator.equals("cart JSON matches")(snapshot.snapshot_json)(
    cartSnapshotReq.snapshot_json,
  );

  // 5. Negative test: Attempt to snapshot a random (unowned) cart
  const otherCartId: string & tags.Format<"uuid"> =
    typia.random<string & tags.Format<"uuid">>();
  // The snapshot request must reference this unowned cart
  const invalidSnapReq: IShoppingMallAiBackendCartSnapshot.ICreate = {
    cart_id: otherCartId,
    snapshot_json: JSON.stringify({ id: otherCartId, status: "active" }),
    snapshot_reason: "manual",
  };
  // The endpoint should reject as permission denied, confirmation by error thrown
  await TestValidator.error("should fail for non-owned cart")(() =>
    api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.create(
      connection,
      {
        cartId: otherCartId,
        body: invalidSnapReq,
      },
    ),
  );
}

