 * This test ensures that a registered customer can successfully update their
 * external authentication link. It covers the following steps:
 *
 * 1. Register a new customer and authenticate, extracting their customerId and Authorization token.
 * 2. Register (create/attach) an external link for the customer with initial data.
 * 3. Update the external link with new information and verify the changes are correctly applied.
 * 4. Assert that only the owner can perform updates by attempting a modification as a non-owner (should fail).
 *
 * Note: Audit log verification is only possible if accessible via API; business policy is explained via comments.
 */
export async function test_api_customer_external_link_update_successful_update_by_owner(
  connection: api.IConnection,
) {
  // 1. Register new customer and authenticate
  const registration = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
