import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerExternalLink } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerExternalLink";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test that an admin can soft-delete a customer's external authentication link (social/OAuth connector), and that all business rule requirements of soft deletion and audit are honored.
 *
 * This test covers the entire workflow:
 * 1. Register a new admin and authenticate the API session. (Admin registration also returns Authorization JWT, which is set in connection.headers.)
 * 2. Register a new customer via customer signup and get the created customer id.
 * 3. Attach a new external authentication link (e.g., social/OAuth) to the customer with a known provider/external_id pair.
 * 4. As admin, call DELETE /shoppingMallAiBackend/admin/customers/{customerId}/externalLinks/{externalLinkId} to soft-delete the external link. No response body is expected (void return), so follow-up GET cannot be called directly (since not exposed), but updating (PUT) or further deletions can be tested for error/idempotence.
 * 5. Confirm via update/PUT that the deleted link's deleted_at is set (that is, updating or linking with the same id should show deleted_at property is non-null). Attempting to delete again should yield error or no-op response (verify with TestValidator.error or TestValidator.predicate on behavior).
 *
 * Validates:
 * - Only admin can perform soft-delete, and the operation sets deleted_at (logical deletion, not physical)
 * - After deletion, link is not available for normal non-admin updates, and evidence of the soft-deleted state exists
 * - Repeated deletion is idempotent or returns an appropriate business logic error
 */
export async function test_api_admin_external_link_soft_delete_success(
  connection: api.IConnection,
) {
  // 1. Register and authenticate as admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword!123";
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);

  // Admin registration sets Authorization JWT in connection

  // 2. Register a customer
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerPassword = "CustomerPW!456";
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: "Test User",
      nickname: "testuser_" + RandomGenerator.alphaNumeric(6),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  const customerId: string = customerSignUp.customer.id;

  // 3. Attach an external link to the customer
  const extProvider = "test_provider";
  const extExternalId = RandomGenerator.alphaNumeric(14);
  const extLink = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(connection, {
    customerId,
    body: {
      id: typia.random<string & tags.Format<"uuid">>(),
      provider: extProvider,
      external_id: extExternalId,
      linked_at: new Date().toISOString(),
    } satisfies IShoppingMallAiBackendCustomerExternalLink.IUpdate,
  });
  typia.assert(extLink);
  const externalLinkId: string = extLink.id;

  // 4. As admin, soft-delete the external link
  await api.functional.shoppingMallAiBackend.admin.customers.externalLinks.erase(connection, {
    customerId,
    externalLinkId,
  });

  // 5. Confirm soft-deletion: update returns deleted_at non-null (link cannot be restored by normal update)
  const linkAfterDeletion = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(connection, {
    customerId,
    body: {
      id: externalLinkId,
    } satisfies IShoppingMallAiBackendCustomerExternalLink.IUpdate,
  });
  typia.assert(linkAfterDeletion);
  TestValidator.predicate("deleted_at is set after soft delete")(!!linkAfterDeletion.deleted_at);

  // 6. Attempting a second delete should error or act as idempotent (business rule dependent)
  await TestValidator.error("duplicate soft delete errors or is idempotent")(() =>
    api.functional.shoppingMallAiBackend.admin.customers.externalLinks.erase(connection, {
      customerId,
      externalLinkId,
    })
  );
}

