 * This test verifies Role-Based Access Control (RBAC) enforcement. It performs the following:
 *
 * 1. Register an admin (setup for potential cleanup/validation if needed)
 * 2. Register a new customer (non-admin user)
 * 3. Attach an external link to the customer (the link to be targeted)
 * 4. As the customer (with their JWT), attempt to call the admin-only soft-delete endpoint for the external link
 * 5. Validate that the API blocks the operation (permission denied error)
 * 6. Confirm the external link record remains undeleted (deleted_at is still null)
 */
export async function test_api_admin_external_link_delete_permission_denied(connection: api.IConnection) {
  // 1. Register an admin (for setup, not used directly in this test, but ensures RBAC context is defined)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin-Password-123";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
