 * 3. Add a cart item (with a mock product ID/option ID) to the created cart.
 * 4. Update the cart item with new valid parameters: quantity, option, note.
 * 5. Validate the updated cart item's fields (including timestamp and unchanged fields).
 * 6. Confirm business rule enforcement by attempting to set quantity < 1 and expecting an error.
 *
 * All steps use only permitted API SDK functions and DTO schemas. All validations follow business logic constraints for updateable cart item fields.
 */
export async function test_api_cart_item_update_with_valid_data_by_customer(
  connection: api.IConnection,
) {
  // 1. Register customer and authenticate
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const signUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "Password123!", // Satisfy standard complexity
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpResponse);
  const customer = signUpResponse.customer;

  // 2. Create an active cart
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      session_token: null,
    } satisfies IShoppingMallAiBackendCart.ICreate,
  });
  typia.assert(cart);

  // 3. Add an item to the cart with mock product_id and product_option_id
  const productId = typia.random<string & tags.Format<"uuid">>();
  const productOptionId = typia.random<string & tags.Format<"uuid">>();
  const initialCartItem = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
    cartId: cart.id,
    body: {
      product_id: productId,
      product_option_id: productOptionId,
      quantity: 2,
      unit_price: 12345.67,
      currency_code: "KRW",
      note: "init item",
    } satisfies IShoppingMallAiBackendCartItem.ICreate,
  });
  typia.assert(initialCartItem);

  // 4. Update the cart item
  const newQuantity = 3;
  const newProductOptionId = null;
  const newNote = "Updated quantity/option";
  const beforeUpdatedAt = initialCartItem.updated_at;
  const updatedCartItem = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.update(connection, {
    cartId: cart.id,
    cartItemId: initialCartItem.id,
    body: {
      quantity: newQuantity,
      product_option_id: newProductOptionId,
      note: newNote,
    } satisfies IShoppingMallAiBackendCartItem.IUpdate,
