  // 5. Validate the update took place and fields are enforced
  TestValidator.equals("id unchanged")(updatedCartItem.id)(initialCartItem.id);
  TestValidator.equals("product_id unchanged")(updatedCartItem.product_id)(initialCartItem.product_id);
  TestValidator.equals("quantity updated")(updatedCartItem.quantity)(newQuantity);
  TestValidator.equals("option updated (now null)")(updatedCartItem.product_option_id)(newProductOptionId);
  TestValidator.equals("note updated")(updatedCartItem.note)(newNote);
  TestValidator.predicate("updated_at is newer")(
    new Date(updatedCartItem.updated_at).getTime() > new Date(beforeUpdatedAt).getTime(),
  );
  TestValidator.equals("unit_price stays the same")(updatedCartItem.unit_price)(initialCartItem.unit_price);
  TestValidator.equals("currency_code stays the same")(updatedCartItem.currency_code)(initialCartItem.currency_code);
  TestValidator.equals("created_at stays the same")(updatedCartItem.created_at)(initialCartItem.created_at);
  TestValidator.equals("deleted_at unchanged")(updatedCartItem.deleted_at)(initialCartItem.deleted_at);

  // 6. Attempt invalid update (quantity < 1 should fail by business rule)
  await TestValidator.error("quantity < 1 triggers business validation error")(async () => {
    await api.functional.shoppingMallAiBackend.customer.carts.cartItems.update(connection, {
      cartId: cart.id,
      cartItemId: initialCartItem.id,
      body: {
        quantity: 0,
      } satisfies IShoppingMallAiBackendCartItem.IUpdate,
    });
  });
}

