/**
 * Validate customer-initiated cart item soft delete operation.
 *
 * This test covers the complete workflow for a customer logically (soft-) deleting an item from their cart. It ensures business compliance and evidence preservation:
 *   - The cart item is created, then soft-deleted (its `deleted_at` would be set by the backend).
 *   - Prior to deletion, validate the item is present with `deleted_at === null`.
 *   - After deletion, while no direct fetch/list exists for cart items, validate workflow by attempting to insert a new item, confirming the cart’s continued activeness.
 *
 * Steps:
 * 1. Register a new customer with unique credentials.
 * 2. Create a cart for this customer.
 * 3. Add a cart item to this cart.
 * 4. Soft-delete the cart item by ID.
 * 5. Add a second cart item to validate cart is still active and not broken by the soft delete.
 * 6. (Skipped: direct verification of deleted_at or item omission from active queries, as no endpoint exists)
 */
export async function test_api_cart_item_soft_delete_by_customer_success(connection: api.IConnection) {
  // 1. Register a new customer (provides authentication via automatic JWT/token response)
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPhone = RandomGenerator.mobile();
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "TestPassword!234",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: customerPhone,
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  TestValidator.equals("setHeaders present")(typeof customerSignUp.setHeaders.Authorization)("string");
  // User is now authenticated via header

  // 2. Create an 'active' cart for the customer
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      session_token: null,
    } satisfies IShoppingMallAiBackendCart.ICreate,
  });
  typia.assert(cart);
  TestValidator.equals("cart is active")(cart.status)("active");
  TestValidator.equals("deleted_at null (active cart)")(cart.deleted_at)(null);

  // 3. Add a new cart item to the cart
  const cartItem = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
    cartId: cart.id,
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      product_option_id: null,
      quantity: 1,
      unit_price: 9000.0,
      currency_code: "KRW",
      note: "Soft delete test",
    } satisfies IShoppingMallAiBackendCartItem.ICreate,
  });
  typia.assert(cartItem);
  TestValidator.equals("cartItem is present and not deleted")(cartItem.deleted_at)(null);

  // 4. Perform logical (soft) delete on the cart item
  await api.functional.shoppingMallAiBackend.customer.carts.cartItems.erase(connection, {
    cartId: cart.id,
    cartItemId: cartItem.id,
  });

  // 5. (Cannot directly verify deletion status or query cart items for omission, as no API exists)
  //    So, as a proxy, check the cart is still active and usable by adding another item.
  const cartItem2 = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
    cartId: cart.id,
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      product_option_id: null,
      quantity: 1,
      unit_price: 11000.0,
      currency_code: "KRW",
      note: "Insert after soft delete",
    } satisfies IShoppingMallAiBackendCartItem.ICreate,
  });
  typia.assert(cartItem2);
  TestValidator.equals("new cartItem is not deleted")(cartItem2.deleted_at)(null);
  TestValidator.notEquals("new cartItemId is unique")(cartItem2.id)(cartItem.id);
}

