    order_id: order.id,
    payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
    payment_method: "card",
    transaction_id: RandomGenerator.alphaNumeric(20),
    amount: order.total_amount,
    currency_code: order.currency_code,
    payment_result: "completed",
  } satisfies IShoppingMallAiBackendOrderPayment.ICreate;
  const payment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, { orderId: order.id, body: paymentCreate });
  typia.assert(payment);

  // 4. Create the initial payment log
  const paymentLogCreate = {
    log_type: "request",
    log_context: JSON.stringify({ audit: "init" }),
    occurred_at: new Date().toISOString(),
  } satisfies IShoppingMallAiBackendOrderPaymentLog.ICreate;
  const paymentLog = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.create(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: paymentLogCreate,
