  const payment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_provider_id: paymentProviderId,
      payment_method: "card",
      transaction_id: `TXN-${RandomGenerator.alphaNumeric(8)}`,
      amount: 10000,
      currency_code: "USD",
      payment_result: "pending",
    } satisfies IShoppingMallAiBackendOrderPayment.ICreate,
  });
  typia.assert(payment);

  // 4. Create a payment log as admin
  const log = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.create(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      log_type: "request",
