/**
 * Test the successful update of an article category by an admin user.
 *
 * This test verifies that an existing article category can be updated via PUT /shoppingMallAiBackend/admin/articleCategories/{categoryId}.
 *
 * Steps:
 * 1. Create a new article category to ensure a valid category exists for updating.
 * 2. Create a separate parent category to allow updating the child category's parent linkage.
 * 3. Update the initial category - changing the name, assigning the new parent_id, toggling is_active, and updating sort_order.
 * 4. Verify the response reflects these changes, with the correct entity id, updated audit timestamps, and all edit fields.
 * 5. Confirm audit integrity: updated_at must be after created_at.
 */
export async function test_api_article_category_update_success(
  connection: api.IConnection,
) {
  // 1. Create initial category to be updated
  const baseCategoryInput: IShoppingMallAiBackendArticleCategory.ICreate = {
    name: "Initial Root Category",
    code: `INIT_${RandomGenerator.alphaNumeric(8)}`,
    is_active: true,
    parent_id: null,
    sort_order: 10,
  };
  const baseCategory = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, { body: baseCategoryInput });
  typia.assert(baseCategory);

  // 2. Create parent category
  const parentCategoryInput: IShoppingMallAiBackendArticleCategory.ICreate = {
    name: "Parent Category",
    code: `PARENT_${RandomGenerator.alphaNumeric(8)}`,
    is_active: true,
    parent_id: null,
    sort_order: 5,
  };
  const parentCategory = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, { body: parentCategoryInput });
  typia.assert(parentCategory);

  // 3. Update initial category's name, parent_id, is_active, sort_order
  const updateDto: IShoppingMallAiBackendArticleCategory.IUpdate = {
    name: "Updated Child Category",
    parent_id: parentCategory.id,
    is_active: false,
    sort_order: 20,
  };

  const updatedCategory = await api.functional.shoppingMallAiBackend.admin.articleCategories.update(connection, {
    categoryId: baseCategory.id,
    body: updateDto,
  });
  typia.assert(updatedCategory);

  // 4. Check all changes are reflected in response
  TestValidator.equals("id matches")(updatedCategory.id)(baseCategory.id);
  TestValidator.equals("name changed")(updatedCategory.name)(updateDto.name);
  TestValidator.equals("parent_id changed")(updatedCategory.parent_id)(parentCategory.id);
  TestValidator.equals("is_active changed")(updatedCategory.is_active)(updateDto.is_active);
  TestValidator.equals("sort_order changed")(updatedCategory.sort_order)(updateDto.sort_order);

  // 5. Confirm audit updated_at is after or equal to created_at
  TestValidator.predicate("audit updated_at after created_at")(new Date(updatedCategory.updated_at) >= new Date(baseCategory.created_at));
}

