/**
 * Validate retrieving a specific coin wallet snapshot detail as admin, with permission and error checks.
 *
 * This test ensures that:
 *  - The snapshot detail endpoint correctly returns the full snapshot information for the supplied wallet and snapshot IDs when accessed by admin.
 *  - All business attributes and audit fields are present.
 *  - Proper authorization is required; non-admin or unauthenticated access is denied.
 *  - Error responses are returned for invalid snapshot or wallet IDs.
 *
 * Workflow:
 * 1. Create a coin wallet as admin (coinWallets.create)
 * 2. Create a snapshot for the wallet as admin (coinWallets.coinSnapshots.create)
 * 3. Retrieve the snapshot detail with the correct admin privileges (coinWallets.coinSnapshots.at)
 * 4. Validate that returned payload matches created snapshot in all core fields
 * 5. Attempt to retrieve same snapshot as (mock) non-admin and verify access is denied
 * 6. Query using invalid or non-existent snapshot and wallet IDs and check for error handling
 */
export async function test_api_coin_wallet_snapshot_detail_success_and_permission(
  connection: api.IConnection,
) {
  // 1. Create a coin wallet (admin role assumed)
  const walletInput: IShoppingMallAiBackendCoinWallet.ICreate = {
    wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(),
