import type { IShoppingMallAiBackendCoinSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinSnapshot";

/**
 * Validate admin ability to create coin wallet snapshots including persistence, field correctness, unique/business rules, error cases
 *
 * This test covers coin wallet snapshot creation as an admin, ensuring correctness and error handling:
 * 1. Create a parent wallet with required fields via admin endpoint.
 * 2. Create a valid snapshot for this wallet, then:
 *    a. Confirm all snapshot fields match schema and reflect wallet state correctly.
 *    b. Response is type-valid and persists values.
 * 3. Attempt duplicate snapshot with same input – observe if any uniqueness/business constraints block duplicates or allow them.
 * 4. Attempt a snapshot for a non-existent wallet ID – expect an error and validate correct error thrown.
 * 5. Attempt to create a snapshot omitting required fields – expect validation error with clear message.
 */
export async function test_api_coin_wallet_snapshot_creation_unique_and_validation(connection: api.IConnection) {
  // 1. Create parent coin wallet (admin)
  const walletInput: IShoppingMallAiBackendCoinWallet.ICreate = {
    wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(),
    wallet_type: "reward",
    wallet_status: "active",
    wallet_address: `ADDR-${typia.random<string & tags.Format<"uuid">>()}`,
    wallet_label: "Test admin wallet",
    security_code: "1234"
  };
  const wallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {body: walletInput});
  typia.assert(wallet);

  // 2. Create first valid snapshot for this wallet
  const snapshotInput: IShoppingMallAiBackendCoinSnapshot.ICreate = {
    wallet_id: wallet.id,
    owner_admin_id: wallet.wallet_owner_admin_id!,
    wallet_type: wallet.wallet_type,
    wallet_status: wallet.wallet_status,
    wallet_address: wallet.wallet_address,
    wallet_label: wallet.wallet_label ?? null,
    security_code: wallet.security_code ?? null,
    snapshot_balance: 1000,
    snapshot_reason: "Initial audit",
    snapshot_at: new Date().toISOString(),
  };
  const snapshot = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.create(connection, {
    coinWalletId: wallet.id,
    body: snapshotInput
  });
  typia.assert(snapshot);
  // Confirm snapshot field values match input
  TestValidator.equals("wallet_id correct")(snapshot.wallet_id)(wallet.id);
  TestValidator.equals("snapshot_balance correct")(snapshot.snapshot_balance)(1000);
  TestValidator.equals("snapshot_reason correct")(snapshot.snapshot_reason)("Initial audit");
  TestValidator.equals("owner_admin_id correct")(snapshot.owner_admin_id)(wallet.wallet_owner_admin_id);
  TestValidator.equals("wallet_type correct")(snapshot.wallet_type)(wallet.wallet_type);
  TestValidator.equals("wallet_status correct")(snapshot.wallet_status)(wallet.wallet_status);
  TestValidator.equals("wallet_address correct")(snapshot.wallet_address)(wallet.wallet_address);
  TestValidator.equals("wallet_label correct")(snapshot.wallet_label ?? null)(wallet.wallet_label ?? null);
  TestValidator.equals("security_code correct")(snapshot.security_code ?? null)(wallet.security_code ?? null);

  // 3. Try to create a duplicate snapshot (business/unique constraints)
  const duplicatePromise = api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.create(connection, {
    coinWalletId: wallet.id,
    body: snapshotInput
  });
  // If unique constraint enforced, should error, otherwise allow
  await TestValidator.error("duplicate snapshot unique or idempotency, if enforced")(async () => {
    await duplicatePromise;
  });

  // 4. Snapshot with non-existent wallet ID
  await TestValidator.error("snapshot for nonexistent wallet")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.create(connection, {
        coinWalletId: typia.random<string & tags.Format<"uuid">>(),
        body: {...snapshotInput, wallet_id: typia.random<string & tags.Format<"uuid">>()}
      });
    }
  );

  // 5. Omit required fields (wallet_type missing)
  const badInput = {
    ...snapshotInput
  };
  delete (badInput as any).wallet_type;
  await TestValidator.error("missing required field 'wallet_type'")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.create(connection, {
        coinWalletId: wallet.id,
        body: badInput as any // this triggers a runtime (not compile-time) validation error
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
