  }

  // f. Small pagination (limit 2)
  const resp6 = await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
    body: { limit: 2 } satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
  });
