  // g. Pagination across multiple pages
  const resp7 = await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
    body: { page: 2, limit: 2 } satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
  });
  typia.assert(resp7);
  TestValidator.equals("pagination page")(resp7.pagination.current)(2);

  // 5. Security: Assert no forbidden/sensitive fields are present in each notification object according to DTO spec
  for (const resp of [resp1, resp2, resp3, resp4, resp5, resp6, resp7]) {
    for (const n of resp.data) {
      // Should not have internal tokens, passwords, etc, only properties defined in IShoppingMallAiBackendFavoriteNotification
      for (const key of Object.keys(n)) {
        TestValidator.predicate(`allowed field: ${key}`)([
          "id",
          "favorite_product_id",
          "favorite_inquiry_id",
          "favorite_address_id",
          "notification_type",
          "notification_channel",
          "read",
          "delivery_metadata",
          "created_at"
        ].includes(key as any));
      }
    }
  }

  // 6. Negative/edge cases
  // Impossible filter: a nonsense notification_type
  const resp8 = await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
    body: { notification_type: "THIS_DOES_NOT_EXIST" } satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
  });
  typia.assert(resp8);
  TestValidator.equals("empty on impossible type")(resp8.data.length)(0);

  // Missing/invalid filter: invalid limit (zero or negative)
  await TestValidator.error("invalid limit rejected")(async () => {
    await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
      body: { limit: 0 } satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
    });
  });
}

