    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminAccount);
  // Authorization is handled in connection

  // 2. Create a customer order (dummy customer for test)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId,
