import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test seller inquiry update – answering product inquiry flow
 *
 * This test covers the end-to-end process for a seller to update one of their product inquiries, adding an answer and setting status to 'answered'.
 *
 * Business context:
 * - Only the seller or admin may update an inquiry (e.g., to post an answer or change status).
 * - A valid flow involves: seller registration, product creation, customer registration, inquiry submission, and then seller marking the inquiry as answered.
 *
 * Steps:
 * 1. Register and authenticate a seller
 * 2. Seller creates a product
 * 3. Register and authenticate a customer
 * 4. Customer submits a product inquiry
 * 5. Switch back to seller authentication
 * 6. Seller updates inquiry status to 'answered'
 * 7. Validate inquiry reflects updated status and correct fields
 */
export async function test_api_seller_product_inquiry_update_seller_response(connection: api.IConnection) {
  // 1. Seller registration: receive sellerId and JWT
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "TestPw1234!";
  const sellerReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(20),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerReg);
  TestValidator.equals("seller registration email")(sellerReg.email)(sellerEmail);

  // Set JWT for seller
  connection.headers = { ...(connection.headers ?? {}), Authorization: sellerReg.setHeaders.Authorization };

  // 2. Seller creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerReg.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(20),
      main_image_uri: null,
      status: "published",
    },
  });
  typia.assert(product);
  TestValidator.equals("product ownership")(product.seller_id)(sellerReg.sellerId);

  // 3. Customer registration: receive customer entity and JWT
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "CusPw1234!";
  const customerReg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerReg);
  TestValidator.equals("customer registration email")(customerReg.customer.email)(customerEmail);

  // Switch to customer JWT
  connection.headers = { ...(connection.headers ?? {}), Authorization: customerReg.setHeaders.Authorization };

  // 4. Customer submits inquiry for the product
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerReg.customer.id,
      product_id: product.id,
      title: "Question about product",
      body: "Is this product waterproof?",
      public: true,
    },
  });
  typia.assert(inquiry);
  TestValidator.equals("inquiry product linkage")(inquiry.product_id)(product.id);
  TestValidator.equals("inquiry customer linkage")(inquiry.customer_id)(customerReg.customer.id);

  // 5. Switch back to seller JWT for answering
  connection.headers = { ...(connection.headers ?? {}), Authorization: sellerReg.setHeaders.Authorization };

  // 6. Seller updates inquiry: status to 'answered'
  const updatedInquiry = await api.functional.shoppingMallAiBackend.seller.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      status: "answered",
    },
  });
  typia.assert(updatedInquiry);
  TestValidator.equals("updated inquiry status is 'answered'")(updatedInquiry.status)("answered");
