/**
 * Test the successful update of a product option by an admin.
 *
 * This test covers the privileged workflow: an admin registers, logs in, creates a product, adds a product option, then successfully updates the product option's metadata via the admin API.
 *
 * Steps:
 * 1. Register a new admin account (unique email/password)
 * 2. Log in as that admin (obtaining JWT via session, no manual token handling)
 * 3. Create a new product using a unique product code and a random seller UUID
 * 4. Add a stable option to the product
 * 5. Update the option, changing specific metadata fields (SKU, option name, extra price, status)
 * 6. Confirm updates persist (option fields are changed, reference/product remain, audit timestamps are modified accordingly)
 *
 * This ensures that option management is fully functional, changes take effect, and audit/compliance history is accurately captured.
 */
export async function test_api_admin_update_product_option_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Adm1nT3st@2024";
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Log in as admin
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(signInResp);
  // (Session JWT automatically handled)

  // 3. Create a product as admin (using a synthetic seller_id)
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const productCode = RandomGenerator.alphabets(12).toUpperCase();
  const productName = RandomGenerator.paragraph()(2);
  const productStatus = "published";

  const createdProduct = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: productCode,
      name: productName,
      status: productStatus,
      description: "Autogenerated product for E2E test.",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(createdProduct);

  // 4. Add a product option
  const initialSKU = RandomGenerator.alphabets(8).toUpperCase();
  const initialOptionName = "Size-Large-" + RandomGenerator.alphaNumeric(4);
  const optionStatus = "active";
  const createdOption = await api.functional.shoppingMallAiBackend.admin.products.productOptions.create(connection, {
    productId: createdProduct.id,
    body: {
      product_id: createdProduct.id,
      sku: initialSKU,
      option_name: initialOptionName,
      option_values: "Large",
      extra_price: 0,
      status: optionStatus,
    } satisfies IShoppingMallAiBackendProductOption.ICreate,
  });
  typia.assert(createdOption);

  // 5. Update the option metadata
  const updatedSKU = initialSKU + "-UPD";
  const updatedOptionName = initialOptionName + "-Edit";
  const updatedExtraPrice = 1500.0;
  const updatedStatus = "inactive";
  const updatedOption = await api.functional.shoppingMallAiBackend.admin.products.productOptions.update(connection, {
    productId: createdProduct.id,
    productOptionId: createdOption.id,
    body: {
      sku: updatedSKU,
      option_name: updatedOptionName,
      extra_price: updatedExtraPrice,
      status: updatedStatus,
    } satisfies IShoppingMallAiBackendProductOption.IUpdate,
  });
  typia.assert(updatedOption);

  // 6. Confirm update: all changed fields, relation, and update timestamp
  TestValidator.equals("SKU was updated")(updatedOption.sku)(updatedSKU);
  TestValidator.equals("Option name was updated")(updatedOption.option_name)(updatedOptionName);
  TestValidator.equals("Extra price was updated")(updatedOption.extra_price)(updatedExtraPrice);
  TestValidator.equals("Option status updated")(updatedOption.status)(updatedStatus);
  TestValidator.equals("Product reference preserved")(updatedOption.product_id)(createdProduct.id);
  TestValidator.notEquals("Update time must change")(updatedOption.updated_at)(createdOption.updated_at);
}

