/**
 * Validate that an admin user can retrieve the paginated list of article categories, and the list contains expected data.
 *
 * This test ensures that after categories are created via the search (patch) endpoint, the listing (get) endpoint returns a correct structure with populated fields and valid pagination metadata. It validates business logic and data organization in the CMS/category tree scenario for the backend.
 *
 * Steps:
 * 1. Use the admin articleCategories search endpoint to create at least two related categories (parent and child), both with required fields populated (no 'sort_order' – only allowed IRequest fields: name, code, is_active, [parent_id]).
 * 2. Call the articleCategories index (listing) endpoint to retrieve the full category list.
 * 3. Validate that the response is not empty and contains both parent and child categories (matched by code).
 * 4. Validate that each object in the list has an id (uuid), name, code, sort_order, is_active, created_at, updated_at. If a child, parent_id matches the parent's id.
 * 5. Validate that the pagination object matches the data count, and all numeric/date formats are correct.
 * 6. Check that at least one active category exists, and parent/child relations are respected (for tree structure).
 */
export async function test_api_article_category_listing_success_admin(
  connection: api.IConnection,
) {
  // 1. Create parent and child categories for test data using PATCH (search) endpoint
  const parentCategoryCode = RandomGenerator.alphaNumeric(8);
  const childCategoryCode = RandomGenerator.alphaNumeric(8);

  // Create parent category (allowed fields only)
  const parentResult = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: {
      name: "Parent Category",
      code: parentCategoryCode,
      is_active: true,
    } satisfies IShoppingMallAiBackendArticleCategory.IRequest,
  });
  typia.assert(parentResult);
  const parentId = parentResult.data[0]?.id;
  TestValidator.predicate("parent category creation")(typeof parentId === "string" && !!parentId);

  // Create child category under parent (allowed fields only)
  const childResult = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: {
      name: "Child Category",
      code: childCategoryCode,
      is_active: true,
      parent_id: parentId,
    } satisfies IShoppingMallAiBackendArticleCategory.IRequest,
  });
  typia.assert(childResult);
  const childId = childResult.data[0]?.id;
  TestValidator.predicate("child category creation")(typeof childId === "string" && !!childId);

  // 2. List all categories using GET index
  const listResponse = await api.functional.shoppingMallAiBackend.admin.articleCategories.index(connection);
  typia.assert(listResponse);

  // 3. Validate existence of parent and child by code
  const codes = listResponse.data.map((cat) => cat.code);
  TestValidator.predicate("parent category in list")(codes.includes(parentCategoryCode));
  TestValidator.predicate("child category in list")(codes.includes(childCategoryCode));

  // 4. Validate structure and relations
  const parentCategory = listResponse.data.find((cat) => cat.code === parentCategoryCode);
  const childCategory = listResponse.data.find((cat) => cat.code === childCategoryCode);
  TestValidator.equals("parent id of child")(childCategory?.parent_id)(parentCategory?.id);
  TestValidator.equals("is_active true for parent")(parentCategory?.is_active)(true);
  TestValidator.equals("is_active true for child")(childCategory?.is_active)(true);
  [parentCategory, childCategory].forEach((cat) => {
    TestValidator.predicate("category id")(typeof cat?.id === "string" && !!cat?.id);
    TestValidator.predicate("category name")(typeof cat?.name === "string" && !!cat?.name);
    TestValidator.predicate("category sort_order")(typeof cat?.sort_order === "number");
    TestValidator.predicate("category created_at")(typeof cat?.created_at === "string" && !!cat?.created_at);
    TestValidator.predicate("category updated_at")(typeof cat?.updated_at === "string" && !!cat?.updated_at);
  });

  // 5. Validate pagination
  const pagination = listResponse.pagination;
  TestValidator.predicate("total records positive")(pagination.records > 0);
  TestValidator.predicate("pages positive")(pagination.pages >= 1);
  TestValidator.predicate("current page")(pagination.current >= 1);
  TestValidator.predicate("limit positive")(pagination.limit > 0);
}

