import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test the successful creation of an order snapshot by an authenticated customer for their own order.
 *
 * Business Value:
 * This test guarantees that customers can securely create immutable snapshots of their orders, supporting features around dispute resolution, audit trails, rollback, and compliance evidence. Only the authenticated customer may perform this action on their own order.
 *
 * Step-by-step Validation:
 * 1. Register a new customer, triggering auto-authentication (JWT attached)
 * 2. Create a customer-owned order simulating a real checkout
 * 3. As the customer, create a snapshot of the order, passing serialized order JSON and a clear reason
 * 4. Verify snapshot creation succeeds, fields match (IDs, JSON string, reason)
 * 5. Assert correct UUID, timestamp format, and correct access control
 *
 * This comprehensive flow validates both happy-path functionality, strict type safety, and downstream compliance requirements.
 */
export async function test_api_order_snapshot_creation_by_customer_success_rollback_and_evidence(connection: api.IConnection) {
  // 1. Register new customer (authentication auto-attached)
  const customerSignUpReq = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassword123!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphaNumeric(10),
    phone: RandomGenerator.mobile(),
  } satisfies ICustomerSignUp.Request;
  const signUpResp = await api.functional.auth.customer.register.signUp(connection, { body: customerSignUpReq });
  typia.assert(signUpResp);
  const customer = signUpResp.customer;

  // 2. Create order owned by the customer
  const orderCreateReq = {
    customer_id: customer.id,
    order_number: RandomGenerator.alphaNumeric(16),
    total_amount: typia.random<number & tags.Minimum<1000> & tags.Maximum<1000000>>(),
    currency_code: "USD",
    note: "E2E order for snapshot test",
    current_status: "created",
  } satisfies IShoppingMallAiBackendOrder.ICreate;
  const createdOrder = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderCreateReq });
  typia.assert(createdOrder);

  // 3. Create a snapshot of this order
  const snapshotReason = "customer_requested_evidence";
  const snapshotPayload = {
    snapshot_json: JSON.stringify(createdOrder),
    snapshot_reason: snapshotReason,
  } satisfies IShoppingMallAiBackendOrderSnapshot.ICreate;
  const snapshot = await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.create(connection, { orderId: createdOrder.id, body: snapshotPayload });
  typia.assert(snapshot);

  // 4. Validate snapshot metadata and content
  TestValidator.equals("order id in snapshot matches")(snapshot.order_id)(createdOrder.id);
  TestValidator.equals("snapshot_reason matches")(snapshot.snapshot_reason)(snapshotReason);
  TestValidator.predicate("snapshot_json strictly matches order JSON")(snapshot.snapshot_json === JSON.stringify(createdOrder));
  TestValidator.predicate("snapshot_json parses back to order")(JSON.stringify(typia.assert<IShoppingMallAiBackendOrder>(JSON.parse(snapshot.snapshot_json))) === JSON.stringify(createdOrder));
  TestValidator.predicate("snapshot id is uuidv4 format")(typeof snapshot.id === "string" && /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/.test(snapshot.id));
  TestValidator.predicate("created_at is valid ISO date-time")(typeof snapshot.created_at === "string" && !isNaN(Date.parse(snapshot.created_at)) && snapshot.created_at.endsWith("Z"));
}

