  const cartsB: IShoppingMallAiBackendCart[] = [];
  for (let i = 0; i < 3; ++i) {
    const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
      body: {
        status: "active",
        session_token: null
      } satisfies IShoppingMallAiBackendCart.ICreate
    });
    typia.assert(cart);
    cartsB.push(cart);
  }
  // Switch back to customer A
  connection.headers = {
    ...connection.headers,
    Authorization: signUpA.setHeaders.Authorization
  };
  // Query with wide-open (no filter); ensure none of B's carts are present
  const searchAll = await api.functional.shoppingMallAiBackend.customer.carts.search(connection, {
    body: {} as IShoppingMallAiBackendCart.IRequest
  });
  typia.assert(searchAll);
  for (const cart of searchAll.data) {
