/**
 * Validates paginated and filtered search over the admin access logs for the backend compliance system.
 *
 * This test ensures:
 * - Admin can log in to obtain authorization
 * - The access logs endpoint supports searching with combinations of filters: actor_id (admin UUID), access_type, occurred_at (date/time), source_ip, etc.
 * - All results returned match the filter criteria
 * - Sensitive fields (such as source_ip, actor_id) are available to the admin
 * - Pagination metadata is accurate for result set size and page
 * - Edge cases such as no results and out-of-range pages return expected metadata and empty data arrays
 *
 * Steps:
 * 1. Admin login to get JWT/token
 * 2. Baseline unfiltered access log search to detect testable filter values
 * 3. Search using strict filters (actor_id, access_type, source_ip, occurred_at range)
 * 4. Validate that all results match the applied filters, with pagination controls
 * 5. Test edge cases: empty results (nonsense source_ip), and page far beyond end
 */
export async function test_api_accesslog_search_pagination_and_filter(
  connection: api.IConnection,
) {
  // 1. Admin login
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "securePw1234!";
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminAuth);

  // 2. Perform baseline unfiltered search (to get coverage for testable filter values)
  const unfiltered = await api.functional.shoppingMallAiBackend.admin.accessLogs.search(connection, {
    body: {},
  });
  typia.assert(unfiltered);
  TestValidator.predicate("Has data array")(
    Array.isArray(unfiltered.data),
  );
  TestValidator.predicate("Pagination meta present")(
    typeof unfiltered.pagination === "object"
  );

  // Select log entry for filter values, if available
  const sampleLog = unfiltered.data.length > 0 ? unfiltered.data[0] : null;
  const filterRequest = {
    actor_id: sampleLog?.actor_id ?? null,
    access_type: sampleLog?.access_type ?? null,
    source_ip: sampleLog?.source_ip ?? null,
    occurred_at_from: sampleLog?.occurred_at ?? null,
    occurred_at_to: sampleLog?.occurred_at ?? null,
    page: 1,
    limit: 1,
    order: "desc" as const,
    sort_by: "occurred_at",
  };
  // 3. Search using filters
  const filtered = await api.functional.shoppingMallAiBackend.admin.accessLogs.search(connection, {
    body: filterRequest,
  });
  typia.assert(filtered);
  TestValidator.equals("pagination page")(filtered.pagination.current)(1);
  TestValidator.equals("pagination limit")(filtered.pagination.limit)(1);

  for (const entry of filtered.data) {
    if (filterRequest.actor_id)
      TestValidator.equals("actor_id matches")(entry.actor_id)(filterRequest.actor_id);
    if (filterRequest.access_type)
      TestValidator.equals("access_type matches")(entry.access_type)(filterRequest.access_type);
    if (filterRequest.source_ip)
      TestValidator.equals("source_ip matches")(entry.source_ip)(filterRequest.source_ip);
    if (filterRequest.occurred_at_from)
      TestValidator.predicate("occurred_at >= from")(entry.occurred_at >= filterRequest.occurred_at_from);
    if (filterRequest.occurred_at_to)
      TestValidator.predicate("occurred_at <= to")(entry.occurred_at <= filterRequest.occurred_at_to);
  }

  // 4. Edge case: search for no results using impossible source_ip
  const noresults = await api.functional.shoppingMallAiBackend.admin.accessLogs.search(connection, {
    body: {
      source_ip: "255.255.255.255"
    },
  });
  typia.assert(noresults);
  TestValidator.equals("no results")(noresults.data.length)(0);
  TestValidator.equals("noresults record count")(noresults.pagination.records)(0);
  TestValidator.equals("noresults pages")(noresults.pagination.pages)(0);

  // 5. Edge case: out-of-bounds pagination (huge page number)
  const overPage = await api.functional.shoppingMallAiBackend.admin.accessLogs.search(connection, {
    body: {
      page: 99999,
    },
  });
  typia.assert(overPage);
  TestValidator.equals("overpage empty results")(
    Array.isArray(overPage.data) && overPage.data.length === 0,
  )(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinWallet";
import type { IShoppingMallAiBackendCoinTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinTransaction";
import type { IPageIShoppingMallAiBackendCoinTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCoinTransaction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching for coin transactions in a wallet with various filters and pagination.
 *
 * Ensures that an admin user can:
 * 1. Create a new coin wallet
 * 2. Insert a coin transaction in that wallet
 * 3. Search for coin transactions in that wallet via a wide variety of filters and pagination controls
 * 4. Handles edge and error scenarios such as invalid filters and non-existent wallets gracefully
 *
 * Steps:
 * 1. Create a coin wallet owned by an admin (simulates admin scenario)
 * 2. Insert a deposit transaction into the wallet (referenceId and reason are unique strings)
 * 3. Retrieve/search transactions in all the following ways:
 *    a. By wallet ID only (happy path: should find one)
 *    b. By matching transaction_type (should match)
 *    c. By wrong transaction_type (should not find any)
 *    d. By reference_id
 *    e. By transaction_reason
 *    f. By creation date inclusive (broad range)
 *    g. By pagination (limit/page)
 *    h. By ordering (order_by and order_dir)
 *    i. By invalid pagination (should error)
 *    j. By non-existent wallet (should return 0 results, not error)
 */
export async function test_api_coin_wallet_transaction_search_with_filters(connection: api.IConnection) {
  // 1. Create a coin wallet owned by an admin
  const createWalletBody: IShoppingMallAiBackendCoinWallet.ICreate = {
    wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(),
    wallet_type: "reward",
    wallet_status: "active",
    wallet_address: RandomGenerator.alphaNumeric(32),
    wallet_label: "Test Wallet",
    security_code: "1234",
  };
  const wallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: createWalletBody,
  });
  typia.assert(wallet);

  // 2. Insert a deposit coin transaction with unique reference and reason strings
  const transactionType = "deposit";
  const referenceId = RandomGenerator.alphaNumeric(12);
  const reason = "test deposit";
  const transactionAmount = 100.0;
  const transactionBody: IShoppingMallAiBackendCoinTransaction.ICreate = {
    wallet_id: wallet.id,
    transaction_type: transactionType,
    transaction_amount: transactionAmount,
    balance_after_transaction: transactionAmount,
    reference_id: referenceId,
    transaction_reason: reason,
  };
  const transaction = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.create(connection, {
    coinWalletId: wallet.id,
    body: transactionBody,
  });
  typia.assert(transaction);

  // 3a. Search transactions by wallet ID (should find the inserted record)
  let response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: wallet.id,
    body: { wallet_id: wallet.id },
  });
  typia.assert(response);
  TestValidator.predicate("Should find at least one transaction")(response.data.length >= 1);
  TestValidator.equals("transaction matches")(response.data[0].id)(transaction.id);

  // 3b. Search by transaction_type
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      transaction_type: transactionType,
    },
  });
  typia.assert(response);
  TestValidator.predicate("Filter by transaction_type should return results")(response.data.length >= 1);
  TestValidator.equals("transaction_type matches")(response.data[0].transaction_type)(transactionType);

  // 3c. Search with non-existent transaction_type (should return none)
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      transaction_type: "withdrawal",
    },
  });
  typia.assert(response);
  TestValidator.equals("No match for wrong type")(response.data.length)(0);

  // 3d. Filter by reference_id (should match inserted)
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      reference_id: referenceId,
    },
  });
  typia.assert(response);
  TestValidator.predicate("Should find transaction by reference_id")(response.data.some(t => t.id === transaction.id));

  // 3e. Filter by transaction_reason
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      transaction_reason: reason,
    },
  });
  typia.assert(response);
  TestValidator.predicate("Should find transaction by reason")(response.data.some(t => t.id === transaction.id));

  // 3f. Filter by created_from/created_to: use range to include test tx
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      created_from: new Date(Date.now() - 60 * 60 * 1000).toISOString(),
      created_to: new Date(Date.now() + 60 * 60 * 1000).toISOString(),
    },
  });
  typia.assert(response);
  TestValidator.predicate("Date range should return transaction")(response.data.some(t => t.id === transaction.id));

  // 3g. Pagination: limit = 1, page = 1
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      limit: 1,
      page: 1,
    },
  });
  typia.assert(response);
  TestValidator.equals("Pagination limit")(response.pagination.limit)(1);
  TestValidator.predicate("Returned page contains transaction")(response.data.some(t => t.id === transaction.id));

  // 3h. Ordering by created_at desc
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      order_by: "created_at",
      order_dir: "desc",
    },
  });
  typia.assert(response);
  TestValidator.predicate("Order by created_at desc returns array")(Array.isArray(response.data));

  // 3i. Invalid filter (bad page value)
  await TestValidator.error("Invalid page number should error")(() =>
    api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
      coinWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        page: -1,
      },
    })
  );

  // 4. Attempt to search in a non-existent wallet (should return empty, not error)
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: typia.random<string & tags.Format<"uuid">>(),
    body: {
      wallet_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(response);
  TestValidator.equals("Non-existent wallet returns 0 results")(response.data.length)(0);
}

