 * 2. Handling of duplicate reference_id
 * 3. Failure case for non-existent wallet
 * 4. Failure for invalid (negative, if not allowed) transaction amount
 * 5. That the balance is updated correctly
 *
 * Steps:
 * 1. Admin creates a new coin wallet
 * 2. Admin creates a valid deposit transaction (positive amount)
 * 3. Assert result and balance calculation
 * 4. Attempt to create another transaction with identical reference_id (should fail if unique constraint enforced)
 * 5. Attempt to create a transaction for a non-existent wallet (should error)
 * 6. Attempt to create a transaction with invalid (negative) amount (should error if not allowed)
 */
export async function test_api_coin_transaction_creation_success_and_conflict(connection: api.IConnection) {
