  TestValidator.equals("order id matches")(orderPayment.order_id)(customerOrder.id);
  TestValidator.equals("amount matches")(orderPayment.amount)(paymentPayload.amount);
  TestValidator.equals("payment provider matches")(orderPayment.payment_provider_id)(paymentPayload.payment_provider_id);
  TestValidator.equals("currency code matches")(orderPayment.currency_code)(paymentPayload.currency_code);
  TestValidator.equals("result matches")(orderPayment.payment_result)(paymentPayload.payment_result);
  TestValidator.equals("transaction id matches")(orderPayment.transaction_id)(paymentPayload.transaction_id);
  TestValidator.equals("payment method matches")(orderPayment.payment_method)(paymentPayload.payment_method);
  TestValidator.predicate("created_at is date-time")(typeof orderPayment.created_at === "string" && !isNaN(Date.parse(orderPayment.created_at)));
  TestValidator.predicate("updated_at is date-time")(typeof orderPayment.updated_at === "string" && !isNaN(Date.parse(orderPayment.updated_at)));
}

