import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";

/**
 * Validates successful update functionality of a product inquiry by an admin user.
 *
 * This test covers the real-world workflow in which an admin needs to update details of a customer-submitted product inquiry. Since updating an inquiry requires a valid inquiry ID, the test first creates a new product inquiry as a customer (dependency step). Using the inquiry ID from this dependency, the admin updates mutable fields to ensure permission, business logic, and schema constraints are all enforced by the API.
 *
 * Test steps:
 * 1. Create a product inquiry as a customer to establish a valid inquiry record.
 * 2. As an authenticated admin, update mutable fields (like status or body) of the created inquiry.
 * 3. Assert the update was successful by inspecting the returned inquiry record for expected changes and type validity.
 */
export async function test_api_product_inquiry_update_admin_success(connection: api.IConnection) {
  // Step 1: Create a product inquiry as a customer (dependency).
  const inquiryCreateInput: IShoppingMallAiBackendProductInquiry.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Inquiry Title for Update Test",
    body: "What is the warranty period for this product?",
    public: true,
  };
  const createdInquiry: IShoppingMallAiBackendProductInquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: inquiryCreateInput,
  });
  typia.assert(createdInquiry);

  // Step 2: Update the inquiry as admin (simulate admin privilege via connection as described).
  const updateInput: IShoppingMallAiBackendProductInquiry.IUpdate = {
    title: "[ADMIN EDITED] Inquiry Title for Update Test",
    body: "[ADMIN] The customer asked about warranty period. Please provide details.",
    public: false,
    status: "answered",
    answer_id: null,
  };
  const updatedInquiry: IShoppingMallAiBackendProductInquiry = await api.functional.shoppingMallAiBackend.admin.productInquiries.update(connection, {
    productInquiryId: createdInquiry.id,
    body: updateInput,
  });
  typia.assert(updatedInquiry);

  // Step 3: Assert the main fields have changed as expected and types are valid.
  TestValidator.equals("title updated")(updatedInquiry.title)(updateInput.title);
  TestValidator.equals("body updated")(updatedInquiry.body)(updateInput.body);
  TestValidator.equals("status updated")(updatedInquiry.status)(updateInput.status);
  TestValidator.equals("public updated")(updatedInquiry.public)(updateInput.public);
  TestValidator.equals("answer_id updated to null")(updatedInquiry.answer_id)(null);
  // Ensure the ID remains unchanged after update
  TestValidator.equals("id unchanged")(updatedInquiry.id)(createdInquiry.id);
}

