/**
 * Validate successful creation of an inquiry snapshot by the owning customer.
 *
 * This test checks the workflow for a registered customer posting a product inquiry and then creating a state snapshot for that inquiry — a critical audit/evidence operation for compliance. Ownership and audit trails must be validated.
 *
 * Steps:
 * 1. Register a customer account (customer is authenticated upon registration).
 * 2. Customer creates a new product inquiry.
 * 3. Customer posts to the inquiry snapshot endpoint, supplying all fields according to IShoppingMallAiBackendInquirySnapshot.ICreate, using the latest inquiry state and current actor.
 * 4. Validate that the returned snapshot matches the supplied data, and all core fields are preserved. Verify business invariants: snapshot links to correct inquiry, actor is the customer, and all current-state fields are present.
 */
export async function test_api_inquiry_snapshot_creation_customer_success(connection: api.IConnection) {
  // Step 1: Register customer and automatically authenticate
  const customerSignUp: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password123!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphaNumeric(8),
