  typia.assert(inquiry);
  TestValidator.equals("inquiry customer matches")(inquiry.customer_id)(customer.id);
  TestValidator.equals("inquiry product_id matches")(inquiry.product_id)(productInquiryCreate.product_id);

  // Step 3: Post inquiry snapshot
  const now = new Date().toISOString();
  const snapshotCreate: IShoppingMallAiBackendInquirySnapshot.ICreate = {
    inquiry_id: inquiry.id,
    title: inquiry.title,
    body: inquiry.body,
    public: inquiry.public,
    status: (inquiry.status as "waiting"),
    actor_id: customer.id,
    ai_sentiment_score: inquiry.ai_sentiment_score ?? null,
