  TestValidator.equals("snapshot inquiry_id")(snapshot.inquiry_id)(inquiry.id);
  TestValidator.equals("snapshot title")(snapshot.title)(inquiry.title);
  TestValidator.equals("snapshot body")(snapshot.body)(inquiry.body);
  TestValidator.equals("snapshot public flag")(snapshot.public)(inquiry.public);
  TestValidator.equals("snapshot status")(snapshot.status)(snapshotCreate.status);
  TestValidator.equals("snapshot actor_id")(snapshot.actor_id)(customer.id);
  TestValidator.equals("ai_sentiment_score")(snapshot.ai_sentiment_score ?? null)(inquiry.ai_sentiment_score ?? null);
  TestValidator.equals("ai_spam_score")(snapshot.ai_spam_score ?? null)(inquiry.ai_spam_score ?? null);
  TestValidator.equals("changed_at ISO date")(snapshot.changed_at.slice(0, 19))(now.slice(0, 19));
}

