 *
 * 1. Register Customer A
 * 2. Register Customer B
 * 3. Customer A creates a product inquiry
 * 4. Switch to Customer B (simulate JWT auth switch)
 * 5. Attempt to create an inquiry snapshot for A's inquiry as B
 * 6. Confirm error and ensure no unauthorized snapshot is created (permission denied)
 */
export async function test_api_inquiry_snapshot_creation_customer_unauthorized(
  connection: api.IConnection,
) {
  // 1. Register Customer A (captures their id and JWT)
  const customerAEmail = typia.random<string & tags.Format<"email">>();
