  const customerAId = customerARegistration.customer.id;
  // 2. Register Customer B (auth state now belongs to B)
  const customerBEmail = typia.random<string & tags.Format<"email">>();
  const customerBRegistration = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerBEmail,
      password: "1234!@#Abc",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerBRegistration);
