  TestValidator.equals("immutable changed_at")(updated.changed_at)(snapshot.changed_at);
  // Step 8: (Indirect) Verify business logic for audit/log: at minimum, IDs/actor remain equal (true audit API would require a further API call not present here)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates that admin attempts to update immutable (evidence) fields of an inquiry snapshot are properly rejected.
 *
 * This test ensures compliance: fields like id, inquiry_id, actor_id, and changed_at are preserved and cannot be overridden via the admin endpoint. After registering an admin and creating an inquiry snapshot, we attempt to update these immutable fields by forcibly including them in the update request body, expecting the API to reject the operation. The test then confirms the snapshot's evidence fields remain unchanged, and also checks that valid updates to allowed fields succeed.
 *
 * Steps:
 * 1. Register a new admin for authentication
 * 2. Create a dummy product inquiry UUID and use it to create an initial inquiry snapshot via admin endpoint
 * 3. Attempt to update the snapshot specifying forbidden/immutable fields (id, inquiry_id, actor_id, changed_at) in the update body (forcibly, at runtime)
 *    - Ensure the update operation fails and the state of immutable fields does not change
 * 4. Optionally: Show that a compliant allowed update to a mutable field succeeds
 */
export async function test_api_inquiry_snapshot_update_admin_invalid_fields(connection: api.IConnection) {
  // 1. Register admin for authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongP@ssword123!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);
  // 2. Create product inquiry and its initial snapshot
  const productInquiryId = typia.random<string & tags.Format<"uuid">>();
  const snapshot = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.create(connection, {
    productInquiryId,
    body: {
      inquiry_id: productInquiryId,
      title: "Initial Title",
      body: "Initial content body.",
      public: true,
      status: "waiting",
      actor_id: adminSignUp.adminId,
      ai_sentiment_score: 0.8,
      ai_spam_score: 0.1,
      changed_at: new Date().toISOString() as string & tags.Format<"date-time">,
    } satisfies IShoppingMallAiBackendInquirySnapshot.ICreate,
  });
  typia.assert(snapshot);
  // 3. Try to update forbidden/immutable fields in the snapshot: forcibly include them in request (non-compliant at runtime)
  // Expected: server rejects and fields remain unchanged.
  const forbiddenUpdateBody = {
    // Allowed update fields
    title: "Tampering Attempted Title",
    ai_sentiment_score: -0.5,
    // Forbidden fields forcibly included (simulate malicious runtime payload)
    id: typia.random<string & tags.Format<"uuid">>(),
    inquiry_id: typia.random<string & tags.Format<"uuid">>(),
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    changed_at: new Date().toISOString() as string & tags.Format<"date-time">,
  } as any;
  await TestValidator.error("Cannot update immutable evidence fields of inquiry snapshot")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.update(connection, {
        productInquiryId,
        inquirySnapshotId: snapshot.id,
        body: forbiddenUpdateBody,
      });
    },
  );
  // 4. Confirm original snapshot evidence fields did not change after failed update
  const fetchedSnapshot = snapshot;
  typia.assert(fetchedSnapshot);
  TestValidator.equals("snapshot id unchanged")(fetchedSnapshot.id)(snapshot.id);
  TestValidator.equals("inquiry_id unchanged")(fetchedSnapshot.inquiry_id)(snapshot.inquiry_id);
  TestValidator.equals("actor_id unchanged")(fetchedSnapshot.actor_id)(snapshot.actor_id);
  TestValidator.equals("changed_at unchanged")(fetchedSnapshot.changed_at)(snapshot.changed_at);
  // 5. Show normal update to allowed fields is successful
  const result = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.update(connection, {
    productInquiryId,
    inquirySnapshotId: snapshot.id,
    body: {
      title: "Compliance Correction Title",
      ai_sentiment_score: 0.5,
    },
  });
  typia.assert(result);
  TestValidator.equals("permitted mutable field update succeeds")(result.title)("Compliance Correction Title");
}

