import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that sellers cannot delete a product bundle belonging to another seller's product (RBAC owner enforcement).
 *
 * This test ensures the API enforces strict owner-based access to bundle deletion:
 * 1. Register Seller A.
 * 2. With Seller A's session, create a Product P.
 * 3. With Seller A's session, create a Bundle B for Product P.
 * 4. Register Seller B with a fresh session.
 * 5. Using Seller B's session, attempt to delete Bundle B from Product P.
 * 6. Validate that the operation fails with a permission/authorization error (RBAC denied).
 *
 * All test inputs are constructed using valid random values. Only provided SDKs and DTOs are used. Unable to confirm bundle existence after failed delete (no list/get API), but error-checking validates RBAC.
 */
export async function test_api_product_bundle_delete_by_seller_not_owner(
  connection: api.IConnection,
) {
  // 1. Register Seller A (bundle owner)
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerARegister = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "Password1!",
      companyName: RandomGenerator.alphaNumeric(10),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(15),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerARegister);
  const sellerAId = sellerARegister.sellerId;

  // Set connection session to Seller A
  connection.headers = {
    ...connection.headers,
    Authorization: sellerARegister.setHeaders.Authorization,
  };

  // 2. Seller A creates Product P
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 3. Seller A creates Bundle B for Product P
  const bundle = await api.functional.shoppingMallAiBackend.seller.products.productBundles.create(connection, {
    productId: product.id,
    body: {
      main_product_id: product.id,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
      bundle_policy: null,
      bundle_price: 1000,
      status: "active",
    } satisfies IShoppingMallAiBackendProductBundle.ICreate,
  });
  typia.assert(bundle);

  // 4. Register Seller B (unauthorized actor)
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBRegister = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "Password2@",
      companyName: RandomGenerator.alphaNumeric(10),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(15),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerBRegister);

  // Set connection session to Seller B
  connection.headers = {
    ...connection.headers,
    Authorization: sellerBRegister.setHeaders.Authorization,
  };

  // 5. Attempt RBAC-violating delete - should error
  await TestValidator.error("RBAC permission denied: seller B cannot delete seller A's bundle")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productBundles.erase(connection, {
        productId: product.id,
        productBundleId: bundle.id,
      });
    },
  );
}

