import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";

/**
 * Validate API behavior for deleting an already deleted or non-existent product bundle.
 *
 * This test ensures that attempting to delete a product bundle that does not exist
 * (either because it never existed or has already been deleted) results in an appropriate
 * not-found error. The test ensures the operation is idempotent and does not cause
 * side effects or succeed erroneously.
 *
 * Steps:
 * 1. Create a product to establish a valid product context for deletion.
 * 2. Generate a random UUID as a bundle ID that is guaranteed not to exist.
 * 3. Attempt to delete the bundle using the API endpoint. Assert that a not-found error is thrown.
 * 4. Repeat the delete operation to confirm idempotency and absence of side effects (error should still occur).
 */
export async function test_api_product_bundle_delete_already_deleted_not_found(
  connection: api.IConnection,
) {
  // 1. Create a product for valid product context
  const productInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.paragraph()(1),
    status: "draft",
  };
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: productInput,
  });
  typia.assert(product);

  // 2. Generate a random (non-existent) bundle UUID
  const nonexistentBundleId = typia.random<string & tags.Format<"uuid">>();

  // 3. Attempt to delete the non-existent bundle—should throw not-found error
  await TestValidator.error("not-found error when deleting non-existent product bundle")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productBundles.erase(connection, {
        productId: product.id,
        productBundleId: nonexistentBundleId,
      });
    }
  );

  // 4. Repeat operation to confirm idempotency
  await TestValidator.error("delete operation is idempotent and remains not-found")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productBundles.erase(connection, {
        productId: product.id,
        productBundleId: nonexistentBundleId,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductContent";
import type { IPageIShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductContent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate successful paginated and filtered search of product content records by an authenticated seller for their product.
 *
 * This test ensures that, after registering as a seller and creating a new product, if the seller adds multiple content records (such as images and documents) to the product, a paginated and filtered search by `content_type` and `status` will only return their own product's data, and the result's pagination and filtering is correct.
 *
 * Steps:
 * 1. Register a new seller account with unique random business/company information
 * 2. Create a new product under the seller's identity
 * 3. Add multiple content records of different `content_type` (e.g., main_image, gallery_image, document) and different `status` (e.g., active, hidden) to the product
 * 4. Perform a PATCH search on productContents for the created product, filtering by a specific `content_type` (e.g., gallery_image) and `status` (e.g., active), with a pagination limit smaller than the total records
 * 5. Assert all returned content records match both `content_type` and `status` filters, and their product_id equals the product created
 * 6. Assert the total count and pagination metadata reflect the true number of filtered results, and no content from other products is included
 */
export async function test_api_product_content_search_by_seller_success(connection: api.IConnection) {
  // 1. Register a new seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "testpassword123!",
      companyName: RandomGenerator.name(),
      businessNumber: "8888888888",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUp);
  // JWT is set in connection.headers automatically

  // 2. Create a product owned by this seller
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerSignUp.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(3),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 3. Add content items (multi content_type, statuses)
  const contentRecords: IShoppingMallAiBackendProductContent[] = [];
  const contentItems = [
    { content_type: "main_image", status: "active" },
    { content_type: "main_image", status: "hidden" },
    { content_type: "gallery_image", status: "active" },
    { content_type: "gallery_image", status: "active" },
    { content_type: "document", status: "hidden" },
    { content_type: "document", status: "active" },
  ];
  for (let i = 0; i < contentItems.length; ++i) {
    const info = contentItems[i];
    const created = await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        content_type: info.content_type,
        content_uri: `https://cdn.example.com/random/${RandomGenerator.alphaNumeric(10)}`,
        content_order: i + 1,
        content_description: RandomGenerator.paragraph()(),
        status: info.status,
      } satisfies IShoppingMallAiBackendProductContent.ICreate,
    });
    typia.assert(created);
    contentRecords.push(created);
  }

  // Pick filter: gallery_image & active, limit=1, page=1
  const filterType = "gallery_image";
  const filterStatus = "active";
  const page = 1;
  const limit = 1;
  const result = await api.functional.shoppingMallAiBackend.seller.products.productContents.search(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      content_type: filterType,
      status: filterStatus,
      page,
      limit,
      order_by: "content_order",
      order_direction: "asc",
    } satisfies IShoppingMallAiBackendProductContent.IRequest,
  });
  typia.assert(result);
  // 5. Assert all records are correct
  TestValidator.predicate("all contents belong to product and match filter")(result.data.every(r => r.product_id === product.id && r.content_type === filterType && r.status === filterStatus));
  // 6. Assert pagination and count
  const totalExpected = contentRecords.filter(c => c.content_type === filterType && c.status === filterStatus).length;
  TestValidator.equals("total filtered count")(result.pagination.records)(totalExpected);
  TestValidator.equals("paginated output length")(result.data.length)(Math.min(limit, totalExpected));
  TestValidator.equals("page number")(result.pagination.current)(page);
  TestValidator.equals("limit per page")(result.pagination.limit)(limit);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductContent";
import type { IPageIShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductContent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that a seller cannot search the contents for products they do not own (permission denied test).
 *
 * This test verifies the API's strict ownership and permission enforcement by ensuring that Seller B cannot access or search content for a product owned by Seller A. The expected outcome is a permission denied error, proving that the API blocks unauthorized cross-seller access.
 *
 * Steps:
 * 1. Register Seller A (owner of the product).
 * 2. Register Seller B (will attempt unauthorized access).
 * 3. Seller A creates a product.
 * 4. Switch to Seller B context (by registering/logging in).
 * 5. Seller B attempts to search product content for the product owned by Seller A using the PATCH /shoppingMallAiBackend/seller/products/{productId}/productContents endpoint.
 * 6. Assert that a permission denied error (authorization error) is returned.
 */
export async function test_api_product_content_search_seller_permission_denied(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerARegistration = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "StrongPass!123",
      companyName: RandomGenerator.name(),
      businessNumber: "1101234567",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(sellerARegistration);

  // 2. Register Seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBRegistration = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "StrongPass!456",
      companyName: RandomGenerator.name(),
      businessNumber: "1109876543",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(sellerBRegistration);

  // 3. Seller A creates a product
  // Set connection back to Seller A (using A's JWT from registration)
  connection.headers = {
    ...connection.headers,
    Authorization: sellerARegistration.setHeaders.Authorization,
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerARegistration.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.content()()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 4. Switch to Seller B context
  connection.headers = {
    ...connection.headers,
    Authorization: sellerBRegistration.setHeaders.Authorization,
  };

  // 5. Seller B attempts to search contents for Seller A's product
  // Expect an authorization/permission denied error
  await TestValidator.error("Permission denied when seller B searches contents of seller A's product")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productContents.search(connection, {
        productId: product.id,
        body: {} satisfies IShoppingMallAiBackendProductContent.IRequest
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductContent";
import type { IPageIShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductContent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that an admin user can search and paginate all content records attached to any product, irrespective of seller or content type.
 *
 * This scenario ensures admin can:
 * 1. Create a new product as a prerequisite
 * 2. Attach multiple diverse content items (images, videos, etc) to that product
 * 3. Perform searches for all product contents with no filters
 * 4. Perform filtered search (by content_type)
 * 5. Paginate content search results and verify correctness
 * 6. Optionally test sorting and verify result order
 *
 * Each step validates API response, filter matching, and pagination structure, ensuring all contents are visible and correctly structured for admin access.
 */
export async function test_api_product_content_search_by_admin_success(
  connection: api.IConnection,
) {
  // Step 1: Create a new product with required fields
  const sellerId: string = typia.random<string & tags.Format<"uuid">>();
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(
    connection,
    {
      body: {
        seller_id: sellerId,
        code: `SKU-${typia.random<string>()}`,
        name: `Product ${typia.random<string>()}`,
        status: "published",
        // Optionally add description/main_image_uri
      } satisfies IShoppingMallAiBackendProduct.ICreate,
    },
  );
  typia.assert(product);

  // Step 2: Create multiple content items of varied types
  const contentTypes = ["main_image", "gallery_image", "video"];
  const productContents: IShoppingMallAiBackendProductContent[] = [];
  for (let i = 0; i < contentTypes.length; ++i) {
    const content = await api.functional.shoppingMallAiBackend.admin.products.productContents.create(
      connection,
      {
        productId: product.id,
        body: {
          product_id: product.id,
          content_type: contentTypes[i],
          content_uri: `https://cdn.example.com/content/${typia.random<string>()}`,
          content_order: i + 1,
          // Description for just one content to test text filter if needed
          content_description: i === 1 ? `Special description for gallery_image` : null,
          status: "active",
        } satisfies IShoppingMallAiBackendProductContent.ICreate,
      },
    );
    typia.assert(content);
    productContents.push(content);
  }

  // Step 3: Search all contents - no filters: expect all records
  const searchAll = await api.functional.shoppingMallAiBackend.admin.products.productContents.search(
    connection,
    {
      productId: product.id,
      body: {}, // No filter: should list all content for product
    },
  );
  typia.assert(searchAll);
  // Assert total equals number of inserted contents
  TestValidator.equals("all contents present")(searchAll.data.length)(productContents.length);
  // IDs must match
  const allIds = productContents.map((c) => c.id).sort();
  const resultIds = searchAll.data.map((c) => c.id).sort();
  TestValidator.equals("returned ids match inserted")(resultIds)(allIds);
  // Pagination: total records and page info
  TestValidator.equals("pagination.records matches")(searchAll.pagination.records)(productContents.length);
  TestValidator.equals("pagination.pages matches")(searchAll.pagination.pages)(1);
  TestValidator.equals("page.current is 1")(searchAll.pagination.current)(1);

  // Step 4: Search by content_type (e.g. "gallery_image")
  const searchGallery = await api.functional.shoppingMallAiBackend.admin.products.productContents.search(
    connection,
    {
      productId: product.id,
      body: {
        content_type: "gallery_image",
      },
    },
  );
  typia.assert(searchGallery);
  // Should find only 1 (the created gallery_image)
  TestValidator.equals("gallery_image only")(searchGallery.data.length)(1);
  TestValidator.equals("gallery_image content_type")(searchGallery.data[0].content_type)("gallery_image");
  // Pagination for match
  TestValidator.equals("pagination.records matches gallery")(searchGallery.pagination.records)(1);

  // Step 5: Paginated search: limit=2, page=2
  const searchPaginated = await api.functional.shoppingMallAiBackend.admin.products.productContents.search(
    connection,
    {
      productId: product.id,
      body: {
        limit: 2,
        page: 2,
        order_by: "content_order",
        order_direction: "asc",
      },
    },
  );
  typia.assert(searchPaginated);
  // Confirm current page info
  TestValidator.equals("paginated: page")(searchPaginated.pagination.current)(2);
  // Confirm correct slice: get the productContents sorted by content_order,
  // take items [2] (zero-indexed: items 2 and onwards for page 2, limit 2 per page)
  const sorted = productContents
    .slice()
    .sort((a, b) => a.content_order - b.content_order);
  const expectedPage2 = sorted.slice(2, 4);
  const returnedIds = searchPaginated.data.map((c) => c.id).sort();
  const expectedIds = expectedPage2.map((c) => c.id).sort();
  TestValidator.equals("ids for page 2")(returnedIds)(expectedIds);
  // Pagination total
  TestValidator.equals("records matches")(searchPaginated.pagination.records)(productContents.length);
  // Should be 2 pages with 3 items and limit=2
  TestValidator.equals("pagination.pages is 2")(searchPaginated.pagination.pages)(2);
  // Step 6: (Optional) Sorting test already covered in page 2: order_by asc
}

