/**
 * Validate the system response when an admin attempts to search product contents with invalid filter criteria.
 *
 * This test ensures that invalid search/filter requests (such as unsupported content types, negative or excessively large pagination parameters) are strictly validated. The API should reject such requests with a clear validation error (not perform the search) and must return structured error information.
 *
 * Workflow:
 * 1. Create a dummy product (dependency: required to have a valid productId to test searching its contents).
 * 2. Attempt productContents search with invalid filter object(s):
 *    a. Use an unsupported content_type (e.g., a value not expected by the system business logic).
 *    b. Use an invalid page number (e.g., zero or negative, or excessively large).
 *    c. Use an excessively large limit value (e.g., 10^9), if limited by business logic.
 * 3. Verify that each invalid request fails and that the backend API returns an error (likely a 400 or 422), with a structured, type-safe error response (never a success with empty/partial data).
 * 4. (Success fallback) If any of these invalid requests result in a successful, non-error response, the test must fail.
 */
export async function test_api_product_content_search_with_invalid_filter(
  connection: api.IConnection,
) {
  // 1. Create a dummy product needed to test product content search (dependency)
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(
    connection,
    {
      body: {
        seller_id: typia.random<string & tags.Format<"uuid">>(),
        code: `SKU-${typia.random<string>()}`,
        name: RandomGenerator.paragraph()(2),
        status: "draft",
        description: null,
        main_image_uri: null,
      } satisfies IShoppingMallAiBackendProduct.ICreate,
    },
  );
  typia.assert(product);

  // 2a. Attempt filter with an unsupported content_type
  await TestValidator.error("unsupported content_type should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productContents.search(
        connection,
        {
          productId: product.id,
          body: {
            content_type: "invalid_content_type",
          },
        },
      );
    },
  );

  // 2b. Attempt with an invalid page (zero or negative)
  await TestValidator.error("negative page number should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productContents.search(
        connection,
        {
          productId: product.id,
          body: {
            page: -1 as number & tags.Type<"int32">,
          },
        },
      );
    },
  );

  // 2c. Attempt with excessive limit
  await TestValidator.error("excessively large limit should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productContents.search(
        connection,
        {
          productId: product.id,
          body: {
            limit: 1000000000 as number & tags.Type<"int32">,
          },
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
