import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPayment";
import type { IShoppingMallAiBackendOrderPaymentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPaymentLog";
import type { IPageIShoppingMallAiBackendOrderPaymentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderPaymentLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * End-to-end test for searching order payment logs as a customer
 *
 * This test verifies:
 * - A customer can search payment log records tied to their own order/payment with various filters (log type, date range, paging, etc.)
 * - Filtering by log_type, occurred_at date ranges, and basic paging (page/limit) works as expected
 * - The result set and pagination meta are correct
 * - Logs not matching filter are not present in the result
 * - Unmatched filter returns empty set and pagination is consistent
 * - Malformed filter/pagination input is handled gracefully
 * - Unauthorized access to another customer’s logs is denied
 *
 * The flow involves:
 * 1. Create an order (as a customer)
 * 2. Create a payment on the order
 * 3. Add several payment log entries for the payment (with various log_type, dates, and log_context/keywords)
 * 4. Exercise search with:
 *    a. no filters (should return all logs)
 *    b. filter by log_type (returns only matching types)
 *    c. filter by occurred_at_from/to (date ranges)
 *    d. filter with page/limit for pagination
 *    e. filter by impossible values (empty result)
 *    f. malformed page/limit (invalid: zero, negative, over max) - test for error/handling
 * 5. Attempt search as a different customer (should get forbidden error)
 *
 * Assertions:
 * - Each search result’s data matches expected logs and respects filter
 * - Pagination meta matches the expected record count and page count
 * - Forbidden error when searching someone else’s order/payment logs
 * - 0 results returned for impossible filters (no data, correct paging)
 * - System responds gracefully to malformed pagination/filter (error thrown)
 */
export async function test_api_order_payment_log_search_with_filtering_as_customer(
  connection: api.IConnection,
) {
  // 1. Create first customer and their order
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id,
      order_number: `ORD-${RandomGenerator.alphaNumeric(8)}`,
      total_amount: 10000,
      currency_code: "KRW",
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(order);

  // 2. Create payment for the order
  const payment_provider_id = typia.random<string & tags.Format<"uuid">>();
  const orderPayment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_provider_id,
      payment_method: "card",
      transaction_id: `TXN-${RandomGenerator.alphaNumeric(10)}`,
      amount: 10000,
      currency_code: "KRW",
      payment_result: "completed",
    } satisfies IShoppingMallAiBackendOrderPayment.ICreate,
  });
  typia.assert(orderPayment);

  // 3. Insert multiple log entries (different types, dates, context)
  const logs = await ArrayUtil.asyncRepeat(5)(async (i) => {
    const log_types = ["request", "response", "error", "event"];
    const type = RandomGenerator.pick(log_types);
    const logDate = new Date(Date.now() - i * 1000 * 60 * 60).toISOString();
    const log = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.create(connection, {
      orderId: order.id,
      orderPaymentId: orderPayment.id,
      body: {
        log_type: type,
        log_context: `Context ${i} - ${RandomGenerator.paragraph()()}`,
        occurred_at: logDate,
      } satisfies IShoppingMallAiBackendOrderPaymentLog.ICreate,
    });
    typia.assert(log);
    return log;
  });

  // 4. Search all logs without filter
  const searchAll = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: orderPayment.id,
    body: {
      order_payment_id: orderPayment.id,
    } satisfies IShoppingMallAiBackendOrderPaymentLog.IRequest,
  });
  typia.assert(searchAll);
  TestValidator.equals("all logs present")(searchAll.pagination.records)(logs.length);

  // 5. Search by log_type, should return only the correct type
  const typeToTest = logs[0].log_type;
  const searchType = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: orderPayment.id,
    body: {
      order_payment_id: orderPayment.id,
      log_type: typeToTest,
    },
  });
  typia.assert(searchType);
  TestValidator.predicate("all logs log_type matches")(searchType.data.every(l => l.log_type === typeToTest));

  // 6. Search with occurred_at_from/occurred_at_to (date window)
  // Pick dates around the 3rd log
  const fromDate = logs[3].occurred_at;
  const toDate = logs[1].occurred_at;
  const searchByDate = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: orderPayment.id,
    body: {
      order_payment_id: orderPayment.id,
      occurred_at_from: fromDate,
      occurred_at_to: toDate,
    },
  });
  typia.assert(searchByDate);
  TestValidator.predicate("logs within date window")(searchByDate.data.every(l => l.occurred_at >= fromDate && l.occurred_at <= toDate));

  // 7. Search with pagination (page=1, limit=2)
  const paged = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: orderPayment.id,
    body: {
      order_payment_id: orderPayment.id,
      page: 1,
      limit: 2,
    },
  });
  typia.assert(paged);
  TestValidator.equals("paged result length")(paged.data.length)(2);
  TestValidator.predicate("pagination meta: correct total records")(paged.pagination.records === logs.length);

  // 8. Search for impossible log_type value, expect 0 results
  const impossible = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: orderPayment.id,
    body: {
      order_payment_id: orderPayment.id,
      log_type: "nonexistent_type",
    },
  });
  typia.assert(impossible);
  TestValidator.equals("no data for impossible filter")(impossible.data.length)(0);

  // 9. Malformed page/limit (page=0, limit=201) (should throw error)
  await TestValidator.error("invalid pagination throws error")(async () => {
    await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
      orderId: order.id,
      orderPaymentId: orderPayment.id,
      body: {
        order_payment_id: orderPayment.id,
        page: 0,             // invalid (should fail)
        limit: 201,          // invalid (max=200)
      },
    });
  });

  // 10. Attempt to search as another customer (simulate by using a different random UUID)
  const otherCustomerOrder = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      order_number: `ORD-${RandomGenerator.alphaNumeric(8)}`,
      total_amount: 5000,
      currency_code: "KRW",
      current_status: "created",
    },
  });
  const otherOrderPayment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId: otherCustomerOrder.id,
    body: {
      order_id: otherCustomerOrder.id,
      payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
      payment_method: "bank_transfer",
      transaction_id: `TXN-${RandomGenerator.alphaNumeric(10)}`,
      amount: 5000,
      currency_code: "KRW",
      payment_result: "completed",
    },
  });
  await TestValidator.error("forbidden to search another customer's logs")(async () => {
    await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
      orderId: otherCustomerOrder.id,
      orderPaymentId: otherOrderPayment.id,
      body: {
        order_payment_id: otherOrderPayment.id,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IPageIShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrder";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPayment";
import type { IShoppingMallAiBackendOrderPaymentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPaymentLog";
import type { IPageIShoppingMallAiBackendOrderPaymentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderPaymentLog";

/**
 * Validate advanced payment log searching for an order payment as an admin.
 *
 * This test verifies that an admin can search, filter, and paginate payment log records for any order payment in the system—regardless of ownership. It applies various filters (log_type, date range, pagination), checks that logs with sensitive or error details are visible to admins as business policy allows, confirms correct response structure, and ensures error handling is proper for invalid access.
 *
 * Steps:
 * 1. Search for an order visible to admin (any order suffices)
 * 2. Create a payment for that order as admin
 * 3. Insert diverse payment logs (types: request, response, error)
 * 4. Search logs
 *    a. Unfiltered (all logs)
 *    b. By log_type
 *    c. By occurred_at date-range
 *    d. By pagination
 * 5. Confirm log content and pagination correctness
 * 6. Validate sensitive/error content is present for admins
 * 7. Test error handling for invalid payment id
 */
export async function test_api_order_payment_log_search_as_admin_with_advanced_filters(
  connection: api.IConnection,
) {
  // 1. Search for any order (admin has global access)
  const orderSearch = await api.functional.shoppingMallAiBackend.admin.orders.search(connection, {
    body: {
      page: 1,
      pageSize: 1,
      sort: '-created_at',
    },
  });
  typia.assert(orderSearch);
  TestValidator.predicate('admin can see at least one order')(orderSearch.data.length > 0);
  const order = orderSearch.data[0];

  // 2. Create payment for the found order
  const payment = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_provider_id: typia.random<string & tags.Format<'uuid'>>(),
      payment_method: 'card',
      transaction_id: `TXN-${Date.now()}`,
      amount: 10000,
      currency_code: order.currency_code,
      payment_result: 'completed',
      payment_context: '{"meta":"test"}',
    },
  });
  typia.assert(payment);

  // 3. Insert three logs (types: request, response, error)
  const now = new Date();
  const logs = await Promise.all([
    api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.create(connection, {
      orderId: order.id,
      orderPaymentId: payment.id,
      body: {
        log_type: 'request',
        log_context: '{"request":"initiated"}',
        occurred_at: new Date(now.getTime() - 1000 * 60 * 10).toISOString(),
      },
    }),
    api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.create(connection, {
      orderId: order.id,
      orderPaymentId: payment.id,
      body: {
        log_type: 'response',
        log_context: '{"response":"ok"}',
        occurred_at: now.toISOString(),
      },
    }),
    api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.create(connection, {
      orderId: order.id,
      orderPaymentId: payment.id,
      body: {
        log_type: 'error',
        log_context: '{"error":"card_declined","details":{"stack":"err_stack_here"}}',
        occurred_at: new Date(now.getTime() + 1000 * 60 * 10).toISOString(),
      },
    }),
  ]);
  logs.forEach(log => typia.assert(log));

  // 4a. Search all logs (no filter)
  const resultAll = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      order_payment_id: payment.id,
    },
  });
  typia.assert(resultAll);
  TestValidator.equals('should return all logs')(resultAll.data.length)(3);

  // 4b. Search by log type (error)
  const resultErrorType = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      order_payment_id: payment.id,
      log_type: 'error',
    },
  });
  typia.assert(resultErrorType);
  TestValidator.equals('should return only error logs')(resultErrorType.data.length)(1);
  TestValidator.equals('error log type matches')(resultErrorType.data[0].log_type)('error');

  // 4c. Filter by occurred_at range (should catch at least 2 logs)
  const resultRange = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      order_payment_id: payment.id,
      occurred_at_from: new Date(now.getTime() - 1000 * 60 * 5).toISOString(),
      occurred_at_to: new Date(now.getTime() + 1000 * 60 * 15).toISOString(),
    },
  });
  typia.assert(resultRange);
  TestValidator.predicate('time range filter works')(resultRange.data.length >= 2);

  // 4d. Pagination: limit 2, page 1
  const paginated = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      order_payment_id: payment.id,
      page: 1,
      limit: 2,
    },
  });
  typia.assert(paginated);
  TestValidator.equals('pagination limit')(paginated.data.length)(2);
  TestValidator.equals('pagination page')(paginated.pagination.current)(1);
  TestValidator.equals('pagination size')(paginated.pagination.limit)(2);

  // 5. Confirm error log's sensitive details are visible
  const errorLog = resultErrorType.data[0];
  TestValidator.predicate('admin sees error stack in log_context')(
    typeof errorLog.log_context === 'string' && errorLog.log_context.includes('stack'),
  );

  // 6. Test error handling: search with invalid orderPaymentId
  await TestValidator.error('invalid payment id triggers error')(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.search(connection, {
        orderId: order.id,
        orderPaymentId: typia.random<string & tags.Format<'uuid'>>(),
        body: {
          order_payment_id: typia.random<string & tags.Format<'uuid'>>(),
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPayment";
import type { IShoppingMallAiBackendOrderPaymentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPaymentLog";

/**
 * Validate retrieval of payment log details for a customer order and enforce correct access/error handling.
 *
 * This test ensures that a customer can fetch detailed information about a specific payment log entry they own, and verifies all log metadata (type, context, timestamps, etc) are returned as per schema. It also verifies access denial for non-existent IDs. (Testing cross-customer denial is omitted as user context switching/auth is not available in this SDK.)
 *
 * Steps:
 * 1. Create a customer order (as customer A).
 * 2. Create a payment for that order (as customer A).
 * 3. Create a payment log for that payment (as customer A).
 * 4. Retrieve the payment log detail and validate all fields.
 * 5. Attempt to fetch a non-existent payment log and verify rejection.
 *
 * NOTE: Access control via different customers is commented, as SDK does not provide dynamic auth switching.
 */
export async function test_api_order_payment_log_detail_as_customer(connection: api.IConnection) {
  // 1. Create a new order as customer A
  const customerIdA = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerIdA,
      order_number: RandomGenerator.alphaNumeric(14),
      total_amount: 120000,
      currency_code: "KRW",
      current_status: "created"
    } satisfies IShoppingMallAiBackendOrder.ICreate
  });
  typia.assert(order);

  // 2. Create an order payment for the order
  const payment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
      payment_method: "card",
      transaction_id: RandomGenerator.alphaNumeric(18),
      amount: order.total_amount,
      currency_code: order.currency_code,
      payment_result: "completed"
    } satisfies IShoppingMallAiBackendOrderPayment.ICreate
  });
  typia.assert(payment);

  // 3. Create a payment log entry for this payment
  const log = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.create(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      log_type: "request",
      log_context: JSON.stringify({ action: "createPayment", status: "initiated" }),
      occurred_at: new Date().toISOString()
    } satisfies IShoppingMallAiBackendOrderPaymentLog.ICreate
  });
  typia.assert(log);

  // 4. Retrieve the payment log detail for customer A
  const detail = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.at(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    orderPaymentLogId: log.id
  });
  typia.assert(detail);
  TestValidator.equals("log id matches")(detail.id)(log.id);
  TestValidator.equals("order payment id matches")(detail.order_payment_id)(payment.id);
  TestValidator.equals("log_type matches")(detail.log_type)(log.log_type);
  TestValidator.equals("log_context matches")(detail.log_context)(log.log_context);
  TestValidator.equals("occurred_at matches")(detail.occurred_at)(log.occurred_at);

  // 5. Try fetching with a fake/non-existent payment log id and expect error
  let fakeLogId = typia.random<string & tags.Format<"uuid">>();
  // Ensure we do NOT use the same value as the real log id
