/**
 * Validate admin access to a single order payment log entry and response correctness.
 *
 * Scenario:
 * 1. As an admin, search for an existing order using admin search (PATCH /shoppingMallAiBackend/admin/orders).
 * 2. Create a payment associated with that order (POST /shoppingMallAiBackend/admin/orders/{orderId}/orderPayments).
 * 3. Generate a payment log entry targeting that payment (POST /shoppingMallAiBackend/admin/orders/{orderId}/orderPayments/{orderPaymentId}/orderPaymentLogs).
 * 4. Retrieve the created payment log's details (GET /shoppingMallAiBackend/admin/orders/{orderId}/orderPayments/{orderPaymentId}/orderPaymentLogs/{orderPaymentLogId}).
 * 5. Confirm all fields (id, order_payment_id, log_type, log_context, occurred_at) are present and match (type/format/content).
 * 6. Test business logic with different log types (e.g., 'request', 'response', 'error').
 * 7. Attempt to fetch with invalid/nonexistent log IDs to verify proper error handling (e.g., 404 or business error).
 *
 * This test validates permission, correctness, field presence, audit completeness, and error boundaries for admin-accessed payment log detail view.
 */
export async function test_api_order_payment_log_detail_access_as_admin(
  connection: api.IConnection,
) {
  // 1. Search for an order via admin search (to get a real admin-manageable orderId)
  const orderPage = await api.functional.shoppingMallAiBackend.admin.orders.search(connection, {
    body: {
      page: 1,
      pageSize: 1,
      sort: "-created_at"
    }
  });
  typia.assert(orderPage);
  if (!orderPage.data.length) throw new Error("No admin-manageable order found for test");
  const { id: orderId } = orderPage.data[0];

  // 2. Create a new payment linked to the order
  const paymentInput = {
    order_id: orderId,
    payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
    payment_method: "card",
    transaction_id: `TXN-${Date.now()}`,
    amount: 12345.67,
    currency_code: "KRW",
    payment_result: "pending",
    payment_context: JSON.stringify({ initial: true }),
  } satisfies IShoppingMallAiBackendOrderPayment.ICreate;
  const payment = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.create(connection, {
    orderId,
    body: paymentInput
  });
  typia.assert(payment);

  // 3. Create a payment log for that payment
  const paymentLogInputRequest = {
    log_type: "request",
    log_context: JSON.stringify({ request: true }),
    occurred_at: new Date().toISOString(),
  } satisfies IShoppingMallAiBackendOrderPaymentLog.ICreate;
  const paymentLog = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.create(connection, {
    orderId,
    orderPaymentId: payment.id,
    body: paymentLogInputRequest
  });
  typia.assert(paymentLog);

  // 4. Retrieve the created payment log entry with admin-permission
  const fetchedLog = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.at(connection, {
    orderId,
    orderPaymentId: payment.id,
    orderPaymentLogId: paymentLog.id
  });
  typia.assert(fetchedLog);
  // Confirm that all fields are present and as expected
  TestValidator.equals("order_payment_id matches")(fetchedLog.order_payment_id)(payment.id);
  TestValidator.equals("log_type matches")(fetchedLog.log_type)(paymentLogInputRequest.log_type);
  TestValidator.equals("log_context matches")(fetchedLog.log_context)(paymentLogInputRequest.log_context);
  TestValidator.equals("occurred_at matches")(fetchedLog.occurred_at)(paymentLogInputRequest.occurred_at);

  // 5. Test a different log type ('error')
  const paymentLogInputError = {
    log_type: "error",
    log_context: JSON.stringify({ error: "Sample error context" }),
    occurred_at: new Date().toISOString(),
  } satisfies IShoppingMallAiBackendOrderPaymentLog.ICreate;
  const errorLog = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.create(connection, {
    orderId,
    orderPaymentId: payment.id,
    body: paymentLogInputError
  });
  typia.assert(errorLog);
  const errorFetchedLog = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.at(connection, {
    orderId,
    orderPaymentId: payment.id,
    orderPaymentLogId: errorLog.id
  });
  typia.assert(errorFetchedLog);
  TestValidator.equals("log_type error")(errorFetchedLog.log_type)("error");
  TestValidator.equals("log_context error")(errorFetchedLog.log_context)(paymentLogInputError.log_context);

  // 6. Try to fetch a log entry with non-existent IDs (should result in an error)
  await TestValidator.error("not found for invalid log ID")(() =>
    api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.at(connection, {
      orderId,
      orderPaymentId: payment.id,
      orderPaymentLogId: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

