    password: "P@ssw0rd!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphaNumeric(12),
    phone: RandomGenerator.mobile(),
  } satisfies ICustomerSignUp.Request;
  const signUpResponse = await api.functional.auth.customer.register.signUp(connection, { body: signUpRequest });
