  // 4. Customer creates an order for the product
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 10000,
      currency_code: "KRW",
      current_status: "created",
    },
  });
  typia.assert(order);

  // 5. Customer writes a review for order (simulate order_item_id)
  // As the order_item_id is required but not given by the order entity, provide a random uuid for testing
  const orderItemId = typia.random<string & tags.Format<"uuid">>();
  const review = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: product.id,
      order_item_id: orderItemId,
