  // 7. Assert snapshot properties
  TestValidator.equals("linked to review")(snapshot.review_id)(review.id);
  TestValidator.equals("snapshot body")(snapshot.body)(review.body);
  TestValidator.equals("snapshot rating")(snapshot.rating)(review.rating);
  TestValidator.equals("snapshot status")(snapshot.status)(review.status);
  TestValidator.equals("actor is seller")(snapshot.actor_id)(sellerId);
}

