/**
 * Validate admin update and access control for order group management.
 *
 * This test simulates realistic order group update scenarios for the admin API:
 *
 * 1. Register as admin (prerequisite for permissions)
 * 2. Create an initial order group (data setup)
 * 3. Update the order group with valid new data (group_name, external_reference, meta_info)
 * 4. Validate persistence (assert changed fields and updated_at)
 * 5. Attempt to update with invalid data (empty group_name)
 * 6. Attempt to update a non-existent group
 * 7. Test uniqueness by creating another group and attempting duplicate group_name
 *
 * Not testable: Non-admin permissions (no endpoint for non-admin), audit trail beyond updated_at, and soft-delete update (no API for soft-delete or fetch deleted).
 */
export async function test_api_order_group_admin_update_success_invalid(connection: api.IConnection) {
  // 1. Register an admin for API authentication and permissions
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SecurePass123!@#";
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  typia.assert(admin);

  // 2. Create initial order group (prerequisite for update)
  const createInput = {
    group_name: "Initial Batch Group",
    external_reference: "REF-123",
    meta_info: JSON.stringify({ source: "unit-test", note: "initial creation" }),
  } satisfies IShoppingMallAiBackendOrderGroup.ICreate;
  const createdOrderGroup = await api.functional.shoppingMallAiBackend.admin.orderGroups.create(connection, {
    body: createInput,
  });
  typia.assert(createdOrderGroup);

  // 3. Update order group with valid data
  const validUpdate = {
    group_name: "Updated Batch Group",
    external_reference: "REF-456",
    meta_info: JSON.stringify({ updated: true }),
  } satisfies IShoppingMallAiBackendOrderGroup.IUpdate;
  const updatedOrderGroup = await api.functional.shoppingMallAiBackend.admin.orderGroups.update(connection, {
    orderGroupId: createdOrderGroup.id,
    body: validUpdate,
  });
  typia.assert(updatedOrderGroup);
  TestValidator.equals("group_name updated")(updatedOrderGroup.group_name)(validUpdate.group_name);
  TestValidator.equals("external_reference updated")(updatedOrderGroup.external_reference)(validUpdate.external_reference);
  TestValidator.equals("meta_info updated")(updatedOrderGroup.meta_info)(validUpdate.meta_info);
  TestValidator.predicate("updated_at timestamp changed")(updatedOrderGroup.updated_at !== createdOrderGroup.updated_at);

  // 4. Partial update (no fields) - should not reset values, just assert id is stable
  const refresh = await api.functional.shoppingMallAiBackend.admin.orderGroups.update(connection, {
    orderGroupId: createdOrderGroup.id,
    body: {},
  });
  typia.assert(refresh);
  TestValidator.equals("id unchanged")(refresh.id)(createdOrderGroup.id);

  // 5. Update with invalid data: empty group_name
  await TestValidator.error("cannot update to empty group_name")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orderGroups.update(connection, {
        orderGroupId: createdOrderGroup.id,
        body: { group_name: "" },
      });
    },
  );

  // 6. Update a non-existent group
  await TestValidator.error("updating non-existent group should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orderGroups.update(connection, {
        orderGroupId: typia.random<string & tags.Format<"uuid">>(),
        body: { group_name: "NewGroupNonExistent" },
      });
    },
  );

  // 7. Create a second group for duplicate name uniqueness test
  const secondGroup = await api.functional.shoppingMallAiBackend.admin.orderGroups.create(connection, {
    body: {
      group_name: "UniqueGroupName",
      external_reference: "REF-789",
      meta_info: null,
    } satisfies IShoppingMallAiBackendOrderGroup.ICreate,
  });
  typia.assert(secondGroup);

  await TestValidator.error("should fail due to duplicate group_name")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orderGroups.update(connection, {
        orderGroupId: createdOrderGroup.id,
        body: { group_name: secondGroup.group_name },
      });
    },
  );
}

