      await api.functional.shoppingMallAiBackend.seller.orders.orderStatusHistories.search(connection, {
        orderId: nonSellerOrder.id,
        body: {
          order_id: nonSellerOrder.id,
          page: 1,
          limit: 1,
        } satisfies IShoppingMallAiBackendOrderStatusHistory.IRequest,
      });
    }
  );
