/**
 * Test admin update of a seller's business verification record, covering both compliance and error-handling cases.
 *
 * This test validates that admin users can perform allowed updates—such as marking as reviewed, editing admin notes, or updating the document URI/status—on a seller's business verification record. It ensures update timestamps and audit trails are refreshed on change, and that the API logs the change as intended. It also confirms that the endpoint correctly throws errors for non-existent records and for attempts to update records in a finalized/compliance-locked state.
 *
 * Steps:
 * 1. Authenticate as admin using valid credentials.
 * 2. Setup: Create or update an initial seller business verification record (simulate as PUT as per available endpoints).
 * 3. Perform multiple compliant update attempts:
 *    a. Mark as reviewed (setting reviewed_by and reviewed_at).
 *    b. Add/update an admin/business note field.
 *    c. Update the document_file_uri and verification_status.
 * 4. After each update, verify that output reflects the changes, and that updated_at is refreshed; also validate presence/consistency of audit/log fields if present.
 * 5. Attempt to update a non-existent seller verification (random UUID).
 * 6. Attempt to update a record simulating a finalized/compliance-locked state.
 * 7. Ensure that appropriate error is thrown per business logic in 5 and 6.
 */
export async function test_api_admin_update_seller_business_verification_compliance_and_error_cases(connection: api.IConnection) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = "StrongPassword123!";
  // Assume that admin exists in system; otherwise, pre-provision or set in env.
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);

  // 2. Setup: Create an initial seller business verification record. For this test, we'll create an initial state using PUT (idempotent update).
  const sellerId = typia.random<string & tags.Format<'uuid'>>();
  const verificationId = typia.random<string & tags.Format<'uuid'>>();
  const initialStatus = "pending";
  const initialVerification = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: verificationId,
      verification_status: initialStatus,
      note: "Initial business verification for E2E test.",
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate,
  });
  typia.assert(initialVerification);

  // 3a. Mark as reviewed (set reviewed_by and reviewed_at)
  const reviewedAt = new Date().toISOString();
  const reviewedVerification = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: verificationId,
      reviewed_by: adminAuth.name,
      reviewed_at: reviewedAt,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate,
  });
  typia.assert(reviewedVerification);
  TestValidator.equals("reviewed_by field updated")(reviewedVerification.reviewed_by)(adminAuth.name);
  TestValidator.equals("reviewed_at field updated")(reviewedVerification.reviewed_at)(reviewedAt);
  TestValidator.predicate("updated_at should be refreshed after review")(reviewedVerification.updated_at !== initialVerification.updated_at);

  // 3b. Add/update admin/business note
  const updatedNote = "Additional admin review note.";
  const noteUpdated = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: verificationId,
      note: updatedNote,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate,
  });
  typia.assert(noteUpdated);
  TestValidator.equals("note updated")(noteUpdated.note)(updatedNote);
  TestValidator.predicate("updated_at should be refreshed after note")(noteUpdated.updated_at !== reviewedVerification.updated_at);

  // 3c. Update document_file_uri and status
  const newStatus = "approved";
  const newDocumentUri = "https://cdn.example.com/new-verification.pdf";
  const docStatusUpdated = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: verificationId,
      verification_status: newStatus,
      document_file_uri: newDocumentUri,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate,
  });
  typia.assert(docStatusUpdated);
  TestValidator.equals("verification_status updated")(docStatusUpdated.verification_status)(newStatus);
  TestValidator.equals("document_file_uri updated")(docStatusUpdated.document_file_uri)(newDocumentUri);

  // 4. Attempt update for non-existent record
  const nonExistentId = typia.random<string & tags.Format<'uuid'>>();
  await TestValidator.error("non-existent record update throws error")(async () => {
    await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
      sellerId,
      body: {
        id: nonExistentId,
        verification_status: "rejected",
      } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate,
    });
  });

  // 5. Simulate finalized/compliance-locked record - this is implementation-specific, but we simulate by updating to a finalized status then attempting another update.
  const finalizedStatus = "approved";
  const finalized = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: verificationId,
      verification_status: finalizedStatus,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate,
  });
  typia.assert(finalized);

  await TestValidator.error("finalized/compliance-locked record cannot be changed")(async () => {
    await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
      sellerId,
      body: {
        id: verificationId,
        note: "Cannot overwrite after finalized.",
      } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate,
    });
  });
}

