/**
 * Validate creation and duplicate-prevention for customer favorite addresses.
 *
 * This test covers the following real-world workflow and business rules:
 * 1. Register a new customer and obtain their authentication session.
 * 2. Ensure the customer has at least one address (added via admin/customer address patch).
 * 3. Mark a customer address as favorite using the POST endpoint, checking for proper linkage.
 * 4. Attempt to favorite the same address again and check that duplication is not allowed.
 * 5. Attempt to favorite an invalid address (not found/not owned).
 * 6. Attempt unauthorized creation as a different customer.
 */
export async function test_api_favorite_address_create_success_and_duplicate_prevention(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "passw0rd!";
  const name = RandomGenerator.name();
  const nickname = RandomGenerator.alphabets(8);
  const phone = RandomGenerator.mobile();

  const registration = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name,
      nickname,
      phone,
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(registration);

  // Use customer and JWT for subsequent ops
  const customer = registration.customer;

  // 2. Add one address for the customer (admin/customer addresses patch/search)
  const addressList = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId: customer.id,
    body: {},
  });
  typia.assert(addressList);

  // If none exists, this would be initialization logic, but in this API only search exists, so simulate with an existing/seeded one for this test (addresses assumed returned)
  TestValidator.predicate("customer address should exist")(addressList.data.length > 0);
  const address = addressList.data[0];

  // 3. Mark as favorite
  const favorite = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(connection, {
    body: {
      customer_id: customer.id,
      address_id: address.id,
    } satisfies IShoppingMallAiBackendFavoriteAddress.ICreate,
  });
  typia.assert(favorite);
  TestValidator.equals("linked customer")(favorite.customer_id)(customer.id);
  TestValidator.equals("linked address")(favorite.address_id)(address.id);
  TestValidator.equals("not deleted")(favorite.deleted_at)(null);

  // 4. Attempt to create duplicate favorite (should fail)
  await TestValidator.error("duplicate favorite not allowed")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(connection, {
        body: {
          customer_id: customer.id,
          address_id: address.id,
        } satisfies IShoppingMallAiBackendFavoriteAddress.ICreate,
      });
    }
  );

  // 5. Attempt to favorite non-existent or foreign address_id (simulate with a new random UUID)
  await TestValidator.error("favorite creation for non-existent address fails")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(connection, {
        body: {
          customer_id: customer.id,
          address_id: typia.random<string & tags.Format<"uuid">>(),
        } satisfies IShoppingMallAiBackendFavoriteAddress.ICreate,
      });
    }
  );

  // 6. Attempt unauthorized favorite creation (as a different customer)
  // Register a second customer
  const email2 = typia.random<string & tags.Format<"email">>();
  const nickname2 = RandomGenerator.alphabets(8);
  const registration2 = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: email2,
      password,
      name: RandomGenerator.name(),
      nickname: nickname2,
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(registration2);
  const customer2 = registration2.customer;

  // Attempt to favorite first customer's address as second customer
  await TestValidator.error("cannot favorite address not owned")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(connection, {
        body: {
          customer_id: customer2.id,
          address_id: address.id,
        } satisfies IShoppingMallAiBackendFavoriteAddress.ICreate,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerAddress";
import type { IPageIShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerAddress";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBackendFavoriteAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteAddress";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate restoring and updating a customer favorite address, including ownership and error handling cases.
 *
 * This test simulates the full customer workflow for favorite address management:
 * - Customer registration and auth (JWT is auto-handled)
 * - Admin creates customer addresses (emulates real onboarding flow)
 * - Customer marks an address as favorite
 * - Customer unfavorites (soft-deletes) the favorite address
 * - Customer restores their favorite address using PUT (deleted_at: null)
 * - Confirms the favorite is active again in system
 * - Validates forbidden actions: modifying another user’s favorite or already deleted record
 *   (as the API supports only soft-delete/restore; no extra metadata)
 *
 * Steps:
 * 1. Register new customer and authenticate, saving Authorization
 * 2. Create multiple addresses for this customer (via admin endpoint)
 * 3. Favorite one address
 * 4. Soft-delete (unfavorite) it
 * 5. Restore via PUT (set deleted_at: null)
 * 6. Confirm active state and that it appears in favorites list
 * 7. Check error on restoring favorite for another user
 * 8. Check error on restoring a non-existent/deleted favorite
 */
export async function test_api_favorite_address_update_restore(connection: api.IConnection) {
  // 1. Register and authenticate a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "pw" + RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(6),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignUp);
  const customer = customerSignUp.customer;

  // 2. List (emulate creation) of customer addresses using admin endpoint
  const addressPage = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId: customer.id,
    body: {
      customer_id: customer.id,
      page: 1,
      limit: 1,
    },
  });
  typia.assert(addressPage);

  // Emulate address by using found address or generating one
  const address: IShoppingMallAiBackendCustomerAddress =
    addressPage.data[0] ?? {
      id: typia.random<string & tags.Format<"uuid">>(),
      customer_id: customer.id,
      alias: null,
      receiver_name: RandomGenerator.name(),
      receiver_phone: RandomGenerator.mobile(),
      postal_code: "12345",
      address_line1: RandomGenerator.paragraph()(),
      address_line2: null,
      city: "Seoul",
      state: "Seoul",
      country: "KR",
      is_primary: true,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      deleted_at: null,
    };

  // 3. Mark address as favorite
  const favorite = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(connection, {
    body: {
      customer_id: customer.id,
      address_id: address.id,
    },
  });
  typia.assert(favorite);
  TestValidator.equals("favorite ownership")(favorite.customer_id)(customer.id);
  TestValidator.equals("active favorite")(favorite.deleted_at)(null);

  // 4. Unfavorite (soft-delete)
  const deletedFavorite = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.update(connection, {
    favoriteAddressId: favorite.id,
    body: {
      deleted_at: new Date().toISOString(),
    },
  });
  typia.assert(deletedFavorite);
  TestValidator.predicate("soft deleted")(typeof deletedFavorite.deleted_at === "string");

  // 5. Restore (set deleted_at: null)
  const restored = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.update(connection, {
    favoriteAddressId: favorite.id,
    body: { deleted_at: null },
  });
  typia.assert(restored);
  TestValidator.equals("restored")(restored.deleted_at)(null);

  // 6. Confirm presence in address list
  const addressListAfterRestore = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId: customer.id,
    body: { customer_id: customer.id, page: 1, limit: 10 },
  });
  typia.assert(addressListAfterRestore);
  TestValidator.predicate("favorite address exists after restore")(
    addressListAfterRestore.data.some((a) => a.id === address.id)
  );

  // 7. Error: try to restore favorite not owned by this user (simulate another customer)
  const otherEmail = typia.random<string & tags.Format<"email">>();
  const otherCustomerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: otherEmail,
      password: "pw" + RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(6),
      phone: RandomGenerator.mobile(),
    },
