 *
 * This test ensures an admin can permanently (hard) delete a specific seller onboarding record. It verifies correct authorization, deletion, audit-trailing, error handling, and that the deleted record is not retrievable afterwards. Also tests edge and negative scenarios to enforce correct system error responses.
 *
 * Steps:
 * 1. Register an admin account.
 * 2. Log in as admin to get Authorization header set.
 * 3. Register a seller (new account, provides sellerId).
 * 4. As admin, search onboarding records for seller (cannot create onboarding).
 * 5. If onboarding exists, delete first onboarding record.
 * 6. Attempt to search for the onboarding again—should not be returned.
 * 7. Try deleting the already-deleted record (should error).
 * 8. Try deleting a random non-existent onboarding id (should error).
 * 9. Authorization and audit flow implicitly tested by requiring admin login for API access throughout.
 */
export async function test_api_admin_delete_seller_onboarding_record(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPW!2345";
