  });
  typia.assert(sellerSignUp);
  const sellerId = sellerSignUp.sellerId;

  // 4. Admin searches for onboarding records for this seller
  const onboardingSearchResp = await api.functional.shoppingMallAiBackend.admin.sellers.onboardings.search(connection, {
    sellerId,
    body: {
      seller_id: sellerId,
      step_code: null,
      step_status: null,
      approved_by: null, occurred_from: null,
      occurred_to: null, page: null, limit: null, orderBy: null, orderDir: null,
    } satisfies IShoppingMallAiBackendSellerOnboarding.IRequest,
  });
  typia.assert(onboardingSearchResp);
  TestValidator.predicate("found at least one onboarding record")(
    onboardingSearchResp.data.length > 0,
  );
  const onboarding: IShoppingMallAiBackendSellerOnboarding.ISummary = onboardingSearchResp.data[0];
  typia.assert(onboarding);

