    !afterDeleteSearch.data.some((o: IShoppingMallAiBackendSellerOnboarding.ISummary) => o.id === onboarding.id),
  );

  // 7. Attempt to delete same onboarding again (should error)
  await TestValidator.error("already deleted onboarding removes with error")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.onboardings.erase(connection, {
        sellerId,
        onboardingId: onboarding.id,
      });
