import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates admin update of a customer's address, including field, business logic, and error validation flows.
 *
 * This test covers:
 * 1. Admin login to obtain authorization
 * 2. Register a new customer (target)
 * 3. Obtain the customer's addresses (must exist or be auto-generated)
 * 4. Update a chosen address via the admin PUT endpoint
 * 5. Assert update is persisted (by new search)
 * 6. Validate runtime errors: missing required fields, bad phone, non-existent address
 */
export async function test_api_admin_customer_address_update_success_and_validation(
  connection: api.IConnection,
) {
  // 1. Admin login to obtain Authorization header
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = "TestAdmin!234";
  const adminLoginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLoginResp);
  connection.headers = {
    ...connection.headers,
    Authorization: adminLoginResp.setHeaders.Authorization,
  };

  // 2. Register a new customer
  const customerEmail = typia.random<string & tags.Format<'email'>>();
  const customerPassword = "Customer!234";
  const signUpOutput = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpOutput);
  const customerId = signUpOutput.customer.id;

  // 3. Obtain addresses for customer. Assume at least one is present/auto-created
  const addressesPage = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: {
      customer_id: customerId,
      limit: 10,
      page: 1,
    } satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });
  typia.assert(addressesPage);
  const addresses = addressesPage.data;
  TestValidator.predicate("Should have at least one address")(addresses.length > 0);
  const targetAddress = addresses[0];

  // 4. Prepare update input; mutate a set of fields
  const updateInput = {
    id: targetAddress.id,
    receiver_name: RandomGenerator.name(),
    receiver_phone: RandomGenerator.mobile(),
    postal_code: "08080",
    address_line1: "123 New Main St",
    city: "Seoul",
    state: "Seoul",
    country: "KR",
    is_primary: !targetAddress.is_primary,
  } satisfies IShoppingMallAiBackendCustomerAddress.IUpdate;

  // 5. Perform the update
  const updated = await api.functional.shoppingMallAiBackend.admin.customers.addresses.update(connection, {
    customerId,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals("receiver_name updated")(updated.receiver_name)(updateInput.receiver_name);
  TestValidator.equals("receiver_phone updated")(updated.receiver_phone)(updateInput.receiver_phone);
  TestValidator.equals("postal_code updated")(updated.postal_code)(updateInput.postal_code);
  TestValidator.equals("is_primary toggled")(updated.is_primary)(updateInput.is_primary);

  // 6. Fetch again to confirm persistence
  const addressesPage2 = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: {
      customer_id: customerId,
      receiver_name: updateInput.receiver_name,
      limit: 10,
      page: 1,
    },
  });
  typia.assert(addressesPage2);
  TestValidator.predicate("refetch updated address present")(
    addressesPage2.data.some((a) => a.id === targetAddress.id && a.receiver_name === updateInput.receiver_name)
  );

  // 7. Try missing required field (receiver_name)
  await TestValidator.error("missing receiver_name should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.addresses.update(connection, {
      customerId,
      body: {
        ...updateInput,
        // Use an empty string for receiver_name to trigger required validation error at runtime
        receiver_name: "",
      },
    });
  });

  // 8. Try invalid phone value
  await TestValidator.error("invalid phone should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.addresses.update(connection, {
      customerId,
      body: {
        ...updateInput,
        receiver_phone: "invalid-phone-123",
      },
    });
  });

  // 9. Try updating a non-existent address id
  await TestValidator.error("non-existent address should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.addresses.update(connection, {
      customerId,
      body: {
        ...updateInput,
        id: typia.random<string & tags.Format<'uuid'>>(),
      },
    });
  });
}

