import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test soft-deleting a customer's address as an admin and validate idempotency and error conditions.
 *
 * This function ensures that:
 *   - A customer can be created, and has at least one address (obtained after registration).
 *   - As an admin, that address can be soft-deleted via DELETE /shoppingMallAiBackend/admin/customers/{customerId}/addresses/{addressId}.
 *   - After deletion, the address is marked with "deleted_at" and is not returned in the active addresses list.
 *   - Deleting an already-deleted address returns a proper error or an idempotent response (should not succeed silently).
 *   - Deleting a non-existent address also yields a precise error.
 *
 * Steps:
 *   1. Create and register a new customer (store credentials and id).
 *   2. From the registration result, get the customer's id and at least one address (ensure at least one exists).
 *   3. Admin logs in to acquire token/authentication.
 *   4. As admin, list all addresses for that customer and pick a valid addressId.
 *   5. As admin, DELETE the address. Confirm operation returns 200 or similar success.
 *   6. As admin, list addresses again; confirm deleted address is no longer present in active list.
 *   7. Optionally, fetch or list all addresses including deleted (if possible), and confirm deleted_at is set for that address.
 *   8. Attempt DELETE again on same address; confirm error or idempotency behavior (if system allows, should return an error, not a success).
 *   9. Attempt DELETE on a random, non-existent address_id; confirm a clear error is returned.
 */
export async function test_api_admin_customer_address_soft_delete_and_idempotency(
  connection: api.IConnection,
) {
  // 1. Register a new customer and extract customerId.
  const regResp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "VerySecurePassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(regResp);
  const customerId = regResp.customer.id;

  // 2. Ensure at least one address exists after registration (assume system auto-creates an address if fields exist).
  // To get it, list addresses (admin endpoint, must login as admin first).

  // 3. Admin login
  const adminEmail = "admin@shoppingmall.com"; // This should be a valid admin email configured in the test env
  const adminPassword = "adminPassword123!";   // Corresponding admin password
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);
  // The connection now has admin privileges (admin JWT)

  // 4. List addresses for this customer (active only)
  const addresses = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: {},
  });
  typia.assert(addresses);
  const activeAddresses = addresses.data.filter(addr => !addr.deleted_at);
  TestValidator.predicate("at least one address exists")(activeAddresses.length > 0);
  const targetAddress = activeAddresses[0];
  const addressId = targetAddress.id;

  // 5. Soft-delete the address via admin endpoint
  await api.functional.shoppingMallAiBackend.admin.customers.addresses.erase(connection, {
    customerId,
    addressId,
  });
  // If endpoint returns nothing, success is implied on no error thrown.

  // 6. Confirm the address is not present in list anymore
  const addressesAfter = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: {},
  });
  typia.assert(addressesAfter);
  const stillPresent = addressesAfter.data.some(addr => addr.id === addressId && !addr.deleted_at);
  TestValidator.predicate("deleted address is not in active list")(!stillPresent);
  // Optionally, can confirm by searching for it if endpoint supports showing deleted

  // 7. Try soft-delete again (should yield error or idempotency behavior)
  await TestValidator.error("deleting already-deleted address fails or returns idempotency")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.customers.addresses.erase(connection, {
        customerId,
        addressId,
      });
    },
  );

  // 8. Attempt to delete a non-existent address (random UUID)
  const nonExistentAddressId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("deleting non-existent address fails")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.customers.addresses.erase(connection, {
        customerId,
        addressId: nonExistentAddressId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
